-- University student_records.db STRUCTURE ONLY (no rows), snapshot 2026-11-05.
-- A from-scratch `alembic upgrade head` does not build this schema (two
-- migrations read columns only runtime code adds), so tests that need the
-- whole current university schema load this instead.

CREATE TABLE abs_tracker_appeals (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id  TEXT, request_id INTEGER, reason TEXT,
            status      TEXT DEFAULT 'open',
            created_at  TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_attendance_disputes (
            id            INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id    TEXT, attendance_id INTEGER, reason TEXT,
            status        TEXT DEFAULT 'open',
            created_at    TEXT DEFAULT CURRENT_TIMESTAMP,
            resolved_at   TEXT, outcome TEXT
        );
CREATE TABLE abs_tracker_audit (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            ts          TEXT DEFAULT CURRENT_TIMESTAMP,
            user_id     INTEGER,
            username    TEXT,
            action      TEXT,
            target      TEXT,
            target_id   TEXT,
            details     TEXT
        );
CREATE TABLE abs_tracker_auto_excuse_rules (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT,
            status     TEXT DEFAULT 'excused',
            enabled    INTEGER DEFAULT 1
        );
CREATE TABLE abs_tracker_co_teachers (
            module_code TEXT, user_id INTEGER,
            PRIMARY KEY (module_code, user_id)
        );
CREATE TABLE abs_tracker_delegations (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            from_user   INTEGER,
            to_user     INTEGER,
            active_from TEXT,
            active_to   TEXT
        );
CREATE TABLE abs_tracker_group_members (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_id INTEGER, student_id TEXT, UNIQUE(group_id, student_id)
        );
CREATE TABLE abs_tracker_groups (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_code TEXT, name TEXT, UNIQUE(module_code, name)
        );
CREATE TABLE abs_tracker_intervention_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id INTEGER, student_id TEXT, action TEXT, outcome TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_module_policy (
            module_code      TEXT PRIMARY KEY,
            min_percent      REAL,
            late_as_absent   INTEGER,
            grace_minutes    INTEGER,
            notes            TEXT
        );
CREATE TABLE abs_tracker_note_requests (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            requester_id TEXT, module_code TEXT, date TEXT,
            status       TEXT DEFAULT 'open',
            created_at   TEXT DEFAULT CURRENT_TIMESTAMP,
            fulfiller_id TEXT
        );
CREATE TABLE abs_tracker_note_share (
            id           INTEGER PRIMARY KEY AUTOINCREMENT,
            owner_id     TEXT, module_code TEXT, date TEXT,
            file_path    TEXT, title TEXT,
            created_at   TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_peer_observations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            observer_id INTEGER, subject_id INTEGER, module_code TEXT,
            date TEXT, notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_request_attachments (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            request_id  INTEGER,
            file_path   TEXT,
            uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_request_comments (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            request_id INTEGER,
            author     TEXT,
            body       TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_request_route (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            request_id INTEGER, routed_to INTEGER, reason TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_request_templates (
            id      INTEGER PRIMARY KEY AUTOINCREMENT,
            name    TEXT UNIQUE,
            body    TEXT
        );
CREATE TABLE abs_tracker_retention (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            policy     TEXT,
            years      INTEGER,
            applied_at TEXT
        );
CREATE TABLE abs_tracker_scheduled_reports (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            name        TEXT,
            frequency   TEXT,
            recipients  TEXT,
            report_type TEXT,
            last_run    TEXT,
            enabled     INTEGER DEFAULT 1
        );
CREATE TABLE abs_tracker_seating (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_code TEXT, date TEXT, layout_json TEXT,
            UNIQUE(module_code, date)
        );
CREATE TABLE abs_tracker_session_notes (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id   INTEGER, module_code TEXT, date TEXT, note TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_session_qr (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_code TEXT, date TEXT, code TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(module_code, date)
        );
CREATE TABLE abs_tracker_session_status (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            module_code TEXT, date TEXT, status TEXT,
            set_by      INTEGER, set_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(module_code, date)
        );
CREATE TABLE abs_tracker_settings (
            key   TEXT PRIMARY KEY,
            value TEXT
        );
CREATE TABLE abs_tracker_sms_queue (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    recipient TEXT, body TEXT,
                    queued_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    status TEXT DEFAULT 'queued');
CREATE TABLE abs_tracker_staff_prefs (
            user_id INTEGER, key TEXT, value TEXT,
            PRIMARY KEY (user_id, key)
        );
CREATE TABLE abs_tracker_staff_tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id INTEGER, task TEXT, done INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            done_at TEXT
        );
CREATE TABLE abs_tracker_statuses (
            code       TEXT PRIMARY KEY,
            label      TEXT,
            counts_as  TEXT
        );
CREATE TABLE abs_tracker_student_badges (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id  TEXT, badge TEXT, awarded_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(student_id, badge)
        );
CREATE TABLE abs_tracker_student_drafts (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id  TEXT, module_code TEXT, date TEXT, reason TEXT,
            saved_at    TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_student_goals (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id  TEXT, module_code TEXT, target_pct REAL,
            created_at  TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(student_id, module_code)
        );
CREATE TABLE abs_tracker_student_prefs (
            student_id TEXT, key TEXT, value TEXT,
            PRIMARY KEY(student_id, key)
        );
CREATE TABLE abs_tracker_study_buddies (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id  TEXT, module_code TEXT,
            created_at  TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(student_id, module_code)
        );
CREATE TABLE abs_tracker_ta_handoff (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id INTEGER, ta_id INTEGER, module_code TEXT, note TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE abs_tracker_trash (
            id             INTEGER PRIMARY KEY AUTOINCREMENT,
            deleted_at     TEXT DEFAULT CURRENT_TIMESTAMP,
            deleted_by     TEXT,
            original_table TEXT,
            original_id    INTEGER,
            payload        TEXT
        );
CREATE TABLE abs_tracker_wellbeing_flags (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id  TEXT, attendance_id INTEGER, note TEXT,
            created_at  TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE absence_evidence_signatures (
         id INTEGER PRIMARY KEY AUTOINCREMENT,
         request_id INTEGER NOT NULL, file_path TEXT NOT NULL,
         sha256 TEXT NOT NULL, signed_by TEXT,
         signed_at TEXT DEFAULT CURRENT_TIMESTAMP
       );
CREATE TABLE absence_push_queue (
         id INTEGER PRIMARY KEY AUTOINCREMENT,
         user_id TEXT NOT NULL,
         title TEXT NOT NULL, body TEXT NOT NULL, payload TEXT,
         created_at TEXT DEFAULT CURRENT_TIMESTAMP,
         delivered_at TEXT, status TEXT DEFAULT 'pending'
       );
CREATE TABLE absence_request_categories (
         id INTEGER PRIMARY KEY AUTOINCREMENT,
         name TEXT UNIQUE NOT NULL,
         description TEXT,
         requires_evidence INTEGER DEFAULT 0,
         approval_route TEXT DEFAULT 'instructor',
         auto_approve INTEGER DEFAULT 0
       );
CREATE TABLE absence_requests (
                 id           INTEGER PRIMARY KEY AUTOINCREMENT,
                 student_id   TEXT NOT NULL,
                 module_code  TEXT NOT NULL,
                 date         TEXT NOT NULL,
                 reason       TEXT NOT NULL,
                 status       TEXT NOT NULL DEFAULT 'pending'
                              CHECK(status IN ('pending','approved','rejected')),
                 submitted_at TEXT DEFAULT CURRENT_TIMESTAMP
               , decided_by TEXT, decided_at TEXT, decision_reason TEXT, is_missed_exam INTEGER NOT NULL DEFAULT 0, exam_id INTEGER, category_id INTEGER, date_end TEXT, "self_certified" INTEGER DEFAULT 0);
CREATE TABLE absence_settings (
         key TEXT PRIMARY KEY, value TEXT
       );
CREATE TABLE "academic_calendar_events" (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    date TEXT,
    date_start TEXT,
    date_end TEXT,
    description TEXT,
    event_type TEXT DEFAULT 'Academic',
    date_added TEXT NOT NULL,
    last_modified TEXT,
    created_by TEXT,
    start_time TEXT,
    end_time TEXT,
    location TEXT,
    audience TEXT,
    assignment_id INTEGER,
    trip_id INTEGER,
    organizer TEXT,
    participants TEXT,
    status TEXT,
    country_code TEXT,
    region TEXT,
    is_active BOOLEAN DEFAULT 1,
    CONSTRAINT valid_event_dates CHECK (
        date_start IS NULL OR date_end IS NULL OR date_start <= date_end
    )
);
CREATE TABLE academic_goals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                parent_id TEXT,
                goal_title TEXT,
                description TEXT,
                target_grade TEXT,
                target_date TEXT,
                current_progress TEXT,
                status TEXT DEFAULT 'active',
                created_date TEXT, "category" TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
            );
CREATE TABLE academic_misconduct_cases (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            case_id TEXT UNIQUE NOT NULL,
            student_name TEXT NOT NULL,
            student_id TEXT NOT NULL,
            student_email TEXT,
            course TEXT NOT NULL,
            violation_type TEXT NOT NULL,
            status TEXT DEFAULT 'Under Review',
            date_filed TEXT NOT NULL,
            severity TEXT NOT NULL,
            notes TEXT,
            hearing_date TEXT,
            hearing_time TEXT,
            hearing_location TEXT,
            ruling TEXT,
            ruling_rationale TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        , system_key TEXT NOT NULL DEFAULT 'university', source_record_id INTEGER);
CREATE TABLE academic_misconduct_chain_of_custody (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                evidence_id INTEGER NOT NULL,
                handler TEXT NOT NULL,
                action TEXT NOT NULL,
                details TEXT DEFAULT '',
                timestamp TEXT NOT NULL,
                FOREIGN KEY (evidence_id) REFERENCES academic_misconduct_evidence(id) ON DELETE CASCADE
            );
CREATE TABLE academic_misconduct_evidence (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            case_id TEXT NOT NULL,
            file_name TEXT NOT NULL,
            file_path TEXT,
            file_size TEXT,
            uploaded_date TEXT NOT NULL,
            uploaded_by TEXT, file_hash TEXT DEFAULT '', category TEXT DEFAULT 'Document', notes TEXT DEFAULT '',
            FOREIGN KEY (case_id) REFERENCES academic_misconduct_cases(case_id)
        );
CREATE TABLE academic_misconduct_evidence_tags (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                evidence_id INTEGER NOT NULL,
                tag TEXT NOT NULL,
                FOREIGN KEY (evidence_id) REFERENCES academic_misconduct_evidence(id) ON DELETE CASCADE
            );
CREATE TABLE academic_misconduct_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            case_id TEXT NOT NULL,
            event_date TEXT NOT NULL,
            event_description TEXT NOT NULL,
            event_type TEXT DEFAULT 'info',
            created_by TEXT,
            FOREIGN KEY (case_id) REFERENCES academic_misconduct_cases(case_id)
        );
CREATE TABLE academic_study_group_members (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                group_id INTEGER,
                user_id TEXT,
                joined_at TEXT,
                FOREIGN KEY (group_id) REFERENCES academic_study_groups (group_id)
            );
CREATE TABLE academic_study_groups (
                group_id INTEGER PRIMARY KEY AUTOINCREMENT,
                group_name TEXT NOT NULL,
                subject TEXT,
                description TEXT,
                max_members INTEGER DEFAULT 10,
                current_members INTEGER DEFAULT 1,
                meeting_schedule TEXT,
                location TEXT,
                created_by TEXT,
                created_at TEXT,
                status TEXT DEFAULT 'active'
            );
CREATE TABLE academic_terms (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL UNIQUE,
        term_type TEXT NOT NULL DEFAULT 'Semester',
        academic_year TEXT NOT NULL DEFAULT '',
        start_date TEXT DEFAULT '',
        end_date TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'Planned',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    , "source" TEXT, "teaching_weeks" INTEGER, "sort_order" INTEGER);
CREATE TABLE academic_transfer_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            source_system TEXT NOT NULL,
            source_student_id TEXT NOT NULL,
            transfer_date TEXT NOT NULL DEFAULT (datetime('now')),
            data_json TEXT NOT NULL
        );
CREATE TABLE academic_warnings (
                    warning_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    warning_type TEXT NOT NULL,
                    severity TEXT NOT NULL,
                    warning_message TEXT NOT NULL,
                    trigger_metric TEXT,
                    trigger_value TEXT,
                    recommendations_json TEXT,
                    acknowledged BOOLEAN DEFAULT 0,
                    acknowledged_at TEXT,
                    resolved BOOLEAN DEFAULT 0,
                    resolved_at TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE academic_workshop_registrations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                workshop_id INTEGER,
                user_id TEXT,
                registered_at TEXT,
                attended INTEGER DEFAULT 0,
                FOREIGN KEY (workshop_id) REFERENCES academic_workshops (workshop_id)
            );
CREATE TABLE academic_workshops (
                workshop_id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                description TEXT,
                instructor TEXT,
                date TEXT,
                time TEXT,
                location TEXT,
                max_participants INTEGER DEFAULT 30,
                registered INTEGER DEFAULT 0,
                status TEXT DEFAULT 'upcoming',
                created_at TEXT
            );
CREATE TABLE academic_years (
                    id TEXT PRIMARY KEY,
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    date_added TEXT NOT NULL,
                    CONSTRAINT valid_dates CHECK (start_date < end_date)
                );
CREATE TABLE access_cards (
                card_id INTEGER PRIMARY KEY AUTOINCREMENT,
                card_number TEXT UNIQUE NOT NULL,
                user_id TEXT,
                user_name TEXT,
                card_type TEXT DEFAULT 'staff',
                access_level TEXT,
                buildings_access TEXT,
                issue_date TEXT,
                expiry_date TEXT,
                status TEXT DEFAULT 'active',
                issued_by TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE accessibility_audit_logs (
    log_id INTEGER PRIMARY KEY AUTOINCREMENT,
    page_url TEXT NOT NULL,
    issues_found TEXT,  -- JSON array
    severity TEXT,  -- low, medium, high, critical
    audited_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    audited_by INTEGER
);
CREATE TABLE accessibility_feedback (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id INTEGER,
                        username TEXT,
                        issue_type TEXT,
                        description TEXT,
                        contact_email TEXT,
                        submitted_date TEXT,
                        status TEXT DEFAULT 'pending'
                    );
CREATE TABLE accessibility_messages (
                    message_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    sender_id TEXT NOT NULL,
                    sender_type TEXT NOT NULL,
                    message TEXT NOT NULL,
                    sent_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    is_read INTEGER DEFAULT 0,
                    FOREIGN KEY (request_id) REFERENCES accommodation_requests(request_id)
                );
CREATE TABLE "accessibility_profiles" (
            profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL UNIQUE,
            disabilities TEXT,
            accommodations TEXT,
            assistive_technologies TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "student_id" TEXT,
            FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        );
CREATE TABLE "accessibility_settings" (
            setting_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL UNIQUE,
            theme TEXT DEFAULT 'standard',
            font_size INTEGER DEFAULT 16,
            contrast_level TEXT DEFAULT 'normal',
            screen_reader_enabled BOOLEAN DEFAULT 0,
            keyboard_navigation BOOLEAN DEFAULT 0, "student_id" TEXT, "extended_time" INTEGER DEFAULT 0, "high_contrast" INTEGER DEFAULT 0, "screen_reader" INTEGER DEFAULT 0, "extra_settings_json" TEXT DEFAULT '{}', "updated_at" TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
        );
CREATE TABLE accommodation_approvals (
    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
    request_id INTEGER NOT NULL,
    approved_by INTEGER NOT NULL,
    approved_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    notes TEXT,
    FOREIGN KEY (request_id) REFERENCES accommodation_requests(request_id)
);
CREATE TABLE accommodation_documentation (
                    doc_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    filename TEXT NOT NULL,
                    file_path TEXT NOT NULL,
                    upload_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    document_type TEXT,
                    FOREIGN KEY (request_id) REFERENCES accommodation_requests(request_id)
                );
CREATE TABLE accommodation_renewals (
                    renewal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    accommodation_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    renewal_request_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    status TEXT NOT NULL,
                    processed_date TIMESTAMP,
                    processed_by TEXT,
                    notes TEXT,
                    FOREIGN KEY (accommodation_id) REFERENCES accommodations(id)
                );
CREATE TABLE accommodation_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    accommodation_type TEXT NOT NULL,  -- extended_time, alternative_format, etc.
    description TEXT,
    status TEXT DEFAULT 'pending',  -- pending, approved, denied
    requested_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    reviewed_by INTEGER,
    review_date TIMESTAMP,
    review_notes TEXT, student_name TEXT, student_email TEXT, submitted_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewer_notes TEXT, "reviewed_date" TIMESTAMP, "reviewer_id" TEXT, "created_at" TEXT,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE accommodation_shares (
        accommodation_id INTEGER NOT NULL,
        recipient        TEXT NOT NULL,
        state            TEXT NOT NULL CHECK (state IN ('shared', 'withdrawn')),
        changed_at       TEXT NOT NULL,
        PRIMARY KEY (accommodation_id, recipient)
    );
CREATE TABLE accommodation_templates (
                    name TEXT PRIMARY KEY,
                    accommodation_type TEXT NOT NULL,
                    description TEXT,
                    start_offset_days INTEGER,
                    duration_days INTEGER,
                    created_by TEXT,
                    created_at TEXT,
                    updated_at TEXT
                );
CREATE TABLE accommodation_types (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    type_name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    requires_approval BOOLEAN DEFAULT 0,
                    max_duration_days INTEGER,
                    created_at TEXT
                );
CREATE TABLE accommodations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    accommodation_type TEXT NOT NULL,
                    description TEXT,
                    start_date TEXT,
                    end_date TEXT,
                    status TEXT DEFAULT 'active',
                    approved_by TEXT,
                    approval_date TEXT,
                    notes TEXT,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL, "expiration_date" DATE, "request_id" INTEGER,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE "account_link_requests" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                requesting_user_id INTEGER NOT NULL,
                target_user_id INTEGER NOT NULL,
                status TEXT NOT NULL DEFAULT 'pending'
                    CHECK(status IN ('pending', 'approved', 'rejected', 'cancelled')),
                reason TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                resolved_at TIMESTAMP,
                resolved_by INTEGER,
                FOREIGN KEY (requesting_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE achievement_badges (
            badge_id INTEGER PRIMARY KEY AUTOINCREMENT,
            badge_name TEXT,
            badge_description TEXT,
            points_required INTEGER,
            badge_icon TEXT,
            category TEXT
        , "description" TEXT, "created_date" TEXT, "criteria" TEXT, "rarity" TEXT, "status" TEXT);
CREATE TABLE achievements (
                    achievement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    achievement_type TEXT NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    date_achieved DATE NOT NULL,
                    points INTEGER DEFAULT 0,
                    category TEXT,
                    is_verified BOOLEAN DEFAULT 0,
                    verified_by TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE active_role_switches (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                original_role TEXT NOT NULL,
                switched_to_role TEXT NOT NULL,
                linked_account_id INTEGER NOT NULL,
                switched_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                reverted_at TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (linked_account_id) REFERENCES linked_accounts(id) ON DELETE CASCADE
            );
CREATE TABLE "activity_log" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            username TEXT NOT NULL,
            action TEXT NOT NULL,
            details TEXT,
            timestamp TEXT NOT NULL,
            ip_address TEXT, "entity_type" TEXT, "entity_id" TEXT, "user_role" TEXT,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE "activity_participants" (
                participant_id INTEGER PRIMARY KEY AUTOINCREMENT,
                activity_id INTEGER NOT NULL,
                user_id TEXT NOT NULL,
                rsvp_status TEXT DEFAULT 'interested',
                joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (activity_id) REFERENCES social_activities(activity_id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users(username) ON DELETE CASCADE,
                UNIQUE(activity_id, user_id)
            );
CREATE TABLE adjustment_requests (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    original_course TEXT,
                    requested_course TEXT,
                    reason TEXT,
                    current_grades TEXT,
                    status TEXT DEFAULT 'pending',
                    requested_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    decided_by TEXT,
                    decided_at TEXT
                );
CREATE TABLE admin_risk_factors (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    factor_name TEXT,
                    factor_value REAL,
                    assessment_id INTEGER,
                    date_calculated TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id),
                    FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
                );
CREATE TABLE admission_application_choices (
            choice_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            programme_code TEXT NOT NULL,
            programme_name TEXT,
            entry_year TEXT,
            rank INTEGER NOT NULL DEFAULT 1 CHECK (rank > 0),
            choice_status TEXT NOT NULL DEFAULT 'active',
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (application_id, rank),
            FOREIGN KEY (application_id)
                REFERENCES admission_applications(application_id) ON DELETE CASCADE
        );
CREATE TABLE admission_applications (
            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
            prospect_id INTEGER NOT NULL,
            application_type TEXT NOT NULL,
            program_applied TEXT NOT NULL,
            academic_year TEXT NOT NULL,
            semester TEXT NOT NULL,
            submission_date TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'submitted',
            decision TEXT,
            decision_date TEXT,
            enrollment_confirmed BOOLEAN DEFAULT 0,
            application_fee_paid BOOLEAN DEFAULT 0, journey_id TEXT, accepted_choice_id INTEGER, converted_student_id TEXT, lifecycle_updated_at TEXT, external_reference TEXT,
            FOREIGN KEY (prospect_id) REFERENCES admission_prospects (prospect_id)
        );
CREATE TABLE admission_conditions (
            condition_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            condition_type TEXT NOT NULL,
            description TEXT NOT NULL,
            amount REAL,
            currency TEXT,
            sponsor_name TEXT,
            due_date TEXT,
            status TEXT NOT NULL DEFAULT 'outstanding',
            satisfied_at TEXT,
            evidence_reference TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (application_id)
                REFERENCES admission_applications(application_id) ON DELETE CASCADE
        );
CREATE TABLE admission_contextual_access_log (
    log_id         INTEGER PRIMARY KEY AUTOINCREMENT,
    application_id INTEGER NOT NULL,
    viewer         TEXT,
    allowed        INTEGER NOT NULL,
    viewed_at      TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE admission_contextual_flags (
    application_id       INTEGER PRIMARY KEY,
    journey_id           TEXT,
    status               TEXT NOT NULL,
    flags_json           TEXT,
    not_held_json        TEXT,
    consent_reference    TEXT,
    consent_granted_date TEXT,
    withheld_reason      TEXT,
    source_event_id      TEXT,
    received_at          TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (application_id)
        REFERENCES admission_applications(application_id) ON DELETE CASCADE
);
CREATE TABLE admission_deposit_decisions (
            decision_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL UNIQUE,
            required_amount REAL NOT NULL,
            currency TEXT NOT NULL,
            received_amount REAL NOT NULL DEFAULT 0,
            status TEXT NOT NULL,
            payment_reference TEXT,
            decided_by TEXT NOT NULL,
            decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(application_id) REFERENCES admission_applications(application_id)
        );
CREATE TABLE admission_handover_route_history (
    history_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    application_id   INTEGER NOT NULL,
    action           TEXT NOT NULL,
    from_route       TEXT,
    from_course_code TEXT,
    from_course_name TEXT,
    from_entry_year  TEXT,
    to_route         TEXT,
    to_institution   TEXT,
    to_course_code   TEXT,
    to_course_name   TEXT,
    to_entry_year    TEXT,
    deferred         INTEGER NOT NULL DEFAULT 0,
    reason           TEXT,
    source_event_id  TEXT,
    recorded_at      TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (application_id)
        REFERENCES admission_applications(application_id) ON DELETE CASCADE
);
CREATE TABLE admission_handover_routing (
    application_id  INTEGER PRIMARY KEY,
    journey_id      TEXT,
    route           TEXT,
    institution     TEXT,
    course_code     TEXT,
    course_name     TEXT,
    entry_year      TEXT,
    deferred        INTEGER NOT NULL DEFAULT 0,
    routing_status  TEXT NOT NULL DEFAULT 'active',
    rerouted_at     TEXT,
    reroute_reason  TEXT,
    source_event_id TEXT,
    created_at      TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at      TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (application_id)
        REFERENCES admission_applications(application_id) ON DELETE CASCADE
);
CREATE TABLE admission_interviews (
            interview_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            activity_type TEXT NOT NULL CHECK (
                activity_type IN ('interview', 'audition')
            ),
            scheduled_at TEXT NOT NULL,
            format TEXT,
            location TEXT,
            panel TEXT,
            outcome TEXT,
            notes TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (application_id)
                REFERENCES admission_applications(application_id) ON DELETE CASCADE
        );
CREATE TABLE admission_prospects (
            prospect_id INTEGER PRIMARY KEY AUTOINCREMENT,
            first_name TEXT NOT NULL,
            last_name TEXT NOT NULL,
            email TEXT NOT NULL,
            phone TEXT,
            date_of_birth TEXT,
            country TEXT,
            state TEXT,
            city TEXT,
            high_school TEXT,
            intended_major TEXT,
            source TEXT,
            status TEXT DEFAULT 'prospect',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            last_contact_date TEXT
        );
CREATE TABLE admission_requirements (
            requirement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            requirement_type TEXT NOT NULL,
            description TEXT NOT NULL,
            due_date TEXT,
            required INTEGER NOT NULL DEFAULT 1,
            status TEXT NOT NULL DEFAULT 'outstanding',
            verified_by TEXT,
            verified_at TEXT,
            evidence_document_id INTEGER,
            notes TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (application_id)
                REFERENCES admission_applications(application_id) ON DELETE CASCADE
        );
CREATE TABLE admission_right_to_study_decisions (
            decision_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL UNIQUE,
            route TEXT NOT NULL,
            evidence_reference TEXT NOT NULL,
            valid_until TEXT,
            status TEXT NOT NULL,
            decided_by TEXT NOT NULL,
            decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(application_id) REFERENCES admission_applications(application_id)
        );
CREATE TABLE admission_sponsorship_decisions (
            decision_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL UNIQUE,
            sponsor_name TEXT NOT NULL,
            reference TEXT NOT NULL,
            amount REAL,
            valid_until TEXT,
            status TEXT NOT NULL,
            decided_by TEXT NOT NULL,
            decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(application_id) REFERENCES admission_applications(application_id)
        );
CREATE TABLE admission_status_history (
            history_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            from_status TEXT,
            to_status TEXT NOT NULL,
            reason TEXT,
            actor_id TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (application_id)
                REFERENCES admission_applications(application_id) ON DELETE CASCADE
        );
CREATE TABLE advanced_detection_results (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                temporal_analysis TEXT,
                citation_analysis TEXT,
                behavioral_analysis TEXT,
                multimodal_analysis TEXT,
                adversarial_analysis TEXT,
                ensemble_prediction TEXT,
                risk_prediction TEXT,
                bias_adjusted_score REAL,
                blockchain_hash TEXT,
                FOREIGN KEY (submission_id) REFERENCES ai_detector_submissions (id)
            );
CREATE TABLE advising_appointments (
                appointment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                advisor_id TEXT NOT NULL,
                appointment_date TEXT NOT NULL,
                appointment_time TEXT NOT NULL,
                duration_minutes INTEGER DEFAULT 30,
                appointment_type TEXT NOT NULL,
                topic TEXT,
                notes TEXT,
                status TEXT DEFAULT 'scheduled',
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            , "advisor_name" TEXT, "follow_up_required" INTEGER DEFAULT 0);
CREATE TABLE advisors (
                    advisor_id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    department TEXT DEFAULT '',
                    email TEXT DEFAULT '',
                    office TEXT DEFAULT '',
                    specialization TEXT DEFAULT '',
                    available_days TEXT DEFAULT 'Mon,Tue,Wed,Thu,Fri',
                    available_hours TEXT DEFAULT '09:00-17:00'
                );
CREATE TABLE ai_alert_settings (
                    id INTEGER PRIMARY KEY,
                    setting_name TEXT UNIQUE,
                    setting_value TEXT,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE ai_audit_chain (
        idx INTEGER PRIMARY KEY,
        event TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        actor TEXT NOT NULL,
        at TEXT NOT NULL,
        prev_hash TEXT NOT NULL,
        hash TEXT NOT NULL UNIQUE
    );
CREATE TABLE ai_chatbot_conversations (
            conversation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            user_type TEXT NOT NULL,
            start_time TEXT DEFAULT CURRENT_TIMESTAMP,
            end_time TEXT,
            message_count INTEGER DEFAULT 0,
            satisfaction_rating INTEGER,
            was_helpful BOOLEAN,
            escalated_to_human BOOLEAN DEFAULT 0
        );
CREATE TABLE ai_chatbot_messages (
            message_id INTEGER PRIMARY KEY AUTOINCREMENT,
            conversation_id INTEGER NOT NULL,
            sender_type TEXT NOT NULL,
            message_text TEXT NOT NULL,
            intent_detected TEXT,
            confidence_score REAL,
            timestamp TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (conversation_id) REFERENCES ai_chatbot_conversations (conversation_id)
        );
CREATE TABLE ai_content_suggestions (
            suggestion_id INTEGER PRIMARY KEY AUTOINCREMENT,
            content_type TEXT NOT NULL,
            context TEXT NOT NULL,
            suggested_content TEXT NOT NULL,
            relevance_score REAL,
            source TEXT,
            was_used BOOLEAN DEFAULT 0,
            created_for TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_detector_academic_records (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    record_id TEXT UNIQUE NOT NULL,
                    student_id TEXT NOT NULL,
                    submission_id TEXT NOT NULL,
                    violation_type TEXT NOT NULL,
                    sanction TEXT NOT NULL,
                    sanction_details TEXT,
                    notes TEXT,
                    reviewer_id TEXT NOT NULL,
                    status TEXT NOT NULL DEFAULT 'active',
                    created_at TEXT NOT NULL,
                    synced_to_external INTEGER DEFAULT 0,
                    synced_at TEXT
                , "ai_result_id" INTEGER, "case_id" INTEGER);
CREATE TABLE ai_detector_activity_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    action TEXT NOT NULL,
                    action_type TEXT,
                    target_id TEXT,
                    details TEXT,
                    ip_address TEXT,
                    timestamp TEXT NOT NULL
                );
CREATE TABLE ai_detector_alert_config (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    config_key TEXT UNIQUE NOT NULL,
                    config_value TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    updated_by TEXT
                );
CREATE TABLE ai_detector_alerts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id TEXT NOT NULL,
                    student_id TEXT NOT NULL,
                    submission_title TEXT,
                    risk_level TEXT NOT NULL,
                    ai_score REAL NOT NULL,
                    status TEXT NOT NULL DEFAULT 'pending',
                    created_at TEXT NOT NULL,
                    reviewed_at TEXT,
                    reviewed_by TEXT,
                    dismissal_reason TEXT,
                    notes TEXT
                , "ai_result_id" INTEGER, "module_code" TEXT, "assignment_id" TEXT, "case_id" INTEGER);
CREATE TABLE ai_detector_assignment_profiles (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    profile_id TEXT UNIQUE NOT NULL,
                    course_code TEXT NOT NULL,
                    assignment_name TEXT NOT NULL,
                    assignment_type TEXT NOT NULL,
                    word_count_min INTEGER,
                    word_count_max INTEGER,
                    references_required INTEGER DEFAULT 0,
                    technical_terms TEXT,
                    allow_collaboration INTEGER DEFAULT 0,
                    created_at TEXT NOT NULL,
                    created_by TEXT,
                    baseline_set INTEGER DEFAULT 0
                );
CREATE TABLE ai_detector_baselines (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    profile_id TEXT UNIQUE NOT NULL,
                    avg_sentence_length REAL,
                    vocabulary_complexity REAL,
                    avg_word_count REAL,
                    samples_analyzed INTEGER,
                    created_at TEXT NOT NULL
                );
CREATE TABLE ai_detector_batch_jobs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    job_id TEXT UNIQUE NOT NULL,
                    job_type TEXT NOT NULL,
                    target_path TEXT NOT NULL,
                    scheduled_time TEXT NOT NULL,
                    notify_email TEXT,
                    status TEXT NOT NULL DEFAULT 'queued',
                    progress INTEGER DEFAULT 0,
                    created_at TEXT NOT NULL,
                    started_at TEXT,
                    completed_at TEXT,
                    result TEXT,
                    error TEXT
                , "course_code" TEXT, "assignment_id" TEXT, "created_by" TEXT, "retries" INTEGER DEFAULT 0);
CREATE TABLE ai_detector_email_alerts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    email TEXT NOT NULL,
                    risk_levels TEXT NOT NULL,
                    include_details INTEGER NOT NULL DEFAULT 1,
                    is_active INTEGER NOT NULL DEFAULT 1,
                    created_at TEXT NOT NULL,
                    created_by TEXT
                );
CREATE TABLE ai_detector_escalations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    escalation_id TEXT UNIQUE NOT NULL,
                    submission_id TEXT NOT NULL,
                    student_id TEXT NOT NULL,
                    violation_type TEXT NOT NULL,
                    summary TEXT NOT NULL,
                    recommended_action TEXT,
                    status TEXT NOT NULL DEFAULT 'pending',
                    escalated_by TEXT,
                    escalated_at TEXT NOT NULL,
                    reviewed_by TEXT,
                    reviewed_at TEXT,
                    resolution TEXT,
                    notes TEXT
                , "ai_result_id" INTEGER, "case_id" INTEGER);
CREATE TABLE ai_detector_metadata (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                time_taken INTEGER,
                browser_info TEXT,
                device_fingerprint TEXT,
                ip_address TEXT,
                location_data TEXT,
                keystroke_data TEXT,
                FOREIGN KEY (submission_id) REFERENCES ai_detector_submissions (id)
            );
CREATE TABLE ai_detector_model_rollbacks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    from_version TEXT,
                    to_version TEXT NOT NULL,
                    reason TEXT,
                    rolled_back_by TEXT,
                    rolled_back_at TEXT NOT NULL
                );
CREATE TABLE ai_detector_model_versions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        version TEXT UNIQUE NOT NULL,
                        model_path TEXT NOT NULL,
                        accuracy REAL,
                        precision_score REAL,
                        recall_score REAL,
                        f1_score REAL,
                        training_samples INTEGER,
                        is_active INTEGER DEFAULT 0,
                        created_at TEXT NOT NULL
                    , "source" TEXT DEFAULT 'trained', "trained_by" TEXT, "sha256" TEXT, "features" TEXT, "metrics" TEXT, "activated_at" TEXT, "note" TEXT);
CREATE TABLE ai_detector_results (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                ai_score REAL NOT NULL,
                confidence REAL NOT NULL,
                detailed_results TEXT,
                created_at TEXT NOT NULL,
                style_deviation REAL, "method" TEXT, "level" TEXT,
                FOREIGN KEY (submission_id) REFERENCES ai_detector_submissions (id)
            );
CREATE TABLE ai_detector_settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE ai_detector_submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                submission_text TEXT NOT NULL,
                title TEXT,
                course_code TEXT,
                assignment_id TEXT,
                submission_date TEXT NOT NULL,
                word_count INTEGER,
                character_count INTEGER,
                institution_id TEXT
            , "assignment_submission_id" INTEGER, "checked_by" TEXT, "file_type" TEXT, "purged" INTEGER DEFAULT 0);
CREATE TABLE ai_federated_updates (
        update_id INTEGER PRIMARY KEY AUTOINCREMENT,
        direction TEXT NOT NULL CHECK (direction IN ('exported', 'imported')),
        institution_id TEXT NOT NULL,
        model_version TEXT,
        features TEXT NOT NULL,
        coef TEXT NOT NULL,
        intercept REAL NOT NULL,
        n_samples INTEGER NOT NULL,
        epsilon REAL,
        sha256 TEXT NOT NULL,
        path TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        used_in_version TEXT
    );
CREATE TABLE ai_feedback_requests (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        assignment_id INTEGER,
                        draft_text TEXT NOT NULL,
                        feedback_json TEXT,
                        requested_at TEXT NOT NULL,
                        completed_at TEXT
                    , "created_at" TEXT, "overall_score" INTEGER);
CREATE TABLE ai_grading_results (
            grading_id INTEGER PRIMARY KEY AUTOINCREMENT,
            submission_id INTEGER NOT NULL,
            assignment_type TEXT NOT NULL,
            auto_score REAL,
            max_score REAL,
            grading_criteria TEXT,
            feedback_generated TEXT,
            confidence_score REAL,
            requires_manual_review BOOLEAN DEFAULT 0,
            manual_override_score REAL,
            graded_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_integration_config (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    service_name TEXT UNIQUE,
                    api_key TEXT,
                    enabled INTEGER DEFAULT 1,
                    last_sync TIMESTAMP,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE ai_model_performance (
            performance_id INTEGER PRIMARY KEY AUTOINCREMENT,
            model_name TEXT NOT NULL,
            model_version TEXT NOT NULL,
            metric_name TEXT NOT NULL,
            metric_value REAL NOT NULL,
            test_dataset TEXT,
            measured_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_plagiarism_checks (
            check_id INTEGER PRIMARY KEY AUTOINCREMENT,
            submission_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            document_text TEXT NOT NULL,
            similarity_score REAL,
            matched_sources TEXT,
            flagged BOOLEAN DEFAULT 0,
            review_status TEXT DEFAULT 'pending',
            checked_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_recommendations (
            recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            recommendation_type TEXT NOT NULL,
            recommendation_content TEXT NOT NULL,
            algorithm_used TEXT,
            confidence_score REAL,
            context_data TEXT,
            was_accepted BOOLEAN,
            feedback_rating INTEGER,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_result_comments (
        comment_id INTEGER PRIMARY KEY AUTOINCREMENT,
        ai_result_id INTEGER NOT NULL,
        author TEXT NOT NULL,
        comment TEXT NOT NULL,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE ai_scheduled_jobs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_type TEXT,
                source_path TEXT,
                scheduled_hour INTEGER,
                scheduled_minute INTEGER,
                status TEXT DEFAULT 'scheduled',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                next_run TIMESTAMP
            );
CREATE TABLE ai_sentiment_analysis (
            analysis_id INTEGER PRIMARY KEY AUTOINCREMENT,
            content_id TEXT NOT NULL,
            content_type TEXT NOT NULL,
            content_text TEXT NOT NULL,
            sentiment_score REAL,
            sentiment_category TEXT,
            emotions_detected TEXT,
            key_phrases TEXT,
            analyzed_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE aid_components (
    component_id INTEGER PRIMARY KEY AUTOINCREMENT,
    package_id INTEGER NOT NULL,
    aid_type TEXT NOT NULL,  -- grant, scholarship, loan, work_study
    source TEXT,  -- federal, state, institutional, private
    name TEXT NOT NULL,
    amount REAL NOT NULL,
    disbursement_plan TEXT,  -- JSON: [{term: 'Fall', amount: 1000}, ...]
    terms_conditions TEXT,
    is_need_based BOOLEAN DEFAULT 0,
    is_renewable BOOLEAN DEFAULT 0,
    status TEXT DEFAULT 'offered',
    FOREIGN KEY (package_id) REFERENCES aid_packages(package_id) ON DELETE CASCADE
);
CREATE TABLE aid_packages (
    package_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    total_aid_amount REAL DEFAULT 0,
    total_grants REAL DEFAULT 0,
    total_scholarships REAL DEFAULT 0,
    total_loans REAL DEFAULT 0,
    total_work_study REAL DEFAULT 0,
    package_status TEXT DEFAULT 'offered',  -- offered, accepted, declined, revised
    offered_date DATE,
    response_deadline DATE,
    response_date DATE,
    created_by INTEGER,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id),
    UNIQUE(student_id, academic_year)
);
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
CREATE TABLE alerts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                alert_type TEXT,
                message TEXT,
                severity TEXT DEFAULT 'medium',
                triggered_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                acknowledged BOOLEAN DEFAULT FALSE,
                resolved BOOLEAN DEFAULT FALSE,
                resolved_at DATETIME,
                user_id TEXT,
                metadata TEXT
            , "alert_id" INTEGER, "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "dismissed_at" TEXT, "expires_at" TEXT, "priority" TEXT DEFAULT 'medium', "read_at" TEXT, "status" TEXT DEFAULT 'active', "target_user_id" INTEGER, "target_user_type" TEXT, "title" TEXT);
CREATE TABLE allergies (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    allergen TEXT,
                    severity TEXT,
                    reaction_description TEXT,
                    diagnosed_date TEXT,
                    provider TEXT,
                    verified INTEGER DEFAULT 0,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE alternative_materials (
    material_id INTEGER PRIMARY KEY AUTOINCREMENT,
    course_id INTEGER NOT NULL,
    original_material_id INTEGER,
    format_type TEXT NOT NULL,  -- braille, audio, large_print, digital
    file_url TEXT,
    created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    created_by INTEGER
);
CREATE TABLE alumni (
            alumni_id TEXT PRIMARY KEY,
            student_id TEXT,
            email_address TEXT,
            title TEXT,
            first_name TEXT,
            middle_name TEXT,
            last_name TEXT,
            gender TEXT,
            dob TEXT,
            graduation_year INTEGER,
            degree_earned TEXT,
            current_employer TEXT,
            job_title TEXT,
            industry TEXT,
            address TEXT,
            city TEXT,
            country TEXT,
            phone TEXT,
            linkedin_url TEXT,
            date_registered TEXT,
            is_donor BOOLEAN,
            is_mentor BOOLEAN,
            is_board_member BOOLEAN,
            profile_photo TEXT,
            bio TEXT,
            skills TEXT,
            achievements TEXT,
            privacy_level INTEGER DEFAULT 1,
            engagement_score INTEGER DEFAULT 0,
            last_activity TEXT,
            social_media_links TEXT,
            is_ambassador BOOLEAN DEFAULT 0, "marketing_consent" INTEGER, "consent_updated_at" TEXT, "consent_source" TEXT, "do_not_contact" INTEGER DEFAULT 0, "email_bounced" INTEGER DEFAULT 0, "deceased_at" TEXT, "anonymised_at" TEXT, "graduate_outcomes_due" TEXT, "updated_at" TEXT, "updated_by" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE alumni_achievements (
            achievement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id TEXT,
            achievement_title TEXT,
            achievement_description TEXT,
            achievement_date TEXT,
            category TEXT,
            verification_status TEXT DEFAULT 'pending',
            verified_by TEXT, "achievement_type" TEXT, "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "date_achieved" TEXT, "is_featured" BOOLEAN DEFAULT 0,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE alumni_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        entity TEXT NOT NULL,
        entity_id TEXT NOT NULL,
        action TEXT NOT NULL,
        actor TEXT,
        detail TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE alumni_badges (
            alumni_badge_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id TEXT,
            badge_id INTEGER,
            earned_date TEXT,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id),
            FOREIGN KEY (badge_id) REFERENCES achievement_badges (badge_id)
        );
CREATE TABLE alumni_chapter_memberships (
            membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter_id INTEGER NOT NULL,
            alumni_id INTEGER NOT NULL,
            join_date TEXT DEFAULT CURRENT_DATE,
            membership_status TEXT DEFAULT 'active',
            FOREIGN KEY (chapter_id) REFERENCES alumni_chapters (chapter_id),
            FOREIGN KEY (alumni_id) REFERENCES alumni_profiles (alumni_id)
        );
CREATE TABLE alumni_chapters (
            chapter_id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter_name TEXT NOT NULL,
            region TEXT NOT NULL,
            chapter_leader_id INTEGER,
            contact_email TEXT,
            description TEXT,
            meeting_frequency TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP, "created_date" TEXT, "location" TEXT,
            FOREIGN KEY (chapter_leader_id) REFERENCES alumni_profiles (alumni_id)
        );
CREATE TABLE alumni_connections (
        connection_id INTEGER PRIMARY KEY AUTOINCREMENT,
        requester_id TEXT NOT NULL,
        recipient_id TEXT NOT NULL,
        status TEXT DEFAULT 'pending',
        message TEXT,
        request_date TEXT DEFAULT (datetime('now')),
        response_date TEXT
    );
CREATE TABLE alumni_content_reports (
        report_id INTEGER PRIMARY KEY AUTOINCREMENT,
        kind TEXT NOT NULL CHECK (kind IN ('forum_post', 'forum_reply', 'story', 'photo')),
        item_id INTEGER NOT NULL,
        reported_by TEXT NOT NULL,
        reason TEXT NOT NULL,
        reported_at TEXT NOT NULL DEFAULT (datetime('now')),
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'upheld', 'dismissed')),
        handled_by TEXT,
        handled_at TEXT
    );
CREATE TABLE alumni_data_requests (
        request_id INTEGER PRIMARY KEY AUTOINCREMENT,
        alumni_id TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('export', 'erasure')),
        requested_by TEXT,
        requested_at TEXT NOT NULL DEFAULT (datetime('now')),
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'completed',
                                                              'refused')),
        completed_by TEXT,
        completed_at TEXT,
        note TEXT
    );
CREATE TABLE alumni_directory_settings (
            alumni_id TEXT PRIMARY KEY,
            show_contact_info BOOLEAN DEFAULT 1,
            show_employment BOOLEAN DEFAULT 1,
            show_education BOOLEAN DEFAULT 1,
            searchable BOOLEAN DEFAULT 1,
            networking_available BOOLEAN DEFAULT 1,
            mentor_available BOOLEAN DEFAULT 0,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE alumni_donations (
            donation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id INTEGER NOT NULL,
            donation_amount REAL NOT NULL,
            donation_date TEXT DEFAULT CURRENT_DATE,
            donation_type TEXT NOT NULL,
            fund_designation TEXT,
            campaign_id INTEGER,
            payment_method TEXT,
            is_recurring BOOLEAN DEFAULT 0,
            recurrence_frequency TEXT,
            tax_receipt_sent BOOLEAN DEFAULT 0,
            acknowledgment_sent BOOLEAN DEFAULT 0, "amount" REAL, "payment_status" TEXT, "purpose" TEXT, "user_id" INTEGER,
            FOREIGN KEY (alumni_id) REFERENCES alumni_profiles (alumni_id)
        );
CREATE TABLE alumni_forum (
            post_id INTEGER PRIMARY KEY AUTOINCREMENT,
            author_id TEXT,
            title TEXT,
            content TEXT,
            category TEXT,
            post_date TEXT,
            last_updated TEXT,
            reply_count INTEGER DEFAULT 0,
            view_count INTEGER DEFAULT 0,
            is_pinned BOOLEAN DEFAULT 0, "hidden_at" TEXT, "hidden_reason" TEXT,
            FOREIGN KEY (author_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE alumni_mentors (
            mentor_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_student_id TEXT NOT NULL,
            job_title TEXT,
            company TEXT,
            industry TEXT,
            expertise_areas TEXT,
            max_mentees INTEGER DEFAULT 3,
            is_active BOOLEAN DEFAULT 1,
            bio TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE alumni_profiles (
            alumni_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL UNIQUE,
            graduation_year INTEGER NOT NULL,
            degree_earned TEXT NOT NULL,
            major TEXT,
            current_employer TEXT,
            current_position TEXT,
            current_industry TEXT,
            current_location TEXT,
            linkedin_url TEXT,
            personal_website TEXT,
            biography TEXT,
            willing_to_mentor BOOLEAN DEFAULT 0,
            willing_to_recruit BOOLEAN DEFAULT 0,
            privacy_level TEXT DEFAULT 'public',
            profile_updated_at TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP, "email" TEXT, "first_name" TEXT, "last_name" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE alumni_roles (
        username TEXT NOT NULL,
        role TEXT NOT NULL CHECK (role IN ('alumni_office', 'fundraising',
                                           'mentoring_coordinator', 'moderator')),
        granted_by TEXT,
        granted_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (username, role)
    );
CREATE TABLE alumni_stories (
            story_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id TEXT,
            title TEXT,
            content TEXT,
            story_type TEXT,
            publish_date TEXT,
            is_featured BOOLEAN DEFAULT 0,
            view_count INTEGER DEFAULT 0,
            category TEXT, "status" TEXT DEFAULT 'published', "consent_at" TEXT, "approved_by" TEXT,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE alumni_transition_steps (
            student_id TEXT NOT NULL, step_name TEXT NOT NULL,
            status TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}',
            completed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY(student_id, step_name)
        );
CREATE TABLE alumni_unsubscribe_tokens (
        token_hash TEXT PRIMARY KEY,
        alumni_id TEXT NOT NULL,
        newsletter_id INTEGER,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        used_at TEXT
    );
CREATE TABLE ambassador_program (
            ambassador_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id TEXT,
            start_date TEXT,
            end_date TEXT,
            status TEXT DEFAULT 'active',
            region TEXT,
            activities TEXT,
            performance_score REAL DEFAULT 0.0,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE analytics_cache (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            cache_key TEXT UNIQUE NOT NULL,
            cache_data TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            expires_at TIMESTAMP NOT NULL
        );
CREATE TABLE analytics_dashboards (
            dashboard_id INTEGER PRIMARY KEY AUTOINCREMENT,
            dashboard_name TEXT NOT NULL,
            dashboard_type TEXT NOT NULL,
            owner_id TEXT NOT NULL,
            is_public BOOLEAN DEFAULT 0,
            layout_config TEXT,
            widget_config TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE analytics_data (
            analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
            metric_name TEXT,
            metric_value REAL,
            metric_date TEXT,
            category TEXT,
            additional_data TEXT
        );
CREATE TABLE analytics_models (
            model_id INTEGER PRIMARY KEY AUTOINCREMENT,
            model_name TEXT NOT NULL,
            model_type TEXT NOT NULL,
            description TEXT,
            model_version TEXT,
            accuracy_score REAL,
            created_date TEXT DEFAULT CURRENT_TIMESTAMP,
            last_trained_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            parameters TEXT
        );
CREATE TABLE analytics_snapshots (
            snapshot_id INTEGER PRIMARY KEY AUTOINCREMENT,
            snapshot_type TEXT NOT NULL,
            snapshot_date TEXT DEFAULT CURRENT_DATE,
            data_json TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE "annotation_templates" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            text TEXT NOT NULL,
            category TEXT DEFAULT 'suggestion',
            created_by INTEGER,
            usage_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE "announcement_reads" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                announcement_id INTEGER,
                parent_id TEXT,
                read_date TEXT,
                acknowledged BOOLEAN DEFAULT 0,
                FOREIGN KEY (announcement_id) REFERENCES school_announcements (id) ON DELETE CASCADE,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
            );
CREATE TABLE "announcement_viewers" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                announcement_id INTEGER NOT NULL,
                viewer_id INTEGER NOT NULL,
                viewed_at TEXT NOT NULL,
                FOREIGN KEY (announcement_id) REFERENCES announcements (id) ON DELETE CASCADE,
                FOREIGN KEY (viewer_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "announcements" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                creator_id INTEGER NOT NULL,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                target_audience TEXT NOT NULL,
                is_urgent INTEGER DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                start_date TEXT NOT NULL,
                end_date TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL, "created_by" INTEGER, "author_id" INTEGER, "module_code" TEXT,
                FOREIGN KEY (creator_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE api_integrations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            integration_name TEXT UNIQUE,
            api_key TEXT,
            endpoint_url TEXT,
            status TEXT DEFAULT 'active',
            last_sync TEXT,
            sync_frequency TEXT DEFAULT 'daily',
            config_data TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE api_keys (
            key_id INTEGER PRIMARY KEY AUTOINCREMENT,
            key_name TEXT NOT NULL,
            api_key TEXT NOT NULL,
            key_hash TEXT NOT NULL,
            permissions TEXT, -- JSON array
            rate_limit INTEGER DEFAULT 1000,
            is_active BOOLEAN DEFAULT 1,
            expires_at TEXT,
            last_used_at TEXT,
            created_by TEXT,
            created_at TEXT
        , "id" INTEGER, "user_id" INTEGER, "created_date" TEXT, "expiry_date" TEXT);
CREATE TABLE api_rate_limits (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                identifier TEXT NOT NULL,
                identifier_type TEXT NOT NULL,
                endpoint TEXT NOT NULL,
                request_count INTEGER DEFAULT 0,
                window_start TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                last_request TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(identifier, identifier_type, endpoint)
            );
CREATE TABLE api_request_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                api_key_id INTEGER,
                user_id INTEGER,
                endpoint TEXT NOT NULL,
                method TEXT NOT NULL,
                ip_address TEXT,
                request_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                response_status INTEGER,
                response_time_ms INTEGER,
                FOREIGN KEY (api_key_id) REFERENCES api_keys(key_id) ON DELETE SET NULL,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
            );
CREATE TABLE api_usage_log (
            usage_id INTEGER PRIMARY KEY AUTOINCREMENT,
            api_key_id INTEGER,
            endpoint TEXT NOT NULL,
            method TEXT NOT NULL,
            ip_address TEXT,
            user_agent TEXT,
            response_status INTEGER,
            response_time_ms INTEGER,
            timestamp TEXT NOT NULL,
            FOREIGN KEY (api_key_id) REFERENCES api_keys (key_id)
        );
CREATE TABLE apl_claims (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    claimant_id TEXT NOT NULL,
                    claimant_name TEXT,
                    target_course TEXT,
                    target_qualification TEXT,
                    claim_type TEXT NOT NULL,
                    summary TEXT,
                    credits_requested INTEGER DEFAULT 0,
                    credits_awarded INTEGER DEFAULT 0,
                    status TEXT DEFAULT 'draft',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    submitted_at TEXT,
                    reviewed_by TEXT,
                    decided_at TEXT,
                    decision_notes TEXT
                );
CREATE TABLE apl_credit_awards (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    claim_id INTEGER NOT NULL,
                    module_code TEXT,
                    module_name TEXT,
                    level INTEGER,
                    credits_awarded INTEGER NOT NULL,
                    grade TEXT,
                    awarded_by TEXT,
                    awarded_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    notes TEXT,
                    FOREIGN KEY (claim_id) REFERENCES apl_claims(id)
                );
CREATE TABLE apl_evidence (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    claim_id INTEGER NOT NULL,
                    evidence_type TEXT,
                    title TEXT NOT NULL,
                    description TEXT,
                    file_path TEXT,
                    issuing_body TEXT,
                    issue_date TEXT,
                    verified INTEGER DEFAULT 0,
                    verified_by TEXT,
                    verified_at TEXT,
                    added_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (claim_id) REFERENCES apl_claims(id)
                );
CREATE TABLE "app_installations" (
                installation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                device_id INTEGER,
                app_version TEXT,
                installation_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                last_active TIMESTAMP, "installed_at" TIMESTAMP, "uninstalled_at" TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (device_id) REFERENCES mobile_devices(device_id) ON DELETE CASCADE
            );
CREATE TABLE application_reviews (
            review_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            reviewer_id TEXT NOT NULL,
            review_stage TEXT NOT NULL,
            score INTEGER,
            recommendation TEXT,
            comments TEXT,
            review_date TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (application_id) REFERENCES admission_applications (application_id)
        );
CREATE TABLE applications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                apprenticeship_id INTEGER NOT NULL,
                application_date TEXT DEFAULT CURRENT_TIMESTAMP,
                status TEXT DEFAULT 'Pending',
                notes TEXT, "employer_id" INTEGER,
                UNIQUE(student_id, apprenticeship_id),
                FOREIGN KEY (student_id) REFERENCES students(student_id) ON DELETE CASCADE,
                FOREIGN KEY (apprenticeship_id) REFERENCES apprenticeships(id) ON DELETE CASCADE
            );
CREATE TABLE appointment_feedback (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        source_table TEXT NOT NULL,
        appointment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        provider_name TEXT,
        rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
        comments TEXT,
        submitted_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (source_table, appointment_id)
    );
