        source_table TEXT NOT NULL,
        appointment_id INTEGER NOT NULL,
        kind TEXT NOT NULL,
        sent_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (source_table, appointment_id, kind)
    );
CREATE TABLE appointment_waitlist (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        appointment_type TEXT NOT NULL,
        provider_name TEXT,
        preferred_from TEXT,
        preferred_to TEXT,
        notes TEXT,
        status TEXT NOT NULL DEFAULT 'waiting'
            CHECK (status IN ('waiting', 'offered', 'booked', 'expired', 'withdrawn')),
        offered_date TEXT,
        offered_time TEXT,
        offered_provider TEXT,
        offered_at TEXT,
        offer_expires_at TEXT,
        booked_appointment_id INTEGER,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE appraisal_cycles (
                    cycle_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    self_review_deadline TEXT,
                    manager_review_deadline TEXT,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE appraisal_goals (
                    goal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    cycle_id INTEGER,
                    title TEXT NOT NULL,
                    description TEXT,
                    category TEXT DEFAULT 'performance',
                    target_date TEXT,
                    progress INTEGER DEFAULT 0,
                    weight REAL DEFAULT 1.0,
                    status TEXT DEFAULT 'active',
                    completion_notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (cycle_id) REFERENCES appraisal_cycles(cycle_id)
                );
CREATE TABLE appraisal_records (
                    appraisal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    cycle_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    reviewer_id TEXT,
                    self_rating REAL,
                    manager_rating REAL,
                    final_rating REAL,
                    self_comments TEXT,
                    manager_comments TEXT,
                    strengths TEXT,
                    areas_for_improvement TEXT,
                    development_plan TEXT,
                    status TEXT DEFAULT 'pending',
                    self_submitted_date TEXT,
                    manager_submitted_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (cycle_id) REFERENCES appraisal_cycles(cycle_id),
                    UNIQUE(cycle_id, user_id)
                );
CREATE TABLE apprenticeships (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                employer_id INTEGER NOT NULL,
                description TEXT,
                duration_months INTEGER NOT NULL,
                salary REAL,
                location TEXT,
                required_course TEXT,
                min_year INTEGER DEFAULT 1,
                positions_available INTEGER DEFAULT 1,
                status TEXT DEFAULT 'Open',
                posted_date TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (employer_id) REFERENCES employers(employer_id) ON DELETE CASCADE
            );
CREATE TABLE approval_committees (
    committee_id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    committee_type TEXT NOT NULL,
    quorum INTEGER NOT NULL,
    active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE approval_requests (
                    request_id TEXT PRIMARY KEY,
                    instance_id INTEGER NOT NULL,
                    workflow_name TEXT NOT NULL,
                    step_id TEXT NOT NULL,
                    step_name TEXT NOT NULL,
