                    context_json TEXT,
                    status TEXT DEFAULT 'pending',
                    created_at TIMESTAMP,
                    due_date TIMESTAMP,
                    decision_at TIMESTAMP,
                    decision_by TEXT,
                    comments TEXT,
                    FOREIGN KEY (instance_id) REFERENCES workflow_instances(instance_id)
                );
CREATE TABLE archive_metadata (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
