                renewal_count INTEGER DEFAULT 0,
                reading_progress INTEGER DEFAULT 0,
                checkout_method TEXT,
                staff_id TEXT,
                notes TEXT,
                archived_at TEXT
            );
CREATE TABLE archived_budget_records (
                    id INTEGER PRIMARY KEY,
                    department TEXT,
                    category TEXT,
                    allocated_amount REAL,
                    spent_amount REAL,
                    fiscal_year TEXT,
                    archived_date TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE archived_financial_aid (
                    id INTEGER PRIMARY KEY,
                    student_id TEXT,
                    aid_type TEXT,
                    amount REAL,
                    academic_year TEXT,
                    status TEXT,
                    awarded_date TEXT,
                    archived_date TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE archived_payments (
                    id INTEGER PRIMARY KEY,
                    student_id TEXT,
                    amount REAL,
                    payment_date TEXT,
                    payment_method TEXT,
                    category TEXT,
                    status TEXT,
                    archived_date TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE archived_transactions (
                    id INTEGER PRIMARY KEY,
                    student_id TEXT,
                    amount REAL,
                    transaction_type TEXT,
                    transaction_date TEXT,
                    description TEXT,
                    payment_method TEXT,
                    status TEXT,
                    archived_date TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE assessment_board_agenda (
    agenda_id INTEGER PRIMARY KEY AUTOINCREMENT,
    board_id INTEGER NOT NULL,
    student_id TEXT NOT NULL,
    programme_code TEXT,
    current_level TEXT,
    credits REAL,
    average_mark REAL,
    proposed_classification TEXT,
    flags TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    UNIQUE(board_id, student_id),
    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)
);
CREATE TABLE assessment_board_corrections (
    correction_id INTEGER PRIMARY KEY AUTOINCREMENT,
    board_id INTEGER NOT NULL,
    decision_id INTEGER,
    reason TEXT NOT NULL,
    requested_by TEXT NOT NULL,
    approved_by TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)
);
CREATE TABLE assessment_board_decisions (
    decision_id INTEGER PRIMARY KEY AUTOINCREMENT,
    board_id INTEGER NOT NULL,
    student_id TEXT NOT NULL,
    module_code TEXT,
    decision_type TEXT NOT NULL,
    original_result TEXT,
    confirmed_result TEXT,
    credits_affected REAL,
    classification TEXT,
    rationale TEXT NOT NULL,
    decided_by TEXT NOT NULL,
    decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    supersedes_decision_id INTEGER,
    UNIQUE(board_id, student_id, module_code, supersedes_decision_id),
    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)
);
CREATE TABLE assessment_board_members (
    board_id INTEGER NOT NULL,
    member_id TEXT NOT NULL,
    role TEXT NOT NULL,
    PRIMARY KEY(board_id, member_id),
    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)
);
CREATE TABLE assessment_board_minutes (
    board_id INTEGER PRIMARY KEY,
    minutes_text TEXT NOT NULL,
    minutes_hash TEXT NOT NULL,
    locked INTEGER NOT NULL DEFAULT 0,
    updated_by TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)
);
CREATE TABLE assessment_board_rules (
    rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
    board_id INTEGER NOT NULL,
    rule_type TEXT NOT NULL,
    minimum_mark REAL,
    maximum_credits REAL,
    exclude_core_modules INTEGER NOT NULL DEFAULT 1,
    notes TEXT,
    active INTEGER NOT NULL DEFAULT 1,
    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)
);
CREATE TABLE assessment_boards (
    board_id INTEGER PRIMARY KEY AUTOINCREMENT,
    board_type TEXT NOT NULL,
    name TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    programme_code TEXT,
    module_code TEXT,
    meeting_at TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    version INTEGER NOT NULL DEFAULT 1,
    chair_id TEXT,
    chair_approved_at TEXT,
    ratified_at TEXT,
    ratified_by TEXT,
    reopened_at TEXT,
    reopened_by TEXT,
    reopen_reason TEXT,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE assessment_competencies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_id INTEGER NOT NULL,
            competency_id INTEGER NOT NULL,
            weight REAL NOT NULL,
            FOREIGN KEY (assessment_id) REFERENCES assessments(assessment_id),
            FOREIGN KEY (competency_id) REFERENCES competencies(competency_id)
        );
CREATE TABLE assessment_outcomes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_id INTEGER NOT NULL,
            outcome_id INTEGER NOT NULL,
            weight REAL NOT NULL,
            FOREIGN KEY (assessment_id) REFERENCES assessments(assessment_id),
            FOREIGN KEY (outcome_id) REFERENCES learning_outcomes(outcome_id)
        );
CREATE TABLE assessments (
            assessment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_name TEXT NOT NULL,
            assessment_type TEXT NOT NULL,
            module_code TEXT NOT NULL,
            max_points REAL NOT NULL,
            weight REAL NOT NULL,
            due_date TEXT,
            date_created TEXT DEFAULT (datetime('now')),
            description TEXT,
            rubric TEXT, duration_minutes INTEGER DEFAULT 0, status TEXT DEFAULT 'Active', updated_at TEXT DEFAULT (datetime('now')), "id" TEXT, [exam_id] INTEGER, "marks_released_at" TEXT, "marks_released_by" TEXT, "anonymous_marking" INTEGER DEFAULT 0, "moderation_required" INTEGER DEFAULT 0, "moderation_sample_pct" REAL DEFAULT 10, "moderation_status" TEXT DEFAULT 'not_started', "reassessment_of" INTEGER, "reassessment_type" TEXT,
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE asset_assignments (
                assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_id INTEGER NOT NULL,
                user_id TEXT NOT NULL,
                user_name TEXT,
                user_department TEXT,
                assigned_by TEXT NOT NULL,
                assigned_by_name TEXT,
                assigned_date TEXT DEFAULT CURRENT_TIMESTAMP,
                expected_return_date TEXT,
                actual_return_date TEXT,
                return_condition TEXT,
                return_notes TEXT,
                return_processed_by TEXT,
                status TEXT DEFAULT 'active',
                purpose TEXT,
                location TEXT,
                acknowledgement_date TEXT,
                acknowledgement_signature TEXT,
                checkout_notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (asset_id) REFERENCES assets(asset_id)
            );
CREATE TABLE asset_audit_log (
                log_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_id INTEGER NOT NULL,
                action TEXT NOT NULL,
                action_category TEXT,
                action_by TEXT NOT NULL,
                action_by_name TEXT,
                action_date TEXT DEFAULT CURRENT_TIMESTAMP,
                old_values TEXT,
                new_values TEXT,
                field_changed TEXT,
                ip_address TEXT,
                user_agent TEXT,
                session_id TEXT,
                notes TEXT,
                FOREIGN KEY (asset_id) REFERENCES assets(asset_id)
            );
CREATE TABLE asset_categories (
                category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL UNIQUE,
                description TEXT,
                depreciation_years INTEGER DEFAULT 5,
                requires_approval INTEGER DEFAULT 0,
                parent_category_id INTEGER,
                is_active INTEGER DEFAULT 1,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (parent_category_id) REFERENCES asset_categories(category_id)
            );
CREATE TABLE asset_depreciation (
                depreciation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_id INTEGER NOT NULL,
                fiscal_year TEXT NOT NULL,
                period TEXT,
                depreciation_method TEXT DEFAULT 'straight-line',
                beginning_value REAL,
                depreciation_amount REAL,
                accumulated_depreciation REAL,
                ending_value REAL,
                calculated_date TEXT DEFAULT CURRENT_TIMESTAMP,
                notes TEXT,
                FOREIGN KEY (asset_id) REFERENCES assets(asset_id),
                UNIQUE(asset_id, fiscal_year, period)
            );
CREATE TABLE asset_issues (
                issue_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_id INTEGER NOT NULL,
                reported_by TEXT NOT NULL,
                reported_by_name TEXT,
                reported_date TEXT DEFAULT CURRENT_TIMESTAMP,
                issue_type TEXT NOT NULL,
                severity TEXT DEFAULT 'medium',
                priority TEXT DEFAULT 'normal',
                title TEXT NOT NULL,
                description TEXT NOT NULL,
                impact TEXT,
                steps_to_reproduce TEXT,
                resolution TEXT,
                resolution_notes TEXT,
                resolved_by TEXT,
                resolved_by_name TEXT,
                resolved_date TEXT,
                resolution_cost REAL,
                status TEXT DEFAULT 'open',
                assigned_to TEXT,
                assigned_to_name TEXT,
                estimated_resolution_date TEXT,
                attachments TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (asset_id) REFERENCES assets(asset_id)
            );
CREATE TABLE asset_maintenance (
                maintenance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_id INTEGER NOT NULL,
                maintenance_type TEXT NOT NULL,
                maintenance_category TEXT DEFAULT 'routine',
                title TEXT,
                description TEXT,
                scheduled_date TEXT,
                scheduled_time TEXT,
                completed_date TEXT,
                performed_by TEXT,
                performed_by_name TEXT,
                vendor TEXT,
                vendor_contact TEXT,
                cost REAL DEFAULT 0,
                labor_cost REAL DEFAULT 0,
                parts_cost REAL DEFAULT 0,
                parts_replaced TEXT,
                work_performed TEXT,
                findings TEXT,
                recommendations TEXT,
                next_maintenance_date TEXT,
                next_maintenance_type TEXT,
                status TEXT DEFAULT 'scheduled',
                priority TEXT DEFAULT 'normal',
                downtime_hours REAL DEFAULT 0,
                attachments TEXT,
                approval_required INTEGER DEFAULT 0,
                approved_by TEXT,
                approved_date TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (asset_id) REFERENCES assets(asset_id)
            );
CREATE TABLE asset_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                requested_by TEXT NOT NULL,
                requested_by_name TEXT,
                department TEXT,
                category_id INTEGER,
                request_type TEXT DEFAULT 'new',
                item_name TEXT NOT NULL,
                item_description TEXT,
                quantity INTEGER DEFAULT 1,
                preferred_vendor TEXT,
                estimated_cost REAL,
                budget_code TEXT,
                justification TEXT,
                business_case TEXT,
                urgency TEXT DEFAULT 'normal',
                needed_by_date TEXT,
                status TEXT DEFAULT 'pending',
                reviewed_by TEXT,
                reviewed_by_name TEXT,
                review_date TEXT,
                review_comments TEXT,
                approved_by TEXT,
                approved_by_name TEXT,
                approved_date TEXT,
                rejection_reason TEXT,
                approved_amount REAL,
                fulfilled_date TEXT,
                fulfilled_asset_ids TEXT,
                attachments TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (category_id) REFERENCES asset_categories(category_id)
            );
CREATE TABLE asset_transfers (
                transfer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_id INTEGER NOT NULL,
                from_location TEXT,
                from_department TEXT,
                from_user_id TEXT,
                to_location TEXT,
                to_department TEXT,
                to_user_id TEXT,
                transfer_date TEXT DEFAULT CURRENT_TIMESTAMP,
                transfer_reason TEXT,
                transferred_by TEXT NOT NULL,
                transferred_by_name TEXT,
                received_by TEXT,
                received_date TEXT,
                condition_at_transfer TEXT,
                status TEXT DEFAULT 'pending',
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (asset_id) REFERENCES assets(asset_id)
            );
CREATE TABLE assets (
                asset_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_tag TEXT UNIQUE NOT NULL,
                name TEXT NOT NULL,
                description TEXT,
                category_id INTEGER NOT NULL,
                serial_number TEXT,
                manufacturer TEXT,
                model TEXT,
                purchase_date TEXT,
                purchase_price REAL,
                supplier TEXT,
                warranty_start TEXT,
                warranty_expiry TEXT,
                warranty_provider TEXT,
                current_value REAL,
                location TEXT,
                building TEXT,
                room TEXT,
                department TEXT,
                status TEXT DEFAULT 'available',
                condition TEXT DEFAULT 'good',
                last_inspection_date TEXT,
                next_inspection_date TEXT,
                disposal_date TEXT,
                disposal_method TEXT,
                disposal_value REAL,
                insurance_policy TEXT,
                insurance_value REAL,
                barcode TEXT,
                qr_code TEXT,
                image_path TEXT,
                notes TEXT,
                created_by TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (category_id) REFERENCES asset_categories(category_id)
            );
CREATE TABLE assignment_candidate_numbers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        assignment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        candidate_number TEXT NOT NULL,
        created_at TEXT NOT NULL,
        UNIQUE (assignment_id, student_id),
        UNIQUE (assignment_id, candidate_number),
        FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE
    );
CREATE TABLE assignment_drafts (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id INTEGER NOT NULL,
                        draft_data TEXT NOT NULL,
                        created_at TEXT NOT NULL,
                        updated_at TEXT NOT NULL
                    , draft_name TEXT);
CREATE TABLE assignment_late_policies (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        assignment_id INTEGER NOT NULL,
                        policy_id INTEGER NOT NULL,
                        applied_at TEXT NOT NULL DEFAULT (datetime('now')), "applied_by" TEXT, "applied_date" TEXT,
                        FOREIGN KEY (policy_id) REFERENCES late_policies(id)
                    );
CREATE TABLE assignment_marker_allocations (
        assignment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        marker_username TEXT NOT NULL,
        allocated_by TEXT,
        allocated_at TEXT NOT NULL,
        PRIMARY KEY (assignment_id, student_id),
        FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE
    );
CREATE TABLE assignment_moderation (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        assignment_id INTEGER NOT NULL,
        submission_id INTEGER NOT NULL UNIQUE,
        first_mark REAL,
        first_marker TEXT,
        second_mark REAL,
        second_marker TEXT,
        agreed_mark REAL,
        agreed_by TEXT,
        notes TEXT,
        status TEXT NOT NULL DEFAULT 'sampled',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE,
        FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE
    );
CREATE TABLE assignment_non_submissions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        assignment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        code TEXT NOT NULL DEFAULT 'NS',
        recorded_at TEXT NOT NULL,
        recorded_by TEXT,
        voided INTEGER NOT NULL DEFAULT 0,
        UNIQUE (assignment_id, student_id),
        FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE
    );
CREATE TABLE assignment_reassessments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        original_assignment_id INTEGER NOT NULL,
        reassessment_assignment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        attempt_type TEXT NOT NULL,
        mark_cap_pct REAL,
        mc_claim_id INTEGER,
        created_at TEXT NOT NULL,
        created_by TEXT,
        UNIQUE (reassessment_assignment_id, student_id),
        FOREIGN KEY (original_assignment_id) REFERENCES assignments (id) ON DELETE CASCADE,
        FOREIGN KEY (reassessment_assignment_id) REFERENCES assignments (id) ON DELETE CASCADE
    );
CREATE TABLE assignment_reminders_sent (
        assignment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        sent_at TEXT NOT NULL,
        PRIMARY KEY (assignment_id, student_id),
        FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE
    );
CREATE TABLE assignment_stages (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        assignment_id INTEGER NOT NULL,
                        stage_number INTEGER NOT NULL,
                        stage_name TEXT NOT NULL,
                        description TEXT,
                        weight_percent REAL NOT NULL DEFAULT 0,
                        deadline TEXT NOT NULL,
                        feedback_required INTEGER NOT NULL DEFAULT 1,
                        created_at TEXT NOT NULL DEFAULT (datetime('now'))
                    , "stage_order" INTEGER);
CREATE TABLE "assignment_submissions" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assignment_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            submission_date TIMESTAMP NOT NULL,
            file_path TEXT,
            file_name TEXT NOT NULL,
            file_size INTEGER,
            file_hash TEXT,
            status TEXT DEFAULT 'submitted',
            grade REAL,
            feedback TEXT,
            late_submission BOOLEAN DEFAULT 0,
            late_days INTEGER DEFAULT 0,
            version_number INTEGER DEFAULT 1,
            is_final_submission BOOLEAN DEFAULT 1,
            graded_by INTEGER,
            graded_date TIMESTAMP, group_id INTEGER, ip_address TEXT, "submitted_at" TEXT, "graded_at" TEXT, "version" INTEGER, "comments" TEXT, "content" TEXT, "raw_grade" REAL, "word_count" INTEGER, "word_penalty_pct" REAL, "capped" INTEGER DEFAULT 0, "grade_released_at" TEXT, "misconduct_penalty" TEXT, "misconduct_case_id" INTEGER, "declaration_at" TEXT, "virus_scan" TEXT, "withdrawn_at" TEXT,
            FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (graded_by) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE "assignment_templates" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                template_data TEXT NOT NULL,
                category TEXT,
                created_by INTEGER,
                created_at TEXT NOT NULL,
                is_active INTEGER DEFAULT 1,
                usage_count INTEGER DEFAULT 0, "template_name" TEXT, "updated_at" TEXT,
                FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "assignments" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_code TEXT NOT NULL,
            title TEXT NOT NULL,
            description TEXT,
            instructions TEXT,
            due_date TIMESTAMP NOT NULL,
            max_marks INTEGER NOT NULL,
            file_types_allowed TEXT,
            max_file_size_mb INTEGER DEFAULT 10,
            assignment_type TEXT DEFAULT 'individual',
            group_size_min INTEGER DEFAULT 1,
            group_size_max INTEGER DEFAULT 1,
            allow_late_submission BOOLEAN DEFAULT 1,
            late_penalty_per_day REAL DEFAULT 0,
            auto_release_grades BOOLEAN DEFAULT 0,
            peer_review_enabled BOOLEAN DEFAULT 0,
            rubric_id INTEGER,
            is_active BOOLEAN DEFAULT 1,
            created_by INTEGER NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, archived INTEGER DEFAULT 0, template_id INTEGER, status TEXT DEFAULT 'active', "module_id" TEXT, "assignment_name" TEXT, "course_name" TEXT, "duration_minutes" TEXT, "max_score" INTEGER, "time_limit" TEXT, "assessment_kind" TEXT DEFAULT 'summative', "module_weight_pct" REAL, "anonymous_marking" INTEGER DEFAULT 0, "word_limit" INTEGER, "word_limit_tolerance_pct" REAL DEFAULT 10, "word_limit_penalty_pct" REAL DEFAULT 10, "feedback_due_date" TEXT, "grade_release_date" TEXT, "moderation_required" INTEGER DEFAULT 0, "moderation_sample_pct" REAL DEFAULT 10, "moderation_status" TEXT DEFAULT 'not_started', "grades_released_at" TEXT, "grades_released_by" TEXT, "reassessment_of" INTEGER, "reassessment_type" TEXT, "available_from" TEXT, "max_late_days" INTEGER, "max_attempts" INTEGER, "automatic_checks" INTEGER DEFAULT 1, "notify_on_submission" INTEGER DEFAULT 1, "reminder_days" INTEGER DEFAULT 2, "announced_at" TEXT,
            FOREIGN KEY (module_code) REFERENCES modules (module_code),
            FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE assistive_tech_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    technology_type TEXT NOT NULL,  -- screen_reader, magnifier, etc.
    status TEXT DEFAULT 'pending',
    requested_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fulfilled_date TIMESTAMP, "justification" TEXT,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE atas_clearances (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            module_code TEXT,
            certificate_number TEXT,
            issued_on TEXT,
            expires_on TEXT,
            status TEXT NOT NULL DEFAULT 'pending',
            notes TEXT,
            recorded_at TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE attendance_alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            alert_id TEXT UNIQUE,
            student_id TEXT,
            module_code TEXT,
            alert_type TEXT,
            severity TEXT,
            message TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            sent_at TEXT,
            acknowledged_at TEXT,
            status TEXT DEFAULT 'pending',
            recipient_email TEXT,
            recipient_phone TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE attendance_analytics (
            analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            attendance_percentage REAL,
            consecutive_absences INTEGER
        , "attended_sessions" INTEGER DEFAULT 0, "last_updated" TEXT DEFAULT CURRENT_TIMESTAMP, "late_arrivals" INTEGER DEFAULT 0, "module_code" TEXT, "total_sessions" INTEGER DEFAULT 0);
CREATE TABLE attendance_anomalies (
         id INTEGER PRIMARY KEY AUTOINCREMENT,
         kind TEXT NOT NULL,
         student_id TEXT, module_code TEXT, details TEXT,
         severity TEXT DEFAULT 'medium',
         detected_at TEXT DEFAULT CURRENT_TIMESTAMP,
         resolved INTEGER DEFAULT 0
       );
CREATE TABLE attendance_appeals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            appeal_id TEXT UNIQUE,
            student_id TEXT,
            module_code TEXT,
            attendance_record_id INTEGER,
            original_status TEXT,
            requested_status TEXT,
            reason TEXT,
            evidence_files TEXT,
            submitted_at TEXT DEFAULT CURRENT_TIMESTAMP,
            reviewed_by TEXT,
            reviewed_at TEXT,
            decision TEXT,
            decision_reason TEXT,
            status TEXT DEFAULT 'pending',
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code),
            FOREIGN KEY (attendance_record_id) REFERENCES attendance_records (id)
        );
CREATE TABLE attendance_audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            action TEXT,
            table_name TEXT,
            record_id TEXT,
            old_values TEXT,
            new_values TEXT,
            timestamp TEXT DEFAULT CURRENT_TIMESTAMP,
            ip_address TEXT,
            user_agent TEXT
        );
CREATE TABLE "attendance_calendar_links" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                attendance_record_id INTEGER,
                event_id TEXT,
                module_code TEXT,
                date TEXT,
                created_at TEXT,
                FOREIGN KEY (attendance_record_id) REFERENCES attendance_records (id),
                FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id)
            );
CREATE TABLE attendance_events (
            attendance_event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_enrolment_id INTEGER NOT NULL,
            session_id TEXT NOT NULL,
            student_id TEXT NOT NULL,
            occurred_at TEXT NOT NULL,
            status TEXT NOT NULL CHECK (
                status IN ('present', 'late', 'absent', 'authorised', 'unknown')
            ),
            source TEXT NOT NULL,
            recorded_by TEXT,
            recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            supersedes_event_id INTEGER,
            reason TEXT,
            UNIQUE (module_enrolment_id, session_id, recorded_at),
            FOREIGN KEY (module_enrolment_id)
                REFERENCES module_enrolments(module_enrolment_id),
            FOREIGN KEY (supersedes_event_id)
                REFERENCES attendance_events(attendance_event_id)
        );
CREATE TABLE attendance_gamification (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            points INTEGER DEFAULT 0,
            level INTEGER DEFAULT 1,
            badges TEXT,
            achievements TEXT,
            streak_days INTEGER DEFAULT 0,
            best_streak INTEGER DEFAULT 0,
            last_attendance_date TEXT,
            total_rewards INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE attendance_grade_config (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        module_code TEXT NOT NULL UNIQUE,
                        attendance_weight REAL NOT NULL DEFAULT 10.0,
                        min_attendance_pct REAL NOT NULL DEFAULT 75.0,
                        created_by TEXT,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE attendance_grade_penalties (
            id           INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id   TEXT NOT NULL,
            module_code  TEXT NOT NULL,
            threshold    REAL,
            pct          REAL,
            applied_at   TEXT DEFAULT CURRENT_TIMESTAMP,
            applied_by   TEXT,
            grade_row_id INTEGER,
            UNIQUE(student_id, module_code)
        );
CREATE TABLE attendance_kiosks (
         kiosk_id TEXT PRIMARY KEY,
         room TEXT, lat REAL, lon REAL,
         radius_m REAL DEFAULT 50,
         active INTEGER DEFAULT 1
       );
CREATE TABLE attendance_notifications (
            notification_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            session_id TEXT NOT NULL,
            recipient_type TEXT NOT NULL,
            recipient_email TEXT NOT NULL,
            notification_type TEXT NOT NULL,
            sent_at TEXT DEFAULT CURRENT_TIMESTAMP,
            is_read BOOLEAN DEFAULT 0, "module_code" TEXT, "status" TEXT DEFAULT 'sent', "id" INTEGER,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (session_id) REFERENCES attendance_sessions (session_id)
        );
CREATE TABLE attendance_policies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            policy_id TEXT UNIQUE,
            name TEXT,
            description TEXT,
            module_code TEXT,
            course TEXT,
            min_attendance_percentage REAL,
            max_consecutive_absences INTEGER,
            late_tolerance_minutes INTEGER DEFAULT 15,
            makeup_allowed BOOLEAN DEFAULT 1,
            auto_fail_threshold REAL,
            grace_period_days INTEGER DEFAULT 0,
            effective_from TEXT,
            effective_until TEXT,
            created_by TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'active'
        , "policy_key" TEXT, "policy_value" TEXT);
CREATE TABLE attendance_predictions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            prediction_date TEXT,
            predicted_attendance_rate REAL,
            risk_level TEXT,
            confidence_score REAL,
            factors TEXT,
            recommendations TEXT,
            model_version TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE "attendance_records" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT,
    module_code TEXT,
    date TEXT,
    status TEXT COLLATE NOCASE,
    notes TEXT,
    reason TEXT,
    recorded_by TEXT,
    recorded_at TEXT,
    check_in_method TEXT DEFAULT 'manual',
    location_data TEXT,
    ip_address TEXT,
    session_id TEXT,
    makeup_for_date TEXT,
    verification_status TEXT,
    record_id INTEGER,
    latitude REAL,
    longitude REAL,
    device_id TEXT,
    facial_recognition_confidence REAL,
    check_in_time TEXT,
    departure_time TEXT,
    FOREIGN KEY (student_id) REFERENCES students (student_id)
);
CREATE TABLE attendance_sessions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            session_id TEXT UNIQUE,
            module_code TEXT,
            date TEXT,
            start_time TEXT,
            end_time TEXT,
            location_name TEXT,
            latitude REAL,
            longitude REAL,
            geofence_radius INTEGER DEFAULT 50,
            qr_code_data TEXT,
            qr_code_expires TEXT,
            session_type TEXT DEFAULT 'lecture',
            max_capacity INTEGER,
            created_by TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'active', "beacon_id" TEXT, "geofence_latitude" REAL, "geofence_longitude" REAL, "geofence_radius_meters" INTEGER DEFAULT 50, "location" TEXT, "qr_code" TEXT, "qr_code_expires_at" TEXT, "require_facial_recognition" BOOLEAN DEFAULT 0, "session_date" TEXT, "session_time" TEXT, "notes" TEXT,
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE attendance_settings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            setting_name TEXT UNIQUE,
            setting_value TEXT,
            description TEXT,
            category TEXT DEFAULT 'general',
            data_type TEXT DEFAULT 'string',
            last_modified TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE attendees (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    email TEXT,
                    phone_number TEXT,
                    student_id TEXT,
                    created_at TEXT NOT NULL
                );
CREATE TABLE audit_log (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            action TEXT NOT NULL,
            table_name TEXT,
            record_id TEXT,
            old_values TEXT, -- JSON
            new_values TEXT, -- JSON
            ip_address TEXT,
            user_agent TEXT,
            session_id TEXT,
            timestamp TEXT NOT NULL
        , accommodation_id INTEGER, details TEXT, "success" BOOLEAN, "table_affected" TEXT, "operation" TEXT, "entity_type" TEXT, "new_value" TEXT, "old_value" TEXT, "user_name" TEXT, "user_type" TEXT);
CREATE TABLE audit_trail (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    action TEXT NOT NULL,
                    resource_type TEXT NOT NULL,
                    resource_id TEXT,
                    user_id INTEGER,
                    username TEXT,
                    ip_address TEXT,
                    details TEXT,
                    function_name TEXT,
                    module_name TEXT,
                    success INTEGER DEFAULT 1,
                    error_message TEXT,
                    data_hash TEXT
                , old_values TEXT, new_values TEXT, user_agent TEXT, duration REAL, "audit_id" INTEGER, "table_name" TEXT);
CREATE TABLE authorized_pickup (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        name TEXT NOT NULL,
                        relationship TEXT,
                        phone TEXT,
                        id_number TEXT,
                        photo_on_file INTEGER DEFAULT 0,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE backup_history (
                    id TEXT PRIMARY KEY,
                    backup_type TEXT NOT NULL,
                    file_path TEXT NOT NULL,
                    file_size INTEGER,
                    backup_time TEXT NOT NULL,
                    status TEXT NOT NULL,
                    notes TEXT
                , "created_at" TEXT, "size_bytes" INTEGER, "backup_filename" TEXT, "backup_size_mb" REAL, "created_by" TEXT, "timestamp" TIMESTAMP);
CREATE TABLE backup_log (
                    log_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_type TEXT,
                    filename TEXT,
                    file_size_mb REAL,
                    event_time DATETIME DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE backups (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                backup_name TEXT,
                backup_path TEXT,
                backup_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                backup_size INTEGER,
                description TEXT
            );
CREATE TABLE badge_definitions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT UNIQUE NOT NULL,
                    description TEXT,
                    category TEXT DEFAULT 'academic',
                    icon_name TEXT,
                    criteria TEXT,
                    points INTEGER DEFAULT 0,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE badge_issuances (
    issuance_id INTEGER PRIMARY KEY AUTOINCREMENT,
    badge_id INTEGER NOT NULL,
    student_id TEXT NOT NULL,
    issued_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    blockchain_hash TEXT,
    evidence_url TEXT,
    expires_at DATE,
    is_revoked BOOLEAN DEFAULT 0,
    FOREIGN KEY (badge_id) REFERENCES digital_badges(badge_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE badge_progress (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    badge_id INTEGER NOT NULL,
                    current_progress INTEGER DEFAULT 0,
                    target_progress INTEGER DEFAULT 100,
                    last_updated TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (badge_id) REFERENCES badge_definitions(id)
                );
CREATE TABLE "badges" (
                            badge_id INTEGER PRIMARY KEY AUTOINCREMENT,
                            student_id TEXT NOT NULL,
                            badge_type TEXT NOT NULL CHECK(badge_type IN (
                                'deans_list', 'club_officer', 'volunteer_hours',
                                'certification', 'competition_winner', 'scholarship',
                                'research_publication', 'leadership', 'academic_excellence',
                                'community_service', 'skill_mastery', 'innovation'
                            )),
                            badge_name TEXT NOT NULL,
                            description TEXT,
                            issuer TEXT NOT NULL,
                            issue_date DATE NOT NULL,
                            expiry_date DATE,
                            verification_status TEXT DEFAULT 'verified' CHECK(verification_status IN (
                                'pending', 'verified', 'expired', 'revoked'
                            )),
                            verification_code TEXT,
                            metadata TEXT,
                            icon_url TEXT,
                            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                        );
CREATE TABLE bakery_app_flags (
                    flag TEXT PRIMARY KEY,
                    value TEXT,
                    updated_at TEXT,
                    updated_by TEXT
                );
CREATE TABLE bakery_batches (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_name TEXT NOT NULL,
                    quantity INTEGER NOT NULL,
                    initial_quantity INTEGER,
                    expiry_date TEXT NOT NULL,
                    received_date TEXT,
                    lot_number TEXT,
                    supplier_id INTEGER,
                    po_id INTEGER,
                    status TEXT DEFAULT 'active'   -- active / expired / depleted
                );
CREATE TABLE bakery_billing_codes (
                    code TEXT PRIMARY KEY,
                    department TEXT,
                    contact TEXT,
                    contact_email TEXT,
                    active INTEGER DEFAULT 1,
                    created_at TEXT
                );
CREATE TABLE bakery_birthday_claims (
                    user TEXT NOT NULL,
                    year INTEGER NOT NULL,
                    claimed_at TEXT,
                    PRIMARY KEY (user, year)
                );
CREATE TABLE bakery_breaks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    shift_id INTEGER,
                    staff TEXT NOT NULL,
                    started_at TEXT NOT NULL,
                    ended_at TEXT,
                    kind TEXT DEFAULT 'break',     -- break / meal
                    notes TEXT
                );
CREATE TABLE bakery_bulk_orders (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user TEXT NOT NULL,
                    department TEXT,
                    billing_code TEXT,
                    items_json TEXT NOT NULL,
                    event_date TEXT NOT NULL,
                    event_location TEXT,
                    attendees INTEGER,
                    total REAL,
                    status TEXT DEFAULT 'submitted',
                    notes TEXT,
                    created_at TEXT,
                    updated_at TEXT
                );
CREATE TABLE bakery_campus_card_txns (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    card_id TEXT NOT NULL,
                    txn_type TEXT NOT NULL,      -- spend / topup / swipe
                    amount REAL,
                    swipes INTEGER DEFAULT 0,
                    order_id TEXT,
                    timestamp TEXT
                );
CREATE TABLE bakery_campus_cards (
                    card_id TEXT PRIMARY KEY,
                    user TEXT,
                    balance REAL DEFAULT 0,
                    meal_swipes INTEGER DEFAULT 0,
                    active INTEGER DEFAULT 1,
                    created_at TEXT,
                    updated_at TEXT
                );
CREATE TABLE bakery_cash_drawer (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    opened_at TEXT NOT NULL,
                    opening_float REAL NOT NULL,
                    closed_at TEXT,
                    closing_amount REAL,
                    expected_amount REAL,
                    variance REAL,
                    operator TEXT,
                    status TEXT DEFAULT 'open',  -- open / closed
                    notes TEXT
                );
CREATE TABLE bakery_catering_trays (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT UNIQUE NOT NULL,
                    description TEXT,
                    items_json TEXT NOT NULL,    -- {"item": qty, ...}
                    serves INTEGER,
                    price REAL NOT NULL,
                    active INTEGER DEFAULT 1,
                    created_at TEXT
                );
CREATE TABLE bakery_checklist_runs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    checklist_id INTEGER NOT NULL,
                    run_date TEXT NOT NULL,
