                , payment_method TEXT, refunded INTEGER DEFAULT 0, refund_ref TEXT, refund_timestamp TEXT, promo_code TEXT, loyalty_earned INTEGER DEFAULT 0, loyalty_redeemed INTEGER DEFAULT 0, discount_breakdown_json TEXT, tip_amount REAL DEFAULT 0, vat_amount REAL DEFAULT 0, split_payments_json TEXT, billing_code TEXT, gift_card_code TEXT);
CREATE TABLE bakery_oven_timers (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
