                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    item_name TEXT NOT NULL,
                    expected_qty INTEGER NOT NULL,
                    actual_qty INTEGER NOT NULL,
