                    notes TEXT
                );
CREATE TABLE bank_statement_lines (
            line_id            INTEGER PRIMARY KEY AUTOINCREMENT,
            statement_id       INTEGER NOT NULL REFERENCES bank_statements(statement_id) ON DELETE CASCADE,
            line_no            INTEGER NOT NULL,
            txn_date           TEXT    NOT NULL,
            amount             REAL    NOT NULL,
            description        TEXT,
            reference          TEXT,
            status             TEXT    NOT NULL DEFAULT 'unmatched'
                                CHECK (status IN ('unmatched','matched_auto','matched_manual','discarded')),
            matched_payment_id INTEGER,
            matched_refund_id  INTEGER,
            matched_at         TEXT,
            matched_by         TEXT,
            notes              TEXT
        );
CREATE TABLE bank_statements (
            statement_id    INTEGER PRIMARY KEY AUTOINCREMENT,
            account_name    TEXT    NOT NULL,
            period_start    TEXT,
            period_end      TEXT,
            opening_balance REAL,
            closing_balance REAL,
            imported_at     TEXT    NOT NULL DEFAULT (datetime('now')),
            imported_by     TEXT,
            source_file     TEXT
        );
CREATE TABLE barber_appointments (
                appointment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                appointment_number TEXT UNIQUE NOT NULL,
                customer_id TEXT NOT NULL,
                customer_name TEXT NOT NULL,
                customer_email TEXT,
                customer_phone TEXT,
                staff_id INTEGER,
                staff_name TEXT,
                service_id INTEGER NOT NULL,
                service_name TEXT NOT NULL,
                appointment_date TEXT NOT NULL,
                appointment_time TEXT NOT NULL,
                duration_minutes INTEGER DEFAULT 30,
                price DECIMAL(10,2) NOT NULL,
                status TEXT DEFAULT 'scheduled',
                payment_status TEXT DEFAULT 'pending',
                payment_method TEXT,
                special_requests TEXT,
                notes TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "booking_ref" TEXT, "user_email" TEXT, "user_id" TEXT, "user_name" TEXT, "service_type" TEXT, "cancellation_reason" TEXT,
                FOREIGN KEY (staff_id) REFERENCES barber_staff(staff_id),
                FOREIGN KEY (service_id) REFERENCES barber_services(service_id)
            );
CREATE TABLE barber_audit_log (
                log_id INTEGER PRIMARY KEY AUTOINCREMENT,
                action_type TEXT NOT NULL,
                entity_type TEXT NOT NULL,
                entity_id TEXT,
                details TEXT,
                user_id TEXT,
                ip_address TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE barber_blocked_slots (
                block_id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_id INTEGER NOT NULL,
                blocked_date TEXT NOT NULL,
                start_time TEXT NOT NULL,
                end_time TEXT NOT NULL,
                reason TEXT,
                blocked_by TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (staff_id) REFERENCES barber_staff(staff_id)
            );
CREATE TABLE barber_cash_drawer (
                drawer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                opening_amount DECIMAL(10,2) NOT NULL,
                closing_amount DECIMAL(10,2),
                expected_amount DECIMAL(10,2),
                discrepancy DECIMAL(10,2),
                opened_by TEXT NOT NULL,
                closed_by TEXT,
                opened_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                closed_at TEXT,
                notes TEXT,
                status TEXT DEFAULT 'open'
            );
