                profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id TEXT UNIQUE NOT NULL,
                name TEXT NOT NULL,
                email TEXT,
                phone TEXT,
                preferences TEXT,
                allergies TEXT,
                notes TEXT,
                is_vip INTEGER DEFAULT 0,
                total_visits INTEGER DEFAULT 0,
                total_spent DECIMAL(10,2) DEFAULT 0,
                no_show_count INTEGER DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE barber_discounts (
                discount_id INTEGER PRIMARY KEY AUTOINCREMENT,
                appointment_id INTEGER NOT NULL,
                discount_type TEXT NOT NULL,
                value DECIMAL(10,2) NOT NULL,
                original_price DECIMAL(10,2) NOT NULL,
                final_price DECIMAL(10,2) NOT NULL,
                reason TEXT,
                applied_by TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (appointment_id) REFERENCES barber_appointments(appointment_id)
            );
CREATE TABLE barber_feedback (
                feedback_id INTEGER PRIMARY KEY AUTOINCREMENT,
                appointment_id INTEGER,
                customer_id TEXT NOT NULL,
                staff_id INTEGER,
                rating INTEGER NOT NULL,
                comment TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (appointment_id) REFERENCES barber_appointments(appointment_id)
            );
CREATE TABLE barber_gift_card_redemptions (
                redemption_id INTEGER PRIMARY KEY AUTOINCREMENT,
                gift_card_id INTEGER NOT NULL,
                amount DECIMAL(10,2) NOT NULL,
                appointment_id INTEGER,
                redeemed_by TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (gift_card_id) REFERENCES barber_gift_cards(gift_card_id)
            );
CREATE TABLE barber_gift_cards (
                gift_card_id INTEGER PRIMARY KEY AUTOINCREMENT,
                code TEXT UNIQUE NOT NULL,
                initial_amount DECIMAL(10,2) NOT NULL,
                current_balance DECIMAL(10,2) NOT NULL,
                purchased_by TEXT,
                recipient_name TEXT,
                recipient_email TEXT,
                message TEXT,
                is_redeemed INTEGER DEFAULT 0,
                redeemed_at TEXT,
                expires_at TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE barber_no_shows (
                no_show_id INTEGER PRIMARY KEY AUTOINCREMENT,
                appointment_id INTEGER NOT NULL,
                customer_id TEXT NOT NULL,
                marked_by TEXT,
                added_to_watchlist INTEGER DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (appointment_id) REFERENCES barber_appointments(appointment_id)
            );
CREATE TABLE barber_recurring_appointments (
                recurring_id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id TEXT NOT NULL,
                customer_name TEXT NOT NULL,
                customer_email TEXT,
                service_id INTEGER NOT NULL,
                staff_id INTEGER,
                day_of_week INTEGER NOT NULL,
                appointment_time TEXT NOT NULL,
                frequency TEXT DEFAULT 'weekly',
                start_date TEXT NOT NULL,
                end_date TEXT,
                is_active INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE barber_reminders (
                reminder_id INTEGER PRIMARY KEY AUTOINCREMENT,
                appointment_id INTEGER NOT NULL,
                reminder_type TEXT NOT NULL,
                scheduled_for TEXT NOT NULL,
                channel TEXT DEFAULT 'email',
                is_sent INTEGER DEFAULT 0,
                sent_at TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (appointment_id) REFERENCES barber_appointments(appointment_id)
            );
CREATE TABLE barber_scheduled_reports (
                report_id INTEGER PRIMARY KEY AUTOINCREMENT,
                report_type TEXT NOT NULL,
                frequency TEXT NOT NULL,
                recipients TEXT NOT NULL,
                params TEXT,
                last_run TEXT,
                next_run TEXT,
                is_active INTEGER DEFAULT 1,
                created_by TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE barber_seasonal_pricing (
                pricing_id INTEGER PRIMARY KEY AUTOINCREMENT,
                service_id INTEGER NOT NULL,
                promotional_price DECIMAL(10,2) NOT NULL,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                description TEXT,
                is_active INTEGER DEFAULT 1,
                created_by TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (service_id) REFERENCES barber_services(service_id)
            );
CREATE TABLE barber_service_addons (
                addon_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                price DECIMAL(10,2) NOT NULL,
                duration_minutes INTEGER DEFAULT 5,
                is_active INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE barber_service_packages (
                package_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                services TEXT,
                total_price DECIMAL(10,2) NOT NULL,
                discount_percent DECIMAL(5,2) DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE barber_services (
                service_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                service_type TEXT NOT NULL,
                description TEXT,
                duration_minutes INTEGER DEFAULT 30,
                price DECIMAL(10,2) NOT NULL,
                is_available INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , "service_name" TEXT, "status" TEXT DEFAULT 'active');
CREATE TABLE barber_staff (
                staff_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                employee_id TEXT UNIQUE,
                specialties TEXT,
                phone TEXT,
                email TEXT,
                is_active INTEGER DEFAULT 1,
                hire_date TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , "specialization" TEXT, "staff_name" TEXT, "availability" TEXT, "status" TEXT DEFAULT 'active');
CREATE TABLE barber_staff_schedules (
                schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_id INTEGER NOT NULL,
                day_of_week INTEGER NOT NULL,
                start_time TEXT,
                end_time TEXT,
                is_working INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (staff_id) REFERENCES barber_staff(staff_id)
            );
CREATE TABLE barber_waitlist (
                waitlist_id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id TEXT NOT NULL,
                customer_name TEXT NOT NULL,
                customer_email TEXT,
                customer_phone TEXT,
                preferred_date TEXT NOT NULL,
                preferred_time TEXT,
                service_id INTEGER,
                staff_id INTEGER,
                notes TEXT,
                status TEXT DEFAULT 'waiting',
                notification_sent_at TEXT,
                available_slot TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE batch_import_mappings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        owner TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('students', 'marks', 'staff')),
        name TEXT NOT NULL,
        mapping_json TEXT NOT NULL,
        shared INTEGER NOT NULL DEFAULT 0,
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (owner, kind, name)
    );
CREATE TABLE batch_job_rows (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        job_id INTEGER NOT NULL REFERENCES batch_jobs(id) ON DELETE CASCADE,
        row_no INTEGER NOT NULL,
        ref TEXT,
        outcome TEXT NOT NULL CHECK (outcome IN ('created', 'updated', 'unchanged', 'skipped',
                                                 'failed', 'undone')),
        message TEXT,
        undo_json TEXT
    );
CREATE TABLE batch_jobs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        kind TEXT NOT NULL CHECK (kind IN ('students', 'marks', 'staff', 'actions')),
        source TEXT,
        mode TEXT,
        actor TEXT NOT NULL,
        reason TEXT,
        status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'done', 'undone')),
        total INTEGER NOT NULL DEFAULT 0,
        succeeded INTEGER NOT NULL DEFAULT 0,
        skipped INTEGER NOT NULL DEFAULT 0,
        failed INTEGER NOT NULL DEFAULT 0,
        started_at TEXT NOT NULL DEFAULT (datetime('now')),
        finished_at TEXT,
        undone_by TEXT,
        undone_at TEXT,
        undo_reason TEXT
    );
CREATE TABLE batch_report_schedules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        owner TEXT NOT NULL,
        report TEXT NOT NULL CHECK (report IN ('success', 'errors', 'performance',
                                              'comprehensive', 'statistics')),
        frequency TEXT NOT NULL CHECK (frequency IN ('daily', 'weekly', 'monthly')),
        recipients TEXT NOT NULL,
        active INTEGER NOT NULL DEFAULT 1,
        last_sent_at TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE batch_settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE batch_watch_folders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        owner TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('students', 'marks')),
        folder TEXT NOT NULL,
        mode TEXT NOT NULL DEFAULT 'create',
        mapping_id INTEGER REFERENCES batch_import_mappings(id) ON DELETE SET NULL,
        reason TEXT NOT NULL,
        active INTEGER NOT NULL DEFAULT 1,
        last_run_at TEXT,
        last_result TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    , "run_at" TEXT, "last_scheduled_on" TEXT);
CREATE TABLE betting_accounts (
                    account_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT UNIQUE NOT NULL,
                    username TEXT NOT NULL,
                    email TEXT,
                    balance DECIMAL(10,2) DEFAULT 0.00,
                    total_deposited DECIMAL(10,2) DEFAULT 0.00,
                    total_withdrawn DECIMAL(10,2) DEFAULT 0.00,
                    total_wagered DECIMAL(10,2) DEFAULT 0.00,
                    total_won DECIMAL(10,2) DEFAULT 0.00,
                    status TEXT DEFAULT 'active',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE betting_events (
                    event_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_name TEXT NOT NULL,
                    event_type TEXT NOT NULL,
                    sport_type TEXT,
                    team_a TEXT,
                    team_b TEXT,
                    odds_a DECIMAL(6,2) DEFAULT 2.00,
                    odds_b DECIMAL(6,2) DEFAULT 2.00,
                    odds_draw DECIMAL(6,2),
                    event_date TEXT NOT NULL,
                    event_time TEXT,
                    status TEXT DEFAULT 'upcoming',
                    result TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    created_by TEXT
                );
CREATE TABLE bgcheck_audit_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    timestamp TEXT NOT NULL,
                    username TEXT,
                    action TEXT NOT NULL,
                    target TEXT,
                    details TEXT
                );
CREATE TABLE bgcheck_persons (
                    case_id TEXT PRIMARY KEY,
                    person_id TEXT UNIQUE NOT NULL,
                    full_name TEXT NOT NULL,
                    role TEXT NOT NULL CHECK(role IN ('student','staff','faculty')),
                    email TEXT,
                    phone TEXT,
                    dob TEXT,
                    department TEXT,
                    status TEXT NOT NULL DEFAULT 'pending'
                        CHECK(status IN ('pending','in-progress','cleared','flagged','inactive')),
                    gpa REAL,
                    criminal_flag INTEGER DEFAULT 0,
                    disciplinary_history TEXT,
                    employment_history TEXT,
                    references_text TEXT,
                    documents TEXT,
                    notes TEXT,
                    tags TEXT,
                    risk_score INTEGER DEFAULT 0,
                    id_hash TEXT,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL
                );
CREATE TABLE bgcheck_search_history (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT,
                    query TEXT,
                    timestamp TEXT NOT NULL
                );
CREATE TABLE bgcheck_watchlist (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    reason TEXT,
                    added_at TEXT NOT NULL
                );
CREATE TABLE bi_custom_metrics (
            metric_id INTEGER PRIMARY KEY AUTOINCREMENT,
            metric_name TEXT NOT NULL,
            metric_category TEXT NOT NULL,
            description TEXT,
            calculation_formula TEXT NOT NULL,
            data_sources TEXT,
            unit_of_measure TEXT,
            target_value REAL,
            created_by TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE bi_data_quality_checks (
            check_id INTEGER PRIMARY KEY AUTOINCREMENT,
            check_name TEXT NOT NULL,
            data_source TEXT NOT NULL,
            check_type TEXT NOT NULL,
            check_rule TEXT NOT NULL,
            last_run_date TEXT,
            passed BOOLEAN,
            issues_found INTEGER,
            details TEXT,
            is_active BOOLEAN DEFAULT 1
        );
CREATE TABLE bi_report_definitions (
            report_id INTEGER PRIMARY KEY AUTOINCREMENT,
            report_name TEXT NOT NULL,
            report_category TEXT NOT NULL,
            description TEXT,
            sql_query TEXT,
            data_source TEXT,
            parameters TEXT,
            visualization_type TEXT,
            created_by TEXT,
            is_public BOOLEAN DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT
        );
CREATE TABLE bi_report_exports (
            export_id INTEGER PRIMARY KEY AUTOINCREMENT,
            report_id INTEGER NOT NULL,
            export_format TEXT NOT NULL,
            file_path TEXT NOT NULL,
            file_size INTEGER,
            generated_by TEXT NOT NULL,
            generated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            parameters_used TEXT,
            row_count INTEGER,
            FOREIGN KEY (report_id) REFERENCES bi_report_definitions (report_id)
        );
CREATE TABLE bi_report_schedules (
            schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
            report_id INTEGER NOT NULL,
            schedule_name TEXT NOT NULL,
            frequency TEXT NOT NULL,
            delivery_method TEXT NOT NULL,
            recipients TEXT NOT NULL,
            export_format TEXT NOT NULL,
            last_run_date TEXT,
            next_run_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (report_id) REFERENCES bi_report_definitions (report_id)
        );
CREATE TABLE bi_visualizations (
            visualization_id INTEGER PRIMARY KEY AUTOINCREMENT,
            visualization_name TEXT NOT NULL,
            chart_type TEXT NOT NULL,
            data_source TEXT NOT NULL,
            x_axis TEXT,
            y_axis TEXT,
            filters TEXT,
            color_scheme TEXT,
            configuration TEXT,
            created_by TEXT,
            is_public BOOLEAN DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE biometric_auth_log (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id TEXT NOT NULL,
                        biometric_type TEXT NOT NULL,
                        match_score REAL,
                        success INTEGER NOT NULL,
                        device_info TEXT,
                        ip_address TEXT,
                        enrollment_id TEXT,
                        error_message TEXT,
                        attempt_at TEXT NOT NULL
                    );
CREATE TABLE biometric_enrollments (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        enrollment_id TEXT UNIQUE,
                        user_id TEXT NOT NULL,
                        biometric_type TEXT NOT NULL,
                        template_data BLOB,
                        template_hash TEXT,
                        device_name TEXT DEFAULT 'Unknown Device',
                        quality_score REAL,
                        created_at TEXT NOT NULL,
                        last_verified_at TEXT,
                        is_active INTEGER DEFAULT 1,
                        verification_count INTEGER DEFAULT 0,
                        failure_count INTEGER DEFAULT 0,
                        metadata TEXT DEFAULT '{}',
                        revoked_at TEXT
                    );
CREATE TABLE blockchain_credentials (
    credential_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    credential_type TEXT NOT NULL,  -- degree, certificate, diploma, transcript
    credential_name TEXT NOT NULL,
    issue_date DATE NOT NULL,
    blockchain_hash TEXT UNIQUE NOT NULL,
    blockchain_address TEXT,
    ipfs_hash TEXT,  -- For document storage
    metadata TEXT,  -- JSON
    is_revoked BOOLEAN DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "revoked_at" TEXT,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE "blockchain_wallets" (
                wallet_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL UNIQUE,
                wallet_address TEXT NOT NULL UNIQUE,
                public_key TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "blockchain_type" TEXT DEFAULT 'ethereum',
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE bm_cleaning_schedules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        building_id INTEGER NOT NULL,
        room_id INTEGER,
        frequency TEXT NOT NULL,
        last_cleaned TEXT,
        next_due TEXT,
        assigned_to TEXT,
        status TEXT DEFAULT 'scheduled',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE bm_occupancy_records (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        building_id INTEGER NOT NULL,
        room_id INTEGER,
        timestamp TEXT NOT NULL,
        occupant_count INTEGER NOT NULL,
        capacity INTEGER NOT NULL,
        utilization_pct REAL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE book_club_books (
                book_id INTEGER PRIMARY KEY AUTOINCREMENT,
                club_id INTEGER,
                title TEXT NOT NULL,
                author TEXT NOT NULL,
                isbn TEXT,
                genre TEXT,
                page_count INTEGER,
                description TEXT,
                discussion_date TEXT,
                proposed_by TEXT,
                proposed_date TEXT,
                status TEXT DEFAULT 'proposed',
                votes INTEGER DEFAULT 0,
                FOREIGN KEY (club_id) REFERENCES student_clubs (club_id)
            );
CREATE TABLE book_club_schedules (
                schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                club_id INTEGER,
                book_title TEXT,
                schedule_content TEXT,
                created_by TEXT,
                created_date TEXT,
                status TEXT DEFAULT 'active',
                FOREIGN KEY (club_id) REFERENCES student_clubs (club_id)
            );
CREATE TABLE book_clubs (
            book_club_id INTEGER PRIMARY KEY AUTOINCREMENT,
            club_name TEXT,
            current_book TEXT,
            book_author TEXT,
            discussion_leader_id TEXT,
            meeting_schedule TEXT,
            max_members INTEGER,
            current_members INTEGER DEFAULT 1,
            status TEXT DEFAULT 'active',
            description TEXT,
            FOREIGN KEY (discussion_leader_id) REFERENCES students (student_id)
        );
CREATE TABLE book_loans (
            loan_id INTEGER PRIMARY KEY AUTOINCREMENT,
            book_id TEXT NOT NULL,
            user_id TEXT NOT NULL,
            checkout_date TEXT NOT NULL,
            due_date TEXT NOT NULL,
            return_date TEXT,
            status TEXT DEFAULT 'active',
            fine_amount REAL DEFAULT 0.0,
            renewal_count INTEGER DEFAULT 0,
            reading_progress INTEGER DEFAULT 0,
            checkout_method TEXT DEFAULT 'manual',
            staff_id TEXT,
            notes TEXT
        , "paid" TEXT, "payment_date" TEXT, "payment_method" TEXT, "copy_id" INTEGER, "recalled_at" TEXT, "original_due_date" TEXT);
CREATE TABLE book_recommendations (
            recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            book_id TEXT NOT NULL,
            recommendation_type TEXT NOT NULL,
            confidence_score REAL DEFAULT 0.0,
            generated_date TEXT NOT NULL,
            status TEXT DEFAULT 'pending',
            clicked BOOLEAN DEFAULT FALSE
        );
CREATE TABLE book_requests (
            request_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            title TEXT NOT NULL,
            author TEXT,
            isbn TEXT,
            reason TEXT,
            status TEXT DEFAULT 'pending',
            priority INTEGER DEFAULT 1,
            requested_date TEXT NOT NULL,
            processed_date TEXT,
            processed_by TEXT,
            notes TEXT
        );
CREATE TABLE book_reservations (
            reservation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            book_id TEXT NOT NULL,
            user_id TEXT NOT NULL,
            reservation_date TEXT NOT NULL,
            expiry_date TEXT NOT NULL,
            status TEXT DEFAULT 'active',
            priority_order INTEGER DEFAULT 1,
            notification_sent BOOLEAN DEFAULT FALSE
        , "copy_id" INTEGER, "ready_at" TEXT, "collect_by" TEXT);
CREATE TABLE book_reviews (
            review_id INTEGER PRIMARY KEY AUTOINCREMENT,
            book_id TEXT NOT NULL,
            user_id TEXT NOT NULL,
            rating INTEGER CHECK(rating >= 1 AND rating <= 5),
            review_text TEXT,
            review_date TEXT NOT NULL,
            status TEXT DEFAULT 'pending',
            helpful_votes INTEGER DEFAULT 0,
            moderated_by TEXT,
            moderation_date TEXT
        , "author" TEXT, "book_title" TEXT, "club_id" INTEGER, "recommend" BOOLEAN, "review_content" TEXT, "reviewer_id" TEXT);
CREATE TABLE booked_seats (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            booking_id INTEGER NOT NULL,
            seat_id INTEGER NOT NULL,
            ticket_type TEXT DEFAULT 'Adult',
            FOREIGN KEY (booking_id) REFERENCES bookings(id),
            FOREIGN KEY (seat_id) REFERENCES seats(id)
        );
CREATE TABLE booking_rules (
                    rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    equipment_id INTEGER,
                    category_id INTEGER,
                    rule_type TEXT NOT NULL,
                    rule_value TEXT NOT NULL,
                    description TEXT,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (equipment_id) REFERENCES lab_equipment(equipment_id),
                    FOREIGN KEY (category_id) REFERENCES equipment_categories(category_id)
                );
CREATE TABLE bookings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            booking_ref TEXT UNIQUE NOT NULL,
            customer_name TEXT NOT NULL,
            customer_email TEXT,
            customer_phone TEXT,
            screening_id INTEGER NOT NULL,
            ticket_types TEXT,
            subtotal REAL NOT NULL,
            discount_amount REAL DEFAULT 0,
            promo_code TEXT,
            snacks_total REAL DEFAULT 0,
            snacks_items TEXT,
            total_amount REAL NOT NULL,
            payment_status TEXT DEFAULT 'pending',
            payment_method TEXT,
            booking_time TEXT NOT NULL,
            status TEXT DEFAULT 'active',
            notes TEXT, group_discount REAL DEFAULT 0, early_bird_discount REAL DEFAULT 0, dynamic_pricing_applied REAL DEFAULT 0, season_pass_id INTEGER, corporate_id INTEGER, qr_code TEXT, snack_pickup_time TEXT,
            FOREIGN KEY (screening_id) REFERENCES screenings(id)
        );
CREATE TABLE books (
            book_id TEXT PRIMARY KEY,
            title TEXT NOT NULL,
            author TEXT NOT NULL,
            isbn TEXT UNIQUE,
            publisher TEXT,
            category TEXT,
            year_published INTEGER,
            description TEXT,
            location TEXT,
            status TEXT DEFAULT 'available',
            added_date TEXT,
            last_updated TEXT,
            reading_level TEXT,
            tags TEXT,
            cover_image_path TEXT,
            digital_copy_path TEXT,
            acquisition_cost REAL DEFAULT 0.0,
            barcode TEXT UNIQUE,
            qr_code_path TEXT,
            total_pages INTEGER,
            language TEXT DEFAULT 'English',
            edition TEXT,
            condition_notes TEXT
        , purchase_price REAL DEFAULT 0.0, purchase_date TEXT, supplier TEXT, quantity INTEGER DEFAULT 1, "available_quantity" INTEGER, "publication_year" INTEGER, "classmark" TEXT);
CREATE TABLE breakout_rooms (
    room_id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id INTEGER NOT NULL,
    room_name TEXT NOT NULL,
    room_number INTEGER,
    participants TEXT,  -- JSON array of user_ids
    facilitator_id INTEGER,
    max_capacity INTEGER DEFAULT 10,
    topic TEXT,
    start_time TIMESTAMP,
    end_time TIMESTAMP,
    duration INTEGER,  -- minutes
    is_active BOOLEAN DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (session_id) REFERENCES virtual_sessions(session_id) ON DELETE CASCADE
);
CREATE TABLE "buddy_requests" (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                sender_id TEXT NOT NULL,
                receiver_id TEXT NOT NULL,
                request_type TEXT NOT NULL,
                destination TEXT,
                message TEXT,
                status TEXT DEFAULT 'pending',
                sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                responded_at TIMESTAMP,
                FOREIGN KEY (sender_id) REFERENCES users(username) ON DELETE CASCADE,
                FOREIGN KEY (receiver_id) REFERENCES users(username) ON DELETE CASCADE
            );
CREATE TABLE budget_alerts (
                        alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        budget_id INTEGER,
                        category_id INTEGER,
                        alert_type TEXT CHECK(alert_type IN ('overspending', 'low-balance', 'goal-milestone', 'recurring-expense', 'custom')),
                        threshold_type TEXT CHECK(threshold_type IN ('percentage', 'amount')),
                        threshold_value REAL NOT NULL,
                        message TEXT NOT NULL,
                        is_active BOOLEAN DEFAULT 1,
                        last_triggered TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (budget_id) REFERENCES student_budgets(budget_id),
                        FOREIGN KEY (category_id) REFERENCES budget_categories(category_id)
                    );
CREATE TABLE budget_categories (
            category_id INTEGER PRIMARY KEY AUTOINCREMENT,
            category_name TEXT NOT NULL,
            category_type TEXT NOT NULL, -- 'revenue', 'expense'
            parent_category_id INTEGER,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT, "allocated_amount" REAL, "budget_id" INTEGER,
            FOREIGN KEY (parent_category_id) REFERENCES budget_categories (category_id)
        );
CREATE TABLE budget_line_items (
            line_item_id INTEGER PRIMARY KEY AUTOINCREMENT,
            budget_id INTEGER NOT NULL,
            category_id INTEGER NOT NULL,
            budgeted_amount DECIMAL(12,2) NOT NULL,
            actual_amount DECIMAL(12,2) DEFAULT 0,
            variance DECIMAL(12,2) DEFAULT 0,
            notes TEXT,
            created_at TEXT,
            updated_at TEXT, "student_id" TEXT,
            FOREIGN KEY (budget_id) REFERENCES budget_plans (budget_id),
            FOREIGN KEY (category_id) REFERENCES budget_categories (category_id)
        );
CREATE TABLE budget_plans (
            budget_id INTEGER PRIMARY KEY AUTOINCREMENT,
            plan_name TEXT NOT NULL,
            academic_year TEXT NOT NULL,
            currency TEXT DEFAULT 'GBP',
            status TEXT DEFAULT 'draft', -- draft, approved, active, closed
            total_revenue_budget DECIMAL(12,2) DEFAULT 0,
            total_expense_budget DECIMAL(12,2) DEFAULT 0,
            created_by TEXT,
            approved_by TEXT,
            notes TEXT,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE budget_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                department TEXT NOT NULL,
                requested_by TEXT NOT NULL,
