                    created_at TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (award_id) REFERENCES bursary_awards (award_id)
                );
CREATE TABLE business_directory (
            business_id INTEGER PRIMARY KEY AUTOINCREMENT,
