                created_by TEXT,
    FOREIGN KEY (product_id) REFERENCES products(product_id)
            );
CREATE TABLE butcher_product_expiry (
                        expiry_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        product_id INTEGER NOT NULL,
                        batch_number TEXT,
                        quantity_kg REAL NOT NULL,
