                        status TEXT DEFAULT 'active',
                        FOREIGN KEY (product_id) REFERENCES products(product_id)
                    );
CREATE TABLE butcher_stock_alerts (
                        alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        product_id INTEGER NOT NULL,
