                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE cafe_staff_schedules (
                schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_name TEXT NOT NULL,
                position TEXT NOT NULL DEFAULT 'barista',
                day_of_week TEXT NOT NULL,
                start_time TIME NOT NULL,
                end_time TIME NOT NULL,
                notes TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE cafe_supplier_products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                supplier_id INTEGER NOT NULL,
                product_id INTEGER NOT NULL,
                cost_per_unit REAL,
                notes TEXT,
                FOREIGN KEY (supplier_id) REFERENCES cafe_suppliers(supplier_id),
                FOREIGN KEY (product_id) REFERENCES products(product_id)
            );
CREATE TABLE cafe_suppliers (
                supplier_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                contact_person TEXT,
                email TEXT,
                phone TEXT,
                address TEXT,
                payment_terms TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE calendar_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        entity TEXT NOT NULL,
        entity_id TEXT NOT NULL,
        action TEXT NOT NULL,
        actor TEXT,
        detail TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE calendar_audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT,
                action TEXT NOT NULL,
                resource_type TEXT NOT NULL,
                resource_id TEXT,
                old_values TEXT,
                new_values TEXT,
                timestamp TEXT NOT NULL,
                ip_address TEXT,
                user_agent TEXT
            );
CREATE TABLE calendar_feed_tokens (
        token_hash TEXT PRIMARY KEY,
        username TEXT NOT NULL,
        role TEXT,
        student_id TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        last_used_at TEXT,
        revoked_at TEXT
    );
CREATE TABLE calendar_key_dates (
        key_date_id INTEGER PRIMARY KEY AUTOINCREMENT,
        year_code TEXT NOT NULL REFERENCES calendar_years(year_code) ON DELETE CASCADE,
        kind TEXT NOT NULL,
        title TEXT NOT NULL,
        start_date TEXT NOT NULL,
        end_date TEXT,
        audience TEXT NOT NULL DEFAULT 'all' CHECK (audience IN ('all', 'students', 'staff')),
        source TEXT NOT NULL DEFAULT 'manual',
        source_ref TEXT,
        notes TEXT
    );
CREATE TABLE calendar_notification_preferences (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        notification_type TEXT NOT NULL,
        enabled BOOLEAN DEFAULT TRUE,
        advance_time INTEGER DEFAULT 60,
        method TEXT DEFAULT 'email',
