        UNIQUE(user_id, notification_type)
    );
CREATE TABLE calendar_permissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                permission_type TEXT NOT NULL,
                resource_id TEXT,
                granted_by TEXT,
                granted_at TEXT NOT NULL,
                expires_at TEXT
            );
CREATE TABLE calendar_published_snapshots (
        year_code TEXT NOT NULL,
        version INTEGER NOT NULL,
        snapshot_json TEXT NOT NULL,
        published_by TEXT,
        published_at TEXT NOT NULL DEFAULT (datetime('now')),
        changes_json TEXT,
        PRIMARY KEY (year_code, version)
    );
CREATE TABLE calendar_reminders (
        reminder_id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        event_id TEXT NOT NULL,
        remind_at TEXT NOT NULL,
        sent_at TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (username, event_id, remind_at)
    );
CREATE TABLE calendar_roles (
        username TEXT NOT NULL PRIMARY KEY,
        role TEXT NOT NULL DEFAULT 'calendar_admin' CHECK (role IN ('calendar_admin')),
        granted_by TEXT,
        granted_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE calendar_sync_settings (
                        id INTEGER PRIMARY KEY,
                        platform TEXT,
                        calendar_url TEXT,
                        auth_token TEXT,
                        auto_create_events INTEGER,
                        include_attendance INTEGER,
                        set_reminders INTEGER,
                        reminder_time INTEGER
                    );
CREATE TABLE calendar_terms (
        term_id INTEGER PRIMARY KEY AUTOINCREMENT,
        year_code TEXT NOT NULL REFERENCES calendar_years(year_code) ON DELETE CASCADE,
        name TEXT NOT NULL,
        start_date TEXT NOT NULL,
        end_date TEXT NOT NULL,
        sort_order INTEGER NOT NULL DEFAULT 0,
        UNIQUE (year_code, name),
        CHECK (end_date > start_date)
    );
CREATE TABLE calendar_years (
        year_code TEXT PRIMARY KEY,
        start_date TEXT NOT NULL,
        end_date TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
        version INTEGER NOT NULL DEFAULT 0,
        bank_holiday_region TEXT NOT NULL DEFAULT 'england-and-wales',
        published_at TEXT,
        published_by TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        notes TEXT,
        CHECK (end_date > start_date)
    );
CREATE TABLE campaign_expenses (
