                order_id INTEGER PRIMARY KEY AUTOINCREMENT,
                ceremony_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                gown_size TEXT DEFAULT '',
                hood_subject TEXT DEFAULT '',
                hat_size TEXT DEFAULT '',
                supplier TEXT DEFAULT '',
                collection_slot TEXT DEFAULT '',
                status TEXT DEFAULT 'ordered',
                created_at TEXT NOT NULL DEFAULT (datetime('now')), cost REAL NOT NULL DEFAULT 0, payment_method TEXT DEFAULT '', payment_status TEXT DEFAULT 'unpaid', payment_reference TEXT DEFAULT '', finance_payment_id INTEGER, paid_at TEXT, "cancelled_at" TEXT, "cancel_reason" TEXT, "refund_id" INTEGER,
                FOREIGN KEY (ceremony_id) REFERENCES graduation_ceremonies(ceremony_id) ON DELETE CASCADE,
                UNIQUE(ceremony_id, student_id)
            );
CREATE TABLE ceremony_guests (
        guest_id INTEGER PRIMARY KEY AUTOINCREMENT,
        ceremony_id INTEGER NOT NULL REFERENCES graduation_ceremonies(ceremony_id)
            ON DELETE CASCADE,
        student_id TEXT NOT NULL,
        guest_name TEXT NOT NULL,
        ticket_ref TEXT NOT NULL UNIQUE,
        access_needs TEXT,
        status TEXT NOT NULL DEFAULT 'issued' CHECK (status IN ('issued', 'cancelled')),
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE ceremony_invitations (
        ceremony_id INTEGER NOT NULL REFERENCES graduation_ceremonies(ceremony_id)
            ON DELETE CASCADE,
        student_id TEXT NOT NULL,
        invited_at TEXT NOT NULL DEFAULT (datetime('now')),
        invited_by TEXT,
        last_reminded_at TEXT,
        PRIMARY KEY (ceremony_id, student_id)
    );
CREATE TABLE ceremony_rsvps (
                rsvp_id INTEGER PRIMARY KEY AUTOINCREMENT,
                ceremony_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                rsvp_status TEXT NOT NULL DEFAULT 'pending',
                num_guests INTEGER NOT NULL DEFAULT 0,
                accessibility_notes TEXT DEFAULT '',
                name_pronunciation TEXT DEFAULT '',
                recorded_at TEXT NOT NULL DEFAULT (datetime('now')), "access_needs" TEXT, "attended_at" TEXT, "checked_in_by" TEXT, "no_show" INTEGER DEFAULT 0, "transferred_to" INTEGER, "recorded_by" TEXT,
                FOREIGN KEY (ceremony_id) REFERENCES graduation_ceremonies(ceremony_id) ON DELETE CASCADE,
                UNIQUE(ceremony_id, student_id)
            );
CREATE TABLE ceremony_seat_assignments (
                assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                ceremony_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                section TEXT DEFAULT 'A',
                row_label TEXT NOT NULL,
                seat_number INTEGER NOT NULL,
                is_accessibility INTEGER DEFAULT 0,
                notes TEXT DEFAULT '',
                FOREIGN KEY (ceremony_id) REFERENCES graduation_ceremonies(ceremony_id) ON DELETE CASCADE,
                UNIQUE(ceremony_id, student_id),
                UNIQUE(ceremony_id, section, row_label, seat_number)
            );
CREATE TABLE ceremony_ticket_requests (
        request_id INTEGER PRIMARY KEY AUTOINCREMENT,
        ceremony_id INTEGER NOT NULL REFERENCES graduation_ceremonies(ceremony_id)
            ON DELETE CASCADE,
        student_id TEXT NOT NULL,
        requested INTEGER NOT NULL CHECK (requested > 0),
        granted INTEGER NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'waiting'
            CHECK (status IN ('waiting', 'granted', 'partly_granted', 'declined', 'withdrawn')),
        requested_at TEXT NOT NULL DEFAULT (datetime('now')),
        decided_at TEXT,
        UNIQUE (ceremony_id, student_id)
    );
CREATE TABLE certificate_names (
        student_id TEXT PRIMARY KEY,
        certificate_name TEXT NOT NULL,
        confirmed_by_student INTEGER NOT NULL DEFAULT 0,
        confirmed_at TEXT,
        set_by TEXT,
        evidence TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE certificate_print_jobs (
        job_id INTEGER PRIMARY KEY AUTOINCREMENT,
        conferral_id INTEGER,
        student_id TEXT NOT NULL,
        certificate_id INTEGER,
        certificate_number TEXT,
        kind TEXT NOT NULL DEFAULT 'original' CHECK (kind IN ('original', 'replacement')),
        delivery TEXT NOT NULL DEFAULT 'ceremony' CHECK (delivery IN ('ceremony', 'post',
                                                                       'collect')),
        ceremony_id INTEGER,
        address TEXT,
        fee REAL NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'printing',
            'printed', 'dispatched', 'collected', 'cancelled', 'failed')),
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        printed_at TEXT,
        dispatched_at TEXT,
        notes TEXT
    );
CREATE TABLE certificates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            certificate_number TEXT UNIQUE NOT NULL,
            certificate_type TEXT NOT NULL,
            course_name TEXT NOT NULL,
            award_date TEXT NOT NULL,
            grade TEXT,
            additional_info TEXT,
            status TEXT NOT NULL DEFAULT 'active',
            issued_by TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE certifications (
                    cert_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    name TEXT NOT NULL,
                    issuing_body TEXT,
                    credential_id TEXT,
                    issue_date TEXT,
                    expiry_date TEXT,
                    document_path TEXT,
                    status TEXT DEFAULT 'active',
                    reminder_sent BOOLEAN DEFAULT 0,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE chapter_members (
                            membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
                            chapter_id INTEGER,
                            member_id  TEXT,
                            role       TEXT DEFAULT 'member',
                            join_date  TEXT DEFAULT (datetime('now')),
                            status     TEXT DEFAULT 'active'
                        );
CREATE TABLE chapter_memberships (
            membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter_id INTEGER,
            alumni_id TEXT,
            join_date TEXT,
            role TEXT DEFAULT 'member',
            FOREIGN KEY (chapter_id) REFERENCES regional_chapters (chapter_id),
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE charity_shop_archived (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                original_id INTEGER,
                name TEXT NOT NULL,
                category TEXT NOT NULL,
                price REAL NOT NULL,
                quantity INTEGER NOT NULL,
                condition TEXT,
                date_added TEXT,
                date_archived TEXT NOT NULL,
                archive_reason TEXT
            );
CREATE TABLE charity_shop_bundles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                bundle_price REAL NOT NULL,
                item_ids TEXT NOT NULL,
                date_created TEXT NOT NULL,
                is_active INTEGER DEFAULT 1,
                times_sold INTEGER DEFAULT 0
            );
CREATE TABLE charity_shop_customers (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT,
                phone TEXT,
                address TEXT,
                date_registered TEXT NOT NULL,
                birthday TEXT,
                is_vip INTEGER DEFAULT 0,
                loyalty_points INTEGER DEFAULT 0,
                total_spent REAL DEFAULT 0,
                referral_code TEXT UNIQUE,
                referred_by INTEGER,
                notes TEXT
            );
CREATE TABLE charity_shop_donations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                donor_id INTEGER,
                item_description TEXT NOT NULL,
                category TEXT,
                quantity INTEGER DEFAULT 1,
                estimated_value REAL,
                date_received TEXT NOT NULL,
                receipt_number TEXT,
                donation_drive_id TEXT,
                notes TEXT,
                FOREIGN KEY (donor_id) REFERENCES charity_shop_donors(id)
            );
CREATE TABLE charity_shop_donors (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT,
                phone TEXT,
                address TEXT,
                date_registered TEXT NOT NULL,
                total_donations INTEGER DEFAULT 0,
                total_value REAL DEFAULT 0,
                notes TEXT
            );
CREATE TABLE charity_shop_feedback (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id INTEGER,
                item_id INTEGER,
                rating INTEGER NOT NULL,
                comment TEXT,
                feedback_date TEXT NOT NULL,
                FOREIGN KEY (customer_id) REFERENCES charity_shop_customers(id),
                FOREIGN KEY (item_id) REFERENCES charity_shop_stock(id)
            );
CREATE TABLE charity_shop_gift_cards (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                code TEXT UNIQUE NOT NULL,
                initial_balance REAL NOT NULL,
                current_balance REAL NOT NULL,
                date_issued TEXT NOT NULL,
                expiry_date TEXT,
                issued_to INTEGER,
                is_active INTEGER DEFAULT 1,
                FOREIGN KEY (issued_to) REFERENCES charity_shop_customers(id)
            );
CREATE TABLE charity_shop_layaway (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_id INTEGER NOT NULL,
                customer_id INTEGER NOT NULL,
                total_price REAL NOT NULL,
                deposit_paid REAL NOT NULL,
                remaining_balance REAL NOT NULL,
                start_date TEXT NOT NULL,
                due_date TEXT NOT NULL,
                status TEXT DEFAULT 'active',
                FOREIGN KEY (item_id) REFERENCES charity_shop_stock(id),
                FOREIGN KEY (customer_id) REFERENCES charity_shop_customers(id)
            );
CREATE TABLE charity_shop_locations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL UNIQUE,
                address TEXT,
                phone TEXT,
                manager TEXT,
                is_active INTEGER DEFAULT 1
            );
CREATE TABLE charity_shop_loyalty (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id INTEGER NOT NULL,
                points_change INTEGER NOT NULL,
                reason TEXT,
                transaction_date TEXT NOT NULL,
                sale_id INTEGER,
                FOREIGN KEY (customer_id) REFERENCES charity_shop_customers(id)
            );
CREATE TABLE charity_shop_price_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_id INTEGER NOT NULL,
                old_price REAL,
                new_price REAL NOT NULL,
                change_date TEXT NOT NULL,
                changed_by TEXT,
                reason TEXT,
                FOREIGN KEY (item_id) REFERENCES charity_shop_stock(id)
            );
CREATE TABLE charity_shop_promotions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                discount_type TEXT NOT NULL,
                discount_value REAL NOT NULL,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                category TEXT,
                min_purchase REAL DEFAULT 0,
                is_active INTEGER DEFAULT 1
            );
CREATE TABLE charity_shop_referrals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                referrer_id INTEGER NOT NULL,
                referred_id INTEGER NOT NULL,
                referral_date TEXT NOT NULL,
                reward_given INTEGER DEFAULT 0,
                reward_amount REAL DEFAULT 0,
                FOREIGN KEY (referrer_id) REFERENCES charity_shop_customers(id),
                FOREIGN KEY (referred_id) REFERENCES charity_shop_customers(id)
            );
CREATE TABLE charity_shop_sales (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_id INTEGER,
                customer_id INTEGER,
                staff_id INTEGER,
                quantity INTEGER NOT NULL,
                unit_price REAL NOT NULL,
                discount_applied REAL DEFAULT 0,
                total_amount REAL NOT NULL,
                payment_method TEXT DEFAULT 'cash',
                sale_date TEXT NOT NULL,
                refunded INTEGER DEFAULT 0,
                refund_date TEXT,
                refund_reason TEXT,
                gift_card_id INTEGER,
                loyalty_points_earned INTEGER DEFAULT 0,
                FOREIGN KEY (item_id) REFERENCES charity_shop_stock(id),
                FOREIGN KEY (customer_id) REFERENCES charity_shop_customers(id),
                FOREIGN KEY (staff_id) REFERENCES charity_shop_staff(id)
            );
CREATE TABLE charity_shop_shifts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_id INTEGER NOT NULL,
                shift_date TEXT NOT NULL,
                start_time TEXT NOT NULL,
                end_time TEXT NOT NULL,
                hours_worked REAL,
                notes TEXT,
                FOREIGN KEY (staff_id) REFERENCES charity_shop_staff(id)
            );
CREATE TABLE charity_shop_staff (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT,
                phone TEXT,
                role TEXT DEFAULT 'volunteer',
                date_joined TEXT NOT NULL,
                is_active INTEGER DEFAULT 1,
                total_hours REAL DEFAULT 0,
                total_sales REAL DEFAULT 0,
                sales_count INTEGER DEFAULT 0
            );
CREATE TABLE charity_shop_stock (
                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                            name TEXT NOT NULL,
                            category TEXT NOT NULL,
                            price REAL NOT NULL,
                            quantity INTEGER NOT NULL,
                            condition TEXT DEFAULT 'Good',
                            date_added TEXT NOT NULL,
                            sold INTEGER DEFAULT 0,
                            sold_date TEXT,
                            sold_quantity INTEGER DEFAULT 0
                        , [low_stock_threshold] INTEGER DEFAULT 5, [barcode] TEXT, [location_id] INTEGER, [discount_percent] REAL DEFAULT 0, [donation_cost] REAL DEFAULT 0);
CREATE TABLE charity_shop_tasks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                description TEXT,
                assigned_to INTEGER,
                priority TEXT DEFAULT 'medium',
                status TEXT DEFAULT 'pending',
                due_date TEXT,
                created_date TEXT NOT NULL,
                completed_date TEXT,
                FOREIGN KEY (assigned_to) REFERENCES charity_shop_staff(id)
            );
CREATE TABLE charity_shop_wishlists (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id INTEGER NOT NULL,
                item_description TEXT NOT NULL,
                category TEXT,
                max_price REAL,
                date_added TEXT NOT NULL,
                notified INTEGER DEFAULT 0,
                FOREIGN KEY (customer_id) REFERENCES charity_shop_customers(id)
            );
CREATE TABLE chat_filter_words (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                word TEXT NOT NULL UNIQUE,
                severity TEXT NOT NULL DEFAULT 'flag',
                created_at TEXT NOT NULL
            );
CREATE TABLE "chat_message_reactions" (
                message_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                emoji TEXT NOT NULL,
                created_at TEXT NOT NULL,
                PRIMARY KEY (message_id, user_id, emoji),
                FOREIGN KEY (message_id) REFERENCES chat_messages (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_message_reads" (
                user_id INTEGER NOT NULL,
                room_id INTEGER NOT NULL,
                last_read_message_id INTEGER NOT NULL DEFAULT 0,
                last_read_at TEXT NOT NULL,
                PRIMARY KEY (user_id, room_id),
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_messages" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER NOT NULL,
                sender_id INTEGER NOT NULL,
                content TEXT NOT NULL,
                sent_at TEXT NOT NULL, [edited_at] TEXT, [is_deleted] INTEGER DEFAULT 0, [reply_to_id] INTEGER, [pinned_at] TEXT, [pinned_by] INTEGER, [attachment_path] TEXT, [attachment_name] TEXT, [attachment_mime] TEXT, [attachment_size] INTEGER, [flagged_at] TEXT, [is_encrypted] INTEGER DEFAULT 0,
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
                FOREIGN KEY (sender_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_poll_options" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                message_id INTEGER NOT NULL,
                label TEXT NOT NULL,
                sort_order INTEGER DEFAULT 0,
                FOREIGN KEY (message_id) REFERENCES chat_polls (message_id) ON DELETE CASCADE
            );
CREATE TABLE "chat_poll_votes" (
                option_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                voted_at TEXT NOT NULL,
                PRIMARY KEY (option_id, user_id),
                FOREIGN KEY (option_id) REFERENCES chat_poll_options (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_polls" (
                message_id INTEGER PRIMARY KEY,
                question TEXT NOT NULL,
                multi_choice INTEGER DEFAULT 0,
                closes_at TEXT,
                FOREIGN KEY (message_id) REFERENCES chat_messages (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_presence" (
                user_id INTEGER NOT NULL,
                room_id INTEGER NOT NULL,
                last_seen_at TEXT NOT NULL,
                PRIMARY KEY (user_id, room_id),
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_reports" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                reporter_id INTEGER NOT NULL,
                target_message_id INTEGER,
                target_user_id INTEGER,
                room_id INTEGER,
                reason TEXT,
                status TEXT NOT NULL DEFAULT 'open',
                created_at TEXT NOT NULL,
                resolved_by INTEGER,
                resolved_at TEXT,
                resolution_note TEXT, [safeguarding_submission_id] INTEGER,
                FOREIGN KEY (reporter_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_room_bans" (
                room_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                banned_at TEXT NOT NULL,
                banned_by INTEGER,
                reason TEXT,
                PRIMARY KEY (room_id, user_id),
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_room_invitations" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            room_id INTEGER NOT NULL,
            user_id INTEGER NOT NULL,
            invited_by INTEGER NOT NULL,
            invited_at TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending',
            responded_at TEXT,
            FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
            FOREIGN KEY (invited_by) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE "chat_room_keys" (
                room_id INTEGER PRIMARY KEY,
                key_b64 TEXT NOT NULL,
                created_at TEXT NOT NULL,
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_room_members" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                joined_at TEXT NOT NULL,
                is_admin INTEGER DEFAULT 0, [is_banned] INTEGER DEFAULT 0, [muted_until] TEXT, [is_favourite] INTEGER DEFAULT 0, "role" TEXT,
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_room_notes" (
                room_id INTEGER PRIMARY KEY,
                content TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL,
                updated_by INTEGER, [version] INTEGER NOT NULL DEFAULT 1,
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_room_queue" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                joined_at TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'waiting',
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_rooms" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                room_type TEXT NOT NULL,
                created_by INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                is_active INTEGER DEFAULT 1, max_members INTEGER DEFAULT 50, [archived_at] TEXT, [archived_by] INTEGER, [category] TEXT, [icon] TEXT, [colour] TEXT, [linked_course_code] TEXT, [linked_assignment_group_id] INTEGER, [announcement_mode] INTEGER DEFAULT 0, [oh_starts_at] TEXT, [oh_ends_at] TEXT, [retention_days] INTEGER, [slow_mode_seconds] INTEGER DEFAULT 0, [is_encrypted] INTEGER DEFAULT 0, [linked_entity_type] TEXT, [linked_entity_id] TEXT, "is_private" INTEGER DEFAULT 0,
                FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_system_posts" (
                room_id INTEGER NOT NULL,
                kind TEXT NOT NULL,
                key TEXT NOT NULL,
                message_id INTEGER,
                posted_at TEXT NOT NULL,
                PRIMARY KEY (room_id, kind, key),
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE
            );
CREATE TABLE "chat_typing" (
                user_id INTEGER NOT NULL,
                room_id INTEGER NOT NULL,
                started_at TEXT NOT NULL,
                PRIMARY KEY (user_id, room_id),
                FOREIGN KEY (room_id) REFERENCES chat_rooms (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE chatbot_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        entity TEXT NOT NULL,
        entity_id TEXT NOT NULL,
        action TEXT NOT NULL,
        actor TEXT,
        detail TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE chatbot_cases (
        case_id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('human_help', 'crisis')),
        message TEXT NOT NULL,
        conversation_id INTEGER,
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'assigned', 'answered',
                                                              'closed')),
        assigned_to TEXT,
        answer TEXT,
        answered_by TEXT,
        answered_at TEXT,
        safeguarding_case_id INTEGER,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        closed_at TEXT,
        closed_by TEXT
    );
CREATE TABLE "chatbot_conversations" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            username TEXT NOT NULL,
            message TEXT NOT NULL,
            response TEXT NOT NULL,
            intent TEXT,
            confidence REAL,
            timestamp TEXT NOT NULL,
            session_id TEXT, "crisis" INTEGER DEFAULT 0, "case_id" INTEGER, "faq_id" INTEGER, "answered" INTEGER DEFAULT 1,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE chatbot_feedback (
        feedback_id INTEGER PRIMARY KEY AUTOINCREMENT,
        conversation_row_id INTEGER NOT NULL,
        username TEXT,
        helpful INTEGER NOT NULL,
        comment TEXT,
        given_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (conversation_row_id, username)
    );
CREATE TABLE chatbot_pending_messages (
    msg_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id    TEXT NOT NULL,
    source     TEXT NOT NULL,
    message    TEXT NOT NULL,
    payload    TEXT,
    is_read    INTEGER NOT NULL DEFAULT 0,
    queued_at  TEXT NOT NULL,
    read_at    TEXT
);
CREATE TABLE chatbot_roles (
        username TEXT NOT NULL,
        role TEXT NOT NULL CHECK (role IN ('agent', 'editor')),
        granted_by TEXT,
        granted_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (username, role)
    );
CREATE TABLE chatbot_settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE chatbot_unanswered (
        question_id INTEGER PRIMARY KEY AUTOINCREMENT,
        question TEXT NOT NULL,
        normalised TEXT NOT NULL UNIQUE,
        times_asked INTEGER NOT NULL DEFAULT 1,
        first_asked_at TEXT NOT NULL DEFAULT (datetime('now')),
        last_asked_at TEXT NOT NULL DEFAULT (datetime('now')),
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'answered', 'dismissed')),
        faq_id INTEGER,
        handled_by TEXT
    );
CREATE TABLE church_announcements (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT,
    content TEXT,
    date TEXT,
    priority TEXT,
    expires TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE church_attendance (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    service_date TEXT,
    service_type TEXT,
    attendance_count INTEGER,
    notes TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE church_donations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    donor_name TEXT,
    donor_email TEXT,
    amount REAL,
    donation_type TEXT,
    payment_method TEXT,
    transaction_ref TEXT,
    date TEXT,
    notes TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, "reference" TEXT);
CREATE TABLE church_expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    description TEXT,
    amount REAL,
    category TEXT,
    date TEXT,
    vendor TEXT,
    approved_by TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE church_members (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    email TEXT,
    phone TEXT,
    address TEXT,
    join_date TEXT,
    membership_type TEXT,
    status TEXT DEFAULT 'Active',
    notes TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, "membership_status" TEXT DEFAULT 'Active');
CREATE TABLE church_prayer_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    requester_name TEXT,
    request TEXT,
    category TEXT,
    status TEXT DEFAULT 'Pending',
    date TEXT,
    is_anonymous INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, "date_submitted" TEXT, "request_text" TEXT, "request_type" TEXT, "answered" BOOLEAN DEFAULT 0);
CREATE TABLE church_sermons (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT,
    speaker TEXT,
    date TEXT,
    scripture TEXT,
    summary TEXT,
    video_url TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, "notes" TEXT, "preacher" TEXT, "sermon_date" TEXT);
CREATE TABLE church_small_groups (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    leader TEXT,
    meeting_day TEXT,
    meeting_time TEXT,
    location TEXT,
    description TEXT,
    members TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE church_volunteers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    email TEXT,
    phone TEXT,
    ministry TEXT,
    availability TEXT,
    skills TEXT,
    status TEXT DEFAULT 'Active',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE cinema_bookings (  booking_id INTEGER PRIMARY KEY AUTOINCREMENT,  showing_id INTEGER NOT NULL,  user_id TEXT NOT NULL,  seats INTEGER DEFAULT 1,  total_price REAL,  booking_date TEXT DEFAULT (datetime('now')),  status TEXT DEFAULT 'booked', "booking_ref" TEXT, "user_name" TEXT, "user_email" TEXT, "screening_id" INTEGER, "movie_title" TEXT, "screening_date" DATE, "screening_time" TEXT, "num_tickets" INTEGER, "ticket_type" TEXT, "seat_numbers" TEXT, "ticket_total" REAL, "snacks_total" REAL DEFAULT 0.00, "member_discount" REAL DEFAULT 0.00, "total_amount" REAL, "payment_method" TEXT, "points_earned" INTEGER DEFAULT 0, "points_redeemed" INTEGER DEFAULT 0, "customer_id" INTEGER, "payment_status" TEXT, "created_at" TEXT,  FOREIGN KEY (showing_id) REFERENCES cinema_showings (id));
CREATE TABLE cinema_exclusive_screenings (
                    exclusive_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    screening_id INTEGER NOT NULL,
                    movie_title TEXT,
                    screening_date DATE,
                    screening_time TEXT,
                    description TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (screening_id) REFERENCES cinema_screenings(screening_id)
                );
CREATE TABLE cinema_memberships (
                    membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT UNIQUE NOT NULL,
                    user_name TEXT,
                    user_email TEXT,
                    membership_type TEXT DEFAULT 'standard',
                    points_balance INTEGER DEFAULT 0,
                    total_points_earned INTEGER DEFAULT 0,
                    total_spent REAL DEFAULT 0.00,
                    join_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    renewal_date DATE,
                    status TEXT DEFAULT 'active',
                    last_activity TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE cinema_movies (
                    movie_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    genre TEXT,
                    rating TEXT,
                    duration_minutes INTEGER,
                    description TEXT,
                    director TEXT,
                    cast TEXT,
                    release_date DATE,
                    status TEXT DEFAULT 'now_showing',
                    poster_url TEXT,
                    trailer_url TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE cinema_points_transactions (
                    transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    booking_ref TEXT,
                    transaction_type TEXT NOT NULL,
                    points INTEGER NOT NULL,
                    description TEXT,
                    transaction_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (user_id) REFERENCES cinema_memberships(user_id)
                );
CREATE TABLE cinema_referrals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            referral_code TEXT UNIQUE NOT NULL,
            referrer_email TEXT NOT NULL,
            referee_email TEXT,
            status TEXT DEFAULT 'pending',
            reward_given INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE cinema_screenings (
                    screening_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    movie_id INTEGER NOT NULL,
                    movie_title TEXT,
                    screen_number INTEGER,
                    screening_date DATE NOT NULL,
                    screening_time TEXT NOT NULL,
                    total_seats INTEGER DEFAULT 100,
                    available_seats INTEGER DEFAULT 100,
                    ticket_price REAL DEFAULT 12.00,
                    status TEXT DEFAULT 'available',
                    screen_type TEXT DEFAULT 'standard',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (movie_id) REFERENCES cinema_movies(movie_id)
                );
CREATE TABLE cinema_seats (
                    seat_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    screening_id INTEGER NOT NULL,
