                    seat_type TEXT DEFAULT 'standard',
                    status TEXT DEFAULT 'available',
                    booking_ref TEXT,
                    FOREIGN KEY (screening_id) REFERENCES cinema_screenings(screening_id),
                    UNIQUE(screening_id, row_letter, seat_number)
                );
CREATE TABLE cinema_settings (
            key TEXT PRIMARY KEY,
            value TEXT,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE cinema_showings (  id INTEGER PRIMARY KEY AUTOINCREMENT,  movie_title TEXT NOT NULL,  showing_date TEXT NOT NULL,  showing_time TEXT NOT NULL,  screen TEXT,  price REAL DEFAULT 0,  total_seats INTEGER DEFAULT 100,  booked_seats INTEGER DEFAULT 0,  rating TEXT,  duration_minutes INTEGER,  genre TEXT,  status TEXT DEFAULT 'scheduled',  created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE cinema_snacks_orders (
