                    , "reviewed_at" TEXT, "student_a" TEXT, "student_b" TEXT, "composite_score" INTEGER, "ngram_similarity" TEXT, "status" TEXT, "structural_similarity" TEXT, "submission_a" TEXT, "submission_b" TEXT, "timing_diff_minutes" INTEGER);
