, "stage" TEXT, "received_on" TEXT, "stage_started" TEXT, "stage_due" TEXT, "assigned_to" TEXT, "outcome" TEXT, "outcome_summary" TEXT, "issues_considered" TEXT, "decision_at" TEXT, "escalation_due" TEXT, "final_decision_at" TEXT, "closed_at" TEXT, "closed_stage" TEXT, "cop_issued_at" TEXT, "cop_path" TEXT, "last_reminder_on" TEXT);
