            current_balance REAL DEFAULT 0,
            payment_terms INTEGER DEFAULT 30,
            discount_percent REAL DEFAULT 10,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE corporate_invoices (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            invoice_number TEXT UNIQUE NOT NULL,
            corporate_id INTEGER NOT NULL,
            invoice_date TEXT NOT NULL,
            due_date TEXT NOT NULL,
            items TEXT NOT NULL,
            subtotal REAL NOT NULL,
            tax_amount REAL DEFAULT 0,
            total_amount REAL NOT NULL,
            amount_paid REAL DEFAULT 0,
            status TEXT DEFAULT 'unpaid',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (corporate_id) REFERENCES corporate_accounts(id)
        );
CREATE TABLE counseling_appointments (
                    appointment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    appointment_date TEXT NOT NULL,
                    appointment_time TEXT NOT NULL,
                    counselor_name TEXT,
                    appointment_type TEXT,
                    status TEXT DEFAULT 'Scheduled',
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE counselling_case_notes (
        note_id INTEGER PRIMARY KEY AUTOINCREMENT,
        referral_id INTEGER NOT NULL REFERENCES counselling_referrals(referral_id),
        student_id TEXT NOT NULL,
        note_type TEXT NOT NULL DEFAULT 'note',
        note TEXT,
        author TEXT NOT NULL,
        created_at TEXT NOT NULL
    );
CREATE TABLE counselling_measures (
        measure_id INTEGER PRIMARY KEY AUTOINCREMENT,
        referral_id INTEGER NOT NULL REFERENCES counselling_referrals(referral_id),
        student_id TEXT NOT NULL,
        measure TEXT NOT NULL,
        stage TEXT NOT NULL,
        session_id INTEGER,
        items TEXT NOT NULL,
        total INTEGER NOT NULL,
        band TEXT,
        risk_flag INTEGER NOT NULL DEFAULT 0,
        recorded_by TEXT NOT NULL,
        recorded_at TEXT NOT NULL
    );
CREATE TABLE counselling_referrals (
        referral_id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        source TEXT NOT NULL DEFAULT 'self',
        referred_by TEXT NOT NULL,
        presenting_issue TEXT,
        reason TEXT,
        consent_to_contact INTEGER NOT NULL DEFAULT 1,
        referred_at TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'referred',
        risk_rating TEXT,
        priority INTEGER,
        pathway TEXT,
        triaged_by TEXT,
        triage_clinician TEXT,
        triaged_at TEXT,
        triage_notes TEXT,
        same_day_due TEXT,
        safeguarding_concern_id INTEGER,
        counsellor_id INTEGER REFERENCES mental_health_counselors(counselor_id),
        allocated_by TEXT,
        allocated_at TEXT,
        session_cap INTEGER NOT NULL DEFAULT 6,
        discharged_by TEXT,
        discharged_at TEXT,
        discharge_reason TEXT,
        discharge_summary TEXT,
        updated_at TEXT,
        FOREIGN KEY (student_id) REFERENCES students(student_id)
    );
CREATE TABLE counselling_sessions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                counsellor TEXT,
                session_date TEXT,
                notes TEXT,
                outcome TEXT,
                created_at TEXT DEFAULT (datetime('now'))
            , referral_id INTEGER, counsellor_id INTEGER, session_number INTEGER, session_stage TEXT, session_time TEXT, duration_minutes INTEGER DEFAULT 50, mode TEXT, status TEXT DEFAULT 'booked', appointment_id INTEGER, recorded_by TEXT, updated_at TEXT);
CREATE TABLE course_analytics (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course_id TEXT NOT NULL,
            semester TEXT NOT NULL,
            year INTEGER NOT NULL,
            total_enrolled INTEGER DEFAULT 0,
            total_completed INTEGER DEFAULT 0,
            average_grade REAL DEFAULT 0.0,
            completion_rate REAL DEFAULT 0.0,
            calculated_at TEXT NOT NULL,
            FOREIGN KEY (course_id) REFERENCES courses (id)
        );
CREATE TABLE course_approval_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        from_stage TEXT DEFAULT '',
        to_stage TEXT NOT NULL,
        actor TEXT DEFAULT '',
        comments TEXT DEFAULT '',
        changed_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE course_approvals (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL UNIQUE,
        stage TEXT NOT NULL DEFAULT 'Draft',
        submitted_by TEXT DEFAULT '',
        reviewer TEXT DEFAULT '',
        comments TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE course_assessment_components (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        name TEXT NOT NULL,
        weight REAL NOT NULL DEFAULT 0.0,
        notes TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE course_bridge_meta (  key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE course_categories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT UNIQUE NOT NULL,
            description TEXT,
            color_code TEXT,
            created_at TEXT NOT NULL
        );
CREATE TABLE course_corequisites (
                    corequisite_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    course_id TEXT NOT NULL,
                    corequisite_course_id TEXT NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (course_id) REFERENCES courses(id),
                    UNIQUE(course_id, corequisite_course_id)
                );
CREATE TABLE course_corequisites_ext (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        corequisite_code TEXT NOT NULL,
        notes TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE(course_code, corequisite_code)
    );
CREATE TABLE course_credit_registrations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_id INTEGER,
                    user_id TEXT,
                    credits INTEGER DEFAULT 1,
                    status TEXT DEFAULT 'registered',
                    registered_at TEXT
                );
CREATE TABLE course_crosslistings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        related_code TEXT NOT NULL,
        relation_type TEXT NOT NULL DEFAULT 'Cross-listed',
        notes TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE(course_code, related_code, relation_type)
    );
CREATE TABLE course_curriculum (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course_code TEXT NOT NULL,
            year INTEGER NOT NULL,
            module_code TEXT NOT NULL,
            module_name TEXT NOT NULL,
            UNIQUE(course_code, module_code)
        );
CREATE TABLE course_demand_predictions (
            prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_code TEXT NOT NULL,
            academic_year TEXT NOT NULL,
            semester TEXT NOT NULL,
            predicted_enrollment INTEGER,
            actual_enrollment INTEGER,
            prediction_date TEXT DEFAULT CURRENT_TIMESTAMP,
            model_id INTEGER,
            factors TEXT,
            FOREIGN KEY (module_code) REFERENCES modules (module_code),
            FOREIGN KEY (model_id) REFERENCES analytics_models (model_id)
        );
CREATE TABLE course_eval_comment_reviews (
        answer_id INTEGER PRIMARY KEY REFERENCES evaluation_answers(answer_id),
        reason TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'released', 'withheld')),
        reviewed_by TEXT,
        reviewed_at TEXT
    );
CREATE TABLE course_eval_invitations (
        evaluation_id INTEGER NOT NULL REFERENCES course_evaluations(evaluation_id),
        student_id TEXT NOT NULL,
        invited_at TEXT NOT NULL DEFAULT (date('now')),
        reminded_at TEXT,
        responded INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (evaluation_id, student_id)
    );
CREATE TABLE course_eval_responses_to_students (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        evaluation_id INTEGER NOT NULL REFERENCES course_evaluations(evaluation_id),
        summary TEXT NOT NULL,
        actions TEXT,
        you_said TEXT,
        we_did TEXT,
        published INTEGER NOT NULL DEFAULT 0,
        author TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        published_at TEXT
    );
CREATE TABLE course_evaluations (
                evaluation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                module_code TEXT NOT NULL,
                academic_year TEXT NOT NULL,
                semester TEXT NOT NULL,
                instructor_id TEXT NOT NULL,
                template_id INTEGER NOT NULL,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                response_count INTEGER DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                created_at TEXT NOT NULL DEFAULT (datetime('now')), "completion_rate" REAL DEFAULT 0, "is_anonymous" BOOLEAN DEFAULT 1, auto_open INTEGER DEFAULT 0, calendar_event_id INTEGER, embargo_until_grades INTEGER DEFAULT 0, grades_submitted_at TEXT, estimated_minutes INTEGER, deleted_at TEXT, "course_code" TEXT, "min_responses" INTEGER DEFAULT 5, "opened_by" TEXT, "closed_at" TEXT,
                FOREIGN KEY (template_id) REFERENCES evaluation_templates(template_id)
            );
CREATE TABLE "course_event_attendance" (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_id TEXT NOT NULL,
                    student_id TEXT NOT NULL,
                    attendance_status TEXT DEFAULT 'present',
                    notes TEXT,
                    recorded_at TEXT NOT NULL,
                    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE,
                    UNIQUE(event_id, student_id)
                );
CREATE TABLE "course_events" (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_id TEXT NOT NULL,
                    course_id TEXT NOT NULL,
                    event_sub_type TEXT,
                    date_added TEXT NOT NULL,
                    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE,
                    FOREIGN KEY (course_id) REFERENCES courses (id) ON DELETE CASCADE,
                    UNIQUE(event_id, course_id)
                );
CREATE TABLE course_exit_awards (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        award_name TEXT NOT NULL,
        total_credits INTEGER NOT NULL CHECK (total_credits > 0),
        credits_at_level INTEGER NOT NULL DEFAULT 0 CHECK (credits_at_level >= 0),
        at_level INTEGER CHECK (at_level IS NULL OR at_level BETWEEN 3 AND 8),
        is_final INTEGER NOT NULL DEFAULT 0,
        UNIQUE (course_code, award_name)
    );
CREATE TABLE course_external_examiners (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        examiner_id INTEGER NOT NULL REFERENCES external_examiners(examiner_id),
        appointed_from TEXT NOT NULL,
        appointed_to TEXT NOT NULL,
        report_due TEXT,
        report_received_at TEXT,
        report_summary TEXT,
        response TEXT,
        responded_at TEXT,
        responded_by TEXT,
        CHECK (appointed_to > appointed_from)
    );
CREATE TABLE course_grading_schemes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL UNIQUE,
        scheme_type TEXT NOT NULL DEFAULT 'Letter',
        pass_mark REAL NOT NULL DEFAULT 50.0,
        notes TEXT DEFAULT '',
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE course_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course_id TEXT NOT NULL,
            field_name TEXT NOT NULL,
            old_value TEXT,
            new_value TEXT,
            changed_by TEXT,
            changed_at TEXT NOT NULL,
            FOREIGN KEY (course_id) REFERENCES courses (id)
        );
CREATE TABLE course_intake_targets (
        course_code TEXT NOT NULL,
        academic_year TEXT NOT NULL,
        mode_of_study TEXT NOT NULL DEFAULT 'full-time',
        target INTEGER NOT NULL CHECK (target >= 0),
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (course_code, academic_year, mode_of_study)
    );
CREATE TABLE course_integrity_settings (
    module_code TEXT PRIMARY KEY,
    ai_detection_enabled INTEGER DEFAULT 1,
    plagiarism_enabled INTEGER DEFAULT 1,
    similarity_threshold REAL DEFAULT 0.3,
    allow_collaboration INTEGER DEFAULT 0,
    notes TEXT,
    updated_at TEXT DEFAULT (datetime('now')),
    updated_by TEXT
);
CREATE TABLE course_learning_outcomes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        outcome_code TEXT NOT NULL DEFAULT '',
        description TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    , bloom_level TEXT);
CREATE TABLE course_materials (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        material_type TEXT NOT NULL DEFAULT 'Textbook',
        title TEXT NOT NULL,
        author TEXT DEFAULT '',
        isbn TEXT DEFAULT '',
        edition TEXT DEFAULT '',
        url TEXT DEFAULT '',
        cost REAL NOT NULL DEFAULT 0.0,
        required INTEGER NOT NULL DEFAULT 1,
        notes TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE course_module_map (
               id INTEGER PRIMARY KEY AUTOINCREMENT,
               course_code TEXT NOT NULL,
               module_code TEXT NOT NULL,
               link_source TEXT NOT NULL DEFAULT 'manual',
               created_at  TEXT NOT NULL DEFAULT (datetime('now')),
               UNIQUE(course_code, module_code)
           );
CREATE TABLE course_offerings (
                    offering_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    course_id TEXT NOT NULL,
                    offered_fall BOOLEAN DEFAULT 1,
                    offered_spring BOOLEAN DEFAULT 1,
                    offered_summer BOOLEAN DEFAULT 0,
                    offered_years TEXT DEFAULT 'Every',
                    typical_enrollment INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP, "academic_year" TEXT, "course_code" TEXT, "instructor" TEXT, "max_enrollment" INTEGER DEFAULT 0, "room" TEXT, "schedule" TEXT, "semester" TEXT, "status" TEXT DEFAULT 'Open',
                    FOREIGN KEY (course_id) REFERENCES courses(id),
                    UNIQUE(course_id)
                );
CREATE TABLE course_outcome_modules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        outcome_id INTEGER NOT NULL REFERENCES course_learning_outcomes(id) ON DELETE CASCADE,
        module_code TEXT NOT NULL,
        module_outcome_code TEXT NOT NULL DEFAULT '',
        coverage TEXT NOT NULL CHECK (coverage IN ('introduced', 'developed', 'assessed')),
        UNIQUE (outcome_id, module_code, module_outcome_code)
    );
CREATE TABLE course_prerequisites (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course_id TEXT NOT NULL,
            prerequisite_course_id TEXT NOT NULL,
            is_required BOOLEAN DEFAULT 1,
            created_at TEXT NOT NULL, minimum_grade TEXT DEFAULT 'D', can_be_concurrent BOOLEAN DEFAULT 0, prerequisite_type TEXT DEFAULT 'Required', "prerequisite_id" INTEGER, "module_code" TEXT, "prerequisite_module_code" TEXT, "min_grade" TEXT, "is_corequisite" BOOLEAN DEFAULT 0, "prerequisite_code" TEXT, "course_code" TEXT,
            FOREIGN KEY (course_id) REFERENCES courses (id),
            FOREIGN KEY (prerequisite_course_id) REFERENCES courses (id),
            UNIQUE(course_id, prerequisite_course_id)
        );
CREATE TABLE course_recommendations (
                    recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    course_id TEXT NOT NULL,
                    recommendation_reason TEXT NOT NULL,
                    relevance_score REAL DEFAULT 0.0,
                    semester_recommended TEXT,
                    prerequisites_met BOOLEAN DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id),
                    FOREIGN KEY (course_id) REFERENCES courses(code)
                );
CREATE TABLE course_requirements (
                requirement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                course_code TEXT,
                program TEXT,
                type_id INTEGER,
                is_mandatory BOOLEAN DEFAULT 1,
                deadline_days INTEGER, "created_by" TEXT, "created_date" TEXT, "year" TEXT,
                FOREIGN KEY (type_id) REFERENCES document_types (type_id)
            );
CREATE TABLE course_restrictions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        restriction_type TEXT NOT NULL DEFAULT 'Major',
        restriction_value TEXT NOT NULL DEFAULT '',
        reserved_seats INTEGER NOT NULL DEFAULT 0,
        active INTEGER NOT NULL DEFAULT 1,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE course_saved_searches (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                name TEXT NOT NULL,
                criteria_json TEXT NOT NULL,
                created_at TEXT NOT NULL,
                UNIQUE(user_id, name)
            );
CREATE TABLE course_schedule (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_id TEXT NOT NULL,
        semester TEXT NOT NULL,
        year INTEGER NOT NULL,
        start_time TEXT,
        end_time TEXT,
        days_of_week TEXT,
        classroom TEXT,
        instructor_id INTEGER,
        created_at TEXT NOT NULL DEFAULT (datetime('now')), "course_code" TEXT, "day_of_week" TEXT, "room_id" INTEGER, "session_type" TEXT,
        FOREIGN KEY(course_id) REFERENCES courses(id),
        FOREIGN KEY(instructor_id) REFERENCES instructors(id),
        UNIQUE(course_id, semester, year)
    );
CREATE TABLE course_sections (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        course_code TEXT NOT NULL,
        term_id INTEGER NOT NULL,
        section_number TEXT NOT NULL DEFAULT '001',
        instructor TEXT DEFAULT '',
        capacity INTEGER NOT NULL DEFAULT 30,
        enrolled INTEGER NOT NULL DEFAULT 0,
        delivery_mode TEXT NOT NULL DEFAULT 'In Person',
        location TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'Open',
        notes TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        FOREIGN KEY (term_id) REFERENCES academic_terms (id),
        UNIQUE(course_code, term_id, section_number)
    );
CREATE TABLE course_sequences (
                    sequence_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    sequence_name TEXT NOT NULL,
                    program_code TEXT,
                    sequence_type TEXT DEFAULT 'Linear',
                    courses_json TEXT NOT NULL,
                    description TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE course_specifications (
        course_code TEXT PRIMARY KEY,
        award_title TEXT,
        ucas_code TEXT,
        hecos_code TEXT,
        mode_of_study TEXT,
        awarding_body TEXT,
        campus TEXT,
        typical_offer TEXT,
        required_subjects TEXT,
        english_requirement TEXT,
        pass_mark REAL CHECK (pass_mark IS NULL OR pass_mark BETWEEN 0 AND 100),
        progression_credits INTEGER CHECK (progression_credits IS NULL OR progression_credits >= 0),
        max_compensated_credits INTEGER
            CHECK (max_compensated_credits IS NULL OR max_compensated_credits >= 0),
        compensation_min_mark REAL
            CHECK (compensation_min_mark IS NULL OR compensation_min_mark BETWEEN 0 AND 100),
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE course_survey_results (
        course_code TEXT NOT NULL,
        survey TEXT NOT NULL DEFAULT 'NSS',
        academic_year TEXT NOT NULL,
        theme TEXT NOT NULL,
        agree_pct REAL NOT NULL CHECK (agree_pct BETWEEN 0 AND 100),
        respondents INTEGER CHECK (respondents IS NULL OR respondents >= 0),
        PRIMARY KEY (course_code, survey, academic_year, theme)
    );
CREATE TABLE course_team (
        course_code TEXT NOT NULL,
        username TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('leader', 'member')),
        added_by TEXT,
        added_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (course_code, username)
    );
CREATE TABLE course_waitlist (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course_id TEXT NOT NULL,
            student_id TEXT NOT NULL,
            position INTEGER NOT NULL,
            added_at TEXT NOT NULL,
            status TEXT DEFAULT 'Waiting', "module_code" TEXT,
            FOREIGN KEY (course_id) REFERENCES courses (id),
            UNIQUE(course_id, student_id)
        );
CREATE TABLE courses (
                    id TEXT PRIMARY KEY,
                    code TEXT UNIQUE NOT NULL,
                    name TEXT NOT NULL,
                    credits INTEGER DEFAULT 3,
                    department TEXT,
                    instructor_id TEXT,
                    academic_year_id TEXT,
                    semester_id INTEGER,
                    status TEXT DEFAULT 'active',
                    date_added TEXT NOT NULL, course_code TEXT, course_name TEXT, level TEXT, credit_hours INTEGER, current_enrollment INTEGER DEFAULT 0, max_enrollment INTEGER DEFAULT 30, description TEXT DEFAULT '', duration INTEGER, course_type TEXT DEFAULT 'Core', updated_at TEXT, created_at TEXT, tags TEXT, availability_periods TEXT DEFAULT 'Fall,Spring', learning_outcomes TEXT, assessment_methods TEXT, required_textbooks TEXT, course_fee REAL DEFAULT 0.0, lab_required BOOLEAN DEFAULT 0, online_available BOOLEAN DEFAULT 0, contact_hours_per_week INTEGER DEFAULT 3, min_ucas_tariff INTEGER DEFAULT 0, "last_modified" TIMESTAMP,
                    FOREIGN KEY (academic_year_id) REFERENCES academic_years (id),
                    FOREIGN KEY (semester_id) REFERENCES semesters (id)
                );
CREATE TABLE cover_assignments (
                    assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    assignee_id TEXT NOT NULL,
                    assigned_by TEXT,
                    accepted INTEGER DEFAULT 0,
                    accepted_date TEXT,
                    completed INTEGER DEFAULT 0,
                    completed_date TEXT,
                    feedback TEXT,
                    rating INTEGER,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (request_id) REFERENCES cover_requests(request_id)
                );
CREATE TABLE cover_offers (
                    offer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    volunteer_id TEXT NOT NULL,
                    message TEXT,
                    status TEXT DEFAULT 'offered',
                    offered_at TEXT DEFAULT CURRENT_TIMESTAMP, "created_at" TEXT,
                    FOREIGN KEY (request_id) REFERENCES cover_requests(request_id)
                );
CREATE TABLE cover_requests (
                    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    requester_id TEXT NOT NULL,
                    request_type TEXT DEFAULT 'teaching',
                    course_code TEXT,
                    course_name TEXT,
                    cover_date TEXT NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    location TEXT,
                    reason TEXT,
                    urgency TEXT DEFAULT 'normal',
                    status TEXT DEFAULT 'open',
                    department TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE cover_skills (
                    skill_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    skill_name TEXT NOT NULL,
                    category TEXT DEFAULT 'general',
                    proficiency TEXT DEFAULT 'intermediate',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE credential_academic_records (
    credential_id INTEGER PRIMARY KEY,
    record_type TEXT NOT NULL,
    record_id TEXT NOT NULL,
    record_hash TEXT NOT NULL,
    FOREIGN KEY (credential_id) REFERENCES blockchain_credentials(credential_id)
);
CREATE TABLE credential_network_attestations (
    attestation_id INTEGER PRIMARY KEY AUTOINCREMENT,
    credential_id INTEGER NOT NULL,
    network_name TEXT NOT NULL,
    external_id TEXT,
    status TEXT NOT NULL,
    receipt TEXT,
    published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (credential_id, network_name),
    FOREIGN KEY (credential_id) REFERENCES blockchain_credentials(credential_id)
);
CREATE TABLE credential_templates (
    template_id INTEGER PRIMARY KEY AUTOINCREMENT,
    template_name TEXT NOT NULL,
    credential_type TEXT NOT NULL,
    template_design TEXT,  -- JSON or HTML
    fields TEXT,  -- JSON array
    is_active BOOLEAN DEFAULT 1
);
CREATE TABLE credential_verifications (
    verification_id INTEGER PRIMARY KEY AUTOINCREMENT,
    credential_id INTEGER,
    badge_issuance_id INTEGER,
    verifier_name TEXT,
    verifier_email TEXT,
    verified_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    verification_method TEXT,  -- blockchain, api, manual
    FOREIGN KEY (credential_id) REFERENCES blockchain_credentials(credential_id),
    FOREIGN KEY (badge_issuance_id) REFERENCES badge_issuances(issuance_id)
);
CREATE TABLE crisis_resources (
                    resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    resource_name TEXT NOT NULL,
                    resource_type TEXT NOT NULL,
                    contact_info TEXT NOT NULL,
                    description TEXT,
                    availability TEXT DEFAULT '24/7',
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE curr_assessment_components (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    module_descriptor_id INTEGER NOT NULL,
                    name TEXT NOT NULL,
                    assessment_type TEXT,
                    weighting_pct REAL,
                    word_count INTEGER,
                    duration_minutes INTEGER,
                    week_due TEXT,
                    learning_outcomes_assessed TEXT,
                    feedback_method TEXT,
                    notes TEXT,
                    FOREIGN KEY (module_descriptor_id) REFERENCES curr_module_descriptors(id)
                );
CREATE TABLE curr_change_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    parent_type TEXT NOT NULL,
                    parent_id INTEGER NOT NULL,
                    from_version TEXT,
                    to_version TEXT,
                    change_type TEXT,
                    summary TEXT NOT NULL,
                    rationale TEXT,
                    impact TEXT,
                    proposed_by TEXT,
                    approved_by TEXT,
                    status TEXT DEFAULT 'proposed',
                    proposed_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    approved_at TEXT
                );
CREATE TABLE curr_learning_outcomes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    parent_type TEXT NOT NULL,
                    parent_id INTEGER NOT NULL,
                    code TEXT,
                    domain TEXT,
                    description TEXT NOT NULL,
                    bloom_level TEXT,
                    sort_order INTEGER DEFAULT 0
                );
CREATE TABLE curr_module_descriptors (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    programme_id INTEGER,
                    module_code TEXT NOT NULL,
                    title TEXT NOT NULL,
                    credits INTEGER,
                    level TEXT,
                    semester TEXT,
                    is_core INTEGER DEFAULT 1,
                    version TEXT DEFAULT '1.0',
                    status TEXT DEFAULT 'draft',
                    aims TEXT,
                    indicative_content TEXT,
                    teaching_methods TEXT,
                    contact_hours INTEGER,
                    independent_study_hours INTEGER,
                    prerequisites TEXT,
                    co_requisites TEXT,
                    reading_list TEXT,
                    module_leader TEXT,
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_id) REFERENCES curr_programmes(id),
                    UNIQUE(module_code, version)
                );
CREATE TABLE curr_programmes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    code TEXT NOT NULL,
                    title TEXT NOT NULL,
                    award TEXT,
                    level TEXT,
                    credits INTEGER,
                    duration_years REAL,
                    department TEXT,
                    faculty TEXT,
                    version TEXT DEFAULT '1.0',
                    status TEXT DEFAULT 'draft',
                    aims TEXT,
                    educational_aims TEXT,
                    target_qualification TEXT,
                    qaa_benchmark TEXT,
                    pedagogic_approach TEXT,
                    entry_requirements TEXT,
                    progression_routes TEXT,
                    last_review_date TEXT,
                    next_review_date TEXT,
                    approved_by TEXT,
                    approved_at TEXT,
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(code, version)
                );
CREATE TABLE currency_settings (
            setting_id INTEGER PRIMARY KEY AUTOINCREMENT,
            base_currency TEXT DEFAULT 'GBP',
            auto_update_rates BOOLEAN DEFAULT 1,
            rate_update_frequency INTEGER DEFAULT 24, -- hours
            last_rate_update TEXT,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE customer_feedback (
                    feedback_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    customer_id INTEGER,
                    customer_name TEXT,
                    order_id INTEGER,
                    rating INTEGER CHECK(rating >= 1 AND rating <= 5),
                    category TEXT,
