                    response TEXT,
                    responded_by TEXT,
                    response_date DATETIME,
                    status TEXT DEFAULT 'Pending',
                    feedback_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (customer_id) REFERENCES restaurant_customers(customer_id),
                    FOREIGN KEY (order_id) REFERENCES orders(order_id)
                );
CREATE TABLE customer_profiles (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            member_id INTEGER UNIQUE NOT NULL,
            avatar_url TEXT,
            favorite_genre TEXT,
            favorite_seats TEXT,
            preferred_snacks TEXT,
            notifications_email INTEGER DEFAULT 1,
            notifications_sms INTEGER DEFAULT 0,
            language_preference TEXT DEFAULT 'en',
            accessibility_needs TEXT, "birthday" TEXT, "created_at" TEXT, "email" TEXT, "name" TEXT, "phone" TEXT, "preferences" TEXT,
            FOREIGN KEY (member_id) REFERENCES members(id)
        );
CREATE TABLE dashboard_permissions (
                        permission_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        dashboard_id INTEGER NOT NULL,
                        user_id TEXT,
                        role TEXT,
                        can_view BOOLEAN DEFAULT 1,
                        can_edit BOOLEAN DEFAULT 0,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (dashboard_id) REFERENCES dashboards(dashboard_id) ON DELETE CASCADE
                    );
CREATE TABLE dashboard_widgets (
            widget_id INTEGER PRIMARY KEY AUTOINCREMENT,
            dashboard_id INTEGER NOT NULL,
            widget_type TEXT NOT NULL,
            widget_title TEXT NOT NULL,
            data_source TEXT,
            chart_type TEXT,
            position_x INTEGER,
            position_y INTEGER,
            width INTEGER DEFAULT 4,
            height INTEGER DEFAULT 3,
            config TEXT, "configuration" TEXT, "refresh_interval" INTEGER DEFAULT 300, "title" TEXT,
            FOREIGN KEY (dashboard_id) REFERENCES analytics_dashboards (dashboard_id)
        );
CREATE TABLE dashboards (
                        dashboard_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        name TEXT NOT NULL,
                        description TEXT,
                        owner_id TEXT NOT NULL,
                        shared BOOLEAN DEFAULT 0,
                        layout_config TEXT,
                        refresh_interval INTEGER DEFAULT 300,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE "data_access_log" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                resource_type TEXT NOT NULL,
                resource_id INTEGER,
                action TEXT NOT NULL,
                session_id INTEGER,
                ip_address TEXT,
                accessed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
            );
CREATE TABLE data_lifecycle_dispositions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        record_type TEXT NOT NULL,
        record_id TEXT NOT NULL,
        action TEXT NOT NULL,
        actor_id TEXT NOT NULL,
        disposed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE data_lifecycle_settings (
        record_type TEXT PRIMARY KEY,
        enabled INTEGER NOT NULL DEFAULT 0,
        updated_by TEXT,
        updated_at TEXT
    );
CREATE TABLE data_privacy_settings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                policy_key TEXT UNIQUE NOT NULL,
                value TEXT,
                description TEXT,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            , policy_name TEXT, status TEXT, last_updated TEXT);
CREATE TABLE data_retention (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                data_type TEXT NOT NULL,
                retention_period INTEGER NOT NULL,
                deletion_date TEXT,
                status TEXT DEFAULT 'active'
            , "cutoff" TEXT, "removed" INTEGER, "run_by" TEXT, "run_at" TEXT);
CREATE TABLE data_retention_policies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            data_type TEXT,
            retention_period_days INTEGER,
            auto_archive INTEGER DEFAULT 0,
            auto_delete INTEGER DEFAULT 0,
            created_at TEXT
        , retention_period_months INTEGER, deletion_method TEXT DEFAULT 'soft', last_cleanup_date TEXT, is_active BOOLEAN DEFAULT 1, updated_at TEXT, "policy_id" INTEGER);
CREATE TABLE degree_course_prerequisites (
                prerequisite_id INTEGER PRIMARY KEY AUTOINCREMENT,
                module_code TEXT NOT NULL,
                prerequisite_module_code TEXT NOT NULL,
                min_grade TEXT,
                is_corequisite INTEGER DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE(module_code, prerequisite_module_code)
            );
CREATE TABLE degree_milestones (
                    milestone_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    program_code TEXT NOT NULL,
                    milestone_name TEXT NOT NULL,
                    milestone_type TEXT NOT NULL,
                    required_credits INTEGER DEFAULT 0,
                    required_gpa REAL DEFAULT 0.0,
                    typical_semester INTEGER DEFAULT 1,
                    description TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE degree_plans (
                    plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    advisor_id TEXT,
                    plan_name TEXT NOT NULL,
                    target_graduation TEXT,
                    total_credits_required INTEGER DEFAULT 120,
                    credits_completed INTEGER DEFAULT 0,
                    notes TEXT DEFAULT '',
                    created_date TEXT DEFAULT (date('now')),
                    last_updated TEXT DEFAULT (date('now')),
                    status TEXT DEFAULT 'active'
                );
CREATE TABLE degree_program_courses (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    program_code TEXT NOT NULL,
                    course_id TEXT NOT NULL,
                    requirement_type TEXT DEFAULT 'Core',
                    year_level INTEGER DEFAULT 1,
                    semester_offered TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(program_code, course_id)
                );
CREATE TABLE degree_programs (
                program_id INTEGER PRIMARY KEY AUTOINCREMENT,
                program_code TEXT UNIQUE NOT NULL,
                program_name TEXT NOT NULL,
                degree_type TEXT NOT NULL,
                department TEXT,
                total_credits_required INTEGER NOT NULL,
                min_gpa_required REAL DEFAULT 2.0,
                max_years_allowed INTEGER DEFAULT 4,
                description TEXT,
                is_active INTEGER DEFAULT 1,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            , "updated_at" TIMESTAMP DEFAULT NULL, "duration_years" INTEGER);
CREATE TABLE degree_programs_test (
                program_id INTEGER PRIMARY KEY AUTOINCREMENT,
                program_code TEXT UNIQUE NOT NULL,
                program_name TEXT NOT NULL
            );
CREATE TABLE degree_requirements (
                requirement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                program_id INTEGER NOT NULL,
                requirement_type TEXT NOT NULL,
                requirement_name TEXT NOT NULL,
                credits_required INTEGER NOT NULL,
                description TEXT,
                min_grade TEXT,
                is_mandatory INTEGER DEFAULT 1,
                display_order INTEGER DEFAULT 0, "module_code" TEXT,
                FOREIGN KEY (program_id) REFERENCES degree_programs(program_id) ON DELETE CASCADE
            );
CREATE TABLE degree_requirements_test (
                requirement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                program_id INTEGER NOT NULL
            );
CREATE TABLE degree_what_if_scenarios (
                scenario_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                scenario_name TEXT NOT NULL,
                target_program_id INTEGER NOT NULL,
                notes TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (target_program_id) REFERENCES degree_programs(program_id)
            );
CREATE TABLE "delegated_access" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                grantor_user_id INTEGER NOT NULL,
                delegate_user_id INTEGER NOT NULL,
                relationship TEXT NOT NULL,
                scope_json TEXT NOT NULL,
                is_active BOOLEAN DEFAULT 1,
                granted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP,
                revoked_at TIMESTAMP,
                revoked_by INTEGER, "created_at" TEXT, "status" TEXT DEFAULT 'active', "updated_at" TEXT,
                FOREIGN KEY (grantor_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (delegate_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (revoked_by) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "delegated_access_audit" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                delegation_id INTEGER NOT NULL,
                delegate_user_id INTEGER NOT NULL,
                target_user_id INTEGER NOT NULL,
                action TEXT NOT NULL,
                resource_type TEXT,
                accessed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "created_at" TEXT,
                FOREIGN KEY (delegation_id) REFERENCES delegated_access(id) ON DELETE CASCADE,
                FOREIGN KEY (delegate_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "delegated_access_requests" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                requester_user_id INTEGER NOT NULL,
                target_user_id INTEGER NOT NULL,
                relationship TEXT NOT NULL,
                requested_scope_json TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'pending'
                    CHECK(status IN ('pending', 'approved', 'rejected', 'cancelled')),
                supporting_documents TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                resolved_at TIMESTAMP,
                resolved_by INTEGER, "scope_json" TEXT, "updated_at" TEXT, "reason" TEXT,
                FOREIGN KEY (requester_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (resolved_by) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "delivery_logs" (
    log_id INTEGER PRIMARY KEY AUTOINCREMENT,
