                    prescription_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    patient_id INTEGER NOT NULL,
                    dentist_id TEXT NOT NULL,
                    dentist_name TEXT NOT NULL,
                    treatment_id INTEGER,
                    medication TEXT NOT NULL,
                    dosage TEXT NOT NULL,
                    frequency TEXT NOT NULL,
                    duration TEXT NOT NULL,
                    instructions TEXT,
                    prescribed_date DATE NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (patient_id) REFERENCES dentist_patients(patient_id),
                    FOREIGN KEY (treatment_id) REFERENCES dentist_treatments(treatment_id)
                );
CREATE TABLE dentist_records (
                    record_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    patient_id INTEGER NOT NULL,
                    record_type TEXT NOT NULL,
                    record_date DATE NOT NULL,
                    description TEXT,
                    file_path TEXT,
                    created_by TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (patient_id) REFERENCES dentist_patients(patient_id)
                );
CREATE TABLE dentist_treatments (
                    treatment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    appointment_id INTEGER,
                    patient_id INTEGER NOT NULL,
                    dentist_id TEXT NOT NULL,
                    dentist_name TEXT NOT NULL,
                    treatment_type TEXT NOT NULL,
                    treatment_date DATE NOT NULL,
                    tooth_number TEXT,
                    description TEXT,
                    fee DECIMAL(10,2) NOT NULL,
                    payment_status TEXT DEFAULT 'pending',
                    notes TEXT,
                    follow_up_required INTEGER DEFAULT 0,
                    follow_up_date DATE,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, procedure_notes TEXT, "diagnosis" TEXT,
                    FOREIGN KEY (appointment_id) REFERENCES dentist_appointments(appointment_id),
                    FOREIGN KEY (patient_id) REFERENCES dentist_patients(patient_id)
                );
