    updated_at TEXT,
    last_run_at TEXT,
    last_result TEXT
);
CREATE TABLE document_repository (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL CHECK(length(title) > 0),
