                    word_count INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "submission_id" INTEGER, "assignment_id" INTEGER, "student_id" TEXT, "academic_year" TEXT, "kind" TEXT DEFAULT 'submission', "purged" INTEGER DEFAULT 0, "source_url" TEXT,
                    FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE CASCADE,
                    FOREIGN KEY (module_code) REFERENCES modules (module_code) ON DELETE SET NULL
                );
