            employer_match_amount REAL DEFAULT 0.0,
            recognition_level TEXT, is_gift_aided INTEGER DEFAULT 0, "campaign_name" TEXT, "goal_amount" REAL, "donor_name" TEXT, "status" TEXT DEFAULT 'received', "gift_aid_declaration_id" INTEGER, "gift_aid_claim_id" INTEGER, "gift_aid_adjusted_in" INTEGER, "pledge_id" INTEGER, "receipt_number" TEXT, "thanked_at" TEXT, "refunded_at" TEXT, "refund_reason" TEXT, "finance_payment_id" INTEGER, "recorded_by" TEXT,
