                    student_id TEXT NOT NULL,
                    letter_type TEXT NOT NULL,
                    reference_code TEXT UNIQUE NOT NULL,
                    verification_token TEXT UNIQUE NOT NULL,
                    content TEXT NOT NULL,
                    issued_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    issued_by TEXT,
                    valid_until TEXT,
                    revoked INTEGER DEFAULT 0,
                    revoked_reason TEXT,
                    FOREIGN KEY(request_id) REFERENCES enrolment_letter_requests(id)
                );
CREATE TABLE enrolment_status_changes (
        change_id        INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id       TEXT NOT NULL,
        module_code      TEXT NOT NULL,
        from_status      TEXT,
        to_status        TEXT NOT NULL,
        changed_at       TEXT NOT NULL DEFAULT (datetime('now')),
        changed_by       TEXT,
        period_id        INTEGER,
        phase            TEXT,
        deadline_applied TEXT,
        source           TEXT,
        note             TEXT
    );
CREATE TABLE equipment (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            equipment_type TEXT NOT NULL,
            screen_number INTEGER,
            brand TEXT,
            model TEXT,
            serial_number TEXT,
            install_date TEXT,
            warranty_until TEXT,
            last_service_date TEXT,
            next_service_due TEXT,
            hours_used INTEGER DEFAULT 0,
            max_hours_before_service INTEGER DEFAULT 2000,
            status TEXT DEFAULT 'operational',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , "category_id" INTEGER, "building" TEXT, "description" TEXT, "location" TEXT, "manufacturer" TEXT, "max_booking_hours" INTEGER, "min_booking_hours" INTEGER, "requires_approval" TEXT, "requires_training" TEXT, "room_number" INTEGER, "updated_at" TEXT);
CREATE TABLE equipment_bookings (
                    booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    equipment_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    booking_date TEXT NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    purpose TEXT,
                    status TEXT DEFAULT 'pending',
                    approved_by TEXT,
                    approved_date TEXT,
                    checked_in_at TEXT,
                    checked_out_at TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (equipment_id) REFERENCES lab_equipment(equipment_id)
                );
CREATE TABLE equipment_categories (
                    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    parent_category_id INTEGER,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (parent_category_id) REFERENCES equipment_categories(category_id)
                );
CREATE TABLE "equipment_checkouts" (
            checkout_id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_id INTEGER,
            borrower_id TEXT,
            club_id INTEGER,
            checkout_date TEXT,
            expected_return TEXT,
            actual_return TEXT,
            condition_out TEXT,
            condition_in TEXT,
            notes TEXT,
            status TEXT DEFAULT 'checked_out',
            FOREIGN KEY (equipment_id) REFERENCES union_equipment (equipment_id),
            FOREIGN KEY (club_id) REFERENCES student_clubs (club_id)
        );
CREATE TABLE equipment_inventory (
    equipment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    equipment_code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    description TEXT,
    daily_rate REAL NOT NULL,
    quantity_available INTEGER DEFAULT 1,
    quantity_total INTEGER DEFAULT 1,
    condition TEXT DEFAULT 'Good',
    created_date TEXT NOT NULL
);
CREATE TABLE equipment_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_code TEXT UNIQUE NOT NULL,
                    name TEXT NOT NULL,
                    description TEXT,
                    category TEXT NOT NULL,
                    brand TEXT,
                    model TEXT,
                    serial_number TEXT,
                    daily_rate DECIMAL(10,2) NOT NULL,
                    hourly_rate DECIMAL(10,2),
                    deposit_required DECIMAL(10,2) DEFAULT 0,
                    quantity_total INTEGER DEFAULT 1,
                    quantity_available INTEGER DEFAULT 1,
                    condition TEXT DEFAULT 'good',
                    location TEXT,
                    image_path TEXT,
                    notes TEXT,
                    requires_training INTEGER DEFAULT 0,
                    is_active INTEGER DEFAULT 1,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE equipment_maintenance (
                    maintenance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_id INTEGER NOT NULL,
                    maintenance_type TEXT NOT NULL,
                    description TEXT,
                    cost DECIMAL(10,2) DEFAULT 0,
                    performed_date TEXT NOT NULL,
                    next_maintenance_date TEXT,
                    performed_by TEXT,
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "equipment_id" INTEGER, "scheduled_date" TEXT, "status" TEXT DEFAULT 'scheduled', "completed_date" TEXT, "next_due_date" TEXT, "updated_at" TEXT,
                    FOREIGN KEY (item_id) REFERENCES equipment_items(item_id)
                );
CREATE TABLE equipment_maintenance_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_id INTEGER NOT NULL,
            maintenance_type TEXT NOT NULL,
            description TEXT,
            performed_by TEXT,
            cost REAL DEFAULT 0,
            parts_replaced TEXT,
            hours_at_service INTEGER,
            next_service_hours INTEGER,
            service_date TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (equipment_id) REFERENCES equipment(id)
        );
CREATE TABLE equipment_rentals (
                    rental_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    rental_number TEXT UNIQUE NOT NULL,
                    item_id INTEGER NOT NULL,
                    quantity INTEGER DEFAULT 1,
                    borrower_id TEXT NOT NULL,
                    borrower_name TEXT NOT NULL,
                    borrower_email TEXT,
                    borrower_phone TEXT,
                    borrower_department TEXT,
                    purpose TEXT,
                    checkout_date TEXT NOT NULL,
                    checkout_time TEXT NOT NULL,
                    due_date TEXT NOT NULL,
                    due_time TEXT NOT NULL,
                    actual_return_date TEXT,
                    actual_return_time TEXT,
                    daily_rate DECIMAL(10,2) NOT NULL,
                    total_days INTEGER NOT NULL,
                    subtotal DECIMAL(10,2) NOT NULL,
                    deposit_amount DECIMAL(10,2) DEFAULT 0,
                    late_fee DECIMAL(10,2) DEFAULT 0,
                    damage_fee DECIMAL(10,2) DEFAULT 0,
                    total_amount DECIMAL(10,2) NOT NULL,
                    payment_status TEXT DEFAULT 'pending',
                    payment_method TEXT,
                    status TEXT DEFAULT 'reserved',
                    condition_checkout TEXT,
                    condition_return TEXT,
                    notes TEXT,
                    created_by TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "created_date" TEXT, "customer_email" TEXT, "customer_name" TEXT, "customer_phone" TEXT, "equipment_id" INTEGER, "expected_return_date" TEXT, "rental_date" TEXT, "rental_status" TEXT DEFAULT 'Active', "student_id" TEXT, "total_cost" REAL, "return_date" TEXT,
                    FOREIGN KEY (item_id) REFERENCES equipment_items(item_id)
                );
CREATE TABLE equipment_reservations (
                    reservation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_id INTEGER NOT NULL,
                    borrower_id TEXT NOT NULL,
                    borrower_name TEXT NOT NULL,
                    requested_date TEXT NOT NULL,
                    requested_duration INTEGER DEFAULT 1,
                    status TEXT DEFAULT 'pending',
                    priority INTEGER DEFAULT 5,
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (item_id) REFERENCES equipment_items(item_id)
                );
CREATE TABLE escalation_rules (
            rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT,
            priority TEXT,
            condition_type TEXT NOT NULL,  -- time_based, status_based, keyword_based
            condition_value TEXT NOT NULL,
            action_type TEXT NOT NULL,  -- escalate, reassign, notify
            action_target TEXT NOT NULL,
            is_active BOOLEAN DEFAULT 1,
            created_by TEXT NOT NULL,
            created_datetime TEXT NOT NULL
        );
CREATE TABLE ethics_conditions (
        condition_id INTEGER PRIMARY KEY AUTOINCREMENT,
        review_id INTEGER NOT NULL REFERENCES ethics_reviews(review_id) ON DELETE CASCADE,
        condition_text TEXT NOT NULL,
        met_at TEXT,
        met_by TEXT,
        evidence TEXT
    );
CREATE TABLE ethics_reviewer_allocations (
        allocation_id INTEGER PRIMARY KEY AUTOINCREMENT,
        review_id INTEGER NOT NULL REFERENCES ethics_reviews(review_id) ON DELETE CASCADE,
        reviewer TEXT NOT NULL,
        allocated_by TEXT,
        allocated_at TEXT NOT NULL DEFAULT (datetime('now')),
        status TEXT NOT NULL DEFAULT 'allocated'
            CHECK (status IN ('allocated', 'conflicted', 'completed', 'withdrawn')),
        conflict_detail TEXT,
        recommendation TEXT CHECK (recommendation IS NULL OR recommendation IN
            ('approve', 'approve_with_conditions', 'revise', 'reject')),
        comments TEXT,
        completed_at TEXT
    );
CREATE TABLE "ethics_reviews" (
            review_id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER,
            review_type TEXT NOT NULL,
            submission_date TEXT NOT NULL,
            review_date TEXT,
            decision TEXT DEFAULT 'pending',
            decision_date TEXT,
            reviewer_comments TEXT,
            conditions TEXT,
            approval_expiry_date TEXT,
            reference TEXT,
            title TEXT,
            principal_investigator_id TEXT,
            department TEXT,
            risk_level TEXT,
            category TEXT,
            notes TEXT, "kind" TEXT DEFAULT 'application', "parent_review_id" INTEGER, "applicant_id" TEXT, "supervisor_id" TEXT, "supervisor_endorsed_by" TEXT, "supervisor_endorsed_at" TEXT, "route" TEXT, "summary" TEXT, "participants" TEXT, "data_handling" TEXT, "start_date" TEXT, "end_date" TEXT, "decided_by" TEXT, "created_by" TEXT, "updated_at" TEXT,
            FOREIGN KEY (project_id) REFERENCES research_projects (project_id)
        );
CREATE TABLE eval_form_answers (
                id INTEGER PRIMARY KEY AUTOINCREMENT, response_id INTEGER NOT NULL,
                question_id INTEGER NOT NULL, rating_value INTEGER, text_value TEXT,
                FOREIGN KEY (response_id) REFERENCES eval_form_responses(id),
                FOREIGN KEY (question_id) REFERENCES eval_form_questions(id));
CREATE TABLE eval_form_comment_reviews (
        answer_id INTEGER PRIMARY KEY REFERENCES eval_form_answers(id),
        reason TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'released', 'withheld')),
        reviewed_by TEXT,
        reviewed_at TEXT
    );
CREATE TABLE eval_form_invitations (
        form_id INTEGER NOT NULL REFERENCES evaluation_forms(id),
        student_id TEXT NOT NULL,
        invited_at TEXT NOT NULL DEFAULT (date('now')),
        reminded_at TEXT,
        responded INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (form_id, student_id)
    );
CREATE TABLE eval_form_questions (
                id INTEGER PRIMARY KEY AUTOINCREMENT, form_id INTEGER NOT NULL,
                question_text TEXT NOT NULL, question_type TEXT DEFAULT 'rating',
                options TEXT, display_order INTEGER DEFAULT 0,
                is_required INTEGER DEFAULT 1, "scope" TEXT DEFAULT 'module', "staff_username" TEXT, "source" TEXT DEFAULT 'standard',
                FOREIGN KEY (form_id) REFERENCES evaluation_forms(id));
CREATE TABLE eval_form_responses (
                id INTEGER PRIMARY KEY AUTOINCREMENT, form_id INTEGER NOT NULL,
                student_hash TEXT NOT NULL, submitted_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (form_id) REFERENCES evaluation_forms(id));
CREATE TABLE eval_form_responses_to_students (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        form_id INTEGER NOT NULL REFERENCES evaluation_forms(id),
        summary TEXT NOT NULL,
        actions TEXT,
        you_said TEXT,
        we_did TEXT,
        published INTEGER NOT NULL DEFAULT 0,
        author TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        published_at TEXT
    );
CREATE TABLE evaluation_ab_assignments (
                assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                ab_id INTEGER NOT NULL,
                response_id INTEGER NOT NULL,
                variant CHAR(1) NOT NULL,
                UNIQUE(ab_id, response_id)
            );
CREATE TABLE evaluation_ab_tests (
                ab_id INTEGER PRIMARY KEY AUTOINCREMENT,
                question_id INTEGER NOT NULL,
                variant_a TEXT NOT NULL,
                variant_b TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_accessibility_audits (
                audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_id INTEGER NOT NULL,
                rule TEXT NOT NULL,
                severity TEXT NOT NULL,
                message TEXT NOT NULL,
                question_id INTEGER,
                checked_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (template_id) REFERENCES evaluation_templates(template_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_anonymity_audit (
                audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
                actor TEXT NOT NULL,
                action TEXT NOT NULL,
                detail TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_answers (
                answer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                response_id INTEGER NOT NULL,
                question_id INTEGER NOT NULL,
                answer_value TEXT,
                numeric_value REAL,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (response_id) REFERENCES evaluation_responses(response_id) ON DELETE CASCADE,
                FOREIGN KEY (question_id) REFERENCES evaluation_questions(question_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_approvals (
                approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_id INTEGER NOT NULL,
                stage TEXT NOT NULL DEFAULT 'draft',
                actor TEXT,
                comment TEXT,
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (template_id) REFERENCES evaluation_templates(template_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_bias_findings (
                finding_id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_id INTEGER,
                question_id INTEGER,
                category TEXT NOT NULL,
                snippet TEXT NOT NULL,
                suggestion TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_calendar_holds (
                hold_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                instructor_id TEXT NOT NULL,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_dashboards (
                dashboard_id INTEGER PRIMARY KEY AUTOINCREMENT,
                owner TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT '*',
                name TEXT NOT NULL,
                layout_json TEXT NOT NULL,
                updated_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_demographics (
                demo_id INTEGER PRIMARY KEY AUTOINCREMENT,
                response_id INTEGER NOT NULL,
                dimension TEXT NOT NULL,
                value TEXT NOT NULL,
                FOREIGN KEY (response_id) REFERENCES evaluation_responses(response_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_drafts (
                draft_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                respondent_token TEXT NOT NULL,
                answers_json TEXT NOT NULL,
                updated_at TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE(evaluation_id, respondent_token),
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_forms (
                id INTEGER PRIMARY KEY AUTOINCREMENT, module_code TEXT NOT NULL,
                module_name TEXT NOT NULL, academic_year TEXT NOT NULL, semester TEXT,
                status TEXT DEFAULT 'draft', created_by TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP, closes_at TEXT,
                is_anonymous INTEGER DEFAULT 1, "opens_at" TEXT, "min_responses" INTEGER DEFAULT 5, "opened_by" TEXT);
CREATE TABLE evaluation_gdpr_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                subject_token TEXT NOT NULL,
                kind TEXT NOT NULL,
                payload_json TEXT,
                status TEXT NOT NULL DEFAULT 'pending',
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                completed_at TEXT
            );
CREATE TABLE evaluation_hr_exports (
                export_id INTEGER PRIMARY KEY AUTOINCREMENT,
                instructor_id TEXT NOT NULL,
                academic_year TEXT NOT NULL,
                aggregate_json TEXT NOT NULL,
                exported_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_imports (
                import_id INTEGER PRIMARY KEY AUTOINCREMENT,
                source_path TEXT NOT NULL,
                rows_seen INTEGER, rows_imported INTEGER, rows_errored INTEGER,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_improvement_plans (
                plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                template_id INTEGER,
                body TEXT NOT NULL,
                author TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_improvement_templates (
                imp_template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                body TEXT NOT NULL,
                trigger_below_score REAL
            );
CREATE TABLE evaluation_instructor_replies (
                reply_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                theme TEXT,
                reply_text TEXT NOT NULL,
                posted_by TEXT,
                posted_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_invitations (
                invite_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                recipient_id TEXT NOT NULL,
                cohort TEXT,
                token TEXT NOT NULL UNIQUE,
                used INTEGER DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                used_at TEXT,
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_lms_links (
                link_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                lms TEXT NOT NULL,
                deep_link_url TEXT NOT NULL,
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_mfa_gates (
                gate_id INTEGER PRIMARY KEY AUTOINCREMENT,
                route TEXT NOT NULL UNIQUE,
                required INTEGER DEFAULT 1
            );
CREATE TABLE evaluation_pulse_responses (
                pulse_resp_id INTEGER PRIMARY KEY AUTOINCREMENT,
                pulse_id INTEGER NOT NULL,
                respondent_hash TEXT NOT NULL,
                rating_value INTEGER,
                text_value TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (pulse_id) REFERENCES evaluation_pulses(pulse_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_pulses (
                pulse_id INTEGER PRIMARY KEY AUTOINCREMENT,
                module_code TEXT NOT NULL,
                question_text TEXT NOT NULL,
                question_type TEXT NOT NULL DEFAULT 'likert',
                cadence_days INTEGER NOT NULL DEFAULT 7,
                next_run TEXT,
                active INTEGER DEFAULT 1,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_question_bank (
                bank_id INTEGER PRIMARY KEY AUTOINCREMENT,
                question_text TEXT NOT NULL,
                question_type TEXT NOT NULL DEFAULT 'likert',
                question_category TEXT,
                scale_min INTEGER DEFAULT 1,
                scale_max INTEGER DEFAULT 5,
                options_json TEXT,
                department TEXT,
                created_by TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_question_locales (
                locale_id INTEGER PRIMARY KEY AUTOINCREMENT,
                question_id INTEGER NOT NULL,
                locale TEXT NOT NULL,
                question_text TEXT NOT NULL,
                aria_label TEXT,
                options_json TEXT,
                UNIQUE(question_id, locale),
                FOREIGN KEY (question_id) REFERENCES evaluation_questions(question_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_question_tags (
                tag_id INTEGER PRIMARY KEY AUTOINCREMENT,
                bank_id INTEGER NOT NULL,
                tag TEXT NOT NULL,
                UNIQUE(bank_id, tag),
                FOREIGN KEY (bank_id) REFERENCES evaluation_question_bank(bank_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_questions (
                question_id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_id INTEGER NOT NULL,
                question_text TEXT NOT NULL,
                question_type TEXT NOT NULL,
                question_category TEXT,
                scale_min INTEGER DEFAULT 1,
                scale_max INTEGER DEFAULT 5,
                display_order INTEGER DEFAULT 0,
                is_required INTEGER DEFAULT 1, "options" TEXT, options_json TEXT, bank_id INTEGER, parent_question_id INTEGER, show_if_value TEXT, show_if_op TEXT, aria_label TEXT,
                FOREIGN KEY (template_id) REFERENCES evaluation_templates(template_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_red_flag_rules (
                rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                category TEXT NOT NULL,
                pattern TEXT NOT NULL,
                route_to TEXT NOT NULL
            );
CREATE TABLE evaluation_red_flags (
                flag_id INTEGER PRIMARY KEY AUTOINCREMENT,
                answer_id INTEGER NOT NULL,
                category TEXT NOT NULL,
                pattern TEXT,
                routed_to TEXT,
                acknowledged INTEGER DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (answer_id) REFERENCES evaluation_answers(answer_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_redaction_rules (
                rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                pattern TEXT NOT NULL,
                replacement TEXT NOT NULL DEFAULT '[redacted]',
                kind TEXT NOT NULL DEFAULT 'regex',
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_reminders (
                reminder_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                offset_days INTEGER NOT NULL,
                channel TEXT NOT NULL DEFAULT 'email',
                message TEXT,
                sent_at TEXT,
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_response_flags (
                flag_id INTEGER PRIMARY KEY AUTOINCREMENT,
                response_id INTEGER NOT NULL,
                flag TEXT NOT NULL,
                score REAL,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (response_id) REFERENCES evaluation_responses(response_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_responses (
                response_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                student_id TEXT,
                is_complete INTEGER DEFAULT 0,
                is_anonymous INTEGER DEFAULT 1,
                time_taken_minutes INTEGER,
                submitted_at TEXT DEFAULT (datetime('now')), "response_date" TIMESTAMP DEFAULT NULL,
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_results (
                result_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                question_id INTEGER NOT NULL,
                average_score REAL,
                response_count INTEGER,
                calculated_at TEXT NOT NULL DEFAULT (datetime('now')), "median_score" REAL, "mode_score" REAL, "percentile_25" REAL, "percentile_75" REAL, "standard_deviation" REAL,
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE,
                FOREIGN KEY (question_id) REFERENCES evaluation_questions(question_id) ON DELETE CASCADE,
                UNIQUE(evaluation_id, question_id)
            );
CREATE TABLE evaluation_retention_policies (
                policy_id INTEGER PRIMARY KEY AUTOINCREMENT,
                target TEXT NOT NULL,
                keep_days INTEGER NOT NULL,
                keep_aggregates INTEGER DEFAULT 1,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_review_queue (
                queue_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                reviewer TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'pending',
                comment TEXT,
                signed_off_at TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_role_redactions (
                redaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                role TEXT NOT NULL,
                field TEXT NOT NULL,
                action TEXT NOT NULL DEFAULT 'hide'
            );
CREATE TABLE evaluation_rosters (
                roster_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                UNIQUE(evaluation_id, student_id),
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_sentiment (
                sentiment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                answer_id INTEGER NOT NULL UNIQUE,
                polarity REAL NOT NULL,
                label TEXT NOT NULL,
                FOREIGN KEY (answer_id) REFERENCES evaluation_answers(answer_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_settings (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL
            );
CREATE TABLE evaluation_significance (
                sig_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                question_id INTEGER,
                comparison TEXT NOT NULL,
                n INTEGER NOT NULL,
                statistic REAL,
                p_value REAL,
                significant INTEGER,
                computed_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (evaluation_id) REFERENCES course_evaluations(evaluation_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_sis_sync_log (
                sync_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER NOT NULL,
                added INTEGER, removed INTEGER, total INTEGER,
                synced_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_template_versions (
                version_id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_id INTEGER NOT NULL,
                version_number INTEGER NOT NULL,
                snapshot_json TEXT NOT NULL,
                change_summary TEXT,
                changed_by TEXT,
                changed_at TEXT NOT NULL DEFAULT (datetime('now')),
                UNIQUE(template_id, version_number),
                FOREIGN KEY (template_id) REFERENCES evaluation_templates(template_id) ON DELETE CASCADE
            );
CREATE TABLE evaluation_templates (
                template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_name TEXT NOT NULL,
                template_type TEXT NOT NULL,
                description TEXT,
                created_by TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                is_active INTEGER DEFAULT 1
            , "is_default" BOOLEAN DEFAULT 0, deleted_at TEXT);
CREATE TABLE evaluation_webhook_log (
                log_id INTEGER PRIMARY KEY AUTOINCREMENT,
                hook_id INTEGER,
                event TEXT NOT NULL,
                payload_json TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );
CREATE TABLE evaluation_webhooks (
                hook_id INTEGER PRIMARY KEY AUTOINCREMENT,
                event TEXT NOT NULL,
                url TEXT NOT NULL,
                secret TEXT,
                active INTEGER DEFAULT 1
            );
CREATE TABLE evaluation_youssaid_wedid (
                ysw_id INTEGER PRIMARY KEY AUTOINCREMENT,
                evaluation_id INTEGER,
                theme TEXT NOT NULL,
                you_said TEXT NOT NULL,
                we_did TEXT,
                status TEXT NOT NULL DEFAULT 'open',
                owner TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                resolved_at TEXT
            );
CREATE TABLE evaluations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                course_id TEXT NOT NULL,
                student_id TEXT NOT NULL,
                teaching_quality INTEGER NOT NULL,
                course_content INTEGER NOT NULL,
                workload INTEGER NOT NULL,
                communication INTEGER NOT NULL,
                overall INTEGER NOT NULL,
                comments TEXT,
                submitted_at TEXT NOT NULL,
                FOREIGN KEY (course_id) REFERENCES courses(id)
            );
CREATE TABLE "event_announcements" (
            announcement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER NOT NULL,
            announcement_text TEXT NOT NULL,
            sent_to TEXT NOT NULL,
            sent_at TEXT DEFAULT CURRENT_TIMESTAMP,
            sent_by TEXT
        );
CREATE TABLE event_calendar_subscriptions (
            subscription_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            calendar_feed_url TEXT NOT NULL,
            filter_categories TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE event_categories (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT UNIQUE NOT NULL,
                    color_code TEXT,
                    description TEXT,
                    date_added TEXT NOT NULL
                );
CREATE TABLE "event_dependencies" (
                    id TEXT PRIMARY KEY,
                    prerequisite_event_id TEXT NOT NULL,
                    dependent_event_id TEXT NOT NULL,
                    dependency_type TEXT NOT NULL,
                    delay_days INTEGER DEFAULT 0,
                    delay_hours INTEGER DEFAULT 0,
                    is_mandatory BOOLEAN DEFAULT TRUE,
                    created_at TEXT NOT NULL, "depends_on_event_id" INTEGER, "event_id" INTEGER, "lag_days" INTEGER DEFAULT 0,
                    FOREIGN KEY (prerequisite_event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE,
                    FOREIGN KEY (dependent_event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE,
                    UNIQUE(prerequisite_event_id, dependent_event_id)
                );
CREATE TABLE event_expenses (
                expense_id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_name TEXT NOT NULL,
                category TEXT NOT NULL,
                amount REAL NOT NULL,
                date TEXT NOT NULL,
                vendor TEXT,
                receipt_number TEXT,
                has_receipt BOOLEAN,
                notes TEXT,
                recorded_by TEXT,
                recorded_date TEXT
            );
CREATE TABLE "event_finances" (
            finance_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER,
            expense_type TEXT,
            amount REAL,
            description TEXT,
            date_recorded TEXT,
            receipt_path TEXT,
            revenue_type TEXT, "category" TEXT, "created_at" TEXT, "transaction_date" TEXT, "transaction_type" TEXT, "vendor" TEXT, "entry_date" TEXT, "entry_type" TEXT,
            FOREIGN KEY (event_id) REFERENCES unified_events(event_id)
        );
CREATE TABLE event_income (
                income_id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_name TEXT NOT NULL,
                source TEXT NOT NULL,
                amount REAL NOT NULL,
                date TEXT NOT NULL,
                payment_method TEXT,
                notes TEXT,
                recorded_by TEXT,
                recorded_date TEXT
            );
CREATE TABLE "event_notifications" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_id TEXT NOT NULL,
                user_id TEXT,
                notification_type TEXT NOT NULL,
                send_at TEXT NOT NULL,
                sent BOOLEAN DEFAULT 0,
                sent_at TEXT,
                created_at TEXT NOT NULL,
    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id)
            );
CREATE TABLE "event_sequences" (
                    id TEXT PRIMARY KEY,
                    workflow_id TEXT NOT NULL,
                    event_id TEXT NOT NULL,
                    sequence_order INTEGER NOT NULL,
                    completion_status TEXT DEFAULT 'pending',
                    completion_date TEXT,
                    FOREIGN KEY (workflow_id) REFERENCES event_workflows (id) ON DELETE CASCADE,
                    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE
                );
CREATE TABLE event_series (
            series_id INTEGER PRIMARY KEY AUTOINCREMENT,
            series_name TEXT NOT NULL,
            series_description TEXT,
            organizer_id TEXT NOT NULL,
            recurrence_pattern TEXT NOT NULL,
            start_date TEXT NOT NULL,
            end_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE "event_sponsors" (
            sponsor_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER NOT NULL,
            sponsor_name TEXT NOT NULL,
            sponsor_type TEXT,
            contribution_amount REAL,
            logo_url TEXT,
            website_url TEXT
        );
CREATE TABLE "event_surveys" (
            survey_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER,
            survey_title TEXT,
            questions TEXT,
            created_date TEXT
        );
CREATE TABLE "event_tag_assignments" (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_id TEXT NOT NULL,
                    tag_id INTEGER NOT NULL,
                    date_added TEXT NOT NULL,
                    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE,
                    FOREIGN KEY (tag_id) REFERENCES event_tags (id) ON DELETE CASCADE,
                    UNIQUE(event_id, tag_id)
                );
CREATE TABLE event_tags (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT UNIQUE NOT NULL,
                    color_code TEXT,
                    date_added TEXT NOT NULL
                );
CREATE TABLE event_templates (
                id TEXT PRIMARY KEY,
                template_name TEXT NOT NULL,
                template_data TEXT NOT NULL,
                created_by TEXT,
                created_at TEXT NOT NULL,
                is_active BOOLEAN DEFAULT TRUE
            );
CREATE TABLE event_ticket_types (
                ticket_type_id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_name TEXT NOT NULL,
                type_name TEXT NOT NULL,
                price REAL NOT NULL,
                total_quantity INTEGER NOT NULL,
                sold_quantity INTEGER DEFAULT 0,
                sale_start_date TEXT,
                sale_end_date TEXT,
                description TEXT,
                created_by TEXT,
                created_date TEXT
            );
CREATE TABLE "event_tickets" (
            ticket_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER,
            ticket_type TEXT,
            price REAL,
            quantity_available INTEGER,
            quantity_sold INTEGER DEFAULT 0,
            student_id TEXT,
            purchase_date TEXT,
            payment_status TEXT DEFAULT 'pending',
            FOREIGN KEY (event_id) REFERENCES unified_events(event_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE "event_timezones" (
                    event_id TEXT PRIMARY KEY,
                    timezone_name TEXT NOT NULL,
                    utc_offset_hours INTEGER NOT NULL,
                    is_dst_active BOOLEAN DEFAULT FALSE,
                    created_at TEXT NOT NULL,
                    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE
                );
CREATE TABLE event_workflows (
                    id TEXT PRIMARY KEY,
                    workflow_name TEXT NOT NULL,
                    description TEXT,
                    template_data TEXT,
                    is_active BOOLEAN DEFAULT TRUE,
                    created_by TEXT,
                    created_at TEXT NOT NULL
                );
CREATE TABLE exam_accommodations (
    accommodation_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    exam_id INTEGER,
    extended_time INTEGER,  -- minutes
    separate_room BOOLEAN DEFAULT 0,
    assistive_technology TEXT,
    reader_scribe BOOLEAN DEFAULT 0,
    status TEXT DEFAULT 'active', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "source_accommodation_id" INTEGER,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE exam_candidate_numbers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        assessment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        candidate_number TEXT NOT NULL,
        created_at TEXT NOT NULL,
        UNIQUE (assessment_id, student_id),
        UNIQUE (assessment_id, candidate_number),
        FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id) ON DELETE CASCADE
    );
CREATE TABLE exam_eligibility (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id      TEXT NOT NULL,
    module_code     TEXT NOT NULL,
    exam_id         INTEGER NOT NULL DEFAULT 0,
    eligible        INTEGER NOT NULL,
    attended        INTEGER,
    total_sessions  INTEGER,
    percentage      REAL,
    threshold       REAL,
    verdict         TEXT,
    computed_at     TEXT NOT NULL,
    UNIQUE(student_id, module_code, exam_id)
);
CREATE TABLE exam_external_examiners (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    exam_id INTEGER NOT NULL,
    examiner_id INTEGER NOT NULL,
    role TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    UNIQUE (exam_id, examiner_id)
);
CREATE TABLE exam_incidents (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        exam_id INTEGER NOT NULL,
        student_id TEXT,
        incident_type TEXT NOT NULL,
        description TEXT NOT NULL,
        minutes_late INTEGER,
        action_taken TEXT,
        occurred_at TEXT NOT NULL,
        reported_by TEXT,
        case_id TEXT,
        created_at TEXT NOT NULL,
        FOREIGN KEY (exam_id) REFERENCES exams (id) ON DELETE CASCADE
    );
CREATE TABLE exam_integrity_logs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            event_type TEXT NOT NULL,
            event_data_json TEXT,
            timestamp TEXT DEFAULT CURRENT_TIMESTAMP, "event_data" TEXT, "created_at" TEXT, "dismissed" TEXT, "dismissed_at" TEXT, "dismissed_by" TEXT, "dismissed_reason" TEXT,
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE exam_integrity_settings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_id INTEGER NOT NULL,
            randomize_questions INTEGER DEFAULT 0,
            randomize_answers INTEGER DEFAULT 0,
            question_count INTEGER,
            time_limit_minutes INTEGER,
            auto_submit INTEGER DEFAULT 1,
            browser_lockdown INTEGER DEFAULT 0,
            proctoring_provider TEXT,
            ip_restriction_enabled INTEGER DEFAULT 0,
            allowed_ips_json TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP, "allowed_ip_ranges" TEXT,
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
        );
CREATE TABLE exam_invigilator_zones (
                zone_id     INTEGER PRIMARY KEY AUTOINCREMENT,
                exam_id     INTEGER NOT NULL,
                invigilator TEXT NOT NULL,
                zone_label  TEXT NOT NULL,
                row_start   INTEGER,
                row_end     INTEGER,
                col_start   INTEGER,
                col_end     INTEGER,
                created_at  TEXT NOT NULL
            );
CREATE TABLE exam_invigilators (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        exam_id INTEGER NOT NULL,
        staff_id TEXT NOT NULL,
        staff_name TEXT,
        role TEXT NOT NULL DEFAULT 'invigilator',
        room TEXT,
        created_at TEXT NOT NULL,
        UNIQUE (exam_id, staff_id),
        FOREIGN KEY (exam_id) REFERENCES exams (id) ON DELETE CASCADE
    );
CREATE TABLE exam_moderation (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        assessment_id INTEGER NOT NULL,
        grade_id INTEGER NOT NULL UNIQUE,
        first_mark REAL,
        first_marker TEXT,
        second_mark REAL,
        second_marker TEXT,
        agreed_mark REAL,
        agreed_by TEXT,
        notes TEXT,
        status TEXT NOT NULL DEFAULT 'sampled',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id) ON DELETE CASCADE,
        FOREIGN KEY (grade_id) REFERENCES grades (grade_id) ON DELETE CASCADE
    );
CREATE TABLE exam_paper_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        paper_id INTEGER NOT NULL,
        from_status TEXT,
        to_status TEXT NOT NULL,
        actor TEXT,
        notes TEXT,
        changed_at TEXT NOT NULL,
        FOREIGN KEY (paper_id) REFERENCES exam_papers (id) ON DELETE CASCADE
    );
CREATE TABLE exam_papers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        exam_id INTEGER NOT NULL UNIQUE,
        status TEXT NOT NULL DEFAULT 'draft',
        setter TEXT,
        internal_checker TEXT,
        internal_checked_at TEXT,
        external_examiner TEXT,
        external_approved_at TEXT,
        print_deadline TEXT,
        printed_at TEXT,
        secured_location TEXT,
        notes TEXT,
        updated_at TEXT NOT NULL,
        FOREIGN KEY (exam_id) REFERENCES exams (id) ON DELETE CASCADE
    );
CREATE TABLE exam_portal_answers (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id      INTEGER NOT NULL,
    question_id     INTEGER NOT NULL,
    answer_text     TEXT,
    is_correct      INTEGER,
    marks_awarded   REAL,
    feedback        TEXT,
    flagged         INTEGER DEFAULT 0,
    time_spent_secs INTEGER DEFAULT 0,
    answered_at     TEXT    DEFAULT (datetime('now')),
    FOREIGN KEY (attempt_id) REFERENCES exam_portal_attempts(id),
    FOREIGN KEY (question_id) REFERENCES exam_portal_questions(id)
);
CREATE TABLE exam_portal_attempts (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    exam_id         INTEGER NOT NULL,
    student_id      TEXT    NOT NULL,
    student_name    TEXT,
    access_token    TEXT    UNIQUE,
    status          TEXT    NOT NULL DEFAULT 'in_progress',
    started_at      TEXT    NOT NULL DEFAULT (datetime('now')),
    submitted_at    TEXT,
    auto_submitted  INTEGER DEFAULT 0,
    time_remaining  INTEGER,
    ip_address      TEXT,
    integrity_flags INTEGER DEFAULT 0,
    score           REAL,
    percentage      REAL,
    passed          INTEGER,
    graded_at       TEXT,
    graded_by       TEXT, applied_accommodations TEXT, "accommodation_notes" TEXT,
    FOREIGN KEY (exam_id) REFERENCES exam_portal_exams(id)
);
CREATE TABLE exam_portal_exams (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    title           TEXT    NOT NULL,
    description     TEXT,
    module_code     TEXT,
    created_by      TEXT    NOT NULL,
    status          TEXT    NOT NULL DEFAULT 'draft',
    duration_minutes INTEGER NOT NULL DEFAULT 60,
    start_time      TEXT,
    end_time        TEXT,
    pass_mark       REAL    DEFAULT 50.0,
    total_marks     REAL    DEFAULT 100.0,
    shuffle_questions INTEGER DEFAULT 0,
    shuffle_answers   INTEGER DEFAULT 0,
    show_results    TEXT    DEFAULT 'after_submit',
    max_attempts    INTEGER DEFAULT 1,
    allow_review    INTEGER DEFAULT 1,
    auto_submit     INTEGER DEFAULT 1,
    instructions    TEXT,
    created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
    updated_at      TEXT    NOT NULL DEFAULT (datetime('now')),
    published_at    TEXT
, "room_id" INTEGER, assignment_id INTEGER, "assessment_id" INTEGER);
CREATE TABLE exam_portal_integrity_events (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    attempt_id      INTEGER NOT NULL,
    event_type      TEXT    NOT NULL,
    event_data      TEXT,
    created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (attempt_id) REFERENCES exam_portal_attempts(id)
);
CREATE TABLE exam_portal_questions (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    exam_id         INTEGER NOT NULL,
    question_type   TEXT    NOT NULL DEFAULT 'mcq',
    question_text   TEXT    NOT NULL,
    options_json    TEXT,
    correct_answer  TEXT,
    marks           REAL    NOT NULL DEFAULT 1.0,
    order_index     INTEGER DEFAULT 0,
    explanation     TEXT,
    difficulty      TEXT    DEFAULT 'medium',
    created_at      TEXT    NOT NULL DEFAULT (datetime('now')),
    FOREIGN KEY (exam_id) REFERENCES exam_portal_exams(id)
);
CREATE TABLE exam_reassessments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        original_assessment_id INTEGER NOT NULL,
        reassessment_assessment_id INTEGER NOT NULL,
        student_id TEXT NOT NULL,
        attempt_type TEXT NOT NULL,
        mark_cap_pct REAL,
        mc_claim_id INTEGER,
        created_at TEXT NOT NULL,
        created_by TEXT,
        UNIQUE (reassessment_assessment_id, student_id),
        FOREIGN KEY (original_assessment_id) REFERENCES assessments (assessment_id) ON DELETE CASCADE,
        FOREIGN KEY (reassessment_assessment_id) REFERENCES assessments (assessment_id) ON DELETE CASCADE
    );
CREATE TABLE exam_room_layouts (
                layout_id   INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id     INTEGER NOT NULL UNIQUE,
                rows_n      INTEGER NOT NULL,
                cols_n      INTEGER NOT NULL,
                seats_total INTEGER NOT NULL,
                created_at  TEXT NOT NULL,
                updated_at  TEXT NOT NULL
            );
CREATE TABLE exam_seat_allocations (
                allocation_id      INTEGER PRIMARY KEY AUTOINCREMENT,
                exam_id            INTEGER NOT NULL,
                student_id         TEXT NOT NULL,
                seat_id            INTEGER NOT NULL,
                accommodation_notes TEXT,
                created_at         TEXT NOT NULL,
                UNIQUE(exam_id, student_id),
                UNIQUE(exam_id, seat_id),
                FOREIGN KEY (seat_id) REFERENCES exam_seats (seat_id)
            );
CREATE TABLE exam_seats (
                seat_id        INTEGER PRIMARY KEY AUTOINCREMENT,
                layout_id      INTEGER NOT NULL,
                seat_label     TEXT NOT NULL,
                row_n          INTEGER NOT NULL,
                col_n          INTEGER NOT NULL,
                is_accessible  INTEGER NOT NULL DEFAULT 0,
                is_left_handed INTEGER NOT NULL DEFAULT 0,
                is_disabled    INTEGER NOT NULL DEFAULT 0,
                created_at     TEXT NOT NULL,
                UNIQUE(layout_id, seat_label),
                FOREIGN KEY (layout_id) REFERENCES exam_room_layouts (layout_id)
            );
CREATE TABLE examiner_actions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    visit_id INTEGER NOT NULL,
                    action_description TEXT NOT NULL,
                    responsible_person TEXT,
                    deadline TEXT,
                    status TEXT DEFAULT 'pending',
                    completed_at TEXT,
                    notes TEXT,
                    FOREIGN KEY (visit_id) REFERENCES examiner_visits(id)
                );
CREATE TABLE examiner_assignments (
                assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                examiner_id INTEGER NOT NULL,
                student_id TEXT,
                student_name TEXT,
                course_code TEXT,
                assignment_type TEXT,
                academic_year TEXT,
                report_submitted INTEGER DEFAULT 0,
                report_date TEXT,
                report_path TEXT,
                feedback TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (examiner_id) REFERENCES external_examiners(examiner_id)
            );
CREATE TABLE examiner_visits (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    examiner_id INTEGER NOT NULL,
                    visit_date TEXT NOT NULL,
                    department TEXT,
                    purpose TEXT,
                    modules_reviewed TEXT,
                    findings TEXT,
                    recommendations TEXT,
                    overall_rating TEXT,
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (examiner_id) REFERENCES external_examiners(examiner_id)
                );
CREATE TABLE exams (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        module_code TEXT NOT NULL,
                        module_name TEXT,
                        date TEXT NOT NULL,
                        start_time TEXT NOT NULL,
                        end_time TEXT NOT NULL,
                        room TEXT,
                        instructor_id INTEGER,
                        instructor_name TEXT,
                        students_enrolled INTEGER DEFAULT 0,
                        enrolled_student_ids TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, parent_exam_id INTEGER, overflow_room TEXT, "exam_name" TEXT, "assessment_id" INTEGER, "status" TEXT DEFAULT 'published', "published_at" TEXT, "published_by" TEXT,
                        FOREIGN KEY (instructor_id) REFERENCES instructors(id)
                    );
CREATE TABLE exchange_rates (
            rate_id INTEGER PRIMARY KEY AUTOINCREMENT,
            from_currency TEXT NOT NULL,
            to_currency TEXT NOT NULL,
