                    effective_to TEXT,
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE expense_requests (
                    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    category TEXT,
                    amount REAL NOT NULL,
                    description TEXT,
                    submitted_by TEXT,
                    submitted_date TEXT,
                    status TEXT DEFAULT 'pending',
                    approved_by TEXT,
                    approved_date TEXT,
                    club_id INTEGER,
                    event_id INTEGER
                );
CREATE TABLE "extension_requests" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assignment_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            requested_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            new_due_date TIMESTAMP NOT NULL,
            reason TEXT NOT NULL,
            status TEXT DEFAULT 'pending',
            reviewed_by INTEGER,
            reviewed_date TIMESTAMP,
            review_comments TEXT, "supporting_documents" TEXT, "approved_extension_days" INTEGER DEFAULT 0, "reviewer_comments" TEXT, "request_date" TEXT, "requested_due_date" TEXT, "review_date" TEXT, "reviewed_at" TEXT, "reviewer_notes" TEXT, "instructor_notes" TEXT, "source_accommodation_id" INTEGER,
            FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE external_api_config (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        config_data TEXT NOT NULL,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE external_db_config (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        config_data TEXT NOT NULL,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE external_examiners (
                examiner_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                institution TEXT,
                email TEXT,
                phone TEXT,
                expertise_area TEXT,
                department TEXT,
                appointment_start TEXT,
                appointment_end TEXT,
                status TEXT DEFAULT 'active',
                contact_person_id TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            , "specialisation" TEXT);
CREATE TABLE external_scholarships (
    external_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    provider_name TEXT NOT NULL,
    scholarship_name TEXT,
    amount REAL NOT NULL,
    academic_year TEXT NOT NULL,
    disbursement_date DATE,
    is_recurring BOOLEAN DEFAULT 0,
    contact_email TEXT,
    contact_phone TEXT,
    documentation_url TEXT,
    reported_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE external_submissions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        assignment_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        url TEXT NOT NULL,
                        link_type TEXT NOT NULL DEFAULT 'other',
                        is_validated INTEGER NOT NULL DEFAULT 0,
                        submitted_at TEXT NOT NULL DEFAULT (datetime('now'))
                    , "validated_at" TEXT, "description" TEXT, "tool_type" TEXT, "validation_notes" TEXT);
CREATE TABLE extracurricular_activities (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                activity_name TEXT,
                description TEXT,
                supervisor TEXT,
                meeting_schedule TEXT,
                location TEXT,
                max_participants INTEGER,
                fee DECIMAL(10,2) DEFAULT 0.00,
                status TEXT DEFAULT 'active'
            );
CREATE TABLE extras_accessibility (
        subject_type TEXT NOT NULL,    -- room | module | student | instructor
        subject_id TEXT NOT NULL,
        flag TEXT NOT NULL,            -- wheelchair | hearing_loop | low_sensory ...
        notes TEXT,
        PRIMARY KEY (subject_type, subject_id, flag)
    );
CREATE TABLE extras_approvals (
        schedule_id INTEGER PRIMARY KEY,
        status TEXT NOT NULL,          -- draft | submitted | approved | rejected
        submitted_by TEXT,
        reviewer TEXT,
        review_notes TEXT,
        updated_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE extras_audit (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        actor TEXT,
        action TEXT NOT NULL,
        details TEXT,
        at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE extras_change_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        schedule_id INTEGER NOT NULL,
        requester TEXT NOT NULL,
        proposal_json TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'open',
        decision_notes TEXT,
        created_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE extras_color_map (
        scheme TEXT NOT NULL,          -- department | program | instructor
        key TEXT NOT NULL,
        color TEXT NOT NULL,
        PRIMARY KEY (scheme, key)
    );
CREATE TABLE extras_comments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        schedule_id INTEGER NOT NULL,
        author TEXT NOT NULL,
        body TEXT NOT NULL,
        created_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE extras_constraints (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE NOT NULL,
        kind TEXT NOT NULL,            -- hard | soft
        rule_json TEXT NOT NULL,
        weight REAL DEFAULT 1.0,
        active INTEGER DEFAULT 1,
        created_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE extras_equipment_req (
        module_code TEXT NOT NULL,
        equipment TEXT NOT NULL,
        PRIMARY KEY (module_code, equipment)
    );
CREATE TABLE extras_instructor_availability (
        instructor_id INTEGER NOT NULL,
        day TEXT NOT NULL,
        start_time TEXT NOT NULL,
        end_time TEXT NOT NULL,
        kind TEXT NOT NULL,            -- preferred | unavailable
        PRIMARY KEY (instructor_id, day, start_time, end_time, kind)
    );
CREATE TABLE extras_kpi_layout (
        user TEXT PRIMARY KEY,
        tiles_json TEXT NOT NULL
    );
CREATE TABLE extras_locks (
        scope TEXT PRIMARY KEY,        -- e.g. 'term:2025-FA'
        owner TEXT NOT NULL,
        acquired_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE extras_pinned (
        user TEXT NOT NULL,
        schedule_id INTEGER NOT NULL,
        pinned_at TEXT DEFAULT (datetime('now')),
        PRIMARY KEY (user, schedule_id)
    );
CREATE TABLE extras_presence (
        user TEXT PRIMARY KEY,
        scope TEXT,
        last_seen TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE extras_room_maintenance (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        room_id INTEGER NOT NULL,
        starts_at TEXT NOT NULL,
        ends_at TEXT NOT NULL,
        reason TEXT
    );
CREATE TABLE extras_room_pool (
        pool_name TEXT NOT NULL,
        room_id INTEGER NOT NULL,
        PRIMARY KEY (pool_name, room_id)
    );
CREATE TABLE extras_schedule_booking_link (
    schedule_id INTEGER NOT NULL,
    booking_id  INTEGER NOT NULL,
    week_start  TEXT    NOT NULL,
    PRIMARY KEY (schedule_id, booking_id)
);
CREATE TABLE extras_schedule_equipment (
    schedule_id INTEGER NOT NULL,
    item_id     INTEGER NOT NULL,
    quantity    INTEGER NOT NULL DEFAULT 1,
    rental_id   INTEGER,
    notes       TEXT,
    PRIMARY KEY (schedule_id, item_id)
);
CREATE TABLE extras_session_templates (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE NOT NULL,
        session_type TEXT NOT NULL,
        duration_minutes INTEGER NOT NULL,
        preferred_room_type TEXT,
        notes TEXT
    );
CREATE TABLE extras_snapshots (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE NOT NULL,
        created_at TEXT DEFAULT (datetime('now')),
        payload_json TEXT NOT NULL
    );
CREATE TABLE extras_student_prefs (
        student_id TEXT NOT NULL,
        module_code TEXT NOT NULL,
        slot_label TEXT NOT NULL,
        score INTEGER DEFAULT 1,
        PRIMARY KEY (student_id, module_code, slot_label)
    );
CREATE TABLE extras_ui_prefs (
        user TEXT NOT NULL,
        key TEXT NOT NULL,
        value TEXT NOT NULL,
        PRIMARY KEY (user, key)
    );
CREATE TABLE facial_recognition_profiles (
            profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL UNIQUE,
            face_encoding TEXT NOT NULL,
            photo_url TEXT,
            last_updated TEXT DEFAULT CURRENT_TIMESTAMP,
            is_active BOOLEAN DEFAULT 1,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE facility_assets (
                asset_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_name TEXT NOT NULL,
                asset_type TEXT NOT NULL,
                asset_tag TEXT UNIQUE,
                building_id INTEGER,
                room_id INTEGER,
                purchase_date TEXT,
                purchase_cost REAL,
                warranty_expiry TEXT,
                maintenance_schedule TEXT,
                last_maintenance_date TEXT,
                condition TEXT DEFAULT 'good',
                status TEXT DEFAULT 'active',
                FOREIGN KEY (building_id) REFERENCES buildings (building_id),
                FOREIGN KEY (room_id) REFERENCES rooms (id)
            );
CREATE TABLE "facility_bookings" (
                    booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    facility_name TEXT,
                    user_id INTEGER,
                    booking_date TEXT,
                    start_time TEXT,
                    end_time TEXT,
                    purpose TEXT,
                    status TEXT DEFAULT 'pending',
                    created_at TEXT, "booker_id" TEXT, "club_id" INTEGER, "notes" TEXT, "rejection_reason" TEXT,
                    FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
                );
CREATE TABLE faculty_notifications (
                    notification_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    accommodation_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    faculty_id TEXT NOT NULL,
                    course_id TEXT NOT NULL,
                    accommodation_summary TEXT NOT NULL,
                    sent_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    acknowledged INTEGER DEFAULT 0,
                    FOREIGN KEY (accommodation_id) REFERENCES accommodations(id)
                );
CREATE TABLE faculty_schedule_blocks (
                    block_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    day_of_week INTEGER NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    activity_type TEXT NOT NULL DEFAULT 'teaching',
                    title TEXT,
                    description TEXT,
                    location TEXT,
                    course_code TEXT,
                    color TEXT,
                    is_locked INTEGER DEFAULT 0,
                    semester TEXT,
                    academic_year TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE "faculty_schedule_templates" (
                            template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                            user_id TEXT,
                            name TEXT NOT NULL,
                            description TEXT,
                            created_by TEXT,
                            blocks_json TEXT NOT NULL,
                            is_shared INTEGER DEFAULT 0,
                            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                            updated_at TEXT
                        );
CREATE TABLE fafsa_data (
    fafsa_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    efc INTEGER,  -- Expected Family Contribution
    submission_date DATE,
    processed_date DATE,
    sai INTEGER,  -- Student Aid Index (new FAFSA metric)
    dependency_status TEXT,  -- dependent, independent
    pell_eligible BOOLEAN DEFAULT 0,
    pell_amount REAL,
    verification_status TEXT DEFAULT 'not_required',
    imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id),
    UNIQUE(student_id, academic_year)
);
CREATE TABLE failed_logins (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT,
                ip_address TEXT,
                reason TEXT,
                timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE faqs (
            faq_id INTEGER PRIMARY KEY AUTOINCREMENT,
            question TEXT NOT NULL,
            answer TEXT NOT NULL,
            category TEXT NOT NULL,
            created_by TEXT NOT NULL,
            created_datetime TEXT NOT NULL,
            updated_datetime TEXT,
            view_count INTEGER DEFAULT 0,
            helpful_votes INTEGER DEFAULT 0,
            tags TEXT,  -- JSON array
            is_featured BOOLEAN DEFAULT 0
        , "status" TEXT DEFAULT 'published', "updated_by" TEXT, "not_helpful_votes" INTEGER DEFAULT 0, "source" TEXT);
CREATE TABLE favorites (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            member_id INTEGER,
            customer_email TEXT,
            movie_id INTEGER NOT NULL,
            added_at TEXT DEFAULT CURRENT_TIMESTAMP,
            notify_screenings INTEGER DEFAULT 1,
            FOREIGN KEY (member_id) REFERENCES members(id),
            FOREIGN KEY (movie_id) REFERENCES movies(id),
            UNIQUE(customer_email, movie_id)
        );
CREATE TABLE federated_learning (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                institution_id TEXT NOT NULL,
                model_update BLOB NOT NULL,
                update_round INTEGER NOT NULL,
                accuracy_metric REAL,
                privacy_budget REAL,
                created_at TEXT NOT NULL
            );
CREATE TABLE fee_types (
            fee_type_id INTEGER PRIMARY KEY AUTOINCREMENT,
            fee_name TEXT NOT NULL,
            description TEXT,
            is_recurring BOOLEAN DEFAULT 0,
            academic_year TEXT,
            is_late_fee BOOLEAN DEFAULT 0,
            late_fee_calculation TEXT, -- 'fixed', 'percentage', 'daily'
            late_fee_amount DECIMAL(10,2),
            grace_period_days INTEGER DEFAULT 0,
            created_at TEXT,
            updated_at TEXT
        , "amount" REAL, "is_active" INTEGER DEFAULT 1);
CREATE TABLE feedback_attachments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    file_name TEXT NOT NULL,
                    file_path TEXT NOT NULL,
                    file_type TEXT,
                    file_size INTEGER,
                    uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_categories (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    icon TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE "feedback_files" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                file_path TEXT NOT NULL,
                file_name TEXT NOT NULL,
                file_type TEXT,
                created_by INTEGER,
                created_at TEXT NOT NULL,
                FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE,
                FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE feedback_impacts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    implementation_date DATE,
                    users_affected INTEGER,
                    satisfaction_increase REAL,
                    cost_savings REAL,
                    description TEXT,
                    metrics TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_responses (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    responder_id TEXT NOT NULL,
                    responder_name TEXT NOT NULL,
                    response_text TEXT NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_status_updates (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    old_status TEXT,
                    new_status TEXT NOT NULL,
                    updated_by TEXT NOT NULL,
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_submissions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT,
                    category_id INTEGER NOT NULL,
                    type TEXT NOT NULL CHECK(type IN ('feedback', 'suggestion')),
                    title TEXT NOT NULL,
                    description TEXT NOT NULL,
                    is_anonymous BOOLEAN DEFAULT 0,
                    status TEXT DEFAULT 'Submitted',
                    priority TEXT DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High', 'Critical')),
                    votes INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (category_id) REFERENCES feedback_categories(id)
                );
CREATE TABLE feedback_votes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    vote_type TEXT DEFAULT 'upvote' CHECK(vote_type IN ('upvote', 'downvote')),
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(submission_id, user_id),
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE file_share_config (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        config_data TEXT NOT NULL,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE "file_versions" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                version_number INTEGER NOT NULL,
                file_path TEXT NOT NULL,
                file_hash TEXT NOT NULL,
                created_at TEXT NOT NULL,
                is_current INTEGER DEFAULT 0,
                FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE
            );
CREATE TABLE finance_ap_invoices (
    id INTEGER PRIMARY KEY,
    invoice_number TEXT NOT NULL,
    supplier_id INTEGER NOT NULL,
    po_id INTEGER,
    net_amount REAL NOT NULL,
    vat_amount REAL DEFAULT 0,
    due_date TEXT,
    status TEXT DEFAULT 'pending',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (supplier_id, invoice_number),
    FOREIGN KEY (supplier_id) REFERENCES finance_suppliers(id)
);
CREATE TABLE finance_approval_items (
    id INTEGER PRIMARY KEY,
    item_type TEXT NOT NULL,
    entity_id INTEGER NOT NULL,
    amount REAL,
    requested_by TEXT,
    status TEXT DEFAULT 'pending',
    decision_by TEXT,
    decision_at TEXT,
    notes TEXT
);
CREATE TABLE finance_cash_movements (
    id INTEGER PRIMARY KEY,
    movement_date TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('inflow', 'outflow')),
    category TEXT,
    amount REAL NOT NULL,
    status TEXT DEFAULT 'forecast',
    description TEXT
);
CREATE TABLE finance_close_tasks (
    id INTEGER PRIMARY KEY,
    period_label TEXT NOT NULL,
    task_name TEXT NOT NULL,
    owner TEXT,
    status TEXT DEFAULT 'pending',
    evidence TEXT,
    UNIQUE (period_label, task_name)
);
CREATE TABLE finance_fixed_assets (
    id INTEGER PRIMARY KEY,
    asset_tag TEXT UNIQUE NOT NULL,
    description TEXT NOT NULL,
    cost REAL NOT NULL,
    acquired_date TEXT NOT NULL,
    useful_life_years INTEGER NOT NULL,
    residual_value REAL DEFAULT 0,
    location TEXT,
    status TEXT DEFAULT 'active'
);
CREATE TABLE finance_fraud_cases (
    id INTEGER PRIMARY KEY,
    payment_id INTEGER,
    risk_score REAL NOT NULL,
    reason TEXT,
    status TEXT DEFAULT 'open',
    assigned_to TEXT,
    decision TEXT,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE finance_holds (
    hold_id      INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id   TEXT NOT NULL,
    amount       REAL NOT NULL DEFAULT 0,
    reason       TEXT NOT NULL,
    source       TEXT NOT NULL,
    reference_id TEXT,
    is_active    INTEGER NOT NULL DEFAULT 1,
    placed_at    TEXT NOT NULL,
    released_at  TEXT,
    placed_by    TEXT,
    released_by  TEXT
);
CREATE TABLE finance_purchase_orders (
    id INTEGER PRIMARY KEY,
    po_number TEXT UNIQUE NOT NULL,
    supplier_id INTEGER NOT NULL,
    description TEXT NOT NULL,
    net_amount REAL NOT NULL,
    status TEXT DEFAULT 'draft',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (supplier_id) REFERENCES finance_suppliers(id)
);
CREATE TABLE finance_refunds (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT,
                        refund_reference TEXT NOT NULL UNIQUE,
                        department TEXT NOT NULL,
                        transaction_id TEXT,
                        amount DECIMAL(10,2) NOT NULL,
                        refund_method TEXT NOT NULL,
                        refund_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        refund_time TEXT,
                        processed_by TEXT,
                        notes TEXT
                    );
CREATE TABLE finance_suppliers (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT,
    bank_verified INTEGER DEFAULT 0,
    risk_rating TEXT DEFAULT 'low',
    status TEXT DEFAULT 'active'
);
CREATE TABLE finance_vat_entries (
    id INTEGER PRIMARY KEY,
    tax_date TEXT NOT NULL,
    source_type TEXT NOT NULL,
    source_id INTEGER,
    tax_code TEXT NOT NULL,
    net_amount REAL NOT NULL,
    vat_amount REAL NOT NULL,
    direction TEXT NOT NULL CHECK (direction IN ('input', 'output'))
);
CREATE TABLE financial_aid (
                aid_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                aid_type TEXT NOT NULL,
                amount REAL NOT NULL,
                status TEXT DEFAULT 'pending',
                academic_year TEXT,
                application_date TEXT,
                decision_date TEXT,
                notes TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "current_timestamp" TEXT,
                FOREIGN KEY (student_id) REFERENCES students(student_id)
            );
CREATE TABLE financial_aid_applications (
    application_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    application_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status TEXT DEFAULT 'pending',  -- pending, under_review, approved, denied
    family_income REAL,
    household_size INTEGER,
    special_circumstances TEXT,
    submitted_by INTEGER,
    reviewed_by INTEGER,
    review_date TIMESTAMP,
    review_notes TEXT,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE financial_aid_types (
            aid_type_id INTEGER PRIMARY KEY AUTOINCREMENT,
            aid_name TEXT NOT NULL,
            aid_category TEXT, -- 'grant', 'loan', 'work_study', 'emergency'
            description TEXT,
            max_amount DECIMAL(10,2),
            eligibility_criteria TEXT,
            application_deadline TEXT,
            is_renewable BOOLEAN DEFAULT 0,
            requires_repayment BOOLEAN DEFAULT 0,
            interest_rate DECIMAL(5,2),
            grace_period_months INTEGER,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE "financial_alerts" (
        alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
        alert_type TEXT NOT NULL,
        priority TEXT DEFAULT 'medium',
        title TEXT NOT NULL,
        message TEXT NOT NULL,
        student_id TEXT,
        amount DECIMAL(10,2),
        currency TEXT DEFAULT 'GBP',
        status TEXT DEFAULT 'active',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        acknowledged_at TEXT,
        resolved_at TEXT,
        acknowledged_by TEXT,
        resolved_by TEXT,
        metadata TEXT, "data" TEXT, "created_date" DATETIME
    );
CREATE TABLE financial_kpis (
            kpi_id INTEGER PRIMARY KEY AUTOINCREMENT,
            kpi_name TEXT NOT NULL,
            kpi_value DECIMAL(15,2) NOT NULL,
            kpi_type TEXT NOT NULL, -- 'amount', 'percentage', 'count', 'ratio'
            calculation_period TEXT NOT NULL, -- 'daily', 'weekly', 'monthly', 'yearly'
            calculation_date TEXT NOT NULL,
            academic_year TEXT,
            created_at TEXT
        );
CREATE TABLE financial_transactions (
                transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                transaction_type TEXT NOT NULL,
                amount REAL NOT NULL,
                description TEXT,
                reference_number TEXT,
                transaction_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                status TEXT DEFAULT 'completed',
                created_by TEXT,
                FOREIGN KEY (student_id) REFERENCES students(student_id)
            );
CREATE TABLE first_aid_course_sessions (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        course      TEXT NOT NULL,
        starts_at   TEXT NOT NULL,
        ends_at     TEXT,
        location    TEXT,
        trainer     TEXT,
        capacity    INTEGER NOT NULL DEFAULT 12,
        description TEXT,
        status      TEXT NOT NULL DEFAULT 'scheduled'
                    CHECK (status IN ('scheduled', 'cancelled', 'completed')),
        created_by  TEXT,
        created_at  TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE first_aid_incidents (
                    id              INTEGER PRIMARY KEY AUTOINCREMENT,
                    submitted_at    TEXT NOT NULL,
                    reporter_user   TEXT,
                    reporter_name   TEXT NOT NULL,
                    reporter_id     TEXT,
                    phone           TEXT,
                    location        TEXT,
                    incident_type   TEXT,
                    severity        TEXT,
                    description     TEXT NOT NULL
                , email TEXT, status TEXT DEFAULT 'Open', "incident_date" TEXT, "person_type" TEXT, "riddor_category" TEXT, "riddor_reportable" INTEGER, "riddor_deadline" TEXT, "riddor_status" TEXT DEFAULT 'not_assessed', "riddor_notes" TEXT, "hse_reference" TEXT, "riddor_assessed_by" TEXT, "riddor_assessed_at" TEXT, "riddor_reported_at" TEXT, "hs_incident_id" INTEGER, "archived" INTEGER DEFAULT 0, "archived_at" TEXT, "archived_by" TEXT, "archive_reason" TEXT);
CREATE TABLE first_aid_kit_inspections (
        id              INTEGER PRIMARY KEY AUTOINCREMENT,
        kit_id          INTEGER NOT NULL REFERENCES first_aid_kits (id) ON DELETE CASCADE,
        inspected_at    TEXT NOT NULL,
        inspected_by    TEXT NOT NULL,
        outcome         TEXT NOT NULL CHECK (outcome IN ('ok', 'restocked', 'faulty')),
        notes           TEXT
    );
CREATE TABLE first_aid_kits (
        id                  INTEGER PRIMARY KEY AUTOINCREMENT,
        kind                TEXT NOT NULL CHECK (kind IN ('kit', 'aed', 'eyewash', 'burns')),
        label               TEXT NOT NULL,
        location            TEXT NOT NULL,
        detail              TEXT,
        last_checked        TEXT,
        check_every_days    INTEGER NOT NULL DEFAULT 30,
        contents_expiry     TEXT,
        aed_pads_expiry     TEXT,
        aed_battery_expiry  TEXT,
        status              TEXT NOT NULL DEFAULT 'in_service'
                            CHECK (status IN ('in_service', 'needs_restock', 'out_of_service',
                                              'retired')),
        created_at          TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at          TEXT
    );
CREATE TABLE first_aid_reminders (
        kind    TEXT NOT NULL,
        ref     TEXT NOT NULL,
        sent_at TEXT NOT NULL,
        PRIMARY KEY (kind, ref)
    );
CREATE TABLE first_aid_training_registrations (
                    id              INTEGER PRIMARY KEY AUTOINCREMENT,
                    submitted_at    TEXT NOT NULL,
                    course          TEXT NOT NULL,
                    user_id         TEXT,
                    name            TEXT NOT NULL,
                    email           TEXT,
                    phone           TEXT,
                    preferred_date  TEXT,
                    notes           TEXT
                , "session_id" INTEGER);
CREATE TABLE first_aiders (
        id                  INTEGER PRIMARY KEY AUTOINCREMENT,
        username            TEXT,
        name                TEXT NOT NULL,
        email               TEXT,
        qualification       TEXT NOT NULL,
        certificate_number  TEXT,
        issued_on           TEXT,
        expires_on          TEXT NOT NULL,
        location            TEXT,
        status              TEXT NOT NULL DEFAULT 'active'
                            CHECK (status IN ('active', 'lapsed', 'withdrawn')),
        notes               TEXT,
        created_at          TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at          TEXT
    );
CREATE TABLE flashcard_reviews (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        flashcard_id INTEGER NOT NULL REFERENCES flashcards(flashcard_id) ON DELETE CASCADE,
        student_id TEXT NOT NULL,
        quality INTEGER NOT NULL CHECK (quality BETWEEN 0 AND 5),
        interval_days INTEGER NOT NULL,
        ease_factor REAL NOT NULL,
        reviewed_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE flashcards (
                    flashcard_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    course_id TEXT,
                    deck_name TEXT NOT NULL,
                    question TEXT NOT NULL,
                    answer TEXT NOT NULL,
                    difficulty_rating INTEGER DEFAULT 0,
                    last_reviewed TEXT,
                    next_review TEXT,
                    review_count INTEGER DEFAULT 0,
                    correct_count INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                , "ease_factor" REAL DEFAULT 2.5, "interval_days" INTEGER DEFAULT 0, "repetitions" INTEGER DEFAULT 0, "lapses" INTEGER DEFAULT 0, "last_quality" INTEGER, "source" TEXT DEFAULT 'manual', "source_ref" TEXT, "suspended" INTEGER DEFAULT 0, "updated_at" TEXT);
CREATE TABLE "forensic_analysis_results" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                evidence_id TEXT NOT NULL,
                analysis_type TEXT NOT NULL,
                results_json TEXT,
                performed_by INTEGER,
                performed_at TEXT NOT NULL,
                FOREIGN KEY (evidence_id) REFERENCES forensic_evidence(evidence_id) ON DELETE CASCADE,
                FOREIGN KEY (performed_by) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "forensic_cases" (
                case_id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                description TEXT,
                priority TEXT NOT NULL DEFAULT 'MEDIUM',
                status TEXT NOT NULL DEFAULT 'OPEN',
                investigator_id INTEGER,
                notes TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                FOREIGN KEY (investigator_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "forensic_custody_log" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                evidence_id TEXT NOT NULL,
                event_type TEXT NOT NULL,
                user_id INTEGER,
                notes TEXT,
                timestamp TEXT NOT NULL,
                FOREIGN KEY (evidence_id) REFERENCES forensic_evidence(evidence_id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "forensic_evidence" (
                evidence_id TEXT PRIMARY KEY,
                case_id TEXT NOT NULL,
                evidence_type TEXT NOT NULL,
                description TEXT,
                file_path TEXT,
                hash_md5 TEXT,
                hash_sha1 TEXT,
                hash_sha256 TEXT,
                hash_sha512 TEXT,
                state TEXT NOT NULL DEFAULT 'ACQUIRED',
                collected_by INTEGER,
                collected_at TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT,
                FOREIGN KEY (case_id) REFERENCES forensic_cases(case_id) ON DELETE CASCADE,
                FOREIGN KEY (collected_by) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE forum_replies (
            reply_id INTEGER PRIMARY KEY AUTOINCREMENT,
            post_id INTEGER,
            author_id TEXT,
            content TEXT,
            reply_date TEXT,
            parent_reply_id INTEGER, "author_name" TEXT, "created_date" TEXT, "hidden_at" TEXT, "hidden_reason" TEXT,
            FOREIGN KEY (post_id) REFERENCES alumni_forum (post_id),
            FOREIGN KEY (author_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE found_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    finder_id TEXT NOT NULL,
                    item_name TEXT NOT NULL,
                    category TEXT NOT NULL,
                    description TEXT NOT NULL,
                    found_date TEXT NOT NULL,
                    found_location TEXT NOT NULL,
                    found_time TEXT,
                    distinctive_features TEXT,
                    color TEXT,
                    brand TEXT,
                    current_location TEXT,
                    storage_info TEXT,
                    contact_email TEXT,
                    contact_phone TEXT,
                    status TEXT DEFAULT 'Available',
                    reported_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (finder_id) REFERENCES students(student_id)
                );
CREATE TABLE free_stuff (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    giver_id TEXT NOT NULL,
                    item_name TEXT NOT NULL,
                    description TEXT NOT NULL,
                    category TEXT NOT NULL,
                    condition_status TEXT DEFAULT 'Used',
                    location TEXT NOT NULL,
                    pickup_instructions TEXT,
                    available_until TEXT,
                    contact_info TEXT,
                    status TEXT DEFAULT 'Available',
                    claimed_by TEXT,
                    claimed_at TEXT,
                    view_count INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (giver_id) REFERENCES students(student_id)
                );
CREATE TABLE frequent_absence_alerts (
                       student_id    TEXT NOT NULL,
                       year_month    TEXT NOT NULL,
                       sent_at       TEXT NOT NULL,
                       count_at_send INTEGER NOT NULL,
                       PRIMARY KEY (student_id, year_month)
                   );
CREATE TABLE frequent_absence_email_prefs (
                       student_id  TEXT PRIMARY KEY,
                       opted_out   INTEGER NOT NULL DEFAULT 0,
                       updated_at  TEXT
                   );
CREATE TABLE ftp_cases (
    case_id            INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id         TEXT    NOT NULL,
    programme          TEXT,
    regulator          TEXT,
    registration_no    TEXT,
    stage              TEXT    NOT NULL DEFAULT 'Concern Raised',
    risk_level         TEXT    DEFAULT 'Medium',
    interim_order      TEXT,
    placement_status   TEXT    DEFAULT 'Continuing',
    date_opened        TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    date_closed        TEXT,
    case_officer       TEXT,
    panel_chair        TEXT,
    summary            TEXT,
    source_record_id   INTEGER,
    created_at         TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at         TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (source_record_id)
        REFERENCES disciplinary_records(record_id) ON DELETE SET NULL
);
CREATE TABLE ftp_concerns (
    concern_id   INTEGER PRIMARY KEY AUTOINCREMENT,
    case_id      INTEGER NOT NULL,
    category     TEXT    NOT NULL,
    description  TEXT,
    raised_by    TEXT,
    raised_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (case_id) REFERENCES ftp_cases(case_id) ON DELETE CASCADE
);
CREATE TABLE ftp_events (
    event_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    case_id      INTEGER NOT NULL,
    event_type   TEXT    NOT NULL,
    notes        TEXT,
    actor        TEXT,
    occurred_at  TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (case_id) REFERENCES ftp_cases(case_id) ON DELETE CASCADE
);
CREATE TABLE ftp_outcomes (
    outcome_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    case_id       INTEGER NOT NULL,
    outcome       TEXT    NOT NULL,
    sanction      TEXT,
    conditions    TEXT,
    review_date   TEXT,
    decided_by    TEXT,
    decided_at    TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (case_id) REFERENCES ftp_cases(case_id) ON DELETE CASCADE
);
CREATE TABLE funding_attendance_confirmations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        term_name TEXT NOT NULL,
        academic_year TEXT,
        status TEXT NOT NULL,
        notes TEXT,
        confirmed_by TEXT,
        confirmed_at TEXT NOT NULL,
        UNIQUE (student_id, term_name)
    );
CREATE TABLE fundraising_campaigns (
            campaign_id INTEGER PRIMARY KEY AUTOINCREMENT,
            campaign_name TEXT,
            description TEXT,
            goal_amount REAL,
            current_amount REAL DEFAULT 0.0,
            start_date TEXT,
            end_date TEXT,
            created_by TEXT,
            created_date TEXT,
            status TEXT DEFAULT 'active',
            category TEXT,
            is_featured BOOLEAN DEFAULT 0
        , "id" INTEGER, "target_amount" DECIMAL(10,2));
CREATE TABLE fundraising_donations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                campaign_id INTEGER,
                parent_id TEXT,
                student_id TEXT,
                amount DECIMAL(10,2),
                donation_date TEXT,
                anonymous BOOLEAN DEFAULT 0,
                FOREIGN KEY (campaign_id) REFERENCES fundraising_campaigns(campaign_id),
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE gateway_transactions (
                    transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    payment_id INTEGER,
                    gateway_id INTEGER NOT NULL,
                    gateway_transaction_id TEXT NOT NULL,
                    amount DECIMAL(10,2) NOT NULL,
                    currency TEXT NOT NULL,
                    status TEXT NOT NULL,
                    gateway_fee DECIMAL(10,2),
                    raw_response TEXT, -- JSON response from gateway
                    webhook_verified BOOLEAN DEFAULT 0,
                    created_at TEXT,
                    updated_at TEXT,
                    FOREIGN KEY (payment_id) REFERENCES payments (payment_id),
                    FOREIGN KEY (gateway_id) REFERENCES payment_gateways (gateway_id)
                );
CREATE TABLE gift_aid_claims (
        claim_id INTEGER PRIMARY KEY AUTOINCREMENT,
        period_from TEXT NOT NULL,
        period_to TEXT NOT NULL,
        donations_total REAL NOT NULL DEFAULT 0,
        claim_total REAL NOT NULL DEFAULT 0,
        adjustments_total REAL DEFAULT 0,
        gift_count INTEGER NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'submitted', 'paid')),
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        submitted_at TEXT,
        hmrc_reference TEXT,
        paid_at TEXT
    );
CREATE TABLE gift_aid_declarations (
        declaration_id INTEGER PRIMARY KEY AUTOINCREMENT,
        alumni_id TEXT NOT NULL,
        full_name TEXT NOT NULL,
        house TEXT NOT NULL,
        postcode TEXT NOT NULL,
        method TEXT NOT NULL CHECK (method IN ('written', 'oral', 'online')),
        made_on TEXT NOT NULL,
        covers_past_four_years INTEGER NOT NULL DEFAULT 1,
        taxpayer_confirmed INTEGER NOT NULL DEFAULT 0,
        recorded_by TEXT,
        cancelled_at TEXT,
        cancelled_by TEXT
    );
CREATE TABLE gift_cards (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            code TEXT UNIQUE NOT NULL,
            initial_value REAL NOT NULL,
            current_balance REAL NOT NULL,
            purchaser_name TEXT,
            purchaser_email TEXT,
            recipient_name TEXT,
            recipient_email TEXT,
            message TEXT,
            purchase_date TEXT DEFAULT CURRENT_TIMESTAMP,
            expiry_date TEXT,
            status TEXT DEFAULT 'active'
        );
CREATE TABLE giving_campaigns (
            campaign_id INTEGER PRIMARY KEY AUTOINCREMENT,
            campaign_name TEXT NOT NULL,
            campaign_description TEXT,
            goal_amount REAL NOT NULL,
            current_amount REAL DEFAULT 0,
            donor_count INTEGER DEFAULT 0,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            campaign_type TEXT NOT NULL,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE gl_accounts (
        account_id        INTEGER PRIMARY KEY AUTOINCREMENT,
        account_code      TEXT    NOT NULL UNIQUE,
        account_name      TEXT    NOT NULL,
        account_type      TEXT    NOT NULL CHECK (account_type IN ('asset','liability','equity','revenue','expense')),
        parent_account_id INTEGER REFERENCES gl_accounts(account_id),
        is_active         INTEGER NOT NULL DEFAULT 1,
        created_at        TEXT    NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE gl_entities (
        entity_id   INTEGER PRIMARY KEY AUTOINCREMENT,
        entity_code TEXT    NOT NULL UNIQUE,
        entity_name TEXT    NOT NULL,
        is_active   INTEGER NOT NULL DEFAULT 1,
        created_at  TEXT    NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE gl_journal_lines (
        line_id    INTEGER PRIMARY KEY AUTOINCREMENT,
        journal_id INTEGER NOT NULL REFERENCES gl_journals(journal_id) ON DELETE CASCADE,
        account_id INTEGER NOT NULL REFERENCES gl_accounts(account_id),
        debit      DECIMAL(12,2) NOT NULL DEFAULT 0,
        credit     DECIMAL(12,2) NOT NULL DEFAULT 0,
        memo       TEXT,
        CHECK ((debit > 0 AND credit = 0) OR (credit > 0 AND debit = 0))
    );
CREATE TABLE gl_journals (
        journal_id     INTEGER PRIMARY KEY AUTOINCREMENT,
        entity_id      INTEGER NOT NULL REFERENCES gl_entities(entity_id),
        journal_date   TEXT    NOT NULL,
        period_id      INTEGER NOT NULL REFERENCES gl_periods(period_id),
        description    TEXT    NOT NULL,
        source_type    TEXT    NOT NULL,
        source_id      INTEGER,
        posted_by      TEXT    NOT NULL,
        posted_at      TEXT    NOT NULL DEFAULT (datetime('now')),
        reversed_by_id INTEGER REFERENCES gl_journals(journal_id),
        is_reversal_of INTEGER REFERENCES gl_journals(journal_id),
        UNIQUE (source_type, source_id)
    );
CREATE TABLE gl_periods (
        period_id   INTEGER PRIMARY KEY AUTOINCREMENT,
        fiscal_year INTEGER NOT NULL,
        period_no   INTEGER NOT NULL,
        start_date  TEXT    NOT NULL,
        end_date    TEXT    NOT NULL,
        status      TEXT    NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed','locked')),
        closed_at   TEXT,
        closed_by   TEXT,
        UNIQUE (fiscal_year, period_no)
    );
CREATE TABLE governed_programmes (
    programme_id INTEGER PRIMARY KEY AUTOINCREMENT,
    programme_code TEXT NOT NULL UNIQUE,
    programme_name TEXT NOT NULL,
    owning_school TEXT,
    award_type TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'proposed',
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE gpa_simulations (
                    simulation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    simulation_name TEXT NOT NULL,
                    current_gpa REAL NOT NULL,
                    simulated_courses_json TEXT NOT NULL,
                    projected_gpa REAL NOT NULL,
                    projection_type TEXT DEFAULT 'What-If',
                    credits_simulated INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE grade_analytics (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                module_code TEXT,
                assessment_date TEXT,
                grade_value DECIMAL(5,2),
                class_average DECIMAL(5,2),
                percentile_rank INTEGER,
                trend_direction TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (module_code) REFERENCES modules (module_code)
            );
CREATE TABLE grade_audit_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER,
                    student_id TEXT,
                    assignment_id INTEGER,
                    old_grade REAL,
                    new_grade REAL,
                    changed_by TEXT,
                    reason TEXT,
                    changed_at TEXT DEFAULT (datetime('now'))
                );
CREATE TABLE grade_change_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        source TEXT NOT NULL,
        record_id INTEGER,
        student_id TEXT,
        module_code TEXT,
        old_value TEXT,
        new_value TEXT,
        reason TEXT NOT NULL,
        changed_by TEXT,
        changed_at TEXT NOT NULL
    );
CREATE TABLE grade_disputes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER,
                    student_id TEXT NOT NULL,
                    assignment_id INTEGER NOT NULL,
                    original_grade REAL,
                    requested_action TEXT,
                    reason TEXT NOT NULL,
                    evidence_path TEXT,
                    status TEXT NOT NULL DEFAULT 'pending',
                    reviewer_id TEXT,
                    reviewer_comments TEXT,
                    new_grade REAL,
                    created_at TEXT NOT NULL,
                    resolved_at TEXT
                , "reviewed_by" TEXT, "reviewed_date" TEXT, "submitted_date" TEXT, "updated_grade" TEXT);
CREATE TABLE grade_predictions (
                    prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    course_id TEXT NOT NULL,
                    current_grade REAL,
                    predicted_final_grade TEXT,
                    confidence_level REAL DEFAULT 0.0,
                    prediction_factors_json TEXT,
                    improvement_suggestions_json TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE grade_statistics (
            stat_id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_id INTEGER,
            mean REAL,
            median REAL,
            std_dev REAL,
            min_score REAL,
            max_score REAL,
            q1 REAL,
            q3 REAL,
            skewness REAL,
            kurtosis REAL,
            date_calculated TEXT,
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
        );
CREATE TABLE grades (
            grade_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            assessment_id INTEGER,
            score REAL,
            letter_grade TEXT,
            submission_date TEXT,
            comments TEXT, graded_by TEXT, "id" INTEGER, "submission_id" INTEGER, "rubric_criteria_id" INTEGER, "points_earned" REAL, "max_points" REAL, "percentage" REAL, "feedback" TEXT, "graded_date" TEXT, "grade" TEXT, "module_code" TEXT, "assessment_type" TEXT, "course_id" INTEGER, "created_at" TEXT, "updated_at" TEXT, "version" INTEGER, "raw_score" REAL, "result_code" TEXT, "capped" INTEGER DEFAULT 0, "released_at" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
        );
CREATE TABLE graduation_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        entity TEXT NOT NULL,
        entity_id TEXT NOT NULL,
        action TEXT NOT NULL,
        actor TEXT,
        detail TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE graduation_ceremonies (
                ceremony_id INTEGER PRIMARY KEY AUTOINCREMENT,
                ceremony_name TEXT NOT NULL,
                ceremony_date TEXT NOT NULL,
                ceremony_time TEXT NOT NULL,
                venue TEXT NOT NULL,
                capacity INTEGER NOT NULL DEFAULT 200,
                cohort_filter TEXT DEFAULT '',
                rsvp_deadline TEXT,
                guest_tickets_per_graduand INTEGER DEFAULT 2,
                status TEXT DEFAULT 'scheduled',
                notes TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            , "gown_order_deadline" TEXT);
CREATE TABLE graduation_checklist (
                checklist_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                program_id INTEGER NOT NULL,
                all_requirements_met INTEGER DEFAULT 0,
                gpa_requirement_met INTEGER DEFAULT 0,
                credit_requirement_met INTEGER DEFAULT 0,
                residency_requirement_met INTEGER DEFAULT 0,
                financial_clearance INTEGER DEFAULT 0,
                conferral_status TEXT DEFAULT 'pending',
                graduation_date TEXT,
                last_checked TEXT NOT NULL DEFAULT (datetime('now')), audit_date TIMESTAMP DEFAULT NULL,
                FOREIGN KEY (program_id) REFERENCES degree_programs(program_id),
                UNIQUE(student_id, program_id)
            );
CREATE TABLE graduation_conferrals (
        conferral_id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        award_id INTEGER NOT NULL,
        programme_code TEXT,
        award_name TEXT NOT NULL,
        classification TEXT,
        academic_year TEXT,
        conferral_date TEXT NOT NULL,
        mode TEXT NOT NULL CHECK (mode IN ('ceremony', 'in_absentia')),
        ceremony_id INTEGER,
        certificate_name TEXT NOT NULL,
        certificate_id INTEGER,
        certificate_number TEXT,
        credential_id INTEGER,
        verification_code TEXT,
        freeze_id INTEGER,
        status TEXT NOT NULL DEFAULT 'conferred'
            CHECK (status IN ('conferred', 'suspended', 'revoked', 'superseded')),
        conferred_by TEXT,
        conferred_at TEXT NOT NULL DEFAULT (datetime('now')),
        status_changed_at TEXT,
        status_changed_by TEXT,
        status_reason TEXT,
        replaces_conferral_id INTEGER
    );
CREATE TABLE graduation_forecasts (
            forecast_id INTEGER PRIMARY KEY AUTOINCREMENT,
            cohort_year INTEGER NOT NULL,
            program_id INTEGER,
            predicted_graduation_rate REAL,
            predicted_4year_rate REAL,
            predicted_5year_rate REAL,
            predicted_6year_rate REAL,
            forecast_date TEXT DEFAULT CURRENT_TIMESTAMP,
            model_id INTEGER,
            confidence_interval TEXT,
            FOREIGN KEY (model_id) REFERENCES analytics_models (model_id)
        );
CREATE TABLE graduation_holds (
        hold_id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('appeal', 'misconduct', 'registry', 'finance',
                                           'other')),
        reason TEXT NOT NULL,
        placed_by TEXT,
        placed_at TEXT NOT NULL DEFAULT (datetime('now')),
        released_by TEXT,
        released_at TEXT,
        release_note TEXT
    );
CREATE TABLE graduation_print_queue (
                queue_id INTEGER PRIMARY KEY AUTOINCREMENT,
                ceremony_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                certificate_id INTEGER,
                certificate_number TEXT,
                status TEXT NOT NULL DEFAULT 'queued',
                printed_at TEXT,
                dispatched_at TEXT,
                notes TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (ceremony_id) REFERENCES graduation_ceremonies(ceremony_id) ON DELETE CASCADE,
                UNIQUE(ceremony_id, student_id)
            );
CREATE TABLE graduation_requirements (
                    id TEXT PRIMARY KEY,
                    requirement_name TEXT NOT NULL,
                    requirement_type TEXT NOT NULL,
                    credits_required INTEGER,
                    course_category TEXT,
                    deadline_date TEXT,
                    is_mandatory BOOLEAN DEFAULT TRUE,
                    created_at TEXT NOT NULL
                );
CREATE TABLE graduation_roles (
        username TEXT NOT NULL,
        role TEXT NOT NULL CHECK (role IN ('graduation_office', 'ceremony_staff')),
        granted_by TEXT,
        granted_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (username, role)
    );
CREATE TABLE grant_applications (
            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
            grant_name TEXT NOT NULL,
            funding_agency TEXT NOT NULL,
            project_id INTEGER,
            principal_investigator_id TEXT NOT NULL,
            co_investigators TEXT,
            requested_amount REAL NOT NULL,
            application_deadline TEXT NOT NULL,
            submission_date TEXT,
            decision_date TEXT,
            decision_status TEXT DEFAULT 'pending',
            awarded_amount REAL,
            grant_period_start TEXT,
            grant_period_end TEXT,
            application_documents TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP, "grant_application_id" INTEGER, "title" TEXT, "status" TEXT DEFAULT 'draft', "department" TEXT, "scheme" TEXT, "funder_rate" REAL DEFAULT 80, "ethics_required" INTEGER DEFAULT 0, "dmp_required" INTEGER DEFAULT 1, "hod_approved_by" TEXT, "hod_approved_at" TEXT, "office_approved_by" TEXT, "office_approved_at" TEXT, "award_reference" TEXT, "accepted_by" TEXT, "accepted_at" TEXT, "closed_at" TEXT, "created_by" TEXT, "decision_note" TEXT,
            FOREIGN KEY (project_id) REFERENCES research_projects (project_id)
        );
CREATE TABLE grant_budget_allocations (
                    allocation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grant_application_id INTEGER NOT NULL,
                    category_id INTEGER NOT NULL,
                    allocated_amount REAL DEFAULT 0,
                    spent_amount REAL DEFAULT 0,
                    committed_amount REAL DEFAULT 0,
                    remaining_amount REAL DEFAULT 0,
                    alert_threshold_pct REAL DEFAULT 80,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (grant_application_id) REFERENCES grant_applications(application_id),
                    FOREIGN KEY (category_id) REFERENCES grant_budget_categories(category_id)
                );
CREATE TABLE grant_budget_categories (
                    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    is_active INTEGER DEFAULT 1,
                    sort_order INTEGER,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                , [updated_at] TEXT);
CREATE TABLE grant_budget_transfers (
                    transfer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grant_application_id INTEGER NOT NULL,
                    from_allocation_id INTEGER NOT NULL,
                    to_allocation_id INTEGER NOT NULL,
                    amount REAL NOT NULL,
                    reason TEXT,
                    status TEXT DEFAULT 'pending',
                    requested_by TEXT,
                    approved_by TEXT,
                    approved_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP, [updated_at] TEXT, "approved_at" TEXT,
                    FOREIGN KEY (grant_application_id) REFERENCES grant_applications(application_id),
                    FOREIGN KEY (from_allocation_id) REFERENCES grant_budget_allocations(allocation_id),
                    FOREIGN KEY (to_allocation_id) REFERENCES grant_budget_allocations(allocation_id)
                );
CREATE TABLE grant_budgets (
            budget_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            category TEXT NOT NULL,
            description TEXT,
            requested_amount REAL NOT NULL,
            approved_amount REAL,
            spent_amount REAL DEFAULT 0,
            remaining_amount REAL,
            FOREIGN KEY (application_id) REFERENCES grant_applications (application_id)
        );
CREATE TABLE grant_cost_lines (
        line_id INTEGER PRIMARY KEY AUTOINCREMENT,
        application_id INTEGER NOT NULL REFERENCES grant_applications(application_id)
            ON DELETE CASCADE,
        category TEXT NOT NULL CHECK (category IN ('directly_incurred', 'directly_allocated',
            'indirect', 'exception')),
        item TEXT NOT NULL,
        amount REAL NOT NULL CHECK (amount >= 0)
    );
CREATE TABLE grant_expense_items (
                    expense_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grant_application_id INTEGER NOT NULL,
                    allocation_id INTEGER NOT NULL,
                    category_id INTEGER NOT NULL,
                    description TEXT NOT NULL,
                    amount REAL NOT NULL,
                    expense_date TEXT,
                    vendor TEXT,
                    receipt_path TEXT,
                    invoice_number TEXT,
                    status TEXT DEFAULT 'draft',
                    submitted_by TEXT,
                    approved_by TEXT,
                    approved_date TEXT,
                    payment_reference TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP, "approved_at" TEXT,
                    FOREIGN KEY (grant_application_id) REFERENCES grant_applications(application_id),
                    FOREIGN KEY (allocation_id) REFERENCES grant_budget_allocations(allocation_id),
                    FOREIGN KEY (category_id) REFERENCES grant_budget_categories(category_id)
                );
CREATE TABLE grant_funding_alerts (
                    alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grant_application_id INTEGER NOT NULL,
                    allocation_id INTEGER,
                    alert_type TEXT DEFAULT 'threshold',
                    severity TEXT DEFAULT 'info',
                    message TEXT NOT NULL,
                    is_read INTEGER DEFAULT 0,
                    is_resolved INTEGER DEFAULT 0,
                    triggered_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    resolved_at TEXT,
                    resolved_by TEXT, "created_at" TEXT,
                    FOREIGN KEY (grant_application_id) REFERENCES grant_applications(application_id),
                    FOREIGN KEY (allocation_id) REFERENCES grant_budget_allocations(allocation_id)
                );
CREATE TABLE grant_reports (
        report_id INTEGER PRIMARY KEY AUTOINCREMENT,
        application_id INTEGER NOT NULL REFERENCES grant_applications(application_id)
            ON DELETE CASCADE,
        kind TEXT NOT NULL CHECK (kind IN ('interim', 'final', 'financial', 'other')),
        due_date TEXT NOT NULL,
        submitted_at TEXT,
        submitted_by TEXT,
        note TEXT
    );
CREATE TABLE grant_spend (
        spend_id INTEGER PRIMARY KEY AUTOINCREMENT,
        budget_id INTEGER NOT NULL REFERENCES grant_budgets(budget_id),
        amount REAL NOT NULL,
        spent_on TEXT NOT NULL,
        description TEXT NOT NULL,
        recorded_by TEXT,
        recorded_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE grant_tracker_alerts (
                id INTEGER PRIMARY KEY AUTOINCREMENT, grant_id INTEGER NOT NULL,
                alert_type TEXT DEFAULT 'submission', alert_date TEXT, message TEXT,
                is_sent INTEGER DEFAULT 0, sent_at TEXT,
                FOREIGN KEY (grant_id) REFERENCES grant_tracker_apps(id));
CREATE TABLE grant_tracker_apps (
                id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL,
                funding_body TEXT, principal_investigator TEXT, co_investigators TEXT,
                department TEXT, amount_requested REAL DEFAULT 0, amount_awarded REAL DEFAULT 0,
                status TEXT DEFAULT 'draft', deadline TEXT, submitted_at TEXT,
                decision_date TEXT, start_date TEXT, end_date TEXT, abstract TEXT,
                created_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE grant_tracker_budget (
                id INTEGER PRIMARY KEY AUTOINCREMENT, grant_id INTEGER NOT NULL,
                category TEXT DEFAULT 'other', description TEXT, amount REAL DEFAULT 0,
                is_approved INTEGER DEFAULT 0,
                FOREIGN KEY (grant_id) REFERENCES grant_tracker_apps(id));
CREATE TABLE grant_tracker_milestones (
                id INTEGER PRIMARY KEY AUTOINCREMENT, grant_id INTEGER NOT NULL,
                milestone_title TEXT NOT NULL, description TEXT, deadline TEXT,
                status TEXT DEFAULT 'pending', completed_at TEXT, notes TEXT,
                FOREIGN KEY (grant_id) REFERENCES grant_tracker_apps(id));
CREATE TABLE green_certifications (
                cert_id INTEGER PRIMARY KEY AUTOINCREMENT,
                entity_name TEXT,
                entity_type TEXT,
                certification_level TEXT,
                score REAL DEFAULT 0,
                awarded_date TEXT,
                expires_date TEXT,
                notes TEXT
            );
CREATE TABLE green_initiatives (
                initiative_id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                description TEXT,
                category TEXT,
                status TEXT DEFAULT 'active',
                created_by TEXT,
                created_date TEXT,
                target_date TEXT,
                carbon_target REAL,
                notes TEXT
            );
CREATE TABLE green_transport_log (
                log_id INTEGER PRIMARY KEY AUTOINCREMENT,
                transport_method TEXT,
                distance_km REAL DEFAULT 0,
                carbon_saved REAL DEFAULT 0,
                trip_date TEXT,
                recorded_by TEXT,
                recorded_date TEXT
            );
CREATE TABLE grievance_actions (
                    action_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grievance_id INTEGER NOT NULL,
                    action_type TEXT NOT NULL,
                    action_date TEXT NOT NULL,
                    taken_by TEXT NOT NULL,
                    details TEXT,
                    outcome TEXT,
                    next_action TEXT,
                    next_action_date TEXT,
                    documents_path TEXT,
                    is_visible_to_complainant BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (grievance_id) REFERENCES grievances(grievance_id)
                );
CREATE TABLE grievance_categories (
                    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    severity_level INTEGER DEFAULT 1,
                    requires_investigation BOOLEAN DEFAULT 1,
                    sla_days INTEGER DEFAULT 30,
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE grievance_meetings (
                    meeting_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grievance_id INTEGER NOT NULL,
                    meeting_date TEXT NOT NULL,
                    meeting_time TEXT,
                    location TEXT,
                    attendees TEXT,
                    purpose TEXT,
                    minutes TEXT,
                    outcomes TEXT,
                    follow_up_actions TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (grievance_id) REFERENCES grievances(grievance_id)
                );
CREATE TABLE grievances (
                    grievance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    reference_number TEXT UNIQUE,
                    complainant_id TEXT NOT NULL,
                    respondent_id TEXT,
                    category_id INTEGER,
                    category_other TEXT,
                    subject TEXT NOT NULL,
                    description TEXT NOT NULL,
                    is_anonymous BOOLEAN DEFAULT 0,
                    is_confidential BOOLEAN DEFAULT 1,
                    status TEXT DEFAULT 'submitted',
                    priority TEXT DEFAULT 'normal',
                    assigned_to TEXT,
                    filed_date TEXT NOT NULL,
                    acknowledged_date TEXT,
                    investigation_start_date TEXT,
                    resolution_date TEXT,
                    resolution_type TEXT,
                    resolution_summary TEXT,
                    outcome TEXT,
                    appeal_deadline TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (category_id) REFERENCES grievance_categories(category_id)
                );
CREATE TABLE grocery_categories (
            category_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            description TEXT,
            display_order INTEGER DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT NOT NULL
        );
CREATE TABLE "grocery_stock_movements" (
            movement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL,
            movement_type TEXT NOT NULL,
            quantity INTEGER NOT NULL,
            previous_stock INTEGER,
            new_stock INTEGER,
            reference TEXT,
            notes TEXT,
            created_by INTEGER,
            created_at TEXT NOT NULL,
    FOREIGN KEY (product_id) REFERENCES products(product_id)
        );
CREATE TABLE grocery_suppliers (
            supplier_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            contact_person TEXT,
            email TEXT,
            phone TEXT,
            address TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT NOT NULL
        );
CREATE TABLE "grocery_transaction_items" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            transaction_id INTEGER NOT NULL,
            product_id INTEGER NOT NULL,
            product_name TEXT NOT NULL,
            quantity INTEGER NOT NULL,
            unit_price REAL NOT NULL,
            discount REAL DEFAULT 0,
            subtotal REAL NOT NULL,
    FOREIGN KEY (transaction_id) REFERENCES transactions(transaction_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
        );
CREATE TABLE "group_members" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                group_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                role TEXT DEFAULT 'member',
                joined_at TEXT NOT NULL,
                contribution_score REAL DEFAULT 0,
                FOREIGN KEY (group_id) REFERENCES groups (id) ON DELETE CASCADE,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE "group_message_recipients" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                message_id INTEGER NOT NULL,
                recipient_id INTEGER NOT NULL,
                is_read INTEGER DEFAULT 0,
                is_archived INTEGER DEFAULT 0,
                is_deleted INTEGER DEFAULT 0,
                read_at TEXT,
                FOREIGN KEY (message_id) REFERENCES group_messages (id) ON DELETE CASCADE,
                FOREIGN KEY (recipient_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "group_messages" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                sender_id INTEGER NOT NULL,
                group_type TEXT NOT NULL,
                group_id TEXT NOT NULL,
                subject TEXT NOT NULL,
                content TEXT NOT NULL,
                attachment_path TEXT,
                sent_at TEXT NOT NULL,
                FOREIGN KEY (sender_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE "groups" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                assignment_id INTEGER NOT NULL,
                group_name TEXT NOT NULL,
                created_at TEXT NOT NULL,
                created_by TEXT,
                is_active INTEGER DEFAULT 1, description TEXT,
                FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE
            );
CREATE TABLE gym_attendance (
                    attendance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    member_id INTEGER NOT NULL,
                    check_in TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    check_out TIMESTAMP,
                    FOREIGN KEY (member_id) REFERENCES gym_memberships(membership_id)
                );
CREATE TABLE gym_class_bookings (
                    booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    booking_ref TEXT UNIQUE NOT NULL,
                    class_id INTEGER NOT NULL,
                    member_id INTEGER NOT NULL,
                    booking_date DATE NOT NULL,
                    status TEXT DEFAULT 'confirmed',
                    attended INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "user_id" TEXT, "user_name" TEXT,
                    FOREIGN KEY (class_id) REFERENCES gym_classes(class_id),
                    FOREIGN KEY (member_id) REFERENCES gym_memberships(membership_id)
                );
CREATE TABLE gym_classes (
                    class_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    class_name TEXT NOT NULL,
                    class_type TEXT NOT NULL,
                    instructor_id TEXT,
                    instructor_name TEXT NOT NULL,
                    schedule_day TEXT NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    location TEXT NOT NULL,
                    max_capacity INTEGER DEFAULT 20,
                    current_enrolled INTEGER DEFAULT 0,
                    description TEXT,
                    difficulty_level TEXT DEFAULT 'all_levels',
                    status TEXT DEFAULT 'active',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE gym_day_passes (
    pass_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    granted_at TEXT NOT NULL,
    used_at    TEXT,
    reason     TEXT
);
CREATE TABLE gym_equipment (
                    equipment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    equipment_name TEXT NOT NULL,
                    category TEXT NOT NULL,
                    brand TEXT,
                    model TEXT,
                    serial_number TEXT,
                    purchase_date DATE,
                    location TEXT,
                    status TEXT DEFAULT 'available',
                    last_maintenance DATE,
                    next_maintenance DATE,
                    notes TEXT
                );
CREATE TABLE gym_memberships (
                    membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    member_number TEXT UNIQUE NOT NULL,
                    user_id TEXT NOT NULL,
                    user_name TEXT NOT NULL,
                    user_email TEXT,
                    user_phone TEXT,
                    membership_type TEXT NOT NULL,
                    monthly_fee DECIMAL(10,2) NOT NULL,
                    start_date DATE NOT NULL,
                    end_date DATE,
                    status TEXT DEFAULT 'active',
                    auto_renew INTEGER DEFAULT 1,
                    emergency_contact TEXT,
                    emergency_phone TEXT,
                    health_conditions TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    created_by TEXT
                );
CREATE TABLE gym_pt_sessions (
                    session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    booking_ref TEXT UNIQUE NOT NULL,
                    member_id INTEGER NOT NULL,
                    trainer_id TEXT,
                    trainer_name TEXT NOT NULL,
                    session_date DATE NOT NULL,
                    session_time TEXT NOT NULL,
                    duration_minutes INTEGER DEFAULT 60,
                    session_type TEXT DEFAULT 'single',
                    fee DECIMAL(10,2) NOT NULL,
                    payment_status TEXT DEFAULT 'pending',
                    status TEXT DEFAULT 'scheduled',
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "user_id" TEXT, "user_name" TEXT,
                    FOREIGN KEY (member_id) REFERENCES gym_memberships(membership_id)
                );
CREATE TABLE health_advisories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT,
            advisory_type TEXT,
            content TEXT,
            priority TEXT,
            target_audience TEXT,
            effective_date TEXT,
            expiry_date TEXT,
            issued_by TEXT,
            status TEXT DEFAULT 'active',
            created_at TEXT
        );
CREATE TABLE health_appointments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    appointment_type TEXT,
                    appointment_date TEXT,
                    appointment_time TEXT,
                    provider TEXT,
                    reason TEXT,
                    status TEXT DEFAULT 'scheduled',
                    notes TEXT,
                    scheduled_at TEXT, "department" TEXT, "has_conflict" INTEGER DEFAULT 0, "duration_minutes" INTEGER DEFAULT 30,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE health_campaigns (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    campaign_name TEXT,
                    campaign_type TEXT,
                    start_date TEXT,
                    end_date TEXT,
                    target_population TEXT,
                    description TEXT,
                    goals TEXT,
                    status TEXT DEFAULT 'planned',
                    budget REAL,
                    created_by TEXT,
                    created_at TEXT
                );
CREATE TABLE health_metrics (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    metric_name TEXT,
                    metric_value REAL,
                    measurement_date TEXT,
                    category TEXT,
                    subcategory TEXT,
                    metadata TEXT,
                    calculated_at TEXT
                );
CREATE TABLE health_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT,
    record_type TEXT,
    record_date TEXT,
    description TEXT,
    provider TEXT,
    confidential INTEGER DEFAULT 0,
    created_at TEXT,
    encrypted_data TEXT
, "allergies" TEXT, "blood_type" TEXT, "conditions" TEXT, "insurance_policy_number" TEXT, "insurance_provider" TEXT, "last_updated" TIMESTAMP, "medications" TEXT, "archived" INTEGER DEFAULT 0, "archived_at" TEXT, "archived_by" TEXT, "archive_reason" TEXT);
CREATE TABLE hear_achievements (
        achievement_id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        category TEXT NOT NULL,
        description TEXT NOT NULL,
        verified_by TEXT,
        verified_at TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE helpdesk_system_settings (
                    setting_key TEXT PRIMARY KEY,
                    setting_value TEXT,
                    updated_at TEXT
                );
CREATE TABLE hesa_field_mappings (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    return_type TEXT NOT NULL,
                    hesa_field TEXT NOT NULL,
                    local_field TEXT NOT NULL,
                    transform_rule TEXT,
                    is_active INTEGER DEFAULT 1
                );
CREATE TABLE hesa_returns (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    academic_year TEXT NOT NULL,
                    return_type TEXT NOT NULL,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    submitted_at TEXT,
                    xml_data TEXT,
                    notes TEXT
                );
CREATE TABLE hesa_submission_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    return_id INTEGER NOT NULL,
                    action TEXT NOT NULL,
                    details TEXT,
                    performed_by TEXT,
                    performed_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (return_id) REFERENCES hesa_returns(id)
                );
CREATE TABLE historical_degree_audits (
            audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL, assignment_id INTEGER NOT NULL,
            regulation_version_id INTEGER NOT NULL, input_json TEXT NOT NULL,
            result_json TEXT NOT NULL, snapshot_hash TEXT NOT NULL,
            calculated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE holidays (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                holiday_name TEXT,
                start_date DATE,
                end_date DATE,
                description TEXT,
                recurring BOOLEAN DEFAULT 0
            , "name" TEXT, "source" TEXT, "year_code" TEXT);
CREATE TABLE homework_assignments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                module_code TEXT,
                assignment_title TEXT,
                description TEXT,
                assigned_date TEXT,
                due_date TEXT,
                completion_status TEXT DEFAULT 'pending',
                submitted_date TEXT,
                grade TEXT,
                teacher_comments TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (module_code) REFERENCES modules (module_code)
            );
CREATE TABLE housing_applications (
            application_id TEXT PRIMARY KEY,
            student_id TEXT NOT NULL,
            application_date TEXT NOT NULL,
            preferred_building_id TEXT,
            preferred_room_type TEXT NOT NULL,
            requested_move_in_date TEXT NOT NULL,
            requested_duration_months INTEGER NOT NULL,
            special_requirements TEXT,
            status TEXT NOT NULL,
            notes TEXT,
            reviewed_by TEXT,
            review_date TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (preferred_building_id) REFERENCES housing_buildings (building_id)
        );
CREATE TABLE housing_assignments (
            assignment_id TEXT PRIMARY KEY,
            application_id TEXT,
            student_id TEXT NOT NULL,
            room_id TEXT NOT NULL,
            move_in_date TEXT NOT NULL,
            planned_move_out_date TEXT NOT NULL,
            actual_move_out_date TEXT,
            contract_number TEXT UNIQUE,
            monthly_rent REAL NOT NULL,
            status TEXT NOT NULL,
            assigned_by TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL, tdp_scheme TEXT, tdp_scheme_reference TEXT, tdp_protected_at TEXT, tdp_prescribed_info_sent_at TEXT, tdp_deadline TEXT, tdp_exempt_reason TEXT, deposit_interest_last_accrual_date TEXT, deposit_interest_policy TEXT, deposit_state TEXT, deposit_interest_rate REAL DEFAULT 0, deposit_interest_accrued REAL DEFAULT 0, "building_name" TEXT, "end_date" TEXT, "room_number" INTEGER, "start_date" TEXT,
            FOREIGN KEY (application_id) REFERENCES housing_applications (application_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (room_id) REFERENCES housing_rooms (room_id)
        );
CREATE TABLE housing_broadcasts (
                    broadcast_id    TEXT PRIMARY KEY,
                    subject         TEXT NOT NULL,
                    body            TEXT NOT NULL,
                    audience_building_id TEXT,
                    audience_room_type   TEXT,
                    recipient_count INTEGER NOT NULL,
                    sent_by         TEXT NOT NULL,
                    sent_at         TEXT NOT NULL
                );
CREATE TABLE housing_buildings (
            building_id TEXT PRIMARY KEY,
            building_name TEXT NOT NULL,
            address TEXT NOT NULL,
            campus_location TEXT NOT NULL,
            total_rooms INTEGER NOT NULL,
            available_rooms INTEGER NOT NULL,
            has_elevator BOOLEAN DEFAULT 0,
            has_accessible_rooms BOOLEAN DEFAULT 0,
            has_kitchen BOOLEAN DEFAULT 0,
            has_laundry BOOLEAN DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE housing_checklist_items (
                    item_id TEXT PRIMARY KEY,
                    checklist_id TEXT NOT NULL,
                    area TEXT NOT NULL,                      -- e.g. 'Kitchen', 'Bathroom'
                    description TEXT NOT NULL,
                    condition TEXT,                          -- 'Good' | 'Damaged' | 'Missing'
                    notes TEXT,
                    FOREIGN KEY (checklist_id)
                        REFERENCES housing_checklists (checklist_id)
                            ON DELETE CASCADE
                );
CREATE TABLE housing_checklist_photos (
                    photo_id TEXT PRIMARY KEY,
                    item_id TEXT NOT NULL,
                    stored_path TEXT NOT NULL,
                    caption TEXT,
                    uploaded_at TEXT NOT NULL,
                    FOREIGN KEY (item_id)
                        REFERENCES housing_checklist_items (item_id)
                            ON DELETE CASCADE
                );
CREATE TABLE housing_checklists (
                    checklist_id TEXT PRIMARY KEY,
                    inspection_id TEXT,
                    assignment_id TEXT NOT NULL,
                    template TEXT NOT NULL,                  -- 'move-in' | 'move-out'
                    completed_by TEXT,
                    completed_at TEXT,
                    notes TEXT,
                    created_at TEXT NOT NULL,
                    FOREIGN KEY (assignment_id)
                        REFERENCES housing_assignments (assignment_id),
                    FOREIGN KEY (inspection_id)
                        REFERENCES housing_inspections (inspection_id)
                );
CREATE TABLE housing_contract_documents (
                    doc_id TEXT PRIMARY KEY,
                    assignment_id TEXT NOT NULL,
                    original_filename TEXT NOT NULL,
                    stored_path TEXT NOT NULL,
                    notes TEXT,
                    uploaded_by TEXT NOT NULL,
                    uploaded_at TEXT NOT NULL,
                    FOREIGN KEY (assignment_id)
                        REFERENCES housing_assignments (assignment_id)
                );
CREATE TABLE housing_deposit_deductions (
            deduction_id TEXT PRIMARY KEY,
            assignment_id TEXT NOT NULL,
            deposit_payment_id TEXT,
            inspection_id TEXT,
            description TEXT NOT NULL,
            amount REAL NOT NULL,
            status TEXT NOT NULL DEFAULT 'Proposed',
            acknowledgement_status TEXT NOT NULL DEFAULT 'Pending',
            acknowledged_at TEXT,
            dispute_reason TEXT,
            dispute_resolution_notes TEXT,
            dispute_resolved_by TEXT,
            dispute_resolved_at TEXT,
            created_by TEXT NOT NULL,
            created_at TEXT NOT NULL,
            applied_at TEXT,
            FOREIGN KEY (assignment_id) REFERENCES housing_assignments (assignment_id),
            FOREIGN KEY (inspection_id) REFERENCES housing_inspections (inspection_id)
        );
CREATE TABLE housing_deposit_interest_accruals (
            accrual_id TEXT PRIMARY KEY,
            assignment_id TEXT NOT NULL,
            period_start TEXT NOT NULL,
            period_end TEXT NOT NULL,
            principal REAL NOT NULL,
            annual_rate REAL NOT NULL,
            days INTEGER NOT NULL,
            amount REAL NOT NULL,
            created_by TEXT NOT NULL,
            created_at TEXT NOT NULL,
            FOREIGN KEY (assignment_id) REFERENCES housing_assignments (assignment_id)
        );
CREATE TABLE housing_deposit_state_log (
            log_id TEXT PRIMARY KEY,
            assignment_id TEXT NOT NULL,
            from_state TEXT,
            to_state TEXT NOT NULL,
            reason TEXT,
            actor TEXT NOT NULL,
            created_at TEXT NOT NULL,
            FOREIGN KEY (assignment_id) REFERENCES housing_assignments (assignment_id)
        );
CREATE TABLE housing_guest_passes (
                    pass_id TEXT PRIMARY KEY,
                    assignment_id TEXT NOT NULL,
                    guest_name TEXT NOT NULL,
                    guest_relation TEXT,
                    id_type TEXT,
                    id_reference TEXT,
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    overnight INTEGER DEFAULT 0,
                    status TEXT NOT NULL DEFAULT 'Pending',  -- 'Pending'|'Approved'|'Denied'|'Cancelled'
                    decision_by TEXT,
                    decision_at TEXT,
                    notes TEXT,
                    requested_by TEXT,
                    requested_at TEXT NOT NULL,
                    FOREIGN KEY (assignment_id)
                        REFERENCES housing_assignments (assignment_id)
                );
CREATE TABLE housing_inspections (
            inspection_id TEXT PRIMARY KEY,
            room_id TEXT NOT NULL,
            inspector TEXT NOT NULL,
            inspection_date TEXT NOT NULL,
            inspection_type TEXT NOT NULL,
            status TEXT NOT NULL,
            findings TEXT,
            action_required TEXT,
            follow_up_date TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL, "acknowledgement_status" TEXT, "amount" REAL, "description" TEXT, "dispute_reason" TEXT, "dispute_resolution_notes" TEXT,
            FOREIGN KEY (room_id) REFERENCES housing_rooms (room_id)
        );
CREATE TABLE housing_inventory (
            item_id TEXT PRIMARY KEY,
            room_id TEXT NOT NULL,
            item_name TEXT NOT NULL,
            item_type TEXT NOT NULL,
            condition TEXT NOT NULL,
            acquisition_date TEXT,
            status TEXT NOT NULL,
            notes TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (room_id) REFERENCES housing_rooms (room_id)
        );
CREATE TABLE housing_maintenance_requests (
            request_id TEXT PRIMARY KEY,
            room_id TEXT NOT NULL,
            student_id TEXT NOT NULL,
            request_date TEXT NOT NULL,
            issue_type TEXT NOT NULL,
            description TEXT NOT NULL,
            priority TEXT NOT NULL,
            status TEXT NOT NULL,
            assigned_to TEXT,
            scheduled_date TEXT,
            completion_date TEXT,
            feedback TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (room_id) REFERENCES housing_rooms (room_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE housing_rooms (
            room_id TEXT PRIMARY KEY,
            building_id TEXT NOT NULL,
            room_number TEXT NOT NULL,
            floor_number INTEGER NOT NULL,
            room_type TEXT NOT NULL,
            max_occupants INTEGER NOT NULL,
            current_occupants INTEGER DEFAULT 0,
            is_accessible BOOLEAN DEFAULT 0,
            status TEXT NOT NULL,
            monthly_rent REAL NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (building_id) REFERENCES housing_buildings (building_id)
        );
CREATE TABLE housing_waitlist (
                    waitlist_id    TEXT PRIMARY KEY,
                    application_id TEXT NOT NULL,
                    student_id     TEXT NOT NULL,
                    building_id    TEXT,
                    room_type      TEXT,
                    priority       INTEGER NOT NULL DEFAULT 0,
                    status         TEXT NOT NULL DEFAULT 'Waiting',
                    notes          TEXT,
                    promoted_to_assignment_id TEXT,
                    added_at       TEXT NOT NULL,
                    updated_at     TEXT NOT NULL,
                    FOREIGN KEY (application_id)
                        REFERENCES housing_applications (application_id),
                    FOREIGN KEY (student_id)
                        REFERENCES students (student_id),
                    FOREIGN KEY (building_id)
                        REFERENCES housing_buildings (building_id)
                );
CREATE TABLE hr_peer_review_assignments (
                    assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    reviewer_id TEXT NOT NULL,
                    assigned_by TEXT,
                    due_date TEXT,
                    status TEXT DEFAULT 'assigned',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES peer_review_submissions(submission_id)
                );
CREATE TABLE hs_hazards (
                    id              INTEGER PRIMARY KEY AUTOINCREMENT,
                    ref             TEXT,
                    category        TEXT,
                    location        TEXT,
                    risk_level      TEXT,
                    description     TEXT,
                    mitigation      TEXT,
                    reported_by     TEXT,
                    department      TEXT,
                    status          TEXT DEFAULT 'Active',
                    reported_at     TEXT NOT NULL
                );
CREATE TABLE hs_incidents (
                    id              INTEGER PRIMARY KEY AUTOINCREMENT,
                    ref             TEXT,
                    incident_type   TEXT,
                    location        TEXT,
                    incident_date   TEXT,
                    severity        TEXT,
                    people_involved TEXT,
                    description     TEXT,
                    actions_taken   TEXT,
                    reported_by     TEXT,
                    department      TEXT,
                    status          TEXT DEFAULT 'Open',
                    reported_at     TEXT NOT NULL,
                    updated_at      TEXT
                );
CREATE TABLE hs_training (
                    id              INTEGER PRIMARY KEY AUTOINCREMENT,
                    user            TEXT NOT NULL,
                    module          TEXT NOT NULL,
                    department      TEXT,
                    completed_at    TEXT NOT NULL
                );
CREATE TABLE hydration_tracking (
                    hydration_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    tracking_date TEXT NOT NULL,
                    glasses_consumed INTEGER DEFAULT 0,
                    daily_goal INTEGER DEFAULT 8,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE immutable_audit_log (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        timestamp TEXT NOT NULL,
                        user_id TEXT,
                        action TEXT NOT NULL,
                        resource_type TEXT,
                        resource_id TEXT,
                        details TEXT,
                        ip_address TEXT,
                        user_agent TEXT,
                        session_id TEXT,
                        previous_hash TEXT,
                        current_hash TEXT NOT NULL,
                        hmac_signature TEXT NOT NULL,
                        UNIQUE(current_hash)
                    );
CREATE TABLE import_history (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        timestamp TEXT NOT NULL,
                        operation_type TEXT NOT NULL,
                        file_path TEXT NOT NULL,
                        total_records INTEGER DEFAULT 0,
                        successful_imports INTEGER DEFAULT 0,
                        failed_imports INTEGER DEFAULT 0,
                        duplicates_found INTEGER DEFAULT 0,
                        validation_errors INTEGER DEFAULT 0,
                        error_details TEXT,
                        duration_seconds REAL,
                        status TEXT DEFAULT 'completed'
                    );
CREATE TABLE "incident_response_actions" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                incident_id INTEGER NOT NULL,
                action_type TEXT NOT NULL,
                action_details TEXT,
                performed_by INTEGER,
                performed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (incident_id) REFERENCES security_incidents(id),
                FOREIGN KEY (performed_by) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE incidents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            incident_type TEXT NOT NULL,
            severity TEXT DEFAULT 'low',
            description TEXT NOT NULL,
            location TEXT,
            screen_number INTEGER,
            incident_datetime TEXT NOT NULL,
            reported_by_staff_id INTEGER,
            witnesses TEXT,
            immediate_action_taken TEXT,
            resolution TEXT,
            resolved_by_staff_id INTEGER,
            resolved_datetime TEXT,
            customer_involved INTEGER DEFAULT 0,
            customer_name TEXT,
            customer_contact TEXT,
            follow_up_required INTEGER DEFAULT 0,
            follow_up_notes TEXT,
            follow_up_completed INTEGER DEFAULT 0,
            status TEXT DEFAULT 'open',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP, "student_id" TEXT, "category" TEXT, "details" TEXT, "raised_by" TEXT,
            FOREIGN KEY (reported_by_staff_id) REFERENCES staff(id),
            FOREIGN KEY (resolved_by_staff_id) REFERENCES staff(id)
        );
CREATE TABLE installed_integrations (
            install_id INTEGER PRIMARY KEY AUTOINCREMENT,
            integration_id INTEGER NOT NULL,
            installed_by TEXT NOT NULL,
            installation_date TEXT DEFAULT CURRENT_TIMESTAMP,
            version_installed TEXT,
            configuration TEXT,
            status TEXT DEFAULT 'active',
            last_sync_date TEXT,
            sync_frequency TEXT,
            is_enabled BOOLEAN DEFAULT 1,
            FOREIGN KEY (integration_id) REFERENCES integration_catalog (integration_id)
        );
CREATE TABLE institutional_case_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT, case_id TEXT NOT NULL,
            event_type TEXT NOT NULL, payload_json TEXT NOT NULL,
            actor_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(case_id) REFERENCES institutional_cases(case_id)
        );
CREATE TABLE institutional_cases (
            case_id TEXT PRIMARY KEY, case_type TEXT NOT NULL,
            subject_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open',
            summary TEXT NOT NULL, owner_id TEXT, confidentiality TEXT NOT NULL,
            opened_by TEXT NOT NULL, opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            closed_at TEXT, UNIQUE(case_type, subject_id, summary)
        );
CREATE TABLE institutions (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                type TEXT,
                country TEXT,
                created_at TEXT NOT NULL
            );
CREATE TABLE instructor_modules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            instructor_id INTEGER NOT NULL,
            module_code TEXT NOT NULL,
            academic_year TEXT,
            semester TEXT,
            FOREIGN KEY (instructor_id) REFERENCES instructors(id),
            FOREIGN KEY (module_code) REFERENCES modules(module_code),
            UNIQUE(instructor_id, module_code)
        );
CREATE TABLE instructor_performance_history (
            performance_id INTEGER PRIMARY KEY AUTOINCREMENT,
            instructor_id TEXT NOT NULL,
            academic_year TEXT NOT NULL,
            semester TEXT NOT NULL,
            avg_overall_rating REAL,
            avg_teaching_effectiveness REAL,
            avg_course_organization REAL,
            avg_student_engagement REAL,
            total_evaluations INTEGER,
            total_responses INTEGER,
            calculated_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE instructor_schedules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            instructor_id INTEGER NOT NULL,
            module_code TEXT NOT NULL,
            day_of_week TEXT NOT NULL,
            time_slot TEXT NOT NULL,
            room TEXT,
            academic_year TEXT,
            semester TEXT,
            FOREIGN KEY (instructor_id) REFERENCES instructors(id),
            FOREIGN KEY (module_code) REFERENCES modules(module_code)
        );
CREATE TABLE instructors (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                first_name TEXT NOT NULL,
                last_name TEXT NOT NULL,
                email TEXT UNIQUE NOT NULL,
                department TEXT DEFAULT '',
                specialization TEXT DEFAULT '',
                max_courses_per_semester INTEGER DEFAULT 4,
                max_hours_per_week INTEGER DEFAULT 40,
                preferred_days TEXT,
                preferred_times TEXT,
                status TEXT DEFAULT 'Active',
                is_active BOOLEAN DEFAULT 1,
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now'))
            , "staff_id" INTEGER);
CREATE TABLE insurance_information (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            insurance_provider TEXT,
            policy_number TEXT,
            group_number TEXT,
            subscriber_name TEXT,
            relationship_to_subscriber TEXT,
            effective_date TEXT,
            expiry_date TEXT,
            created_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE insurance_integration_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                claim_id TEXT,
                patient_id TEXT,
                event_type TEXT,        -- submitted/approved/denied/cancelled
                status TEXT,
                external_id TEXT,
                correlation_id TEXT,
                payload TEXT,
                response TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT
            );
CREATE TABLE integration_catalog (
            integration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            integration_name TEXT NOT NULL,
            provider_name TEXT NOT NULL,
            integration_type TEXT NOT NULL,
            category TEXT NOT NULL,
            description TEXT,
            version TEXT,
            logo_url TEXT,
            documentation_url TEXT,
            pricing_model TEXT,
            is_official BOOLEAN DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            rating REAL DEFAULT 0,
            install_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , min_version TEXT);
CREATE TABLE integration_credentials (
            credential_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            credential_type TEXT NOT NULL,
            api_key TEXT,
            api_secret TEXT,
            oauth_token TEXT,
            refresh_token TEXT,
            token_expiry TEXT,
            endpoint_url TEXT,
            additional_config TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT, "oauth_refresh_token" TEXT,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_data_mappings (
            mapping_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            source_field TEXT NOT NULL,
            target_field TEXT NOT NULL,
            transformation_rule TEXT,
            is_active BOOLEAN DEFAULT 1,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_log (
    log_id        INTEGER PRIMARY KEY AUTOINCREMENT,
    event_name    TEXT NOT NULL,
    source_module TEXT NOT NULL,
    payload_json  TEXT NOT NULL,
    created_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE integration_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                provider TEXT,          -- e.g., 'insurance','lab','hl7','fhir'
                system   TEXT,          -- optional: vendor/system name
                event_type TEXT,
                status TEXT,            -- success, error, pending
                message TEXT,
                correlation_id TEXT,
                http_status INTEGER,
                duration_ms INTEGER,
                endpoint TEXT,
                payload TEXT,
                response TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE integration_sync_logs (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            sync_start_time TEXT DEFAULT CURRENT_TIMESTAMP,
            sync_end_time TEXT,
            sync_status TEXT NOT NULL,
            records_synced INTEGER DEFAULT 0,
            errors_encountered INTEGER DEFAULT 0,
            error_details TEXT,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_usage_analytics (
            analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            metric_name TEXT NOT NULL,
            metric_value REAL NOT NULL,
            measurement_date TEXT DEFAULT CURRENT_DATE,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_webhooks (
            webhook_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            webhook_url TEXT NOT NULL,
            event_type TEXT NOT NULL,
            secret_key TEXT,
            is_active BOOLEAN DEFAULT 1,
            last_triggered_at TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integrity_acknowledgements (
        username TEXT NOT NULL,
        notice_version TEXT NOT NULL,
        acknowledged_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (username, notice_version)
    );
CREATE TABLE integrity_ai_reviews (
        ai_result_id INTEGER PRIMARY KEY,
        decision TEXT NOT NULL CHECK (decision IN ('no_concern', 'refer')),
        note TEXT,
        reviewed_by TEXT,
        reviewed_at TEXT NOT NULL DEFAULT (datetime('now')),
        case_id INTEGER
    );
CREATE TABLE integrity_appeals (
        appeal_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL,
        grounds TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'lodged' CHECK (status IN ('lodged', 'upheld', 'rejected')),
        lodged_by TEXT NOT NULL,
        lodged_at TEXT NOT NULL DEFAULT (datetime('now')),
        decided_by TEXT,
        decided_at TEXT,
        decision_note TEXT
    );
CREATE TABLE integrity_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        entity TEXT NOT NULL,
        entity_id TEXT,
        action TEXT NOT NULL,
        actor TEXT,
        detail TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE integrity_case_events (
        event_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL,
        stage TEXT NOT NULL,
        note TEXT,
        actor TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE "integrity_cases" (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        assignment_id INTEGER,
        case_type TEXT NOT NULL CHECK(case_type IN ('plagiarism', 'collusion', 'cheating', 'contract_cheating', 'ai_misuse', 'fabrication', 'other')),
        description TEXT,
        evidence_path TEXT,
        status TEXT NOT NULL DEFAULT 'open'
            CHECK(status IN ('open','investigating','resolved','dismissed')),
        outcome TEXT,
        penalty TEXT,
        created_by TEXT,
        created_at TEXT DEFAULT (datetime('now')),
        resolved_at TEXT,
        evidence TEXT,
        updated_at TEXT,
        result_id INTEGER,
        submission_id INTEGER,
        stage TEXT DEFAULT 'referred',
        decided_by TEXT,
        decided_at TEXT,
        grade_before REAL,
        appeal_deadline TEXT,
        source TEXT DEFAULT 'manual',
        source_ref TEXT,
        legacy_case_id TEXT,
        module_code TEXT,
        severity TEXT,
        offence_number INTEGER,
        tariff TEXT,
        tariff_departure TEXT,
        response_due TEXT,
        closed_at TEXT
    );
CREATE TABLE integrity_check_failures (
        submission_id INTEGER PRIMARY KEY,
        attempts INTEGER NOT NULL DEFAULT 1,
        last_error TEXT,
        first_failed_at TEXT NOT NULL DEFAULT (datetime('now')),
        last_attempt_at TEXT NOT NULL DEFAULT (datetime('now')),
        resolved_at TEXT,
        resolved_by TEXT,
        resolution TEXT
    );
CREATE TABLE integrity_evidence (
        evidence_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('file', 'note', 'meeting_record', 'similarity_result',
                                           'ai_result', 'exam_incident', 'disciplinary_record',
                                           'legacy')),
        title TEXT NOT NULL,
        detail TEXT,
        file_name TEXT,
        file_path TEXT,
        sha256 TEXT,
        ref TEXT,
        visible_to_student INTEGER NOT NULL DEFAULT 1,
        added_by TEXT,
        added_at TEXT NOT NULL DEFAULT (datetime('now')),
        removed_at TEXT
    );
CREATE TABLE integrity_external_searches (
        search_id INTEGER PRIMARY KEY AUTOINCREMENT,
        document_id INTEGER NOT NULL,
        provider TEXT NOT NULL,
        queries INTEGER NOT NULL DEFAULT 0,
        sources_added INTEGER NOT NULL DEFAULT 0,
        error TEXT,
        ran_by TEXT,
        ran_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE integrity_reminders (
        kind TEXT NOT NULL,
        ref TEXT NOT NULL,
        sent_at TEXT NOT NULL,
        PRIMARY KEY (kind, ref)
    );
CREATE TABLE integrity_roles (
        username TEXT NOT NULL,
        role TEXT NOT NULL CHECK (role IN ('reviewer', 'officer')),
        granted_by TEXT,
        granted_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (username, role)
    );
CREATE TABLE integrity_settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE integrity_statements (
        statement_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL,
        author TEXT NOT NULL,
        statement TEXT NOT NULL,
        submitted_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE interdepartmental_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                request_type TEXT NOT NULL,
                from_department TEXT,
                to_department TEXT,
                requested_by TEXT NOT NULL,
                requested_by_name TEXT,
                request_title TEXT NOT NULL,
                request_description TEXT,
                priority TEXT DEFAULT 'normal',
                status TEXT DEFAULT 'pending',
                assigned_to TEXT,
                assigned_to_name TEXT,
                due_date TEXT,
                completed_date TEXT,
                response TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE "interest_matches" (
                match_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user1_id TEXT NOT NULL,
                user2_id TEXT NOT NULL,
                compatibility_score REAL NOT NULL,
                shared_interests TEXT,
                match_reason TEXT,
                match_status TEXT DEFAULT 'suggested',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user1_id) REFERENCES users(username) ON DELETE CASCADE,
                FOREIGN KEY (user2_id) REFERENCES users(username) ON DELETE CASCADE,
                UNIQUE(user1_id, user2_id)
            );
CREATE TABLE interlibrary_loans (
            ill_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            title TEXT NOT NULL,
            author TEXT,
            isbn TEXT,
            source_library TEXT,
            request_date TEXT NOT NULL,
            expected_arrival TEXT,
            actual_arrival TEXT,
            due_date TEXT,
            return_date TEXT,
            status TEXT DEFAULT 'requested',
            cost REAL DEFAULT 0.0
        );
CREATE TABLE internship_applications (
            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            internship_id INTEGER,
            application_date TEXT,
            status TEXT DEFAULT 'pending',
            cv_filename TEXT,
            cover_letter TEXT,
            feedback TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (internship_id) REFERENCES internships (internship_id)
        );
CREATE TABLE internship_placements (
            placement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            internship_id INTEGER,
            start_date TEXT,
            end_date TEXT,
            supervisor_name TEXT,
            supervisor_email TEXT,
            status TEXT DEFAULT 'active',
            feedback_student TEXT,
            feedback_employer TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (internship_id) REFERENCES internships (internship_id)
        );
CREATE TABLE internships (
            internship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            company TEXT NOT NULL,
            location TEXT,
            description TEXT,
            requirements TEXT,
            start_date TEXT,
            end_date TEXT,
            is_paid BOOLEAN,
            salary TEXT,
            hours_per_week INTEGER,
            posted_date TEXT,
            deadline_date TEXT,
            status TEXT DEFAULT 'active',
            contact_email TEXT,
            course_relevance TEXT,
            created_by TEXT,
            created_date TEXT
        );
CREATE TABLE intervention_outcomes (
                    intervention_id INTEGER PRIMARY KEY,
                    subject_area TEXT,
                    sessions_total INTEGER DEFAULT 0,
                    sessions_completed INTEGER DEFAULT 0,
                    pre_assessment_score REAL,
                    pre_assessment_date TEXT,
                    post_assessment_score REAL,
                    post_assessment_date TEXT,
                    value_added REAL,
                    impact_notes TEXT,
                    created_at TEXT DEFAULT (datetime('now')),
                    updated_at TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (intervention_id)
                        REFERENCES early_warning_interventions (intervention_id)
                );
CREATE TABLE intervention_recommendations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            intervention_type TEXT NOT NULL,
            priority INTEGER,
            description TEXT,
            timeline TEXT,
            risk_score REAL,
            risk_level TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE intervention_records (
                    student_id   TEXT PRIMARY KEY,
                    name         TEXT,
                    program      TEXT,
                    gpa          TEXT,
                    email        TEXT,
                    risk         TEXT,
                    status       TEXT,
                    intervention TEXT,
                    last_contact TEXT,
                    notes        TEXT,
                    updated_at   TEXT,
                    updated_by   TEXT
                );
CREATE TABLE intervention_sessions (
                    session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    intervention_id INTEGER NOT NULL,
                    session_date TEXT NOT NULL,
                    duration_minutes INTEGER,
                    status TEXT DEFAULT 'attended',
                    notes TEXT,
                    recorded_by TEXT,
                    created_at TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (intervention_id)
                        REFERENCES early_warning_interventions (intervention_id)
                );
CREATE TABLE intervention_types (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT,
            description TEXT
        , "type_id" INTEGER);
CREATE TABLE interview_schedules (
            interview_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            interview_type TEXT NOT NULL,
            interview_date TEXT NOT NULL,
            interview_time TEXT NOT NULL,
            duration_minutes INTEGER DEFAULT 60,
            location TEXT,
            interviewer_name TEXT,
            meeting_link TEXT,
            status TEXT DEFAULT 'scheduled',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP, "applicant_name" TEXT, "interview_round" INTEGER DEFAULT 1, "interviewers" TEXT, "video_link" TEXT, "concerns" TEXT, "feedback" TEXT, "overall_score" INTEGER, "recommendation" TEXT, "strengths" TEXT,
            FOREIGN KEY (application_id) REFERENCES job_applications (application_id)
        );
CREATE TABLE inventory (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_name TEXT NOT NULL,
                quantity INTEGER NOT NULL,
                unit TEXT NOT NULL,
                minimum_threshold INTEGER DEFAULT 10,
                supplier TEXT,
                cost_per_unit REAL,
                last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE inventory_transactions (
                transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_id INTEGER,
                transaction_type TEXT,
                quantity REAL,
                transaction_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                user_id INTEGER,
                notes TEXT
            );
CREATE TABLE ip_deadlines (
        deadline_id INTEGER PRIMARY KEY AUTOINCREMENT,
        disclosure_id INTEGER NOT NULL REFERENCES ip_disclosures(disclosure_id)
            ON DELETE CASCADE,
        kind TEXT NOT NULL,
        due_date TEXT NOT NULL,
        done_at TEXT,
        done_by TEXT,
        note TEXT
    );
CREATE TABLE ip_disclosures (
                    disclosure_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    description TEXT,
                    ip_type TEXT DEFAULT 'invention',
                    development_stage TEXT DEFAULT 'concept',
                    funding_source TEXT,
                    department TEXT,
                    status TEXT DEFAULT 'draft',
                    submitted_date TEXT,
                    reviewed_by TEXT,
                    review_date TEXT,
                    review_comments TEXT,
                    created_by TEXT NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                , reference TEXT, inventor_id TEXT, jurisdiction TEXT, commercial_route TEXT, "project_id" INTEGER, "filing_date" TEXT, "application_number" TEXT);
CREATE TABLE ip_inventor_payments (
        payment_id INTEGER PRIMARY KEY AUTOINCREMENT,
        revenue_id INTEGER NOT NULL REFERENCES ip_revenue_shares(revenue_id) ON DELETE CASCADE,
        username TEXT NOT NULL,
        amount REAL NOT NULL
    );
CREATE TABLE ip_inventors (
                    inventor_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    disclosure_id INTEGER,
                    patent_id INTEGER,
                    user_id TEXT NOT NULL,
                    contribution_percentage REAL DEFAULT 0,
                    is_primary INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (disclosure_id) REFERENCES ip_disclosures(disclosure_id),
                    FOREIGN KEY (patent_id) REFERENCES patents(patent_id)
                );
CREATE TABLE ip_licenses (
                    license_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    patent_id INTEGER,
                    disclosure_id INTEGER,
                    licensee_name TEXT NOT NULL,
                    license_type TEXT DEFAULT 'non_exclusive',
                    royalty_rate REAL DEFAULT 0,
                    territory TEXT DEFAULT 'worldwide',
                    start_date TEXT NOT NULL,
                    end_date TEXT,
                    annual_fee REAL DEFAULT 0,
                    status TEXT DEFAULT 'active',
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (patent_id) REFERENCES patents(patent_id),
                    FOREIGN KEY (disclosure_id) REFERENCES ip_disclosures(disclosure_id)
                );
CREATE TABLE ip_revenue_shares (
                    revenue_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    license_id INTEGER NOT NULL,
                    period TEXT NOT NULL,
                    total_revenue REAL DEFAULT 0,
                    university_share REAL DEFAULT 0,
                    inventor_share REAL DEFAULT 0,
                    department_share REAL DEFAULT 0,
                    payment_date TEXT,
                    status TEXT DEFAULT 'pending',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (license_id) REFERENCES ip_licenses(license_id)
                );
CREATE TABLE irb_applications (
                            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
                            project_id INTEGER NOT NULL,
                            protocol_number TEXT,
                            submission_date TEXT NOT NULL,
                            review_type TEXT NOT NULL,
                            decision TEXT DEFAULT 'Pending',
                            decision_date TEXT,
                            status TEXT DEFAULT 'Submitted',
                            study_description TEXT,
                            risk_assessment TEXT,
                            reviewer_comments TEXT,
                            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                            FOREIGN KEY (project_id) REFERENCES research_projects (project_id)
                        );
CREATE TABLE item_claims (
                    claim_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    found_item_id INTEGER NOT NULL,
                    claimant_id TEXT NOT NULL,
                    claim_description TEXT NOT NULL,
                    verification_questions TEXT,
                    verification_answers TEXT,
                    supporting_evidence TEXT,
                    status TEXT DEFAULT 'Pending',
                    submitted_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    reviewed_at TEXT,
                    reviewed_by TEXT,
                    resolution_notes TEXT,
                    FOREIGN KEY (found_item_id) REFERENCES found_items(item_id) ON DELETE CASCADE,
                    FOREIGN KEY (claimant_id) REFERENCES students(student_id)
                );
CREATE TABLE item_matches (
                    match_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    lost_item_id INTEGER NOT NULL,
                    found_item_id INTEGER NOT NULL,
                    match_score REAL NOT NULL,
                    match_reasons TEXT,
                    status TEXT DEFAULT 'Suggested',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (lost_item_id) REFERENCES lost_items(item_id) ON DELETE CASCADE,
                    FOREIGN KEY (found_item_id) REFERENCES found_items(item_id) ON DELETE CASCADE
                );
CREATE TABLE item_photos (
                    photo_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_type TEXT NOT NULL,
                    item_id INTEGER NOT NULL,
                    photo_path TEXT NOT NULL,
                    photo_hash TEXT,
                    caption TEXT,
                    uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE job_applications (
            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
            job_id INTEGER,
            applicant_id TEXT,
            application_date TEXT,
            status TEXT DEFAULT 'submitted',
            cover_letter TEXT,
            resume_path TEXT, "applied_date" TEXT DEFAULT CURRENT_TIMESTAMP, "notes" TEXT, "resume_id" INTEGER, "reviewed_date" TEXT, "student_id" TEXT,
            FOREIGN KEY (job_id) REFERENCES job_postings (job_id),
            FOREIGN KEY (applicant_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE job_interests (
        interest_id INTEGER PRIMARY KEY AUTOINCREMENT,
        job_id INTEGER NOT NULL REFERENCES job_postings (job_id),
        user_id TEXT NOT NULL,
        expressed_date TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'interested',
        UNIQUE (job_id, user_id));
CREATE TABLE job_postings (
            job_id INTEGER PRIMARY KEY AUTOINCREMENT,
            posted_by TEXT,
            company_name TEXT,
            job_title TEXT,
            job_description TEXT,
            location TEXT,
            job_type TEXT,
            salary_range TEXT,
            requirements TEXT,
            application_method TEXT,
            contact_email TEXT,
            post_date TEXT,
            expiry_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            category TEXT,
            experience_level TEXT, "application_deadline" TEXT, "applications_count" INTEGER DEFAULT 0, "description" TEXT, "employer_id" INTEGER, "posted_date" TEXT DEFAULT CURRENT_DATE, "responsibilities" TEXT, "status" TEXT DEFAULT 'active', "views_count" INTEGER DEFAULT 0, "interest_count" INTEGER,
            FOREIGN KEY (posted_by) REFERENCES alumni (alumni_id)
        );
CREATE TABLE "job_skill_requirements" (
                        requirement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        job_id INTEGER NOT NULL,
                        skill_name TEXT NOT NULL,
                        is_required BOOLEAN DEFAULT 1,
                        minimum_proficiency TEXT CHECK(minimum_proficiency IN ('beginner', 'intermediate', 'advanced', 'expert')),
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (job_id) REFERENCES campus_job_postings(job_id) ON DELETE CASCADE,
                        UNIQUE(job_id, skill_name)
                    );
CREATE TABLE kb_articles (
            article_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            summary TEXT,
            category TEXT NOT NULL,
            tags TEXT,  -- JSON array
            author_id TEXT NOT NULL,
            created_datetime TEXT NOT NULL,
            updated_datetime TEXT,
            published_datetime TEXT,
            is_published BOOLEAN DEFAULT 0,
            view_count INTEGER DEFAULT 0,
            helpful_votes INTEGER DEFAULT 0,
            not_helpful_votes INTEGER DEFAULT 0,
            search_keywords TEXT,  -- Space-separated keywords for search
            related_articles TEXT  -- JSON array of related article IDs
        );
CREATE TABLE key_assignments (
                assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                key_number TEXT NOT NULL,
                key_type TEXT,
                room_location TEXT,
                building TEXT,
                assigned_to TEXT,
                assigned_to_name TEXT,
                assigned_date TEXT,
                return_date TEXT,
                status TEXT DEFAULT 'assigned',
                issued_by TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE "knowledge_base" (
            article_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            category TEXT,
            tags TEXT,
            author_id INTEGER,
            status TEXT DEFAULT 'draft',
            views INTEGER DEFAULT 0,
            helpful_votes INTEGER DEFAULT 0,
            unhelpful_votes INTEGER DEFAULT 0,
            search_keywords TEXT,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE knowledge_transfer (
                    transfer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    departing_user_id TEXT NOT NULL,
                    receiving_user_id TEXT,
                    topic TEXT NOT NULL,
                    description TEXT,
                    documentation_path TEXT,
                    priority TEXT DEFAULT 'medium',
                    status TEXT DEFAULT 'pending',
                    scheduled_date TEXT,
                    completed_date TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE kpi_metrics (
            kpi_id INTEGER PRIMARY KEY AUTOINCREMENT,
            kpi_name TEXT NOT NULL,
            kpi_category TEXT NOT NULL,
            current_value REAL NOT NULL,
            target_value REAL,
            measurement_date TEXT DEFAULT CURRENT_DATE,
            period TEXT,
            trend TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE lab_equipment (
                    equipment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    category_id INTEGER,
                    location TEXT,
                    building TEXT,
                    room_number TEXT,
                    serial_number TEXT,
                    model TEXT,
                    manufacturer TEXT,
                    status TEXT DEFAULT 'available',
                    max_booking_hours INTEGER DEFAULT 8,
                    min_booking_hours INTEGER DEFAULT 1,
                    requires_approval INTEGER DEFAULT 0,
                    requires_training INTEGER DEFAULT 0,
                    description TEXT,
                    image_url TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (category_id) REFERENCES equipment_categories(category_id)
                );
CREATE TABLE lab_integration_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                order_id TEXT,
                patient_id TEXT,
                test_code TEXT,
                event_type TEXT,        -- order_sent/result_received/ack/error
                status TEXT,
                external_id TEXT,
                correlation_id TEXT,
                payload TEXT,
                response TEXT,
                result_at TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT
            );
CREATE TABLE lab_results (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    test_name TEXT,
                    test_code TEXT,
                    result_value TEXT,
                    reference_range TEXT,
                    units TEXT,
                    status TEXT,
                    ordered_date TEXT,
                    collected_date TEXT,
                    resulted_date TEXT,
                    ordering_provider TEXT,
                    lab_name TEXT,
                    abnormal_flag TEXT,
                    created_at TEXT, "date_performed" TEXT, "normal_range" TEXT, "reviewed" INTEGER DEFAULT 0, "test_type" TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE late_fees (
            late_fee_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_fee_id INTEGER NOT NULL,
            late_fee_amount DECIMAL(10,2) NOT NULL,
            calculation_method TEXT, -- 'fixed', 'percentage', 'daily'
            days_overdue INTEGER NOT NULL,
            applied_date TEXT NOT NULL,
            waived BOOLEAN DEFAULT 0,
            waived_by TEXT,
            waived_date TEXT,
            waiver_reason TEXT,
            created_at TEXT,
            FOREIGN KEY (student_fee_id) REFERENCES student_fees (student_fee_id)
        );
CREATE TABLE late_pass_recommendations (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        assignment_id INTEGER,
                        recommendation TEXT NOT NULL,
                        confidence_score REAL NOT NULL,
                        reasoning_json TEXT,
                        created_at TEXT NOT NULL
                    , "grade_trend" TEXT, "on_time_rate" REAL, "prior_grants" TEXT);
CREATE TABLE late_passes (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        assignment_id INTEGER,
                        used INTEGER NOT NULL DEFAULT 0,
                        granted_by TEXT,
                        granted_at TEXT NOT NULL DEFAULT (datetime('now')),
                        reason TEXT
                    , "granted_date" TEXT, "extra_days" INTEGER, "status" TEXT);
CREATE TABLE late_policies (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        name TEXT NOT NULL UNIQUE,
                        description TEXT,
                        penalty_type TEXT NOT NULL DEFAULT 'percentage'
                            CHECK(penalty_type IN ('percentage', 'fixed', 'none')),
                        penalty_per_day REAL NOT NULL DEFAULT 10.0,
                        max_late_days INTEGER NOT NULL DEFAULT 5,
                        grace_period_hours INTEGER NOT NULL DEFAULT 0,
                        min_grade_floor REAL NOT NULL DEFAULT 0.0,
                        is_default INTEGER NOT NULL DEFAULT 0,
                        created_by TEXT,
                        created_at TEXT NOT NULL DEFAULT (datetime('now'))
                    , "created_date" TEXT);
CREATE TABLE learning_outcomes (
            outcome_id INTEGER PRIMARY KEY AUTOINCREMENT,
            outcome_code TEXT NOT NULL,
            description TEXT NOT NULL,
            category TEXT,
            level INTEGER
        , course TEXT, importance INTEGER, "programme_id" INTEGER, "module_code" TEXT, "code" TEXT, "bloom_level" TEXT DEFAULT 'understand', "outcome_type" TEXT DEFAULT 'programme', "created_at" TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leave_balances (
                    balance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    leave_type_id INTEGER NOT NULL,
                    year INTEGER NOT NULL,
                    allocated_days REAL DEFAULT 0,
                    used_days REAL DEFAULT 0,
                    carried_over REAL DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP, "bank_holiday_days" REAL DEFAULT 0, "carry_over_expires" TEXT, "carry_over_expired" REAL DEFAULT 0, "allocation_basis" TEXT,
                    UNIQUE(user_id, leave_type_id, year),
                    FOREIGN KEY (leave_type_id) REFERENCES leave_types(leave_type_id)
                );
CREATE TABLE leave_requests (
                    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    leave_type_id INTEGER NOT NULL,
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    total_days REAL NOT NULL,
                    reason TEXT,
                    document_path TEXT,
                    status TEXT DEFAULT 'pending',
                    approved_by TEXT,
                    approved_date TEXT,
                    rejection_reason TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP, "working_days" REAL, "start_half" INTEGER DEFAULT 0, "end_half" INTEGER DEFAULT 0, "source" TEXT DEFAULT 'leave', "source_id" INTEGER, "cancelled_by" TEXT,
                    FOREIGN KEY (leave_type_id) REFERENCES leave_types(leave_type_id)
                );
CREATE TABLE leave_types (
                    leave_type_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    max_days_per_year INTEGER DEFAULT 0,
                    requires_approval BOOLEAN DEFAULT 1,
                    is_paid BOOLEAN DEFAULT 1,
                    color_code TEXT DEFAULT '#3498db',
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE lecturer_eval_comment_reviews (
        evaluation_id INTEGER PRIMARY KEY REFERENCES lecturer_evaluations(evaluation_id),
        reason TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'released', 'withheld')),
        reviewed_by TEXT,
        reviewed_at TEXT
    );
CREATE TABLE lecturer_eval_invitations (
        form_id INTEGER NOT NULL REFERENCES evaluation_forms(id),
        lecturer TEXT NOT NULL,
        student_id TEXT NOT NULL,
        invited_at TEXT NOT NULL DEFAULT (date('now')),
        reminded_at TEXT,
        responded INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (form_id, lecturer, student_id)
    );
CREATE TABLE lecturer_evaluations (
    evaluation_id INTEGER PRIMARY KEY AUTOINCREMENT,
    form_id INTEGER NOT NULL REFERENCES evaluation_forms(id),
    module_code TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    lecturer TEXT NOT NULL,
    respondent TEXT NOT NULL,
    knowledge INTEGER NOT NULL CHECK (knowledge BETWEEN 1 AND 5),
    communication INTEGER NOT NULL CHECK (communication BETWEEN 1 AND 5),
    preparation INTEGER NOT NULL CHECK (preparation BETWEEN 1 AND 5),
    engagement INTEGER NOT NULL CHECK (engagement BETWEEN 1 AND 5),
    fairness INTEGER NOT NULL CHECK (fairness BETWEEN 1 AND 5),
    availability INTEGER NOT NULL CHECK (availability BETWEEN 1 AND 5),
    overall INTEGER NOT NULL CHECK (overall BETWEEN 1 AND 5),
    comments TEXT,
    submitted_at TEXT NOT NULL
);
CREATE TABLE lecturer_reflections (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        form_id INTEGER NOT NULL REFERENCES evaluation_forms(id),
        lecturer TEXT NOT NULL,
        reflection TEXT NOT NULL,
        actions TEXT,
        you_said TEXT,
        we_did TEXT,
        published INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        published_at TEXT
    );
CREATE TABLE legal_cases (
                    case_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    case_number TEXT UNIQUE NOT NULL,
                    client_id TEXT NOT NULL,
                    client_name TEXT NOT NULL,
                    client_email TEXT,
                    case_type TEXT NOT NULL,
                    case_title TEXT NOT NULL,
                    case_description TEXT,
                    status TEXT DEFAULT 'open',
                    priority TEXT DEFAULT 'normal',
                    assigned_lawyer TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    closed_at TIMESTAMP,
                    total_fees DECIMAL(10,2) DEFAULT 0.00,
                    amount_paid DECIMAL(10,2) DEFAULT 0.00,
                    created_by TEXT
                , "assigned_attorney" TEXT, "client_phone" TEXT, "created_date" TEXT, "description" TEXT, "student_id" TEXT, "updated_date" TEXT, "closed_date" TEXT);
CREATE TABLE legal_consultations (
                    consultation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    case_id INTEGER,
                    client_id TEXT NOT NULL,
                    client_name TEXT NOT NULL,
                    client_email TEXT,
                    consultation_type TEXT NOT NULL,
                    scheduled_date TEXT NOT NULL,
                    scheduled_time TEXT NOT NULL,
                    duration_minutes INTEGER DEFAULT 30,
                    lawyer_id TEXT,
                    lawyer_name TEXT,
                    fee DECIMAL(10,2) DEFAULT 0.00,
                    payment_status TEXT DEFAULT 'pending',
                    payment_id TEXT,
                    notes TEXT,
                    status TEXT DEFAULT 'scheduled',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "attorney" TEXT, "consultation_date" TEXT, "consultation_time" TEXT, "created_date" TEXT,
                    FOREIGN KEY (case_id) REFERENCES legal_cases(case_id)
                );
CREATE TABLE lesson_courses (
                    code        TEXT PRIMARY KEY,
                    name        TEXT,
                    dept        TEXT,
                    credits     TEXT,
                    semester    TEXT,
                    description TEXT,
                    updated_at  TEXT,
                    updated_by  TEXT
                );
CREATE TABLE lesson_plan_content (
        lesson_id    INTEGER PRIMARY KEY AUTOINCREMENT,
        schedule_id  INTEGER REFERENCES module_schedule(id) ON DELETE CASCADE,
        module_code  TEXT,
        title        TEXT NOT NULL DEFAULT '',
        lesson_type  TEXT NOT NULL DEFAULT '',
        notes        TEXT,
        legacy_slot  TEXT,
        created_at   TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at   TEXT NOT NULL DEFAULT (datetime('now')),
        updated_by   TEXT
    );
CREATE TABLE lesson_plans (
                    id          INTEGER PRIMARY KEY AUTOINCREMENT,
                    course      TEXT,
                    title       TEXT,
                    instructor  TEXT,
                    type        TEXT,
                    day         TEXT,
                    start       TEXT,
                    end         TEXT,
                    room        TEXT,
                    notes       TEXT,
                    updated_at  TEXT,
                    updated_by  TEXT
                );
CREATE TABLE library_accounts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                book_title TEXT,
                author TEXT,
                isbn TEXT,
                checkout_date TEXT,
                due_date TEXT,
                return_date TEXT,
                fine_amount DECIMAL(10,2) DEFAULT 0.00,
                status TEXT DEFAULT 'checked_out',
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE library_analytics (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT,
                action TEXT NOT NULL,
                details TEXT,
                timestamp TEXT NOT NULL
            );
CREATE TABLE library_borrower_overrides (
        borrower_ref TEXT PRIMARY KEY,
        category TEXT NOT NULL
            CHECK (category IN ('undergraduate', 'postgraduate', 'staff', 'external', 'extended')),
        reason TEXT NOT NULL,
        until TEXT,
        set_by TEXT,
        set_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE library_borrower_rules (
        category TEXT PRIMARY KEY
            CHECK (category IN ('undergraduate', 'postgraduate', 'staff', 'external', 'extended')),
        max_loans INTEGER NOT NULL CHECK (max_loans >= 0),
        loan_days INTEGER NOT NULL CHECK (loan_days > 0),
        max_renewals INTEGER NOT NULL CHECK (max_renewals >= 0),
        short_loans_allowed INTEGER NOT NULL DEFAULT 1
    );
CREATE TABLE library_cards (
                card_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                card_number TEXT UNIQUE,
                issue_date TEXT,
                expiry_date TEXT,
                status TEXT DEFAULT 'active'
            );
CREATE TABLE library_charges (
        charge_id INTEGER PRIMARY KEY AUTOINCREMENT,
        borrower_ref TEXT NOT NULL,
        loan_id INTEGER,
        copy_id INTEGER,
        kind TEXT NOT NULL CHECK (kind IN ('lost', 'damage', 'overdue')),
        amount REAL NOT NULL CHECK (amount >= 0),
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'paid', 'waived')),
        note TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        resolved_at TEXT
    );
CREATE TABLE library_copies (
        copy_id INTEGER PRIMARY KEY AUTOINCREMENT,
        book_id TEXT NOT NULL REFERENCES books(book_id) ON DELETE CASCADE,
        barcode TEXT NOT NULL UNIQUE,
        item_type TEXT NOT NULL DEFAULT 'standard'
            CHECK (item_type IN ('standard', 'short_24h', 'short_3day', 'reference')),
        location TEXT,
        status TEXT NOT NULL DEFAULT 'available'
            CHECK (status IN ('available', 'on_loan', 'hold_shelf', 'lost', 'damaged',
                              'missing', 'withdrawn', 'on_order')),
        condition_notes TEXT,
        price REAL CHECK (price IS NULL OR price >= 0),
        acquired_date TEXT,
        last_seen TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE library_eresource_usage (
        resource_id INTEGER NOT NULL REFERENCES library_eresources(resource_id) ON DELETE CASCADE,
        period TEXT NOT NULL,
        uses INTEGER NOT NULL CHECK (uses >= 0),
        PRIMARY KEY (resource_id, period)
    );
CREATE TABLE library_eresources (
        resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        provider TEXT,
        resource_type TEXT,
        url TEXT,
        concurrent_users INTEGER CHECK (concurrent_users IS NULL OR concurrent_users > 0),
        annual_cost REAL CHECK (annual_cost IS NULL OR annual_cost >= 0),
        currency TEXT NOT NULL DEFAULT 'GBP',
        start_date TEXT,
        renewal_date TEXT,
        notice_days INTEGER NOT NULL DEFAULT 90,
        status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('trial', 'active', 'cancelled')),
        owner TEXT,
        notes TEXT
    );
CREATE TABLE library_event_attendance (
    attendance_id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL,
    attendee_id TEXT NOT NULL,
    attendee_name TEXT,
    registered_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (event_id) REFERENCES library_events (event_id) ON DELETE CASCADE
);
CREATE TABLE library_events (
                event_id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_name TEXT NOT NULL,
                event_date TEXT NOT NULL,
                event_time TEXT NOT NULL,
                location TEXT,
                description TEXT,
                max_capacity INTEGER DEFAULT 50,
                registered_count INTEGER DEFAULT 0,
                created_by TEXT,
                created_at TEXT
            , "status" TEXT DEFAULT 'scheduled');
CREATE TABLE library_fine_payments (
            payment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            loan_id INTEGER NOT NULL,
            user_id TEXT NOT NULL,
            book_id TEXT NOT NULL,
            book_title TEXT,
            fine_amount REAL NOT NULL,
            payment_amount REAL NOT NULL,
            payment_method TEXT NOT NULL,
            payment_date TEXT NOT NULL,
            processed_by TEXT,
            transaction_ref TEXT,
            status TEXT DEFAULT 'completed',
            refund_amount REAL DEFAULT 0.0,
            refunded_date TEXT,
            refunded_by TEXT,
            refund_reason TEXT,
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (loan_id) REFERENCES book_loans(loan_id)
        );
CREATE TABLE library_funds (
        fund_code TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        department TEXT,
        academic_year TEXT NOT NULL,
        allocation REAL NOT NULL CHECK (allocation >= 0)
    );
CREATE TABLE library_item_rules (
        item_type TEXT PRIMARY KEY
            CHECK (item_type IN ('standard', 'short_24h', 'short_3day', 'reference')),
        loan_hours INTEGER CHECK (loan_hours IS NULL OR loan_hours > 0),
        loanable INTEGER NOT NULL DEFAULT 1,
        renewable INTEGER NOT NULL DEFAULT 1,
        fine_per_day REAL CHECK (fine_per_day IS NULL OR fine_per_day >= 0),
        fine_per_hour REAL CHECK (fine_per_hour IS NULL OR fine_per_hour >= 0)
    );
CREATE TABLE library_orders (
        order_id INTEGER PRIMARY KEY AUTOINCREMENT,
        request_id INTEGER,
        book_id TEXT,
        title TEXT NOT NULL,
        author TEXT,
        isbn TEXT,
        supplier TEXT NOT NULL,
        fund_code TEXT NOT NULL REFERENCES library_funds(fund_code),
        quantity INTEGER NOT NULL CHECK (quantity > 0),
        unit_price REAL NOT NULL CHECK (unit_price >= 0),
        item_type TEXT NOT NULL DEFAULT 'standard',
        status TEXT NOT NULL DEFAULT 'ordered'
            CHECK (status IN ('ordered', 'part_received', 'received', 'cancelled')),
        received_qty INTEGER NOT NULL DEFAULT 0,
        ordered_by TEXT,
        ordered_at TEXT NOT NULL DEFAULT (datetime('now')),
        received_at TEXT,
        cancelled_reason TEXT
    );
CREATE TABLE library_payments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                receipt_id TEXT UNIQUE,
                user_id TEXT,
                amount REAL,
                payment_method TEXT,
                payment_date TEXT
            );
CREATE TABLE library_settings (
                setting_name TEXT PRIMARY KEY,
                setting_value TEXT NOT NULL,
                description TEXT,
                setting_type TEXT DEFAULT 'string',
                min_value REAL,
                max_value REAL,
                allowed_values TEXT
            );
CREATE TABLE library_stocktake_scans (
        stocktake_id INTEGER NOT NULL REFERENCES library_stocktakes(stocktake_id),
        barcode TEXT NOT NULL,
        scanned_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (stocktake_id, barcode)
    );
CREATE TABLE library_stocktakes (
        stocktake_id INTEGER PRIMARY KEY AUTOINCREMENT,
        location TEXT NOT NULL,
        started_by TEXT,
        started_at TEXT NOT NULL DEFAULT (datetime('now')),
        finished_at TEXT,
        missing_marked INTEGER
    );
CREATE TABLE "linked_accounts" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                primary_user_id INTEGER NOT NULL,
                secondary_user_id INTEGER NOT NULL,
                linked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                linked_by INTEGER NOT NULL,
                is_active BOOLEAN DEFAULT 1,
                FOREIGN KEY (primary_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (secondary_user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (linked_by) REFERENCES users(id) ON DELETE CASCADE,
                UNIQUE(primary_user_id, secondary_user_id)
            );
CREATE TABLE listing_photos (
                    photo_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    listing_type TEXT NOT NULL,
                    listing_id INTEGER NOT NULL,
                    photo_path TEXT NOT NULL,
                    is_primary BOOLEAN DEFAULT 0,
                    caption TEXT,
                    uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE lms_access_grants (
         id INTEGER PRIMARY KEY AUTOINCREMENT,
         student_id TEXT NOT NULL, module_code TEXT NOT NULL,
         session_date TEXT NOT NULL, resource TEXT NOT NULL,
         granted INTEGER DEFAULT 0, reason TEXT,
         created_at TEXT DEFAULT CURRENT_TIMESTAMP,
         UNIQUE(student_id, module_code, session_date, resource)
       );
CREATE TABLE lms_settings (
                        id INTEGER PRIMARY KEY,
                        platform TEXT,
                        api_url TEXT,
                        api_key TEXT,
                        username TEXT,
                        auto_sync INTEGER,
                        sync_grades INTEGER,
                        bidirectional INTEGER,
                        sync_frequency TEXT
                    );
CREATE TABLE login_attempts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL,
            attempt_time TEXT NOT NULL,
            ip_address TEXT,
            success INTEGER NOT NULL
        , "user_agent" TEXT);
CREATE TABLE logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                user_id TEXT,
                username TEXT,
                action TEXT,
                status TEXT,
                module TEXT,
                message TEXT,
                ip_address TEXT,
                user_agent TEXT
            , "log_id" INTEGER, "new_values" TEXT, "old_values" TEXT, "record_id" TEXT, "session_id" TEXT, "table_name" TEXT, "details" TEXT, "hash" TEXT, "role" TEXT);
CREATE TABLE lost_found (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            item_description TEXT NOT NULL,
            category TEXT DEFAULT 'other',
            location_found TEXT,
            screen_number INTEGER,
            found_date TEXT NOT NULL,
            found_time TEXT,
            found_by_staff_id INTEGER,
            storage_location TEXT,
            claimed INTEGER DEFAULT 0,
            claimed_by_name TEXT,
            claimed_by_email TEXT,
            claimed_by_phone TEXT,
            claim_date TEXT,
            verified_by_staff_id INTEGER,
            identification_method TEXT,
            status TEXT DEFAULT 'unclaimed',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (found_by_staff_id) REFERENCES staff(id),
            FOREIGN KEY (verified_by_staff_id) REFERENCES staff(id)
        );
CREATE TABLE lost_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    reporter_id TEXT NOT NULL,
                    item_name TEXT NOT NULL,
                    category TEXT NOT NULL,
                    description TEXT NOT NULL,
                    lost_date TEXT NOT NULL,
                    lost_location TEXT NOT NULL,
                    lost_time TEXT,
                    distinctive_features TEXT,
                    color TEXT,
                    brand TEXT,
                    estimated_value REAL,
                    contact_email TEXT,
                    contact_phone TEXT,
                    status TEXT DEFAULT 'Active',
                    reported_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (reporter_id) REFERENCES students(student_id)
                );
CREATE TABLE loyalty_bonus_points (
                        bonus_id INTEGER PRIMARY KEY AUTOINCREMENT,
