            support_type TEXT NOT NULL,
            notes TEXT,
            session_count INTEGER DEFAULT 0,
            last_session_date TEXT,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , "match_date" TEXT DEFAULT CURRENT_DATE);
CREATE TABLE mental_health_resources (
            resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
            category TEXT NOT NULL,
            title TEXT NOT NULL,
            description TEXT,
            content_type TEXT NOT NULL,
            content_url TEXT,
            tags TEXT,
            view_count INTEGER DEFAULT 0,
            is_published INTEGER DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE mentee_preferences (
                    mentee_id INTEGER PRIMARY KEY,
                    course TEXT,
                    learning_goals_csv TEXT,
                    preferred_languages_csv TEXT,
                    availability_csv TEXT,
                    preferred_year_min INTEGER,
                    updated_at TEXT
                );
CREATE TABLE mentor_match_recommendations (
                    recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    mentee_id INTEGER NOT NULL,
                    mentor_id INTEGER NOT NULL,
                    score INTEGER NOT NULL,
                    reasons_json TEXT,
                    created_at TEXT,
                    status TEXT DEFAULT 'suggested'
                );
CREATE TABLE mentor_profiles (
                    mentor_id INTEGER PRIMARY KEY,
                    year_of_study INTEGER,
                    course TEXT,
                    strengths_csv TEXT,
                    availability_csv TEXT,
                    languages_csv TEXT,
                    max_mentees INTEGER DEFAULT 3,
                    bio TEXT,
                    updated_at TEXT
                );
CREATE TABLE mentor_vetting (
        alumni_id TEXT PRIMARY KEY,
        status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved',
                                                                 'rejected')),
        training_completed INTEGER NOT NULL DEFAULT 0,
        checked_by TEXT,
        checked_at TEXT,
        expires_on TEXT,
        notes TEXT,
        offered_at TEXT NOT NULL DEFAULT (datetime('now')),
        focus_areas TEXT
    );
CREATE TABLE mentoring_concerns (
        concern_id INTEGER PRIMARY KEY AUTOINCREMENT,
        mentorship_id INTEGER NOT NULL,
        raised_by TEXT NOT NULL,
        raised_at TEXT NOT NULL DEFAULT (datetime('now')),
        description TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'escalated', 'closed')),
        handled_by TEXT,
        handled_at TEXT,
        outcome TEXT
    );
CREATE TABLE mentoring_outcomes (
                    outcome_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    pair_id INTEGER NOT NULL,
                    confidence_pre INTEGER,
                    confidence_post INTEGER,
                    goals_met INTEGER,
                    satisfaction INTEGER,
                    would_recommend INTEGER,
                    narrative TEXT,
                    recorded_at TEXT
                );
CREATE TABLE mentorship_matches (
            match_id INTEGER PRIMARY KEY AUTOINCREMENT,
            mentor_id INTEGER NOT NULL,
            mentee_student_id TEXT NOT NULL,
            match_date TEXT DEFAULT CURRENT_DATE,
            status TEXT DEFAULT 'active',
            meeting_frequency TEXT DEFAULT 'monthly',
            last_meeting_date TEXT,
            notes TEXT,
            FOREIGN KEY (mentor_id) REFERENCES alumni_mentors (mentor_id),
            FOREIGN KEY (mentee_student_id) REFERENCES students (student_id)
        );
CREATE TABLE mentorship_ratings (
        rating_id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id INTEGER NOT NULL REFERENCES mentorship_sessions (session_id),
        rater_id TEXT NOT NULL,
        rating INTEGER,
        feedback TEXT,
        is_anonymous INTEGER DEFAULT 0,
        rating_date TEXT,
        UNIQUE (session_id, rater_id));
CREATE TABLE mentorship_relationships (
            relationship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            mentor_id TEXT,
            mentee_id TEXT,
            skill_area TEXT,
            start_date TEXT,
            end_date TEXT,
            status TEXT DEFAULT 'active',
            mentor_rating REAL,
            mentee_rating REAL,
            notes TEXT,
            FOREIGN KEY (mentor_id) REFERENCES students (student_id),
            FOREIGN KEY (mentee_id) REFERENCES students (student_id)
        );
CREATE TABLE mentorship_sessions (
            session_id INTEGER PRIMARY KEY AUTOINCREMENT,
            relationship_id INTEGER,
            session_date TEXT,
            duration_minutes INTEGER,
            notes TEXT,
            mentor_feedback TEXT,
            mentee_feedback TEXT,
            progress_rating INTEGER, "agenda" TEXT, "created_date" TEXT, "location" TEXT, "status" TEXT,
            FOREIGN KEY (relationship_id) REFERENCES mentorship_relationships (relationship_id)
        );
CREATE TABLE mentorships (
            mentorship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            mentor_id TEXT,
            mentee_id TEXT,
            start_date TEXT,
            end_date TEXT,
            status TEXT,
            focus_area TEXT,
            notes TEXT,
            match_score REAL DEFAULT 0.0,
            meeting_frequency TEXT,
            communication_preference TEXT,
            goals TEXT, "student_consent_at" TEXT, "matched_by" TEXT, "ended_by" TEXT, "ended_reason" TEXT,
            FOREIGN KEY (mentor_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE menu_items (
                item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                price REAL NOT NULL,
                category TEXT,
                allergens TEXT,
                vegetarian BOOLEAN DEFAULT 0,
                vegan BOOLEAN DEFAULT 0,
                available BOOLEAN DEFAULT 1
            , "id" INTEGER, "ingredients" TEXT, "created_at" TIMESTAMP DEFAULT NULL, "updated_at" TIMESTAMP DEFAULT NULL, "cost_price" REAL, "popularity_score" INTEGER DEFAULT 0, "calories" INTEGER, "protein" REAL, "carbs" REAL, "fat" REAL, "prep_time" INTEGER, "image_path" TEXT);
CREATE TABLE message_recipients (
    recipient_id INTEGER PRIMARY KEY AUTOINCREMENT,
    message_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    delivery_status TEXT DEFAULT 'pending',  -- pending, sent, delivered, failed, read
    delivered_at TIMESTAMP,
    read_at TIMESTAMP,
    error_message TEXT,
    FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE
);
CREATE TABLE "messages" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            sender_id INTEGER NOT NULL,
            recipient_id INTEGER NOT NULL,
            subject TEXT NOT NULL,
            message TEXT,
            content TEXT,
            attachment_path TEXT,
            assignment_id INTEGER,
            is_read INTEGER DEFAULT 0,
            is_archived INTEGER DEFAULT 0,
            is_deleted_by_sender INTEGER DEFAULT 0,
            is_deleted_by_recipient INTEGER DEFAULT 0,
            sent_at TEXT NOT NULL,
            read_at TEXT,
            reply_to INTEGER,
            FOREIGN KEY (sender_id) REFERENCES users (id) ON DELETE CASCADE,
            FOREIGN KEY (recipient_id) REFERENCES users (id) ON DELETE CASCADE,
            FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE,
            FOREIGN KEY (reply_to) REFERENCES messages (id) ON DELETE CASCADE
        );
CREATE TABLE mfa_enforcement_policies (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                role_name TEXT NOT NULL UNIQUE,
                mfa_required BOOLEAN DEFAULT 0,
                allowed_methods TEXT,  -- JSON array: ["totp", "sms", "email"]
                minimum_methods INTEGER DEFAULT 1,  -- Require at least N methods
                grace_period_days INTEGER DEFAULT 7,  -- Days to enable MFA after enforcement
                enforce_on_login BOOLEAN DEFAULT 1,
                enforce_on_sensitive_actions BOOLEAN DEFAULT 1,
                allow_device_trust BOOLEAN DEFAULT 1,
                device_trust_duration_days INTEGER DEFAULT 30,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE mfa_methods (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        method_type TEXT NOT NULL,
        is_enabled INTEGER DEFAULT 0,
        secret_key TEXT,
        phone_number TEXT,
        email TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        last_used_at TIMESTAMP, method_identifier TEXT, is_primary BOOLEAN DEFAULT 0, setup_completed_at TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
        UNIQUE(user_id, method_type)
    );
CREATE TABLE mfa_otp_codes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                method_type TEXT NOT NULL CHECK(method_type IN ('sms', 'email')),
                code TEXT NOT NULL,
                code_hash TEXT NOT NULL,  -- Hashed version for secure comparison
                expires_at TIMESTAMP NOT NULL,
                is_used BOOLEAN DEFAULT 0,
                used_at TIMESTAMP,
                attempts INTEGER DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE mfa_recovery_codes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                code_hash TEXT NOT NULL,  -- Hashed recovery code
                is_used BOOLEAN DEFAULT 0,
                used_at TIMESTAMP,
                generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP,  -- Optional expiration
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE mfa_trusted_devices (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                device_id TEXT NOT NULL,  -- Unique device identifier
                device_name TEXT,
                device_fingerprint TEXT,  -- Browser/OS fingerprint
                ip_address TEXT,
                trust_token TEXT NOT NULL UNIQUE,  -- Secure token for verification
                is_trusted BOOLEAN DEFAULT 1,
                trusted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP NOT NULL,  -- Trust expiration (default 30 days)
                last_used_at TIMESTAMP,
                revoked_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                UNIQUE(user_id, device_id)
            );
CREATE TABLE mfa_user_settings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL UNIQUE,
        mfa_enabled INTEGER DEFAULT 0,
        backup_codes_generated INTEGER DEFAULT 0,
        enforcement_deadline TIMESTAMP,
        bypass_until TIMESTAMP,
        failed_attempts INTEGER DEFAULT 0,
        locked_until TIMESTAMP,
        last_successful_verification TIMESTAMP,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, verification_disabled BOOLEAN DEFAULT 0, mfa_status TEXT DEFAULT 'disabled' CHECK(mfa_status IN ('active', 'disabled')), disabled_at TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );
CREATE TABLE mfa_verification_attempts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                method_type TEXT NOT NULL,
                success BOOLEAN NOT NULL,
                failure_reason TEXT,
                ip_address TEXT,
                user_agent TEXT,
                device_id TEXT,
                attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE micro_credentials (
    micro_id INTEGER PRIMARY KEY AUTOINCREMENT,
    skill_name TEXT NOT NULL,
    description TEXT,
    criteria TEXT NOT NULL,
    points INTEGER DEFAULT 1,
    category TEXT,  -- technical, soft_skills, academic
    is_stackable BOOLEAN DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE ml_predictions (
                prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                prediction_type TEXT NOT NULL,
                risk_score REAL,
                prediction_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                actual_outcome TEXT,
                model_version TEXT
            );
CREATE TABLE "mobile_analytics" (
                analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                event_type TEXT NOT NULL,
                event_data TEXT,
                timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "device_id" INTEGER,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "mobile_devices" (
                device_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                device_name TEXT,
                device_type TEXT,
                os_version TEXT,
                app_version TEXT,
                push_token TEXT,
                registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                last_active TIMESTAMP, "is_active" BOOLEAN DEFAULT 1, "device_token" TEXT, "created_at" TEXT, "platform" TEXT,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "mobile_preferences" (
                pref_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL UNIQUE,
                notifications_enabled BOOLEAN DEFAULT 1,
                dark_mode BOOLEAN DEFAULT 0,
                language TEXT DEFAULT 'en',
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "auto_sync" BOOLEAN DEFAULT 1, "data_saver_mode" BOOLEAN DEFAULT 0, "offline_mode_enabled" BOOLEAN DEFAULT 1, "theme" TEXT DEFAULT 'light',
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "mobile_sessions" (
                session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                device_id INTEGER,
                login_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                logout_time TIMESTAMP,
                session_token TEXT, "ip_address" TEXT, "location" TEXT, "created_at" TEXT, "user_agent" TEXT,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (device_id) REFERENCES mobile_devices(device_id) ON DELETE CASCADE
            );
CREATE TABLE mobility_agreements (
    mobility_agreement_id INTEGER PRIMARY KEY AUTOINCREMENT,
    partner_id            INTEGER,
    host_institution      TEXT    NOT NULL,
    country               TEXT,
    mobility_type         TEXT,
    subject_area          TEXT,
    level                 TEXT,
    places_outgoing       INTEGER DEFAULT 0,
    places_incoming       INTEGER DEFAULT 0,
    language_of_tuition   TEXT,
    language_requirement  TEXT,
    valid_from            TEXT,
    valid_to              TEXT,
    coordinator           TEXT,
    active                INTEGER NOT NULL DEFAULT 1,
    notes                 TEXT,
    created_at            TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at            TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE mobility_credit_recognitions (
    recognition_id      INTEGER PRIMARY KEY AUTOINCREMENT,
    placement_id        INTEGER NOT NULL,
    line_id             INTEGER,
    host_module_code    TEXT,
    host_grade          TEXT,
    host_credits        REAL,
    home_module_code    TEXT,
    home_credits        REAL,
    converted_mark      REAL,
    mode                TEXT,
    outcome             TEXT    NOT NULL DEFAULT 'Recognised',
    recognised_by       TEXT,
    recognised_at       TEXT,
    notes               TEXT,
    created_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (placement_id)
        REFERENCES mobility_placements(placement_id) ON DELETE CASCADE,
    FOREIGN KEY (line_id)
        REFERENCES mobility_learning_agreements(line_id) ON DELETE SET NULL
);
CREATE TABLE mobility_learning_agreements (
    line_id             INTEGER PRIMARY KEY AUTOINCREMENT,
    placement_id        INTEGER NOT NULL,
    host_module_code    TEXT,
    host_module_title   TEXT    NOT NULL,
    host_credits        REAL,
    host_credit_system  TEXT DEFAULT 'ECTS',
    home_module_code    TEXT,
    home_module_title   TEXT,
    home_credits        REAL,
    state               TEXT    NOT NULL DEFAULT 'Draft',
    approved_by_home    TEXT,
    approved_by_host    TEXT,
    approved_at         TEXT,
    amendment_of        INTEGER,
    notes               TEXT,
    created_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (placement_id)
        REFERENCES mobility_placements(placement_id) ON DELETE CASCADE
);
CREATE TABLE mobility_placements (
    placement_id          INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id            TEXT    NOT NULL,
    direction             TEXT    NOT NULL DEFAULT 'outgoing',
    mobility_agreement_id INTEGER,
    host_institution      TEXT,
    host_country          TEXT,
    mobility_type         TEXT,
    funding_scheme        TEXT,
    grant_amount          REAL,
    academic_year         TEXT,
    start_date            TEXT,
    end_date              TEXT,
    status                TEXT    NOT NULL DEFAULT 'Applied',
    home_programme        TEXT,
    host_programme        TEXT,
    credits_expected      REAL,
    credits_recognised    REAL DEFAULT 0,
    recognition_mode      TEXT,
    recognition_state     TEXT DEFAULT 'Awaiting Transcript',
    insurance_confirmed   INTEGER NOT NULL DEFAULT 0,
    risk_assessed         INTEGER NOT NULL DEFAULT 0,
    coordinator           TEXT,
    notes                 TEXT,
    created_at            TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at            TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (mobility_agreement_id)
        REFERENCES mobility_agreements(mobility_agreement_id) ON DELETE SET NULL
);
CREATE TABLE module_assessment_plan (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        module_code TEXT NOT NULL,
        component TEXT NOT NULL,
        assessment_type TEXT,
        weight REAL NOT NULL CHECK (weight > 0 AND weight <= 100),
        size TEXT,
        outcomes TEXT,
        sort_order INTEGER NOT NULL DEFAULT 0
    );
CREATE TABLE module_change_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        module_code TEXT NOT NULL,
        field TEXT NOT NULL,
        old_value TEXT,
        new_value TEXT,
        changed_by TEXT,
        changed_at TEXT NOT NULL DEFAULT (datetime('now')),
        request_id INTEGER REFERENCES module_change_requests(id)
    );
CREATE TABLE module_change_requests (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        module_code TEXT NOT NULL,
        summary TEXT NOT NULL,
        changes_json TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'approved', 'rejected', 'withdrawn')),
        proposed_by TEXT NOT NULL,
        proposed_at TEXT NOT NULL DEFAULT (datetime('now')),
        decided_by TEXT,
        decided_at TEXT,
        decision_note TEXT
    );
CREATE TABLE module_choice_items (
        submission_id INTEGER NOT NULL REFERENCES module_choice_submissions(id)
            ON DELETE CASCADE,
        module_code TEXT NOT NULL,
        result TEXT,
        PRIMARY KEY (submission_id, module_code)
    );
CREATE TABLE module_choice_submissions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        academic_year TEXT NOT NULL,
        year_of_study INTEGER,
        status TEXT NOT NULL DEFAULT 'submitted'
            CHECK (status IN ('submitted', 'approved', 'rejected', 'withdrawn')),
        submitted_by TEXT,
        submitted_at TEXT NOT NULL DEFAULT (datetime('now')),
        decided_by TEXT,
        decided_at TEXT,
        note TEXT
    );
CREATE TABLE module_enrolments (
            module_enrolment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            registration_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            module_code TEXT NOT NULL,
            academic_year TEXT NOT NULL,
            teaching_period TEXT,
            attempt_number INTEGER NOT NULL DEFAULT 1,
            status TEXT NOT NULL DEFAULT 'enrolled',
            effective_from TEXT NOT NULL,
            effective_to TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (
                student_id, module_code, academic_year,
                teaching_period, attempt_number
            ),
            FOREIGN KEY (registration_id)
                REFERENCES programme_registrations(registration_id),
            FOREIGN KEY (student_id) REFERENCES students(student_id)
        );
CREATE TABLE module_exclusions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        module_code TEXT NOT NULL,
        excluded_module_code TEXT NOT NULL,
        reason TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (module_code, excluded_module_code),
        CHECK (module_code <> excluded_module_code)
    );
CREATE TABLE module_external_examiners (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        module_code TEXT NOT NULL,
        examiner_id INTEGER NOT NULL REFERENCES external_examiners(examiner_id),
        academic_year TEXT NOT NULL DEFAULT '',
        assigned_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (module_code, examiner_id, academic_year)
    );
CREATE TABLE module_forum_post_likes (
            post_id INTEGER NOT NULL,
            user_id TEXT NOT NULL,
            liked_at TEXT NOT NULL DEFAULT (datetime('now')),
            PRIMARY KEY (post_id, user_id),
            FOREIGN KEY (post_id) REFERENCES module_forum_posts (post_id) ON DELETE CASCADE
        );
CREATE TABLE module_forum_posts (
            post_id INTEGER PRIMARY KEY AUTOINCREMENT,
            forum_id INTEGER,
            user_id TEXT,
            content TEXT,
            parent_post_id INTEGER,
            attachments TEXT,
            likes_count INTEGER DEFAULT 0,
            is_instructor_post INTEGER DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (forum_id) REFERENCES module_forums(forum_id) ON DELETE CASCADE
        );
CREATE TABLE module_forums (
            forum_id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_code TEXT NOT NULL,
            topic TEXT NOT NULL,
            description TEXT,
            created_by TEXT NOT NULL,
            is_pinned INTEGER DEFAULT 0,
            is_locked INTEGER DEFAULT 0,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (module_code) REFERENCES modules(module_code)
        );
CREATE TABLE module_grades (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            final_score REAL,
            final_grade TEXT,
            completion_date TEXT, "date_recorded" TEXT, "status" TEXT DEFAULT 'provisional', "locked" INTEGER DEFAULT 0, "outcome" TEXT, "credits_awarded" REAL, "board_id" INTEGER, "confirmed_at" TEXT, "attempt" INTEGER DEFAULT 1, "is_complete" INTEGER DEFAULT 0,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE module_programme_designations (
        course_code TEXT NOT NULL,
        module_code TEXT NOT NULL,
        category TEXT NOT NULL CHECK (category IN ('core', 'compulsory', 'optional')),
        year_of_study INTEGER CHECK (year_of_study IS NULL OR year_of_study BETWEEN 0 AND 7),
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (course_code, module_code)
    );
CREATE TABLE module_schedule (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                module_code TEXT,
                day_of_week TEXT,
                start_time TEXT,
                end_time TEXT,
                room_id INTEGER,
                instructor_id INTEGER,
                session_type TEXT,
                created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                modified_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, semester TEXT DEFAULT 'Fall', year INTEGER DEFAULT 0, status TEXT DEFAULT 'published', recurrence TEXT DEFAULT 'weekly', recurrence_until TEXT, parent_schedule_id INTEGER, "enrolled" TEXT, "reassignment_needed" TEXT, "section_id" INTEGER, "week_pattern" TEXT, "online_url" TEXT,
                FOREIGN KEY (module_code) REFERENCES modules (module_code),
                FOREIGN KEY (room_id) REFERENCES rooms (id),
                FOREIGN KEY (instructor_id) REFERENCES instructors (id)
            );
CREATE TABLE module_scheduling_saved_views (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            name TEXT NOT NULL,
            criteria_json TEXT NOT NULL,
            created_at TEXT NOT NULL,
            UNIQUE(user_id, name)
        );
CREATE TABLE module_session_changes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        schedule_id INTEGER NOT NULL REFERENCES module_schedule(id) ON DELETE CASCADE,
        session_date TEXT NOT NULL,
        action TEXT NOT NULL CHECK (action IN ('cancel', 'move')),
        new_date TEXT,
        new_start TEXT,
        new_end TEXT,
        new_room_id INTEGER REFERENCES rooms(id),
        reason TEXT NOT NULL,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (schedule_id, session_date),
        CHECK (action = 'cancel' OR new_date IS NOT NULL)
    );
CREATE TABLE module_sessions (
                       id INTEGER PRIMARY KEY AUTOINCREMENT,
                       module_code TEXT NOT NULL,
                       schedule_id INTEGER,
                       date TEXT NOT NULL,
                       start_time TEXT,
                       end_time TEXT,
                       generated_at TEXT DEFAULT (datetime('now')),
                       UNIQUE (module_code, date, start_time)
                   );
CREATE TABLE module_specifications (
        module_code TEXT PRIMARY KEY,
        aims TEXT,
        indicative_content TEXT,
        teaching_methods TEXT,
        contact_hours REAL CHECK (contact_hours IS NULL OR contact_hours >= 0),
        independent_study_hours REAL
            CHECK (independent_study_hours IS NULL OR independent_study_hours >= 0),
        placement_hours REAL CHECK (placement_hours IS NULL OR placement_hours >= 0),
        reading_list TEXT,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE module_staff (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        module_code TEXT NOT NULL,
        username TEXT NOT NULL,
        role TEXT NOT NULL
            CHECK (role IN ('leader', 'lecturer', 'tutor', 'marker', 'moderator')),
        hours REAL NOT NULL DEFAULT 0 CHECK (hours >= 0),
        academic_year TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (module_code, username, role, academic_year)
    );
CREATE TABLE module_waitlist (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        module_code TEXT NOT NULL,
        student_id TEXT NOT NULL,
        section_id INTEGER,
        position INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'waiting'
            CHECK (status IN ('waiting', 'enrolled', 'removed')),
        added_at TEXT NOT NULL DEFAULT (datetime('now')),
        resolved_at TEXT,
        resolved_by TEXT,
        note TEXT
    );
CREATE TABLE modules (
        module_id TEXT PRIMARY KEY,
        module_name TEXT NOT NULL,
        description TEXT,
        credits INTEGER DEFAULT 0,
        semester TEXT,
        year TEXT,
        instructor TEXT,
        department TEXT,
        prerequisites TEXT,
        is_active BOOLEAN DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    , module_code TEXT, module_type TEXT DEFAULT 'Standard', "course" TEXT, "academic_year" TEXT, "instructor_id" INTEGER, "capacity" INTEGER, "difficulty_level" INTEGER, "level" INTEGER);
CREATE TABLE mood_tracking (
                    mood_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    mood_date TEXT NOT NULL,
                    mood_type TEXT NOT NULL,
                    intensity INTEGER CHECK(intensity BETWEEN 1 AND 5),
                    triggers TEXT,
                    activities TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE movie_series (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE movie_series_link (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            movie_id INTEGER NOT NULL,
            series_id INTEGER NOT NULL,
            sequence_number INTEGER DEFAULT 1,
            FOREIGN KEY (movie_id) REFERENCES movies(id),
            FOREIGN KEY (series_id) REFERENCES movie_series(id),
            UNIQUE(movie_id, series_id)
        );
CREATE TABLE movie_translations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            movie_id INTEGER NOT NULL,
            language_code TEXT NOT NULL,
            title TEXT NOT NULL,
            description TEXT,
            FOREIGN KEY (movie_id) REFERENCES movies(id),
            UNIQUE(movie_id, language_code)
        );
CREATE TABLE movies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            duration INTEGER NOT NULL,
            genre TEXT,
            rating TEXT,
            description TEXT,
            release_date TEXT,
            director TEXT,
            poster_url TEXT,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , trailer_url TEXT, age_rating TEXT, language TEXT DEFAULT 'en');
CREATE TABLE "musicshop_wishlists" (
        wishlist_id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id TEXT NOT NULL,
        product_id INTEGER NOT NULL,
        added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id) REFERENCES products(product_id),
        UNIQUE(customer_id, product_id)
    );
CREATE TABLE nailbar_appointment_treatments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                appointment_id INTEGER NOT NULL,
                treatment_id INTEGER NOT NULL,
                treatment_name TEXT NOT NULL,
                price DECIMAL(10,2) NOT NULL,
                duration_minutes INTEGER NOT NULL,
                notes TEXT,
                FOREIGN KEY (appointment_id) REFERENCES nailbar_appointments(appointment_id),
                FOREIGN KEY (treatment_id) REFERENCES nailbar_treatments(treatment_id)
            );
CREATE TABLE nailbar_appointments (
                appointment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                booking_reference TEXT UNIQUE NOT NULL,
                customer_id TEXT NOT NULL,
                customer_name TEXT NOT NULL,
                customer_email TEXT,
                customer_phone TEXT,
                technician_id INTEGER,
                technician_name TEXT,
                appointment_date TEXT NOT NULL,
                appointment_time TEXT NOT NULL,
                status TEXT DEFAULT 'booked',
                total_amount DECIMAL(10,2) DEFAULT 0.00,
                payment_status TEXT DEFAULT 'pending',
                payment_method TEXT,
                special_requests TEXT,
                notes TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "booking_ref" TEXT, "total_duration" INTEGER, "total_price" REAL, "treatment_ids" TEXT, "treatment_names" TEXT, "user_email" TEXT, "user_id" TEXT, "user_name" TEXT, "completion_notes" TEXT,
                FOREIGN KEY (technician_id) REFERENCES nailbar_technicians(technician_id)
            );
CREATE TABLE nailbar_customer_preferences (
                preference_id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id TEXT NOT NULL UNIQUE,
                preferred_technician_id INTEGER,
                favorite_colors TEXT,
                nail_type TEXT,
                allergies TEXT,
                last_visit TEXT,
                visit_count INTEGER DEFAULT 0,
                loyalty_points INTEGER DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE nailbar_payments (
                        payment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        booking_ref TEXT NOT NULL,
                        appointment_id INTEGER,
                        amount REAL NOT NULL,
                        tip_amount REAL DEFAULT 0.0,
                        total_amount REAL NOT NULL,
                        payment_method TEXT NOT NULL,
                        payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        technician_id INTEGER,
                        technician_name TEXT,
                        receipt_number TEXT UNIQUE NOT NULL,
                        status TEXT DEFAULT 'completed',
                        FOREIGN KEY (appointment_id) REFERENCES nailbar_appointments(appointment_id),
                        FOREIGN KEY (technician_id) REFERENCES nailbar_technicians(technician_id)
                    );
CREATE TABLE nailbar_technicians (
                technician_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                employee_id TEXT UNIQUE,
                specialties TEXT,
                phone TEXT,
                email TEXT,
                certification TEXT,
                is_active INTEGER DEFAULT 1,
                hire_date TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , "max_capacity" INTEGER DEFAULT 8, "specialization" TEXT, "status" TEXT DEFAULT 'active', "technician_name" TEXT, "working_hours" TEXT, "updated_at" TIMESTAMP);
CREATE TABLE nailbar_treatments (
                treatment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                category TEXT NOT NULL,
                description TEXT,
                duration_minutes INTEGER DEFAULT 45,
                price DECIMAL(10,2) NOT NULL,
                is_available INTEGER DEFAULT 1,
                requires_appointment INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , "status" TEXT DEFAULT 'active', "treatment_name" TEXT, "updated_at" TIMESTAMP);
CREATE TABLE navigation_favorites (
                    favorite_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    location_type TEXT NOT NULL,
                    location_id INTEGER NOT NULL,
                    nickname TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE navigation_history (
                    history_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT,
                    start_location TEXT NOT NULL,
                    end_location TEXT NOT NULL,
                    route_taken TEXT,
                    duration_minutes INTEGER,
                    accessibility_required BOOLEAN DEFAULT 0,
                    navigation_date TEXT DEFAULT CURRENT_TIMESTAMP,
                    rating INTEGER,
                    feedback TEXT
                );
CREATE TABLE networking_connections (
            connection_id INTEGER PRIMARY KEY AUTOINCREMENT,
            requester_id TEXT,
            recipient_id TEXT,
            connection_date TEXT,
            status TEXT DEFAULT 'pending',
            message TEXT,
            FOREIGN KEY (requester_id) REFERENCES alumni (alumni_id),
            FOREIGN KEY (recipient_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE newsletter_deliveries (
        newsletter_id INTEGER NOT NULL,
        alumni_id TEXT NOT NULL,
        outcome TEXT NOT NULL,
        at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (newsletter_id, alumni_id)
    );
CREATE TABLE newsletters (
            newsletter_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT,
            content TEXT,
            template_id INTEGER,
            target_audience TEXT,
            send_date TEXT,
            created_date TEXT,
            created_by TEXT,
            status TEXT DEFAULT 'draft',
            open_rate REAL DEFAULT 0.0,
            click_rate REAL DEFAULT 0.0
        , "sent_at" TEXT, "sent_by" TEXT, "sent_count" INTEGER DEFAULT 0, "suppressed_count" INTEGER DEFAULT 0, "audience_json" TEXT);
CREATE TABLE normalized_grades (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            grade_id INTEGER,
            z_score REAL,
            percentile REAL,
            curved_score REAL,
            curved_letter TEXT,
            FOREIGN KEY (grade_id) REFERENCES grades (grade_id)
        );
CREATE TABLE "notification_actions" (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        notification_id INTEGER NOT NULL,
        action_text TEXT NOT NULL,
        action_url TEXT NOT NULL,
        action_type TEXT DEFAULT 'link',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE "notification_queue" (
                    id TEXT PRIMARY KEY,
                    user_id TEXT NOT NULL,
                    event_id TEXT,
                    notification_type TEXT NOT NULL,
                    scheduled_time TEXT NOT NULL,
                    status TEXT DEFAULT 'pending',
                    message TEXT,
                    date_added TEXT NOT NULL,
                    sent_at TEXT, "delivery_method" TEXT DEFAULT 'email', "notification_id" INTEGER, "title" TEXT, "sent" BOOLEAN DEFAULT FALSE,
                    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE
                );
CREATE TABLE notification_schedules (
            schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
            template_id INTEGER NOT NULL,
            trigger_condition TEXT NOT NULL, -- JSON with conditions
            days_before_due INTEGER,
            max_reminders INTEGER DEFAULT 3,
            reminder_interval_days INTEGER DEFAULT 7,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (template_id) REFERENCES notification_templates (template_id)
        );
CREATE TABLE notification_settings (
                        setting_key TEXT PRIMARY KEY,
                        setting_value TEXT,
                        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE "notification_subscriptions" (
    subscription_id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    topic TEXT NOT NULL,  -- course_updates, events, grades, announcements
    channel TEXT DEFAULT 'email',  -- email, sms, push
    is_active BOOLEAN DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(user_id, topic, channel)
);
CREATE TABLE notification_templates (
            template_id INTEGER PRIMARY KEY AUTOINCREMENT,
            template_name TEXT NOT NULL,
            template_type TEXT NOT NULL, -- 'payment_reminder', 'overdue_notice', 'payment_confirmation', etc.
            subject_template TEXT NOT NULL,
            body_template TEXT NOT NULL,
            send_method TEXT DEFAULT 'email', -- 'email', 'sms', 'push'
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE notification_type_preferences (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id TEXT NOT NULL,
                        notification_type TEXT NOT NULL,
                        email_enabled INTEGER DEFAULT 1,
                        sms_enabled INTEGER DEFAULT 0,
                        push_enabled INTEGER DEFAULT 1,
                        in_app_enabled INTEGER DEFAULT 1,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP,
                        UNIQUE(user_id, notification_type)
                    );
CREATE TABLE ocr_results (
            ocr_id INTEGER PRIMARY KEY AUTOINCREMENT,
            document_id INTEGER,
            extracted_text TEXT,
            confidence_score REAL,
            processing_date TEXT,
            FOREIGN KEY (document_id) REFERENCES documents (document_id)
        );
CREATE TABLE office_hour_bookings (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        office_hour_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        booking_date TEXT NOT NULL,
                        notes TEXT DEFAULT '',
                        status TEXT DEFAULT 'confirmed',
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP, "module_code" TEXT, "slot_start" TEXT, "slot_end" TEXT, "mode" TEXT, "attendance" TEXT, "meeting_notes" TEXT, "actions" TEXT, "recorded_by" TEXT, "recorded_at" TEXT, "reminder_sent_at" TEXT, "cancelled_at" TEXT, "cancelled_by" TEXT, "cancel_reason" TEXT,
                        FOREIGN KEY (office_hour_id) REFERENCES office_hours(id)
                    );
CREATE TABLE office_hour_exceptions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        office_hour_id INTEGER NOT NULL REFERENCES office_hours(id),
        exception_date TEXT NOT NULL,
        reason TEXT NOT NULL,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (office_hour_id, exception_date)
    );
CREATE TABLE office_hour_waitlist (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        office_hour_id INTEGER NOT NULL REFERENCES office_hours(id),
        booking_date TEXT NOT NULL,
        student_id TEXT NOT NULL,
        module_code TEXT,
        notes TEXT,
        position INTEGER NOT NULL,
        status TEXT NOT NULL DEFAULT 'waiting'
            CHECK (status IN ('waiting', 'booked', 'removed', 'expired')),
        added_at TEXT NOT NULL DEFAULT (datetime('now')),
        resolved_at TEXT
    );
CREATE TABLE office_hours (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        instructor_id TEXT NOT NULL,
                        day_of_week TEXT NOT NULL,
                        start_time TEXT NOT NULL,
                        end_time TEXT NOT NULL,
                        location TEXT NOT NULL,
                        capacity INTEGER DEFAULT 5,
                        notes TEXT DEFAULT '',
                        is_active INTEGER DEFAULT 1,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                    , "slot" TEXT, "slot_minutes" INTEGER, "mode" TEXT DEFAULT 'in_person', "online_url" TEXT, "module_code" TEXT, "min_notice_hours" INTEGER, "cancel_cutoff_hours" INTEGER, "max_per_student_week" INTEGER);
CREATE TABLE "offline_sync_queue" (
    queue_id INTEGER PRIMARY KEY AUTOINCREMENT,
    device_id INTEGER NOT NULL,
    action_type TEXT NOT NULL,  -- create, update, delete
    entity_type TEXT NOT NULL,  -- assignment, grade, attendance
    data TEXT NOT NULL,  -- JSON
    sync_status TEXT DEFAULT 'pending',  -- pending, synced, failed
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    synced_at TIMESTAMP, "user_id" INTEGER, "entity_id" INTEGER, "payload" TEXT,
    FOREIGN KEY (device_id) REFERENCES mobile_devices(device_id) ON DELETE CASCADE
);
CREATE TABLE ofs_app_milestones (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            plan_year INTEGER NOT NULL,
            milestone_text TEXT NOT NULL,
            target_value REAL,
            target_date TEXT,
            current_value REAL,
            achieved INTEGER NOT NULL DEFAULT 0,
            achieved_date TEXT,
            owner_id INTEGER,
            notes TEXT,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            updated_at TEXT NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE ofs_b3_metrics (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            cohort_year INTEGER NOT NULL,
            course TEXT,
            metric_type TEXT NOT NULL,
            value_pct REAL NOT NULL,
            numerator INTEGER NOT NULL,
            denominator INTEGER NOT NULL,
            computed_at TEXT NOT NULL DEFAULT (datetime('now')),
            UNIQUE (cohort_year, course, metric_type)
        );
CREATE TABLE ofs_protection_plans (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            version TEXT NOT NULL,
            in_force_from TEXT NOT NULL,
            in_force_to TEXT,
            plan_text TEXT NOT NULL,
            approved_by INTEGER,
            approved_at TEXT,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            UNIQUE (version)
        );
CREATE TABLE onboarding_assignments (
                    assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    template_id INTEGER NOT NULL,
                    assigned_by TEXT,
                    start_date TEXT NOT NULL,
                    target_completion_date TEXT,
                    actual_completion_date TEXT,
                    status TEXT DEFAULT 'in_progress',
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP, "staff_id" INTEGER,
                    FOREIGN KEY (template_id) REFERENCES onboarding_templates(template_id)
                );
CREATE TABLE onboarding_task_progress (
                    progress_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    assignment_id INTEGER NOT NULL,
                    task_id INTEGER NOT NULL,
                    status TEXT DEFAULT 'pending',
                    assigned_to TEXT,
                    due_date TEXT,
                    completed_by TEXT,
                    completed_date TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (assignment_id) REFERENCES onboarding_assignments(assignment_id),
                    FOREIGN KEY (task_id) REFERENCES onboarding_template_tasks(task_id),
                    UNIQUE(assignment_id, task_id)
                );
CREATE TABLE onboarding_template_tasks (
                    task_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    template_id INTEGER NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    category TEXT DEFAULT 'general',
                    assigned_to_role TEXT DEFAULT 'employee',
                    due_days INTEGER DEFAULT 0,
                    is_required BOOLEAN DEFAULT 1,
                    order_num INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (template_id) REFERENCES onboarding_templates(template_id)
                );
CREATE TABLE onboarding_templates (
                    template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    role TEXT,
                    department TEXT,
                    template_type TEXT DEFAULT 'onboarding',
                    estimated_days INTEGER DEFAULT 30,
                    is_active BOOLEAN DEFAULT 1,
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE operational_degraded_states (
            state_id INTEGER PRIMARY KEY AUTOINCREMENT,
            component TEXT NOT NULL,
            code TEXT NOT NULL,
            severity TEXT NOT NULL,
            message TEXT NOT NULL,
            retryable INTEGER NOT NULL DEFAULT 0,
            correlation_id TEXT,
            details_json TEXT NOT NULL DEFAULT '{}',
            status TEXT NOT NULL DEFAULT 'open',
            occurrence_count INTEGER NOT NULL DEFAULT 1,
            first_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            resolved_at TEXT,
            resolved_by TEXT,
            resolution_notes TEXT,
            UNIQUE(component, code, status)
        );
CREATE TABLE order_discounts (
                                discount_id INTEGER PRIMARY KEY AUTOINCREMENT,
                                order_id INTEGER,
                                discount_amount REAL,
                                discount_type TEXT,
                                discount_value REAL,
                                promo_code TEXT,
                                reason TEXT,
                                manager_approved BOOLEAN,
                                discount_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                                FOREIGN KEY (order_id) REFERENCES orders(order_id)
                            );
CREATE TABLE order_items (
    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
    source_type TEXT NOT NULL,
    order_id INTEGER,
    source_order_id TEXT,
    product_id TEXT,
    item_name TEXT,
    artist TEXT,
    quantity REAL DEFAULT 1,
    unit_type TEXT,
    unit_price REAL,
    subtotal REAL,
    special_cut TEXT,
    special_instructions TEXT,
    warranty_id TEXT,
    serial_number TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
, "quantity_kg" TEXT);
CREATE TABLE orders (
    order_id INTEGER PRIMARY KEY AUTOINCREMENT,
    source_type TEXT NOT NULL,
    source_order_id TEXT,
    order_number TEXT,
    customer_id TEXT,
    customer_name TEXT,
    customer_email TEXT,
    customer_phone TEXT,
    student_id TEXT,
    user_id INTEGER,
    restaurant_id TEXT,
    order_type TEXT,
    order_date TEXT DEFAULT (datetime('now')),
    subtotal REAL,
    tax_amount REAL,
    shipping_fee REAL,
    delivery_fee REAL,
    discount_amount REAL,
    total_amount REAL,
    payment_method TEXT,
    payment_status TEXT,
    payment_reference TEXT,
    order_status TEXT DEFAULT 'pending',
    delivery_address TEXT,
    shipping_address TEXT,
    delivery_type TEXT,
    estimated_delivery TEXT,
    actual_delivery TEXT,
    pickup_date TEXT,
    pickup_time TEXT,
    special_instructions TEXT,
    age_verified INTEGER,
    rating INTEGER,
    review TEXT,
    notes TEXT,
    processed_by TEXT,
    created_by TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT
, "id" INTEGER, "completed_at" TIMESTAMP, "items" TEXT, "completed_date" TEXT, "status" TEXT, "table_id" INTEGER, "tip_amount" REAL, "user_email" TEXT, "user_name" TEXT, "actual_time" TEXT, "discount_applied" TEXT);
CREATE TABLE organizations (
            org_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            domain TEXT,
            contact_email TEXT,
            phone TEXT,
            address TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        , "code" TEXT, "description" TEXT, "parent_org_id" INTEGER);
CREATE TABLE orphaned_health_records (
        orphan_id INTEGER PRIMARY KEY AUTOINCREMENT,
        source_table TEXT NOT NULL,
        source_id INTEGER,
        student_id TEXT,
        reason TEXT NOT NULL,
        original_json TEXT NOT NULL,
        quarantined_at TEXT NOT NULL DEFAULT (datetime('now')),
        resolved_at TEXT,
        resolution TEXT
    );
CREATE TABLE outbreak_investigations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        disease_name TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'monitoring', 'closed')),
        case_count INTEGER NOT NULL DEFAULT 0,
        case_ids TEXT,
        locations TEXT,
        findings TEXT,
        actions TEXT,
        opened_by TEXT,
        opened_at TEXT NOT NULL DEFAULT (datetime('now')),
        closed_at TEXT,
        closed_by TEXT
    );
CREATE TABLE outcome_alignments (
                    alignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    programme_outcome_id INTEGER NOT NULL,
                    module_outcome_id INTEGER NOT NULL,
                    alignment_strength TEXT DEFAULT 'moderate',
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_outcome_id) REFERENCES learning_outcomes(outcome_id),
                    FOREIGN KEY (module_outcome_id) REFERENCES learning_outcomes(outcome_id)
                );
CREATE TABLE outcome_program_mappings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        outcome_id INTEGER NOT NULL,
        standard_type TEXT NOT NULL DEFAULT 'Program Outcome',
        standard_code TEXT NOT NULL DEFAULT '',
        standard_description TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        FOREIGN KEY (outcome_id) REFERENCES course_learning_outcomes (id)
    );
CREATE TABLE outcome_results (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            outcome_id INTEGER NOT NULL,
            achievement_level REAL,
            assessment_date TEXT,
            evidence TEXT, "date_assessed" TEXT,
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (outcome_id) REFERENCES learning_outcomes(outcome_id)
        );
CREATE TABLE parent_accounts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id TEXT UNIQUE,
            first_name TEXT,
            last_name TEXT,
            email TEXT UNIQUE,
            phone TEXT,
            address TEXT,
            emergency_contact BOOLEAN DEFAULT 0,
            registration_date TEXT,
            two_factor_enabled BOOLEAN DEFAULT 0,
            two_factor_secret TEXT,
            profile_photo TEXT
        , "created_at" TEXT, "relationship" TEXT, "user_id" INTEGER, "verified" INTEGER DEFAULT 0);
CREATE TABLE parent_activity_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                action TEXT,
                details TEXT,
                ip_address TEXT,
                user_agent TEXT,
                timestamp TEXT, "activity_description" TEXT, "activity_type" TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
            );
CREATE TABLE parent_communications (
    comm_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id TEXT NOT NULL,
    staff_id INTEGER,
    student_id TEXT,
    subject TEXT,
    message TEXT NOT NULL,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_read BOOLEAN DEFAULT 0, "content" TEXT, "id" INTEGER, "read_at" TEXT, "sent_at" TEXT, "type" TEXT,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_conference_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id TEXT NOT NULL,
    teacher_id INTEGER NOT NULL,
    student_id TEXT NOT NULL,
    preferred_times TEXT,  -- JSON array
    reason TEXT,
    status TEXT DEFAULT 'pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "id" INTEGER, "instructor_id" INTEGER, "requested_date" TEXT, "preferred_time" TEXT,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_conferences (
    conference_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id TEXT NOT NULL,
    teacher_id INTEGER NOT NULL,
    student_id TEXT,
    datetime TIMESTAMP NOT NULL,
    location TEXT,
    meeting_type TEXT DEFAULT 'in_person',  -- in_person, virtual, phone
    meeting_link TEXT,
    status TEXT DEFAULT 'scheduled',
    notes TEXT, "id" INTEGER, "instructor_id" INTEGER, "scheduled_date" TEXT, "duration" INTEGER DEFAULT 30, "created_at" TEXT, "scheduled_for" TEXT, "staff_id" INTEGER,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_contacts (
                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                            student_id TEXT NOT NULL,
                            parent_name TEXT NOT NULL,
                            relationship TEXT,
                            email TEXT,
                            phone TEXT,
                            preferred_contact TEXT DEFAULT 'email',
                            created_at TEXT DEFAULT CURRENT_TIMESTAMP, "contact_type" TEXT, "contact_value" TEXT, "is_primary" INTEGER DEFAULT 0, "parent_id" INTEGER, "verified" INTEGER DEFAULT 0,
                            FOREIGN KEY (student_id) REFERENCES students (student_id)
                        );
CREATE TABLE parent_document_access (
    access_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id TEXT NOT NULL,
    student_id TEXT NOT NULL,
    document_id INTEGER,
    document_type TEXT,
    accessed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "id" INTEGER,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE parent_issues (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                category TEXT,
                subject TEXT,
                description TEXT,
                priority TEXT,
                status TEXT DEFAULT 'open',
                created_date TEXT,
                resolved_date TEXT,
                response TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
            );
CREATE TABLE "parent_messages" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                teacher_id INTEGER,
                student_id TEXT,
                message_content TEXT,
                created_date TEXT,
                is_read BOOLEAN DEFAULT 0,
                is_from_parent BOOLEAN DEFAULT 1,
                message_type TEXT DEFAULT 'individual',
                group_id TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (teacher_id) REFERENCES users (id) ON DELETE CASCADE,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE parent_notification_settings (
                        id INTEGER PRIMARY KEY,
                        auto_absence INTEGER,
                        auto_low_attendance INTEGER,
                        low_attendance_threshold INTEGER,
                        absence_template TEXT,
                        low_attendance_template TEXT
                    );
CREATE TABLE parent_notifications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                student_id TEXT,
                notification_type TEXT,
                notification_content TEXT,
                created_date TEXT,
                read_status BOOLEAN DEFAULT 0, "created_at" TEXT, "is_read" INTEGER DEFAULT 0, "message" TEXT, "read_at" TEXT, "title" TEXT, "type" TEXT, sent_at TEXT DEFAULT CURRENT_TIMESTAMP, parent_name TEXT, method TEXT, status TEXT, subject TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE parent_permissions (
    permission_id INTEGER PRIMARY KEY AUTOINCREMENT,
    link_id INTEGER NOT NULL,
    permission_type TEXT NOT NULL,  -- view_grades, view_attendance, view_financial
    granted BOOLEAN DEFAULT 1, "id" INTEGER, "parent_id" INTEGER, "student_id" TEXT, "granted_at" TEXT, "expires_at" TEXT,
    FOREIGN KEY (link_id) REFERENCES parent_student_links(link_id),
    UNIQUE(link_id, permission_type)
);
CREATE TABLE parent_portal_activity (
    activity_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id TEXT NOT NULL,
    action_type TEXT NOT NULL,
    details TEXT,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    ip_address TEXT, "activity_type" TEXT, "created_at" TEXT, "description" TEXT, "id" INTEGER,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_preferences (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id TEXT UNIQUE,
            email_notifications BOOLEAN DEFAULT 1,
            sms_notifications BOOLEAN DEFAULT 0,
            grade_alerts BOOLEAN DEFAULT 1,
            attendance_alerts BOOLEAN DEFAULT 1,
            behavior_alerts BOOLEAN DEFAULT 1,
            assignment_alerts BOOLEAN DEFAULT 0,
            weekly_summary BOOLEAN DEFAULT 1,
            notification_timing TEXT DEFAULT '08:00',
            quiet_hours_start TEXT DEFAULT '20:00',
            quiet_hours_end TEXT DEFAULT '07:00', "subject_preferences" TEXT, "preferred_notification_time" TEXT,
            FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
        );
CREATE TABLE parent_student_links (
    link_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id TEXT NOT NULL,
    student_id TEXT NOT NULL,
    relationship TEXT NOT NULL,  -- parent, guardian, other
    permissions TEXT,  -- JSON
    is_primary BOOLEAN DEFAULT 0,
    verified BOOLEAN DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "id" INTEGER, "is_primary_contact" INTEGER DEFAULT 0, "can_view_grades" INTEGER DEFAULT 1, "can_view_attendance" INTEGER DEFAULT 1, "can_view_finances" INTEGER DEFAULT 0,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id),
    UNIQUE(parent_id, student_id)
);
CREATE TABLE parent_student_relationships (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id TEXT,
            student_id TEXT,
            relationship_type TEXT,
            access_level TEXT DEFAULT 'full',
            date_added TEXT,
            FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE "parent_teacher_meetings" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                teacher_id INTEGER,
                student_id TEXT,
                meeting_date TEXT,
                start_time TEXT,
                end_time TEXT,
                location TEXT,
                meeting_type TEXT,
                status TEXT DEFAULT 'scheduled',
                agenda TEXT,
                notes TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (teacher_id) REFERENCES users (id) ON DELETE CASCADE,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE "parent_user_mapping" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            parent_id TEXT UNIQUE,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
            FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
        );
CREATE TABLE parking_lots (
            lot_id              TEXT    PRIMARY KEY,
            lot_name            TEXT,
            location            TEXT,
            total_spaces        INTEGER,
            available_spaces    INTEGER,
            zone                TEXT,
            hours_of_operation  TEXT
        , hourly_rate DECIMAL(5,2) DEFAULT 0.00, daily_rate DECIMAL(5,2) DEFAULT 0.00, monthly_rate DECIMAL(5,2) DEFAULT 0.00, is_active BOOLEAN DEFAULT 1, created_at TEXT DEFAULT NULL, updated_at TEXT DEFAULT NULL);
CREATE TABLE parking_occupancy (
    occupancy_id INTEGER PRIMARY KEY AUTOINCREMENT,
    lot_id TEXT NOT NULL,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    available_spaces INTEGER NOT NULL,
    total_spaces INTEGER NOT NULL, "id" INTEGER, "occupancy_rate" REAL DEFAULT 0.0, "occupied_spaces" INTEGER DEFAULT 0,
    FOREIGN KEY (lot_id) REFERENCES parking_lots(lot_id)
);
CREATE TABLE "parking_permits" (
            permit_id     TEXT    PRIMARY KEY,
            user_id       INTEGER,
            full_name     TEXT,
            email         TEXT,
            zone          TEXT,
            permit_type   TEXT,
            start_date    TEXT,
            end_date      TEXT,
            active_status TEXT,
            vehicle_id    TEXT,
            issue_date    TEXT, "expiry_date" TEXT, "fee_paid" DECIMAL(10,2) DEFAULT 0.00, "lot_id" INTEGER, "status" TEXT DEFAULT 'active', "student_id" TEXT, "created_at" TIMESTAMP DEFAULT NULL, "updated_at" TIMESTAMP DEFAULT NULL, "permit_number" TEXT, "vehicle_make" TEXT, "vehicle_model" TEXT,
            FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE CASCADE,
            FOREIGN KEY (user_id)    REFERENCES users(id) ON DELETE CASCADE
        );
CREATE TABLE parking_spaces (
            space_id         TEXT    PRIMARY KEY,
            lot_id           TEXT,
            space_number     TEXT,
            space_type       TEXT,
            occupancy_status TEXT,
            reserved_for     TEXT, "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "is_accessible" BOOLEAN DEFAULT 0, "is_available" BOOLEAN DEFAULT 1, "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (lot_id) REFERENCES parking_lots(lot_id)
        );
CREATE TABLE "parking_violations" (
            violation_id    TEXT    PRIMARY KEY,
            vehicle_id      TEXT,
            license_plate   TEXT,
            violation_type  TEXT,
            violation_date  TEXT,
            fine_amount     REAL,
            payment_status  TEXT,
            location        TEXT,
            officer_id      INTEGER, "issued_by" TEXT, "lot_id" INTEGER, "notes" TEXT, "paid_date" TEXT, "space_id" INTEGER, "status" TEXT DEFAULT 'pending', "created_at" TIMESTAMP DEFAULT NULL, "updated_at" TIMESTAMP DEFAULT NULL,
            FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE CASCADE,
            FOREIGN KEY (officer_id) REFERENCES users(id) ON DELETE CASCADE
        );
CREATE TABLE partner_cohorts (
    cohort_id           INTEGER PRIMARY KEY AUTOINCREMENT,
    collab_programme_id INTEGER NOT NULL,
    academic_year       TEXT    NOT NULL,
    intake_month        TEXT,
    planned_headcount   INTEGER,
    actual_headcount    INTEGER,
    registered_headcount INTEGER,
    completed_headcount INTEGER,
    notes               TEXT,
    created_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (collab_programme_id)
        REFERENCES collaborative_programmes(collab_programme_id) ON DELETE CASCADE
);
CREATE TABLE partner_institutions (
    partner_id          INTEGER PRIMARY KEY AUTOINCREMENT,
    name                TEXT    NOT NULL,
    partner_type        TEXT,
    country             TEXT,
    city                TEXT,
    ukprn               TEXT,
    website             TEXT,
    contact_name        TEXT,
    contact_email       TEXT,
    contact_phone       TEXT,
    risk_level          TEXT    DEFAULT 'Medium',
    due_diligence_date  TEXT,
    due_diligence_due   TEXT,
    notes               TEXT,
    active              INTEGER NOT NULL DEFAULT 1,
    created_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(name, country)
);
CREATE TABLE partner_reviews (
    review_id           INTEGER PRIMARY KEY AUTOINCREMENT,
    partner_id          INTEGER NOT NULL,
    agreement_id        INTEGER,
    review_type         TEXT    NOT NULL,
    review_date         TEXT    NOT NULL,
    reviewer            TEXT,
    outcome             TEXT,
    findings            TEXT,
    conditions          TEXT,
    next_review_due     TEXT,
    created_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (partner_id)
        REFERENCES partner_institutions(partner_id) ON DELETE CASCADE,
    FOREIGN KEY (agreement_id)
        REFERENCES partnership_agreements(agreement_id) ON DELETE SET NULL
);
CREATE TABLE partnership_agreements (
    agreement_id        INTEGER PRIMARY KEY AUTOINCREMENT,
    partner_id          INTEGER NOT NULL,
    reference           TEXT,
    delivery_model      TEXT    NOT NULL,
    status              TEXT    NOT NULL DEFAULT 'Under Negotiation',
    start_date          TEXT,
    end_date            TEXT,
    review_due          TEXT,
    max_students        INTEGER,
    fee_share_pct       REAL,
    signed_by           TEXT,
    signed_date         TEXT,
    contract_ref        TEXT,
    notes               TEXT,
    created_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TEXT    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (partner_id)
        REFERENCES partner_institutions(partner_id) ON DELETE CASCADE
);
CREATE TABLE "password_history" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                password_hash TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE "password_policy_compliance" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER UNIQUE NOT NULL,
                last_password_change TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                password_expires_at TIMESTAMP,
                must_change INTEGER DEFAULT 0, "failed_attempts" INTEGER DEFAULT 0, "locked_until" TEXT, "mfa_enabled" INTEGER DEFAULT 0,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE pastoral_assignments (
                    assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    group_id INTEGER NOT NULL,
                    tutor_id INTEGER NOT NULL,
                    role TEXT NOT NULL DEFAULT 'personal_tutor',
                    assigned_date TEXT NOT NULL,
                    ended_date TEXT,
                    is_active INTEGER DEFAULT 1,
                    FOREIGN KEY (group_id) REFERENCES tutor_groups (group_id)
                );
CREATE TABLE patents (
                    patent_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    disclosure_id INTEGER,
                    patent_number TEXT,
                    title TEXT NOT NULL,
                    patent_office TEXT DEFAULT 'USPTO',
                    filing_date TEXT,
                    publication_date TEXT,
                    grant_date TEXT,
                    expiry_date TEXT,
                    status TEXT DEFAULT 'pending',
                    cost_to_date REAL DEFAULT 0,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (disclosure_id) REFERENCES ip_disclosures(disclosure_id)
                );
CREATE TABLE pay_awards (
        award_id INTEGER PRIMARY KEY AUTOINCREMENT,
        pay_year TEXT NOT NULL UNIQUE,
        from_pay_year TEXT NOT NULL,
        uplift_percent REAL NOT NULL,
        minimum_uplift REAL NOT NULL DEFAULT 0,
        points_updated INTEGER NOT NULL DEFAULT 0,
        notes TEXT,
        applied_by TEXT,
        applied_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE pay_grade_jobs (
        job_title TEXT PRIMARY KEY COLLATE NOCASE,
        grade_code TEXT NOT NULL REFERENCES pay_grades (grade_code) ON DELETE CASCADE,
        created_by TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE pay_grades (
        grade_code TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        min_point INTEGER NOT NULL,
        max_point INTEGER NOT NULL,
        contribution_max_point INTEGER,
        is_active INTEGER NOT NULL DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT,
        CHECK (min_point <= max_point),
        CHECK (contribution_max_point IS NULL OR contribution_max_point >= max_point)
    );
CREATE TABLE pay_increment_moves (
        move_id INTEGER PRIMARY KEY AUTOINCREMENT,
        run_id INTEGER NOT NULL REFERENCES pay_increment_runs (run_id) ON DELETE CASCADE,
        contract_id INTEGER NOT NULL,
        user_id TEXT NOT NULL,
        from_point INTEGER,
        to_point INTEGER,
        outcome TEXT NOT NULL,
        reason TEXT
    );
CREATE TABLE pay_increment_runs (
        run_id INTEGER PRIMARY KEY AUTOINCREMENT,
        effective_date TEXT NOT NULL UNIQUE,
        pay_year TEXT NOT NULL,
        run_by TEXT,
        run_at TEXT DEFAULT CURRENT_TIMESTAMP,
        moved INTEGER NOT NULL DEFAULT 0,
        held INTEGER NOT NULL DEFAULT 0
    );
CREATE TABLE pay_settings (
        key TEXT PRIMARY KEY,
        value TEXT,
        updated_by TEXT,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE pay_spine_points (
        point INTEGER PRIMARY KEY,
        label TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE pay_spine_values (
        point INTEGER NOT NULL REFERENCES pay_spine_points (point) ON DELETE CASCADE,
        pay_year TEXT NOT NULL,
        annual_value REAL NOT NULL CHECK (annual_value >= 0),
        set_by TEXT,
        set_at TEXT DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (point, pay_year)
    );
CREATE TABLE payment_allocations (
                allocation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                payment_id INTEGER NOT NULL,
                student_fee_id INTEGER NOT NULL,
                amount DECIMAL(10,2) NOT NULL,
                created_at TEXT,
                FOREIGN KEY (payment_id) REFERENCES payments (payment_id),
                FOREIGN KEY (student_fee_id) REFERENCES student_fees (student_fee_id)
            );
CREATE TABLE payment_gateways (
            gateway_id INTEGER PRIMARY KEY AUTOINCREMENT,
            gateway_name TEXT NOT NULL,
            gateway_type TEXT NOT NULL, -- 'stripe', 'paypal', 'bank_transfer', etc.
            configuration TEXT, -- JSON with gateway config
            is_active BOOLEAN DEFAULT 1,
            transaction_fee_percentage DECIMAL(5,4),
            transaction_fee_fixed DECIMAL(10,2),
            supported_currencies TEXT, -- JSON array
            webhook_url TEXT,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE payment_plan_installments (
                installment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                payment_plan_id INTEGER NOT NULL,
                installment_number INTEGER NOT NULL,
                amount DECIMAL(10,2) NOT NULL,
                due_date TEXT NOT NULL,
                status TEXT DEFAULT 'pending',
                payment_id INTEGER,
                late_fee_amount DECIMAL(10,2) DEFAULT 0,
                created_at TEXT,
                updated_at TEXT,
                FOREIGN KEY (payment_plan_id) REFERENCES student_payment_plans (payment_plan_id),
                FOREIGN KEY (payment_id) REFERENCES payments (payment_id)
            );
CREATE TABLE payment_plan_templates (
            template_id INTEGER PRIMARY KEY AUTOINCREMENT,
            template_name TEXT NOT NULL,
            description TEXT,
            number_of_installments INTEGER NOT NULL,
            installment_frequency TEXT NOT NULL, -- 'weekly', 'monthly', 'quarterly'
            setup_fee DECIMAL(10,2) DEFAULT 0,
            interest_rate DECIMAL(5,2) DEFAULT 0,
            early_payment_discount DECIMAL(5,2) DEFAULT 0,
            late_payment_penalty DECIMAL(5,2) DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE payment_risk_scores (
            score_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            risk_score DECIMAL(5,2) NOT NULL, -- 0-100
            risk_level TEXT NOT NULL, -- 'low', 'medium', 'high'
            factors TEXT, -- JSON with risk factors
            last_calculated TEXT,
            created_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE payment_schedules (
    schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
    award_id INTEGER,
    component_id INTEGER,
    student_id TEXT NOT NULL,
    total_amount REAL NOT NULL,
    payment_date DATE NOT NULL,
    amount REAL NOT NULL,
    academic_term TEXT,
    status TEXT DEFAULT 'scheduled',  -- scheduled, paid, cancelled
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "plan_id" INTEGER, "installment_number" INTEGER, "due_date" TEXT, "paid_date" TEXT, "paid_amount" REAL,
    FOREIGN KEY (award_id) REFERENCES scholarship_awards(award_id),
    FOREIGN KEY (component_id) REFERENCES aid_components(component_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE payments (
    payment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT,
    amount DECIMAL(10,2) NOT NULL,
    currency TEXT DEFAULT 'GBP',
    payment_method TEXT,
    gateway_transaction_id TEXT,
    gateway_name TEXT,
    transaction_id TEXT,
    payment_date TEXT,
    status TEXT DEFAULT 'completed',
    notes TEXT,
    created_by TEXT,
    created_at TEXT,
    fraud_score DECIMAL(3,2),
    is_suspicious BOOLEAN DEFAULT 0,
    source_type TEXT DEFAULT 'general',
    source_payment_id TEXT,
    customer_email TEXT,
    payment_type TEXT,
    payment_reference TEXT,
    reference_type TEXT,
    reference_id TEXT,
    department TEXT,
    description TEXT,
    payment_period_start TEXT,
    payment_period_end TEXT,
    receipt_sent INTEGER DEFAULT 0,
    processed_by TEXT,
    updated_at TEXT
, vat_rate TEXT, vat_amount REAL);
CREATE TABLE payroll_allowances (
                    allowance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    allowance_type TEXT NOT NULL,
                    amount REAL NOT NULL,
                    frequency TEXT DEFAULT 'monthly',
                    start_date TEXT NOT NULL,
                    end_date TEXT,
                    is_active INTEGER DEFAULT 1,
                    approved_by TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                , "updated_at" TEXT);
CREATE TABLE payroll_overtime (
                    overtime_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    date TEXT NOT NULL,
                    hours REAL NOT NULL,
                    rate_multiplier REAL DEFAULT 1.5,
                    reason TEXT,
                    status TEXT DEFAULT 'pending',
                    approved_by TEXT,
                    approved_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE payroll_periods (
                    period_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    period_type TEXT NOT NULL DEFAULT 'monthly',
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    payment_date TEXT,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                , "updated_by" TEXT, "contracted_hours" INTEGER, "leave_notes" TEXT);
CREATE TABLE payroll_records (
                    record_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    period_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    contract_id INTEGER,
                    basic_salary REAL DEFAULT 0,
                    overtime_pay REAL DEFAULT 0,
                    allowances_total REAL DEFAULT 0,
                    gross_pay REAL DEFAULT 0,
                    tax_deduction REAL DEFAULT 0,
                    ni_deduction REAL DEFAULT 0,
                    pension_deduction REAL DEFAULT 0,
                    student_loan_deduction REAL DEFAULT 0,
                    other_deductions REAL DEFAULT 0,
                    net_pay REAL DEFAULT 0,
                    payment_status TEXT DEFAULT 'pending',
                    payment_reference TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP, "employer_pension" REAL DEFAULT 0, "pension_scheme" TEXT, "fte" REAL, "days_paid" INTEGER, "period_days" INTEGER, "unpaid_leave_days" REAL DEFAULT 0, "salary_source" TEXT, "notice_sent_at" TEXT,
                    FOREIGN KEY (period_id) REFERENCES payroll_periods(period_id)
                );
CREATE TABLE peep_buddies (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        peep_id INTEGER NOT NULL REFERENCES peeps(peep_id),
        name TEXT NOT NULL,
        contact TEXT,
        notes TEXT);
CREATE TABLE peeps (
        peep_id INTEGER PRIMARY KEY AUTOINCREMENT,
        person_type TEXT NOT NULL CHECK (person_type IN ('student', 'staff')),
        person_ref TEXT NOT NULL,
        person_name TEXT,
        locations TEXT NOT NULL DEFAULT '[]',
        assistance_needed TEXT NOT NULL,
        evacuation_method TEXT,
        equipment TEXT,
        refuge_points TEXT,
        alarm_method TEXT,
        other_notes TEXT,
        status TEXT NOT NULL DEFAULT 'draft',
        review_date TEXT,
        manager_username TEXT,
        last_reviewed_by TEXT, last_reviewed_at TEXT,
        reminder_sent_for TEXT,
        created_by TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE peer_matches (
            match_id INTEGER PRIMARY KEY AUTOINCREMENT,
            requester_id TEXT NOT NULL,
            matched_id TEXT,
            requester_anon_id TEXT NOT NULL,
            matched_anon_id TEXT,
            topic TEXT,
            match_type TEXT DEFAULT 'One-on-one',
            status TEXT DEFAULT 'pending',
            matched_date TEXT,
            created_date TEXT NOT NULL
        );
CREATE TABLE peer_messages (
            message_id INTEGER PRIMARY KEY AUTOINCREMENT,
            match_id INTEGER NOT NULL,
            sender_anon_id TEXT NOT NULL,
            message_text TEXT NOT NULL,
            sent_date TEXT NOT NULL,
            FOREIGN KEY (match_id) REFERENCES peer_matches (match_id)
        );
CREATE TABLE peer_observations (
                observation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                observer_id TEXT NOT NULL,
                observer_name TEXT,
                observee_id TEXT NOT NULL,
                observee_name TEXT,
                course_code TEXT,
                course_name TEXT,
                observation_date TEXT,
                observation_type TEXT DEFAULT 'peer',
                class_size INTEGER,
                duration_minutes INTEGER,
                strengths TEXT,
                areas_for_development TEXT,
                action_points TEXT,
                overall_rating INTEGER,
                status TEXT DEFAULT 'draft',
                acknowledged_date TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE "peer_review_assignments" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assignment_id TEXT UNIQUE NOT NULL,
            session_id TEXT NOT NULL,
            reviewer_id TEXT NOT NULL,
            reviewee_id TEXT NOT NULL,
            submission_id INTEGER,
            due_date TIMESTAMP,
            status TEXT DEFAULT 'pending',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "completed_at" TEXT, "assigned_at" TEXT, "assigned_date" TEXT, "feedback" REAL, "rating" TEXT,
            FOREIGN KEY (reviewer_id) REFERENCES students (student_id),
            FOREIGN KEY (reviewee_id) REFERENCES students (student_id),
            FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE
        );
CREATE TABLE peer_review_config (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assignment_id INTEGER NOT NULL UNIQUE,
            reviews_per_student INTEGER NOT NULL DEFAULT 2,
            review_deadline_days INTEGER NOT NULL DEFAULT 7,
            is_anonymous INTEGER NOT NULL DEFAULT 1,
            grading_weight REAL NOT NULL DEFAULT 0,
            created_at TEXT,
            FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE
        );
CREATE TABLE "peer_review_criteria" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            review_id INTEGER NOT NULL,
            criteria_name TEXT NOT NULL,
            score INTEGER NOT NULL,
            comment TEXT, "assignment_id" INTEGER, "criterion_description" TEXT, "criterion_name" TEXT, "max_points" INTEGER DEFAULT 10,
            FOREIGN KEY (review_id) REFERENCES peer_reviews (id) ON DELETE CASCADE
        );
CREATE TABLE "peer_review_criteria_templates" (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    config_id INTEGER NOT NULL,
                    criteria_name TEXT NOT NULL,
                    max_score INTEGER DEFAULT 5,
                    order_index INTEGER NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE peer_review_cycles (
                    cycle_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    cycle_type TEXT DEFAULT 'teaching_materials',
                    department TEXT,
                    start_date TEXT,
                    end_date TEXT,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE peer_review_feedback (
                feedback_id INTEGER PRIMARY KEY AUTOINCREMENT,
                assignment_id INTEGER NOT NULL,
                submission_id INTEGER NOT NULL,
                reviewer_id TEXT NOT NULL,
                overall_rating INTEGER,
                content_quality INTEGER,
                clarity INTEGER,
                alignment_with_outcomes INTEGER,
                engagement_potential INTEGER,
                strengths TEXT,
                improvements TEXT,
                detailed_comments TEXT,
                recommendation TEXT DEFAULT 'approve',
                is_confidential INTEGER DEFAULT 0,
                submitted_date TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (assignment_id) REFERENCES hr_peer_review_assignments(assignment_id),
                FOREIGN KEY (submission_id) REFERENCES peer_review_submissions(submission_id)
            );
CREATE TABLE peer_review_resource_ratings (
                    rating_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    resource_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    rating INTEGER NOT NULL,
                    comment TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (resource_id) REFERENCES peer_review_shared_resources(resource_id),
                    UNIQUE(resource_id, user_id)
                );
CREATE TABLE peer_review_shared_resources (
                    resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    description TEXT,
                    resource_type TEXT DEFAULT 'template',
                    subject_area TEXT,
                    course_code TEXT,
                    file_path TEXT,
                    file_name TEXT,
                    shared_by TEXT NOT NULL,
                    download_count INTEGER DEFAULT 0,
                    rating_sum INTEGER DEFAULT 0,
                    rating_count INTEGER DEFAULT 0,
                    is_approved INTEGER DEFAULT 0,
                    status TEXT DEFAULT 'active',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE peer_review_submissions (
                    submission_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    cycle_id INTEGER NOT NULL,
                    submitter_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    material_type TEXT DEFAULT 'other',
                    course_code TEXT,
                    file_path TEXT,
                    file_name TEXT,
                    version INTEGER DEFAULT 1,
                    parent_submission_id INTEGER,
                    status TEXT DEFAULT 'draft',
                    submitted_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (cycle_id) REFERENCES peer_review_cycles(cycle_id),
                    FOREIGN KEY (parent_submission_id) REFERENCES peer_review_submissions(submission_id)
                );
CREATE TABLE "peer_reviews" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    assignment_id INTEGER NOT NULL,
    reviewer_id TEXT NOT NULL,
    reviewee_id TEXT,
    submission_id INTEGER,
    reviewee_submission_id INTEGER,
    score REAL,
    overall_score REAL,
    feedback TEXT,
    review_text TEXT,
    rubric_scores TEXT,
    is_anonymous INTEGER DEFAULT 1,
    status TEXT DEFAULT 'pending',
    review_date TIMESTAMP,
    submitted_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (assignment_id) REFERENCES assignments (id) ON DELETE CASCADE,
    FOREIGN KEY (reviewer_id) REFERENCES students (student_id),
    FOREIGN KEY (reviewee_id) REFERENCES students (student_id),
    FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE,
    FOREIGN KEY (reviewee_submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE
);
CREATE TABLE peer_support_groups (
            group_id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_name TEXT,
            description TEXT,
            support_type TEXT,
            facilitator_id TEXT,
            max_members INTEGER,
            current_members INTEGER DEFAULT 0,
            meeting_schedule TEXT,
            status TEXT DEFAULT 'active',
            created_date TEXT,
            FOREIGN KEY (facilitator_id) REFERENCES students (student_id)
        );
CREATE TABLE peer_tutoring_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                session_id INTEGER,
                student_id TEXT NOT NULL,
                message TEXT,
                status TEXT DEFAULT 'pending',
                created_at TEXT,
                FOREIGN KEY (session_id) REFERENCES peer_tutoring_sessions (session_id)
            );
CREATE TABLE peer_tutoring_sessions (
                session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                tutor_id TEXT NOT NULL,
                subject TEXT,
                description TEXT,
                availability TEXT,
                rate TEXT DEFAULT 'Free',
                status TEXT DEFAULT 'available',
                created_at TEXT
            );
CREATE TABLE pension_memberships (
        membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        scheme_code TEXT NOT NULL REFERENCES pension_schemes (scheme_code),
        joined_on TEXT NOT NULL,
        opted_out_on TEXT,
        opt_out_reason TEXT,
        created_by TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT
    );
CREATE TABLE pension_scheme_tiers (
        scheme_code TEXT NOT NULL REFERENCES pension_schemes (scheme_code) ON DELETE CASCADE,
        lower_limit REAL NOT NULL,
        upper_limit REAL,
        employee_rate_pct REAL NOT NULL,
        PRIMARY KEY (scheme_code, lower_limit)
    );
CREATE TABLE pension_schemes (
        scheme_code TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        employee_rate_pct REAL NOT NULL DEFAULT 0,
        employer_rate_pct REAL NOT NULL DEFAULT 0,
        tiered INTEGER NOT NULL DEFAULT 0,
        tier_basis TEXT NOT NULL DEFAULT 'actual' CHECK (tier_basis IN ('actual', 'fte')),
        is_active INTEGER NOT NULL DEFAULT 1,
        updated_by TEXT,
        updated_at TEXT
    );
CREATE TABLE performance_trends (
            trend_id INTEGER PRIMARY KEY AUTOINCREMENT,
            metric_name TEXT NOT NULL,
            metric_category TEXT NOT NULL,
            time_period TEXT NOT NULL,
            value REAL NOT NULL,
            change_from_previous REAL,
            trend_direction TEXT,
            recorded_date TEXT DEFAULT CURRENT_DATE
        );
CREATE TABLE "permission_changes_log" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                changed_by INTEGER NOT NULL,
                target_user_id INTEGER NOT NULL,
                permission_name TEXT NOT NULL,
                action TEXT NOT NULL,
                reason TEXT,
                changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "change_reason" TEXT, "new_permissions" TEXT, "old_permissions" TEXT, "user_id" INTEGER,
                FOREIGN KEY (changed_by) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE permissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            permission_name TEXT UNIQUE NOT NULL,
            description TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
CREATE TABLE personal_health_metrics (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL REFERENCES students (student_id),
        metric TEXT NOT NULL,
        value REAL NOT NULL,
        value2 REAL,
        unit TEXT,
        notes TEXT,
        recorded_on TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE pgr_approvals (
    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    approval_type TEXT NOT NULL,
    reference TEXT,
    risk_level TEXT,
    status TEXT NOT NULL DEFAULT 'required',
    submitted_at TEXT,
    approved_at TEXT,
    expires_at TEXT,
    conditions TEXT,
    approved_by TEXT,
    UNIQUE(project_id, approval_type, reference),
    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)
);
CREATE TABLE pgr_corrections (
    correction_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    correction_type TEXT NOT NULL,
    description TEXT NOT NULL,
    due_date TEXT NOT NULL,
    submitted_at TEXT,
    approved_at TEXT,
    approved_by TEXT,
    status TEXT NOT NULL DEFAULT 'outstanding',
    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)
);
CREATE TABLE pgr_examiners (
    nomination_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    examiner_id TEXT NOT NULL,
    examiner_type TEXT NOT NULL,
    institution TEXT,
    expertise TEXT,
    conflict_declaration TEXT NOT NULL,
    nominated_by TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'nominated',
    approved_by TEXT,
    approved_at TEXT,
    UNIQUE(project_id, examiner_id),
    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)
);
CREATE TABLE pgr_final_deposits (
    deposit_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL UNIQUE,
    repository_reference TEXT NOT NULL,
    deposited_at TEXT NOT NULL,
    embargo_until TEXT,
    licence TEXT NOT NULL,
    checked_by TEXT NOT NULL,
    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)
);
CREATE TABLE pgr_history (
    history_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    action TEXT NOT NULL,
    from_status TEXT,
    to_status TEXT,
    actor_id TEXT NOT NULL,
    reason TEXT,
    metadata_json TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)
);
CREATE TABLE pgr_milestones (
    milestone_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    milestone_type TEXT NOT NULL,
    title TEXT NOT NULL,
    due_date TEXT NOT NULL,
    completed_at TEXT,
    status TEXT NOT NULL DEFAULT 'pending',
    extension_until TEXT,
    extension_reason TEXT,
    extension_approved_by TEXT,
    UNIQUE(project_id, milestone_type, title),
    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)
);
CREATE TABLE pgr_overdue_escalations (
            escalation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER NOT NULL, source_type TEXT NOT NULL,
            source_id INTEGER NOT NULL, due_date TEXT NOT NULL,
            severity TEXT NOT NULL, owner TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open',
            escalated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(source_type, source_id, status)
        );
CREATE TABLE pgr_progress_reviews (
    review_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    review_year INTEGER NOT NULL,
    due_date TEXT NOT NULL,
    submitted_at TEXT,
    panel_json TEXT,
    student_report TEXT,
    supervisor_report TEXT,
    outcome TEXT,
    conditions TEXT,
    approved_at TEXT,
    approved_by TEXT,
    status TEXT NOT NULL DEFAULT 'due',
    UNIQUE(project_id, review_year),
    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)
);
CREATE TABLE pgr_projects (
    project_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    proposal_title TEXT NOT NULL,
    abstract TEXT NOT NULL,
    research_questions TEXT,
    methodology TEXT,
    department TEXT,
    route TEXT NOT NULL DEFAULT 'MPhil/PhD',
    status TEXT NOT NULL DEFAULT 'proposal',
    start_date TEXT,
    expected_end_date TEXT,
    current_deadline TEXT,
    legacy_thesis_id INTEGER,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(student_id, proposal_title)
);
CREATE TABLE pgr_supervision_meetings (
    meeting_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    meeting_at TEXT NOT NULL,
    attendees_json TEXT NOT NULL,
    progress_summary TEXT NOT NULL,
    actions_json TEXT NOT NULL,
