                    employer_feedback TEXT,
                    student_feedback TEXT,
                    supervisor_feedback TEXT,
                    actions TEXT,
                    next_review_date TEXT,
                    employer_signed INTEGER DEFAULT 0,
                    student_signed INTEGER DEFAULT 0,
                    supervisor_signed INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT (datetime('now')),
                    updated_at TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (placement_id) REFERENCES internship_placements (placement_id)
                );
CREATE TABLE plagiarism_matches (
        match_id INTEGER PRIMARY KEY AUTOINCREMENT,
        result_id INTEGER NOT NULL REFERENCES plagiarism_results (id) ON DELETE CASCADE,
        matched_document_id INTEGER REFERENCES document_repository (id) ON DELETE SET NULL,
        score REAL NOT NULL,
        matched_words INTEGER NOT NULL DEFAULT 0,
        passages TEXT NOT NULL DEFAULT '[]'
    , "match_kind" TEXT DEFAULT 'exact', "counted" INTEGER DEFAULT 1);
CREATE TABLE plagiarism_results (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    document_id INTEGER NOT NULL,
                    matched_document_id INTEGER,
                    similarity_score REAL NOT NULL CHECK(similarity_score >= 0 AND similarity_score <= 1),
                    check_date TEXT NOT NULL,
                    checked_by INTEGER,
                    status TEXT NOT NULL,
                    report TEXT,
                    threshold_used REAL DEFAULT 0.3,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "submission_id" INTEGER, "assignment_id" INTEGER, "words_checked" INTEGER, "words_excluded" INTEGER, "review_status" TEXT DEFAULT 'not_needed', "reviewed_by" TEXT, "reviewed_at" TEXT, "review_note" TEXT, "case_id" INTEGER, "released_to_student" INTEGER DEFAULT 0, "paraphrase_score" REAL, "obfuscated_chars" INTEGER DEFAULT 0, "external_checked_at" TEXT,
                    FOREIGN KEY (document_id) REFERENCES document_repository (id) ON DELETE CASCADE,
                    FOREIGN KEY (matched_document_id) REFERENCES document_repository (id) ON DELETE SET NULL,
                    FOREIGN KEY (checked_by) REFERENCES users (id) ON DELETE SET NULL
                );
CREATE TABLE plan_schedule_conflicts (
                    conflict_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    plan_id INTEGER NOT NULL,
                    conflict_type TEXT NOT NULL,
                    severity TEXT NOT NULL,
                    description TEXT NOT NULL,
                    affected_courses_json TEXT,
                    affected_semester INTEGER,
                    resolution_suggestions_json TEXT,
                    is_resolved BOOLEAN DEFAULT 0,
                    detected_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (plan_id) REFERENCES semester_plans(plan_id) ON DELETE CASCADE
                );
CREATE TABLE planned_courses (
                        planned_course_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        plan_id INTEGER NOT NULL,
                        course_id TEXT NOT NULL,
                        semester_number INTEGER NOT NULL,
                        semester_name TEXT NOT NULL,
                        is_locked BOOLEAN DEFAULT 0,
                        priority INTEGER DEFAULT 0,
                        notes TEXT,
                        added_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (plan_id) REFERENCES semester_plans(plan_id) ON DELETE CASCADE,
                        UNIQUE(plan_id, course_id)
                    );
CREATE TABLE points_of_interest (
                    poi_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    building_id INTEGER,
                    poi_name TEXT NOT NULL,
                    poi_type TEXT NOT NULL,
                    floor_number INTEGER,
                    room_number TEXT,
                    description TEXT,
                    latitude REAL,
                    longitude REAL,
                    is_accessible BOOLEAN DEFAULT 1,
                    operating_hours TEXT,
                    contact_info TEXT,
                    tags TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (building_id) REFERENCES campus_buildings(building_id) ON DELETE CASCADE
                );
CREATE TABLE police_case_counter (
