                    status TEXT DEFAULT 'pending',
                    comments TEXT,
                    reviewed_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_id) REFERENCES programmes(programme_id)
                );
CREATE TABLE programme_business_cases (
    business_case_id INTEGER PRIMARY KEY AUTOINCREMENT,
    proposal_id INTEGER NOT NULL UNIQUE,
    forecast_students_json TEXT NOT NULL,
    income_json TEXT NOT NULL,
    costs_json TEXT NOT NULL,
    staffing_plan TEXT,
    facilities_plan TEXT,
    risk_register TEXT,
    approved INTEGER NOT NULL DEFAULT 0,
    approved_by TEXT,
    approved_at TEXT,
    FOREIGN KEY (proposal_id) REFERENCES programme_proposals(proposal_id)
);
CREATE TABLE programme_credit_rules (
        course_code TEXT NOT NULL,
        year_of_study INTEGER NOT NULL CHECK (year_of_study BETWEEN 0 AND 7),
        target_credits INTEGER NOT NULL DEFAULT 120 CHECK (target_credits > 0),
        max_credits INTEGER NOT NULL DEFAULT 140,
        min_optional INTEGER NOT NULL DEFAULT 0,
        max_optional INTEGER,
        needs_approval INTEGER NOT NULL DEFAULT 1,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (course_code, year_of_study),
        CHECK (max_credits >= target_credits)
    );
CREATE TABLE programme_governance_history (
    history_id INTEGER PRIMARY KEY AUTOINCREMENT,
    programme_id INTEGER NOT NULL,
    version_id INTEGER,
    action TEXT NOT NULL,
    actor_id TEXT NOT NULL,
    reason TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
