                    module_code TEXT NOT NULL,
                    module_name TEXT,
                    year_of_study INTEGER NOT NULL DEFAULT 1,
                    semester INTEGER NOT NULL DEFAULT 1,
                    is_core INTEGER DEFAULT 1,
                    credits INTEGER DEFAULT 20,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_id) REFERENCES programmes(programme_id)
                );
CREATE TABLE programme_proposals (
    proposal_id INTEGER PRIMARY KEY AUTOINCREMENT,
    programme_id INTEGER NOT NULL,
    rationale TEXT NOT NULL,
    market_need TEXT,
    strategic_alignment TEXT,
    proposed_start_year TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'draft',
    submitted_at TEXT,
    submitted_by TEXT,
    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id)
);
CREATE TABLE programme_registrations (
            registration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            programme_code TEXT NOT NULL,
            regulation_version_id INTEGER,
            academic_year TEXT NOT NULL,
            occurrence_code TEXT NOT NULL DEFAULT 'MAIN',
            mode_of_study TEXT NOT NULL DEFAULT 'full-time',
            status TEXT NOT NULL DEFAULT 'registration_pending',
            effective_from TEXT NOT NULL,
            effective_to TEXT,
            registered_at TEXT,
            registered_by TEXT,
            source_application_id INTEGER,
            version INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (student_id, programme_code, academic_year, occurrence_code),
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (source_application_id)
                REFERENCES admission_applications(application_id)
        );
CREATE TABLE programme_teach_out_plans (
    plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
    programme_id INTEGER NOT NULL,
    version_id INTEGER,
    last_intake_year TEXT NOT NULL,
    final_delivery_year TEXT NOT NULL,
    student_communication TEXT NOT NULL,
    staffing_commitment TEXT NOT NULL,
    module_availability_json TEXT NOT NULL,
    approved_by TEXT NOT NULL,
    approved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status TEXT NOT NULL DEFAULT 'active',
    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id)
);
CREATE TABLE programme_validations (
    validation_id INTEGER PRIMARY KEY AUTOINCREMENT,
    version_id INTEGER NOT NULL,
    committee_id INTEGER NOT NULL,
    meeting_at TEXT NOT NULL,
    members_json TEXT NOT NULL,
    external_advisers_json TEXT NOT NULL DEFAULT '[]',
    conditions_json TEXT NOT NULL DEFAULT '[]',
    outcome TEXT NOT NULL,
    minutes_reference TEXT NOT NULL,
    chair_id TEXT NOT NULL,
    decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (version_id) REFERENCES programme_versions(version_id),
    FOREIGN KEY (committee_id) REFERENCES approval_committees(committee_id)
);
CREATE TABLE programme_versions (
    version_id INTEGER PRIMARY KEY AUTOINCREMENT,
    programme_id INTEGER NOT NULL,
    version_number INTEGER NOT NULL,
    effective_academic_year TEXT NOT NULL,
    end_academic_year TEXT,
    status TEXT NOT NULL DEFAULT 'draft',
    curriculum_json TEXT NOT NULL,
    regulations_json TEXT NOT NULL,
    snapshot_hash TEXT,
    validation_outcome TEXT,
    approved_at TEXT,
    approved_by TEXT,
    supersedes_version_id INTEGER,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(programme_id, version_number),
    UNIQUE(programme_id, effective_academic_year),
    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id)
);
CREATE TABLE programmes (
                    programme_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    code TEXT NOT NULL UNIQUE,
                    name TEXT NOT NULL,
                    level TEXT NOT NULL DEFAULT 'undergraduate',
                    department TEXT,
                    total_credits INTEGER DEFAULT 360,
                    duration_years INTEGER DEFAULT 3,
                    description TEXT,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    approved_by TEXT,
                    approved_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE progress_snapshots (
                    snapshot_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    semester TEXT NOT NULL,
                    overall_gpa REAL DEFAULT 0.0,
                    semester_gpa REAL DEFAULT 0.0,
                    total_credits INTEGER DEFAULT 0,
                    credits_this_semester INTEGER DEFAULT 0,
                    degree_completion_percentage REAL DEFAULT 0.0,
                    class_standing TEXT,
                    academic_status TEXT DEFAULT 'Good Standing',
                    warnings_count INTEGER DEFAULT 0,
                    snapshot_date TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE project_milestones (
                    id TEXT PRIMARY KEY,
                    project_name TEXT NOT NULL,
                    milestone_name TEXT NOT NULL,
                    due_date TEXT NOT NULL,
                    completion_percentage REAL DEFAULT 0.0,
                    status TEXT DEFAULT 'pending',
                    course_id TEXT,
                    student_id TEXT,
                    description TEXT,
                    created_at TEXT NOT NULL, last_updated TEXT,
                    FOREIGN KEY (course_id) REFERENCES courses (id),
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE promo_codes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            code TEXT UNIQUE NOT NULL,
            discount_type TEXT NOT NULL,
            discount_value REAL NOT NULL,
            min_purchase REAL DEFAULT 0,
            max_uses INTEGER DEFAULT NULL,
            times_used INTEGER DEFAULT 0,
            valid_from TEXT,
            valid_until TEXT,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE prospect_interactions (
            interaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            prospect_id INTEGER NOT NULL,
            interaction_type TEXT NOT NULL,
            interaction_date TEXT DEFAULT CURRENT_TIMESTAMP,
            notes TEXT,
            next_followup_date TEXT,
            staff_member TEXT,
            FOREIGN KEY (prospect_id) REFERENCES admission_prospects (prospect_id)
        );
CREATE TABLE provider_schedule_templates (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL UNIQUE,
        pattern_json TEXT NOT NULL,
        max_appointments INTEGER NOT NULL DEFAULT 8,
        specialty TEXT,
        location TEXT,
        active INTEGER NOT NULL DEFAULT 1,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE provider_schedules (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    provider_name TEXT,
                    day_of_week INTEGER,
                    start_time TEXT,
                    end_time TEXT,
                    max_appointments INTEGER DEFAULT 10,
                    specialty TEXT,
                    location TEXT,
                    active INTEGER DEFAULT 1,
                    created_at TEXT
                );
CREATE TABLE provider_time_off (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        provider_name TEXT NOT NULL,
        start_date TEXT NOT NULL,
        end_date TEXT NOT NULL,
        start_time TEXT,
        end_time TEXT,
        reason TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE "public_profiles" (
                            profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                            student_id TEXT NOT NULL UNIQUE,
                            public_url TEXT NOT NULL UNIQUE,
                            visibility TEXT DEFAULT 'private' CHECK(visibility IN (
                                'public', 'private', 'unlisted'
                            )),
                            show_contact BOOLEAN DEFAULT 0,
                            show_gpa BOOLEAN DEFAULT 0,
                            show_courses BOOLEAN DEFAULT 1,
                            show_projects BOOLEAN DEFAULT 1,
                            show_skills BOOLEAN DEFAULT 1,
                            show_endorsements BOOLEAN DEFAULT 1,
                            custom_sections TEXT,
                            theme TEXT DEFAULT 'professional',
                            view_count INTEGER DEFAULT 0,
                            last_viewed TIMESTAMP,
                            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                        );
CREATE TABLE purchase_orders (
                    order_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    order_date TEXT,
                    total_amount REAL,
                    status TEXT DEFAULT 'pending',
                    vendor TEXT,
                    description TEXT,
                    department TEXT,
                    approved_by TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                , "actual_delivery" DATE, "expected_delivery" DATE, "notes" TEXT, "ordered_by" TEXT, "po_id" INTEGER, "po_number" TEXT, "received_by" TEXT, "shipping_cost" DECIMAL(10,2) DEFAULT 0, "supplier_id" INTEGER, "tax_amount" DECIMAL(10,2) DEFAULT 0, "updated_at" DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE push_delivery_log (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        subscription_id INTEGER,
                        user_id TEXT NOT NULL,
                        title TEXT NOT NULL,
                        message TEXT NOT NULL,
                        status TEXT DEFAULT 'pending',
                        error_message TEXT,
                        sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        delivered_at TIMESTAMP,
                        FOREIGN KEY (subscription_id) REFERENCES push_subscriptions(id)
                    );
CREATE TABLE push_subscriptions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id TEXT NOT NULL,
                        endpoint TEXT NOT NULL UNIQUE,
                        p256dh_key TEXT NOT NULL,
                        auth_key TEXT NOT NULL,
                        user_agent TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        last_used TIMESTAMP,
                        is_active INTEGER DEFAULT 1
                    );
CREATE TABLE qa_answers (
                    answer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    question_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    anonymous_id TEXT NOT NULL,
                    answer_text TEXT NOT NULL,
                    upvotes INTEGER DEFAULT 0,
                    downvotes INTEGER DEFAULT 0,
                    is_accepted BOOLEAN DEFAULT 0,
                    is_instructor_answer BOOLEAN DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (question_id) REFERENCES qa_board(question_id) ON DELETE CASCADE
                );
CREATE TABLE qa_board (
                    question_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    course_id TEXT NOT NULL,
                    student_id TEXT NOT NULL,
                    anonymous_id TEXT NOT NULL,
                    question_title TEXT NOT NULL,
                    question_text TEXT NOT NULL,
                    category TEXT DEFAULT 'General',
                    difficulty_level TEXT DEFAULT 'Medium',
                    upvotes INTEGER DEFAULT 0,
                    downvotes INTEGER DEFAULT 0,
                    view_count INTEGER DEFAULT 0,
                    is_answered BOOLEAN DEFAULT 0,
                    is_resolved BOOLEAN DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE qa_hesa_links (
        qa_submission_id INTEGER NOT NULL,
        hesa_return_id INTEGER NOT NULL,
        linked_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (qa_submission_id, hesa_return_id)
    );
CREATE TABLE qa_submissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            framework TEXT NOT NULL,
            submission_year INTEGER NOT NULL,
            submission_date TEXT,
            status TEXT NOT NULL DEFAULT 'draft',
            assigned_to INTEGER,
            notes TEXT,
            signed_off_by INTEGER,
            signed_off_at TEXT,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            updated_at TEXT NOT NULL DEFAULT (datetime('now')), system_key TEXT NOT NULL DEFAULT 'university',
            UNIQUE (framework, submission_year)
        );
CREATE TABLE qa_votes (
                    vote_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    target_type TEXT NOT NULL,
                    target_id INTEGER NOT NULL,
                    vote_type TEXT NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(student_id, target_type, target_id)
                );
CREATE TABLE qr_codes (
                        qr_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        table_number TEXT,
                        qr_data TEXT,
                        generated_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                        image_path TEXT
                    , "is_branded" BOOLEAN DEFAULT 0, "is_active" BOOLEAN DEFAULT 1, "version" INTEGER DEFAULT 1);
CREATE TABLE qr_scans (
                scan_id INTEGER PRIMARY KEY AUTOINCREMENT,
                table_number TEXT,
                scan_time DATETIME DEFAULT CURRENT_TIMESTAMP,
                customer_id INTEGER,
                device_type TEXT
            );
CREATE TABLE quality_metrics (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    metric_name TEXT,
                    metric_category TEXT,
                    target_value REAL,
                    actual_value REAL,
                    measurement_period TEXT,
                    measured_date TEXT,
                    status TEXT,
                    improvement_needed INTEGER DEFAULT 0,
                    created_at TEXT
                );
CREATE TABLE "question_banks" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            module_code TEXT,
            description TEXT,
            created_by INTEGER,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (module_code) REFERENCES modules (module_code),
            FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE questions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            bank_id INTEGER NOT NULL,
            question_type TEXT NOT NULL CHECK (question_type IN ('mcq', 'fill_blank', 'coding')),
            question_text TEXT NOT NULL,
            options_json TEXT,
            correct_answer TEXT,
            points REAL DEFAULT 1.0,
            difficulty TEXT DEFAULT 'medium' CHECK (difficulty IN ('easy', 'medium', 'hard')),
            topic TEXT,
            time_limit_seconds INTEGER,
            test_cases_json TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP, "options" TEXT,
            FOREIGN KEY (bank_id) REFERENCES question_banks (id) ON DELETE CASCADE
        );
CREATE TABLE "ranked_votes" (
                    vote_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    election_id INTEGER,
                    voter_id TEXT,
                    candidate_preferences TEXT,
                    vote_time TEXT,
                    FOREIGN KEY (election_id) REFERENCES elections (id),
                    FOREIGN KEY (voter_id) REFERENCES students (student_id)
                );
CREATE TABLE ratified_student_awards (
    award_id INTEGER PRIMARY KEY AUTOINCREMENT,
    board_id INTEGER NOT NULL,
    student_id TEXT NOT NULL,
    programme_code TEXT NOT NULL,
    award_name TEXT NOT NULL,
    classification TEXT,
    academic_year TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'ratified',
    ratified_at TEXT NOT NULL,
    ratified_by TEXT NOT NULL,
    release_authorised INTEGER NOT NULL DEFAULT 1,
    superseded_by_award_id INTEGER,
    UNIQUE(student_id, programme_code, academic_year),
    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)
);
CREATE TABLE reading_goals (
            goal_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            goal_type TEXT NOT NULL,
            target_value INTEGER NOT NULL,
            current_value INTEGER DEFAULT 0,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            status TEXT DEFAULT 'active',
            created_date TEXT NOT NULL
        );
CREATE TABLE reading_list_items (
            item_id INTEGER PRIMARY KEY AUTOINCREMENT,
            list_id INTEGER NOT NULL,
            book_id TEXT NOT NULL,
            added_date TEXT NOT NULL,
            added_by TEXT NOT NULL,
            notes TEXT,
            order_index INTEGER DEFAULT 0
        , "importance" TEXT DEFAULT 'recommended');
CREATE TABLE reading_lists (
            list_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            creator_id TEXT NOT NULL,
            created_date TEXT NOT NULL,
            is_public BOOLEAN DEFAULT FALSE,
            is_collaborative BOOLEAN DEFAULT FALSE,
            category TEXT,
            target_reading_level TEXT
        , "module_code" TEXT);
CREATE TABLE realtime_notifications (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    type TEXT NOT NULL,
                    recipient_id INTEGER,
                    title TEXT NOT NULL,
                    message TEXT,
                    data TEXT,
                    priority INTEGER DEFAULT 2,
                    created_at TEXT NOT NULL,
                    read_at TEXT,
                    expires_at TEXT
                , "user_id" INTEGER, "notification_type" TEXT DEFAULT 'info', "is_read" INTEGER DEFAULT 0, "action_url" TEXT);
CREATE TABLE recommended_interventions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            risk_factor_id INTEGER,
            intervention_type_id INTEGER,
            recommended_date TEXT,
            status TEXT DEFAULT 'pending', "notes" TEXT, "priority" INTEGER, "risk_assessment_id" INTEGER,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (risk_factor_id) REFERENCES risk_factors (id),
            FOREIGN KEY (intervention_type_id) REFERENCES intervention_types (id)
        );
CREATE TABLE recruitment_campaigns (
            campaign_id INTEGER PRIMARY KEY AUTOINCREMENT,
            campaign_name TEXT NOT NULL,
            campaign_type TEXT NOT NULL,
            target_audience TEXT,
            start_date TEXT,
            end_date TEXT,
            status TEXT DEFAULT 'draft',
            message_template TEXT,
            sent_count INTEGER DEFAULT 0,
            opened_count INTEGER DEFAULT 0,
            clicked_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE recurring_event_series (
                series_id INTEGER PRIMARY KEY AUTOINCREMENT,
                series_name TEXT NOT NULL,
                pattern TEXT NOT NULL,
                day_of_week TEXT,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                start_time TEXT NOT NULL,
                duration_hours REAL,
                location TEXT,
                description TEXT,
                created_by TEXT,
                created_date TEXT,
                status TEXT DEFAULT 'active'
            );
CREATE TABLE "recurring_events" (
                    id TEXT PRIMARY KEY,
                    base_event_id TEXT NOT NULL,
                    frequency TEXT NOT NULL,
                    interval_count INTEGER DEFAULT 1,
                    days_of_week TEXT,
                    day_of_month INTEGER,
                    month_of_year INTEGER,
                    end_date TEXT,
                    occurrence_count INTEGER,
                    timezone TEXT DEFAULT 'UTC',
                    exceptions TEXT,
                    date_added TEXT NOT NULL, "max_occurrences" INTEGER, "parent_event_id" INTEGER, "recurrence_interval" INTEGER, "recurrence_type" TEXT, "status" TEXT DEFAULT 'active', "current_occurrences" INTEGER DEFAULT 0,
                    FOREIGN KEY (base_event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE
                );
CREATE TABLE ref_environment_statements (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            uoa TEXT NOT NULL,
            narrative_text TEXT NOT NULL,
            version INTEGER NOT NULL DEFAULT 1,
            drafted_by INTEGER,
            created_at TEXT NOT NULL DEFAULT (datetime('now')), "drafted_by_username" TEXT,
            UNIQUE (uoa, version)
        );
CREATE TABLE ref_impact_cases (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            uoa TEXT NOT NULL,
            title TEXT NOT NULL,
            summary TEXT,
            lead_author_id INTEGER,
            status TEXT NOT NULL DEFAULT 'draft',
            reach_significance TEXT,
            beneficiaries TEXT,
            evidence_links TEXT,
            quality_rating TEXT,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            updated_at TEXT NOT NULL DEFAULT (datetime('now'))
        , "lead_username" TEXT);
CREATE TABLE ref_staff_uoa (
        username TEXT NOT NULL PRIMARY KEY,
        uoa TEXT NOT NULL,
        fte REAL NOT NULL DEFAULT 1 CHECK (fte > 0 AND fte <= 1),
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE referrals (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    referring_provider TEXT,
                    specialist_provider TEXT,
                    specialty TEXT,
                    reason TEXT,
                    urgency TEXT,
                    referral_date TEXT,
                    appointment_date TEXT,
                    status TEXT DEFAULT 'pending',
                    notes TEXT,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE regional_chapters (
            chapter_id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter_name TEXT,
            location TEXT,
            coordinator_id TEXT,
            description TEXT,
            created_date TEXT,
            member_count INTEGER DEFAULT 0, coordinator_name TEXT, contact_email TEXT, created_by TEXT, status TEXT DEFAULT 'active',
            FOREIGN KEY (coordinator_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE registration_periods (
        period_id           INTEGER PRIMARY KEY AUTOINCREMENT,
        term_id             INTEGER,
        academic_year       TEXT NOT NULL DEFAULT '',
        name                TEXT NOT NULL DEFAULT '',
        registration_opens  TEXT NOT NULL,
        registration_closes TEXT NOT NULL,
        add_deadline        TEXT,
        drop_deadline       TEXT,
        withdraw_deadline   TEXT,
        late_add_allowed    INTEGER NOT NULL DEFAULT 0,
        is_active           INTEGER NOT NULL DEFAULT 1,
        notes               TEXT,
        created_at          TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at          TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE reimbursements (
                    reimbursement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    claim_id INTEGER NOT NULL,
                    amount REAL NOT NULL,
                    currency TEXT DEFAULT 'GBP',
                    payment_date TEXT,
                    payment_method TEXT,
                    reference_number TEXT,
                    bank_account_last4 TEXT,
                    status TEXT DEFAULT 'pending',
                    processed_by TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (claim_id) REFERENCES expense_claims(claim_id)
                );
CREATE TABLE remember_me_tokens (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    token_hash TEXT UNIQUE NOT NULL,
                    user_id INTEGER NOT NULL,
                    device_fingerprint TEXT NOT NULL,
                    created_at TIMESTAMP NOT NULL,
                    expires_at TIMESTAMP NOT NULL,
                    last_used TIMESTAMP,
                    use_count INTEGER DEFAULT 0,
                    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
                );
CREATE TABLE renewal_requirements (
    requirement_id INTEGER PRIMARY KEY AUTOINCREMENT,
    award_id INTEGER NOT NULL,
    academic_year TEXT NOT NULL,
    gpa_required REAL,
    credit_hours_required INTEGER,
    enrollment_status_required TEXT,  -- full_time, half_time
    service_hours_required INTEGER,
    other_requirements TEXT,
    verification_deadline DATE,
    is_met BOOLEAN,
    verified_by INTEGER,
    verified_date TIMESTAMP,
    notes TEXT, "description" TEXT, "min_credits" INTEGER, "min_gpa" REAL, "requirement_type" TEXT, "scholarship_id" INTEGER,
    FOREIGN KEY (award_id) REFERENCES scholarship_awards(award_id) ON DELETE CASCADE
);
CREATE TABLE report_history (
                        history_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        report_id INTEGER,
                        report_type TEXT NOT NULL,
                        generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        generated_by TEXT,
                        file_path TEXT,
                        file_size INTEGER,
                        recipients_json TEXT,
                        status TEXT DEFAULT 'success',
                        error_message TEXT,
                        FOREIGN KEY (report_id) REFERENCES scheduled_reports(report_id)
                    );
CREATE TABLE requirement_completion (
                completion_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                requirement_id INTEGER NOT NULL,
                is_completed INTEGER DEFAULT 0,
                credits_earned INTEGER DEFAULT 0,
                completed_date TEXT, "credits_completed" REAL DEFAULT 0,
                FOREIGN KEY (requirement_id) REFERENCES degree_requirements(requirement_id) ON DELETE CASCADE
            );
CREATE TABLE requirement_courses (
                req_course_id INTEGER PRIMARY KEY AUTOINCREMENT,
                requirement_id INTEGER NOT NULL,
                module_code TEXT NOT NULL,
                is_alternative INTEGER DEFAULT 0,
                alternative_group INTEGER,
                FOREIGN KEY (requirement_id) REFERENCES degree_requirements(requirement_id) ON DELETE CASCADE
            );
CREATE TABLE research_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        entity TEXT NOT NULL,
        entity_id TEXT NOT NULL,
        action TEXT NOT NULL,
        actor TEXT,
        detail TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE research_data_plans (
        plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_id INTEGER NOT NULL REFERENCES research_projects(project_id),
        version INTEGER NOT NULL DEFAULT 1,
        status TEXT NOT NULL DEFAULT 'draft'
            CHECK (status IN ('draft', 'submitted', 'approved', 'changes_requested',
                              'superseded')),
        data_types TEXT,
        storage TEXT,
        sharing TEXT,
        repository TEXT,
        retention_years INTEGER,
        personal_data INTEGER NOT NULL DEFAULT 0,
        dpia_reference TEXT,
        author TEXT,
        submitted_at TEXT,
        reviewed_by TEXT,
        reviewed_at TEXT,
        review_note TEXT,
        UNIQUE (project_id, version)
    );
CREATE TABLE research_equipment (
            equipment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_name TEXT NOT NULL,
            equipment_type TEXT NOT NULL,
            model_number TEXT,
            serial_number TEXT,
            purchase_date TEXT,
            purchase_cost REAL,
            current_location TEXT,
            assigned_project_id INTEGER,
            maintenance_schedule TEXT,
            last_maintenance_date TEXT,
            status TEXT DEFAULT 'available',
            FOREIGN KEY (assigned_project_id) REFERENCES research_projects (project_id)
        );
CREATE TABLE research_ethics_applications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                reference TEXT UNIQUE NOT NULL,
                title TEXT NOT NULL,
                principal_investigator_id INTEGER,
                department TEXT,
                risk_level TEXT,              -- 'Low', 'Medium', 'High'
                category TEXT,                -- 'Human participants', 'Animal', 'Data-only', etc.
                submitted_date TEXT,
                decision_date TEXT,
                status TEXT NOT NULL,         -- 'Draft','Submitted','Under Review','Approved','Rejected','Revisions Required','Expired'
                approval_expiry TEXT,
                notes TEXT,
                FOREIGN KEY (principal_investigator_id) REFERENCES research_people(id)
            );
CREATE TABLE research_interest_declarations (
        declaration_id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN ('none', 'financial', 'shareholding', 'consultancy',
            'directorship', 'gift', 'personal', 'other')),
        counterpart TEXT,
        description TEXT,
        value REAL,
        project_id INTEGER REFERENCES research_projects(project_id),
        declared_at TEXT NOT NULL DEFAULT (datetime('now')),
        status TEXT NOT NULL DEFAULT 'declared'
            CHECK (status IN ('declared', 'no_action', 'managed', 'closed')),
        management_plan TEXT,
        reviewed_by TEXT,
        reviewed_at TEXT
    );
CREATE TABLE research_ip_assets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                reference TEXT UNIQUE NOT NULL,
                title TEXT NOT NULL,
                ip_type TEXT NOT NULL,        -- 'Patent','Copyright','Trademark','Know-how','Software','Design'
                inventor_id INTEGER,
                disclosure_date TEXT,
                filing_date TEXT,
                grant_date TEXT,
                jurisdiction TEXT,
                status TEXT NOT NULL,         -- 'Disclosed','Evaluating','Filed','Granted','Licensed','Abandoned'
                commercial_route TEXT,        -- 'License','Spin-out','Assignment','None yet'
                licensee TEXT,
                revenue_to_date REAL DEFAULT 0,
                notes TEXT,
                FOREIGN KEY (inventor_id) REFERENCES research_people(id)
            );
CREATE TABLE "research_milestones" (
            milestone_id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER,
            milestone_name TEXT NOT NULL,
            milestone_description TEXT,
            target_date TEXT,
            completion_date TEXT,
            status TEXT DEFAULT 'pending',
            deliverables TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            thesis_id INTEGER,
            notes TEXT,
            FOREIGN KEY (project_id) REFERENCES research_projects (project_id)
        );
CREATE TABLE research_office_roles (
        username TEXT NOT NULL,
        role TEXT NOT NULL CHECK (role IN ('research_office', 'ethics_chair',
            'ethics_reviewer', 'head_of_department', 'ref_lead', 'tto')),
        scope TEXT NOT NULL DEFAULT '',
        granted_by TEXT,
        granted_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (username, role, scope)
    );
CREATE TABLE research_output_authors (
        publication_id INTEGER NOT NULL REFERENCES research_publications(publication_id)
            ON DELETE CASCADE,
        position INTEGER NOT NULL,
        name TEXT NOT NULL,
        username TEXT,
        PRIMARY KEY (publication_id, position)
    );
CREATE TABLE research_output_reviews (
        review_id INTEGER PRIMARY KEY AUTOINCREMENT,
        publication_id INTEGER NOT NULL REFERENCES research_publications(publication_id)
            ON DELETE CASCADE,
        reviewer TEXT NOT NULL,
        score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 4),
        comment TEXT,
        reviewed_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (publication_id, reviewer)
    );
CREATE TABLE research_outputs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                output_type TEXT NOT NULL,    -- 'Journal article','Conference paper','Book','Book chapter','Dataset','Software','Other'
                authors TEXT,                 -- comma separated
                lead_author_id INTEGER,
                venue TEXT,                   -- journal/conference/publisher
                publication_date TEXT,
                doi TEXT,
                uoa TEXT,                     -- Unit of Assessment
                ref_submitted INTEGER DEFAULT 0,  -- boolean 0/1
                open_access INTEGER DEFAULT 0,
                quality_rating TEXT,          -- '1*','2*','3*','4*', or ''
                abstract TEXT,
                FOREIGN KEY (lead_author_id) REFERENCES research_people(id)
            );
CREATE TABLE research_people (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT,
                role TEXT NOT NULL,           -- 'staff', 'student', 'examiner', 'external'
                department TEXT,
                created_at TEXT NOT NULL
            );
CREATE TABLE research_profiles (
                profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT UNIQUE NOT NULL,
                research_interests TEXT,
                h_index INTEGER DEFAULT 0,
                total_citations INTEGER DEFAULT 0,
                total_publications INTEGER DEFAULT 0,
                orcid_id TEXT,
                google_scholar_id TEXT,
                researchgate_url TEXT,
                scopus_id TEXT,
                last_updated TEXT DEFAULT CURRENT_TIMESTAMP,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE research_projects (
            project_id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_title TEXT NOT NULL,
            project_description TEXT,
            principal_investigator_id TEXT NOT NULL,
            department TEXT NOT NULL,
            project_type TEXT NOT NULL,
            start_date TEXT NOT NULL,
            end_date TEXT,
            status TEXT DEFAULT 'active',
            total_budget REAL DEFAULT 0,
            funding_source TEXT,
            ethics_approval_status TEXT DEFAULT 'pending',
            ethics_approval_date TEXT,
            publications_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , "reference" TEXT, "created_by" TEXT, "closed_at" TEXT, "needs_ethics" INTEGER DEFAULT 0);
CREATE TABLE research_publications (
            publication_id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER,
            title TEXT NOT NULL,
            authors TEXT NOT NULL,
            publication_type TEXT NOT NULL,
            journal_name TEXT,
            conference_name TEXT,
            publication_date TEXT,
            doi TEXT,
            url TEXT,
            abstract TEXT,
            keywords TEXT,
            citation_count INTEGER DEFAULT 0,
            is_peer_reviewed BOOLEAN DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP, uoa TEXT, ref_submitted INTEGER DEFAULT 0, open_access INTEGER DEFAULT 0, quality_rating TEXT, lead_author_id TEXT, venue TEXT, "acceptance_date" TEXT, "deposit_date" TEXT, "repository_url" TEXT, "oa_route" TEXT, "oa_exception" TEXT, "issn" TEXT, "created_by" TEXT, "updated_at" TEXT,
            FOREIGN KEY (project_id) REFERENCES research_projects (project_id)
        );
CREATE TABLE research_team_members (
            member_id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_id INTEGER NOT NULL,
            staff_id TEXT NOT NULL,
            role TEXT NOT NULL,
            join_date TEXT DEFAULT CURRENT_DATE,
            leave_date TEXT,
            contribution_percentage REAL,
            is_active BOOLEAN DEFAULT 1,
            FOREIGN KEY (project_id) REFERENCES research_projects (project_id)
        );
CREATE TABLE research_theses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id INTEGER NOT NULL,
                title TEXT NOT NULL,
                degree TEXT NOT NULL,         -- 'PhD','MPhil','MRes','Masters'
                department TEXT,
                primary_supervisor_id INTEGER,
                secondary_supervisor_id INTEGER,
                start_date TEXT,
                expected_submission TEXT,
                submission_date TEXT,
                viva_date TEXT,
                internal_examiner_id INTEGER,
                external_examiner_id INTEGER,
                status TEXT NOT NULL,         -- 'Active','Submitted','Under Examination','Viva Scheduled','Passed','Minor Corrections','Major Corrections','Failed','Withdrawn'
                outcome TEXT,
                FOREIGN KEY (student_id) REFERENCES research_people(id),
                FOREIGN KEY (primary_supervisor_id) REFERENCES research_people(id),
                FOREIGN KEY (secondary_supervisor_id) REFERENCES research_people(id),
                FOREIGN KEY (internal_examiner_id) REFERENCES research_people(id),
                FOREIGN KEY (external_examiner_id) REFERENCES research_people(id)
            );
CREATE TABLE research_thesis_milestones (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                thesis_id INTEGER NOT NULL,
                name TEXT NOT NULL,
                due_date TEXT,
                completed_date TEXT,
                status TEXT NOT NULL,         -- 'Pending','Completed','Overdue','Missed'
                notes TEXT,
                FOREIGN KEY (thesis_id) REFERENCES research_theses(id) ON DELETE CASCADE
            );
CREATE TABLE "resource_bookings" (
                    id TEXT PRIMARY KEY,
                    resource_id TEXT NOT NULL,
                    event_id TEXT,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    status TEXT DEFAULT 'confirmed',
                    notes TEXT,
                    date_added TEXT NOT NULL,
                    FOREIGN KEY (resource_id) REFERENCES resources (id) ON DELETE CASCADE,
                    FOREIGN KEY (event_id) REFERENCES unified_events(source_event_id) ON DELETE CASCADE
                );
CREATE TABLE resources (
                    id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    type TEXT NOT NULL,
                    capacity INTEGER,
                    location TEXT,
                    equipment TEXT,
                    status TEXT DEFAULT 'available',
                    date_added TEXT NOT NULL
                );
CREATE TABLE response_templates (
            template_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            subject TEXT,
            content TEXT NOT NULL,
            category TEXT,
            created_by TEXT NOT NULL,
            created_datetime TEXT NOT NULL,
            is_active BOOLEAN DEFAULT 1,
            usage_count INTEGER DEFAULT 0,
            variables TEXT  -- JSON array of variable names
        );
CREATE TABLE restaurant_audit_logs (
        log_id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        action TEXT NOT NULL,
        table_name TEXT,
        record_id TEXT,
        old_values TEXT,
        new_values TEXT,
        timestamp TEXT NOT NULL,
        ip_address TEXT,
        user_agent TEXT);
CREATE TABLE restaurant_budgets (
            budget_id TEXT PRIMARY KEY,
            category TEXT NOT NULL,
            period_start TEXT NOT NULL,
            period_end TEXT NOT NULL,
            allocated_amount REAL NOT NULL,
            spent_amount REAL DEFAULT 0,
            created_date TEXT,
            created_by TEXT,
            notes TEXT
        );
CREATE TABLE restaurant_customer_segments (
            segment_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            criteria TEXT NOT NULL,
            customer_count INTEGER DEFAULT 0,
            created_date TEXT,
            last_updated TEXT
        );
CREATE TABLE restaurant_customers (
                customer_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT,
                phone TEXT,
                loyalty_tier TEXT DEFAULT 'Bronze',
                loyalty_points INTEGER DEFAULT 0,
                total_spent REAL DEFAULT 0
            , "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP, student_id TEXT, "dietary_restrictions" TEXT, "birthday" TEXT, "address" TEXT, "emergency_contact" TEXT, "last_visit" TEXT, "visit_count" INTEGER DEFAULT 0, "preferences" TEXT, "notes" TEXT);
CREATE TABLE restaurant_food_safety_checks (
            check_id TEXT PRIMARY KEY,
            check_type TEXT NOT NULL,
            check_date TEXT NOT NULL,
            performed_by TEXT NOT NULL,
            results TEXT NOT NULL,
            notes TEXT,
            corrective_actions TEXT,
            follow_up_date TEXT,
            status TEXT DEFAULT 'Completed'
        );
CREATE TABLE restaurant_inventory (
                item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                quantity REAL DEFAULT 0,
                unit TEXT,
                cost_per_unit REAL,
                reorder_level REAL DEFAULT 0
            , "expiry_date" TEXT, "last_updated" TEXT, "max_level" REAL, "supplier_id" INTEGER, "category" TEXT, "batch_number" TEXT, "location" TEXT, "temperature_req" TEXT);
CREATE TABLE restaurant_marketing_campaigns (
            campaign_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            type TEXT NOT NULL,
            target_audience TEXT,
            start_date TEXT,
            end_date TEXT,
            budget REAL DEFAULT 0,
            spent_amount REAL DEFAULT 0,
            impressions INTEGER DEFAULT 0,
            clicks INTEGER DEFAULT 0,
            conversions INTEGER DEFAULT 0,
            status TEXT DEFAULT 'Draft',
            created_by TEXT,
            created_date TEXT
        );
CREATE TABLE restaurant_mobile_orders (
            mobile_order_id TEXT PRIMARY KEY,
            order_id INTEGER NOT NULL,
            app_type TEXT NOT NULL,
            device_info TEXT,
            location_info TEXT,
            pickup_time TEXT,
            notification_sent INTEGER DEFAULT 0,
            FOREIGN KEY (order_id) REFERENCES orders (order_id)
        );
CREATE TABLE restaurant_notifications (
            notification_id TEXT PRIMARY KEY,
            user_id TEXT,
            type TEXT NOT NULL,
            title TEXT NOT NULL,
            message TEXT NOT NULL,
            created_date TEXT NOT NULL,
            read_date TEXT,
            priority TEXT DEFAULT 'Normal',
            category TEXT,
            action_required INTEGER DEFAULT 0
        );
CREATE TABLE restaurant_offer_usage (
            usage_id TEXT PRIMARY KEY,
            offer_id TEXT NOT NULL,
            customer_id INTEGER NOT NULL,
            order_id INTEGER NOT NULL,
            usage_date TEXT,
            discount_amount REAL,
            FOREIGN KEY (offer_id) REFERENCES restaurant_special_offers (offer_id),
            FOREIGN KEY (customer_id) REFERENCES restaurant_customers (customer_id),
            FOREIGN KEY (order_id) REFERENCES orders (order_id)
        );
CREATE TABLE restaurant_orders (
                        order_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        customer_id INTEGER,
                        order_time DATETIME DEFAULT CURRENT_TIMESTAMP,
                        total_price REAL,
                        tax_amount REAL,
                        status TEXT DEFAULT 'Pending',
                        payment_method TEXT
                    , "total_amount" REAL, "created_at" TEXT, "delivery_address" TEXT, "items" TEXT, "special_instructions" TEXT);
CREATE TABLE restaurant_purchase_order_items (
                item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                order_id INTEGER NOT NULL,
                item_name TEXT NOT NULL,
                quantity REAL NOT NULL,
                unit_of_measure TEXT,
                unit_cost REAL NOT NULL,
                total_cost REAL NOT NULL,
                received_quantity REAL DEFAULT 0,
                FOREIGN KEY (order_id) REFERENCES restaurant_purchase_orders(order_id) ON DELETE CASCADE
            );
CREATE TABLE restaurant_purchase_orders (
                order_id INTEGER PRIMARY KEY AUTOINCREMENT,
                po_number TEXT UNIQUE NOT NULL,
                supplier_id INTEGER NOT NULL,
                order_date DATE NOT NULL,
                expected_delivery_date DATE,
                actual_delivery_date DATE,
                total_cost REAL NOT NULL DEFAULT 0,
                tax_amount REAL DEFAULT 0,
                status TEXT DEFAULT 'Pending',
                payment_method TEXT,
                payment_status TEXT DEFAULT 'Unpaid',
                notes TEXT,
                created_by TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP, "total_amount" REAL, "actual_delivery" TEXT,
                FOREIGN KEY (supplier_id) REFERENCES restaurant_suppliers(supplier_id)
            );
CREATE TABLE restaurant_reservations (
                    reservation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    customer_id INTEGER,
                    table_id INTEGER,
                    reservation_date TEXT NOT NULL,
                    reservation_time TEXT NOT NULL,
                    party_size INTEGER NOT NULL,
                    status TEXT DEFAULT 'Confirmed',
                    notes TEXT,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (customer_id) REFERENCES restaurant_customers(customer_id),
                    FOREIGN KEY (table_id) REFERENCES restaurant_tables(table_id)
                );
CREATE TABLE restaurant_schedules (
                    schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    staff_id INTEGER NOT NULL,
                    shift_date TEXT NOT NULL,
                    shift_start TEXT NOT NULL,
                    shift_end TEXT NOT NULL,
                    role TEXT,
                    notes TEXT,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (staff_id) REFERENCES restaurant_staff(staff_id)
                );
CREATE TABLE restaurant_shift_swaps (
                swap_id INTEGER PRIMARY KEY AUTOINCREMENT,
                original_shift_id INTEGER NOT NULL,
                requesting_staff_id INTEGER NOT NULL,
                covering_staff_id INTEGER,
                swap_date DATE NOT NULL,
                status TEXT DEFAULT 'Pending',
                notes TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (original_shift_id) REFERENCES restaurant_shifts(shift_id),
                FOREIGN KEY (requesting_staff_id) REFERENCES restaurant_staff(staff_id),
                FOREIGN KEY (covering_staff_id) REFERENCES restaurant_staff(staff_id)
            );
CREATE TABLE restaurant_shifts (
                shift_id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_id INTEGER NOT NULL,
                shift_date DATE NOT NULL,
                start_time TIME NOT NULL,
                end_time TIME,
                break_minutes INTEGER DEFAULT 0,
                hours_worked REAL,
                hourly_rate REAL,
                total_pay REAL,
                status TEXT DEFAULT 'Scheduled',
                notes TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (staff_id) REFERENCES restaurant_staff(staff_id)
            );
CREATE TABLE restaurant_special_offers (
            offer_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            description TEXT,
            discount_type TEXT DEFAULT 'percentage',
            discount_value REAL NOT NULL,
            min_order_amount REAL DEFAULT 0,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            applicable_items TEXT,
            max_uses INTEGER DEFAULT -1,
            uses_count INTEGER DEFAULT 0,
            applicable_days TEXT,
            applicable_times TEXT,
            customer_type TEXT DEFAULT 'all',
            status TEXT DEFAULT 'Active'
        );
CREATE TABLE restaurant_staff (
                staff_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                role TEXT NOT NULL,
                hourly_rate REAL,
                status TEXT DEFAULT 'Active',
                performance_score REAL
            , "email" TEXT, "phone" TEXT, "hire_date" TEXT, "position" TEXT, "is_active" BOOLEAN DEFAULT 1);
CREATE TABLE restaurant_suppliers (
                supplier_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                contact_person TEXT,
                email TEXT,
                phone TEXT,
                address TEXT,
                payment_terms TEXT,
                notes TEXT,
                is_active BOOLEAN DEFAULT 1,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            , "category" TEXT, "status" TEXT DEFAULT 'Active', "rating" REAL DEFAULT 0, "delivery_schedule" TEXT);
CREATE TABLE restaurant_tables (
                table_id INTEGER PRIMARY KEY AUTOINCREMENT,
                capacity INTEGER NOT NULL,
                status TEXT DEFAULT 'Available',
                location TEXT,
                table_type TEXT DEFAULT 'Standard'
            , "current_order_id" TEXT, "last_cleaned" TEXT);
CREATE TABLE restaurant_temperature_logs (
            log_id TEXT PRIMARY KEY,
            equipment_id TEXT NOT NULL,
            temperature REAL NOT NULL,
            recorded_date TEXT NOT NULL,
            recorded_by TEXT,
            location TEXT,
            notes TEXT,
            alert_triggered INTEGER DEFAULT 0
        );
CREATE TABLE restaurant_user_access (
        access_id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL COLLATE NOCASE UNIQUE,
        staff_id INTEGER REFERENCES restaurant_staff (staff_id) ON DELETE SET NULL,
        staff_name TEXT,
        role TEXT NOT NULL,
        active INTEGER NOT NULL DEFAULT 1,
        granted_by TEXT,
        granted_at TEXT,
        removed_by TEXT,
        removed_at TEXT,
        removed_reason TEXT);
CREATE TABLE restaurant_waste (
                waste_id INTEGER PRIMARY KEY AUTOINCREMENT,
                waste_date DATE NOT NULL,
                item_name TEXT NOT NULL,
                quantity REAL NOT NULL,
                unit_of_measure TEXT,
                cost_value REAL NOT NULL,
                waste_type TEXT,
                reason TEXT NOT NULL,
                responsible_staff TEXT,
                notes TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            , "unit" TEXT);
CREATE TABLE restaurant_waste_categories (
                category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                category_name TEXT UNIQUE NOT NULL,
                description TEXT,
                target_percentage REAL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE resume_templates (
                    template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    template_name TEXT NOT NULL,
                    template_type TEXT CHECK(template_type IN (
                        'traditional', 'modern', 'creative', 'technical', 'academic'
                    )),
                    template_data TEXT NOT NULL,
                    is_default BOOLEAN DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE retention_predictions (
            prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            model_id INTEGER NOT NULL,
            retention_probability REAL NOT NULL,
            risk_level TEXT NOT NULL,
            prediction_date TEXT DEFAULT CURRENT_TIMESTAMP,
            prediction_year INTEGER,
            factors TEXT,
            recommendations TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (model_id) REFERENCES analytics_models (model_id)
        );
CREATE TABLE reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            movie_id INTEGER NOT NULL,
            member_id INTEGER,
            customer_name TEXT,
            rating INTEGER NOT NULL CHECK(rating >= 1 AND rating <= 5),
            review_text TEXT,
            helpful_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'active',
            FOREIGN KEY (movie_id) REFERENCES movies(id),
            FOREIGN KEY (member_id) REFERENCES members(id)
        );
CREATE TABLE revoked_credentials (
    revocation_id INTEGER PRIMARY KEY AUTOINCREMENT,
    credential_id INTEGER,
    badge_issuance_id INTEGER,
    revoked_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    reason TEXT NOT NULL,
    revoked_by INTEGER,
    blockchain_revocation_hash TEXT,
    FOREIGN KEY (credential_id) REFERENCES blockchain_credentials(credential_id),
    FOREIGN KEY (badge_issuance_id) REFERENCES badge_issuances(issuance_id)
);
CREATE TABLE "rideshare_posts" (
                post_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                post_type TEXT NOT NULL,
                departure_location TEXT NOT NULL,
                destination TEXT NOT NULL,
                departure_time TIMESTAMP NOT NULL,
                seats_available INTEGER,
                price_per_seat REAL,
                notes TEXT,
                status TEXT DEFAULT 'active',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE right_to_study_checks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            checked_at TEXT NOT NULL DEFAULT (datetime('now')),
            checked_by INTEGER,
            method TEXT,
            documents_seen TEXT,
            outcome TEXT NOT NULL DEFAULT 'pass',
            notes TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE risk_assessments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    assessment_type TEXT,
                    risk_score INTEGER,
                    risk_factors TEXT,
                    recommendations TEXT,
                    assessed_date TEXT,
                    assessed_by TEXT,
                    follow_up_date TEXT,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE risk_details (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            risk_factor_id INTEGER,
            detail TEXT,
            weight REAL,
            created_at TEXT,
            FOREIGN KEY (risk_factor_id) REFERENCES risk_factors (id)
        );
CREATE TABLE risk_factors (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            factor_name TEXT,
            factor_value REAL,
            assessment_id INTEGER,
            date_calculated TEXT, "name" TEXT, "description" TEXT, "weight" REAL,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
        );
CREATE TABLE risks (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                title       TEXT NOT NULL,
                category    TEXT NOT NULL,
                department  TEXT NOT NULL,
                description TEXT,
                likelihood  INTEGER NOT NULL CHECK(likelihood BETWEEN 1 AND 5),
                impact      INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 5),
                status      TEXT NOT NULL,
                owner       TEXT,
                mitigation  TEXT,
                created     TEXT NOT NULL,
                updated     TEXT NOT NULL
            , reference_id TEXT, next_review_date TEXT, expires_at TEXT, closed_at TEXT);
CREATE TABLE role_permissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            role_id INTEGER NOT NULL,
            permission_id INTEGER NOT NULL,
            FOREIGN KEY (role_id) REFERENCES roles (id),
            FOREIGN KEY (permission_id) REFERENCES permissions (id),
            UNIQUE(role_id, permission_id)
        );
CREATE TABLE roles (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            role_name TEXT UNIQUE NOT NULL,
            description TEXT NOT NULL,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE room_bookings (
                booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER NOT NULL,
                booked_by TEXT NOT NULL,
                booking_type TEXT NOT NULL,
                purpose TEXT,
                start_datetime TEXT NOT NULL,
                end_datetime TEXT NOT NULL,
                setup_required TEXT,
                equipment_needed TEXT,
                expected_attendees INTEGER,
                recurrence_pattern TEXT,
                booking_status TEXT DEFAULT 'confirmed',
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (room_id) REFERENCES rooms (id)
            );
CREATE TABLE roommate_matches (
                    match_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    profile_id_1 INTEGER NOT NULL,
                    profile_id_2 INTEGER NOT NULL,
                    compatibility_score REAL NOT NULL,
                    match_reasons TEXT,
                    status TEXT DEFAULT 'Suggested',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (profile_id_1) REFERENCES roommate_profiles(profile_id) ON DELETE CASCADE,
                    FOREIGN KEY (profile_id_2) REFERENCES roommate_profiles(profile_id) ON DELETE CASCADE
                );
CREATE TABLE roommate_messages (
                    message_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    match_id INTEGER NOT NULL,
                    sender_profile_id INTEGER NOT NULL,
                    receiver_profile_id INTEGER NOT NULL,
                    message_text TEXT NOT NULL,
                    is_read BOOLEAN DEFAULT 0,
                    sent_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (match_id) REFERENCES roommate_matches(match_id) ON DELETE CASCADE,
                    FOREIGN KEY (sender_profile_id) REFERENCES roommate_profiles(profile_id) ON DELETE CASCADE,
                    FOREIGN KEY (receiver_profile_id) REFERENCES roommate_profiles(profile_id) ON DELETE CASCADE
                );
CREATE TABLE roommate_profiles (
                    profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT UNIQUE NOT NULL,
                    display_name TEXT NOT NULL,
                    bio TEXT,
                    budget_min INTEGER,
                    budget_max INTEGER,
                    move_in_date TEXT,
                    preferred_gender TEXT,
                    age INTEGER,
                    major TEXT,
                    year_of_study TEXT,
                    smoking_preference TEXT DEFAULT 'No',
                    pet_preference TEXT DEFAULT 'No pets',
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE rooms (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_number TEXT,
                building TEXT,
                capacity INTEGER,
                room_type TEXT,
                equipment TEXT,
                notes TEXT,
                is_active BOOLEAN DEFAULT 1
            , building_id INTEGER, room_name TEXT, floor_number INTEGER, area_sqft REAL, features TEXT, accessibility_compliant BOOLEAN DEFAULT 1, status TEXT DEFAULT 'available', "room_id" INTEGER);
CREATE TABLE rubric_criteria (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            rubric_id INTEGER NOT NULL,
            criteria_name TEXT NOT NULL,
            description TEXT,
            max_points REAL NOT NULL,
            weight REAL DEFAULT 1.0,
            display_order INTEGER DEFAULT 0, "criteria_description" TEXT, "order_index" INTEGER DEFAULT 0, "criterion_name" TEXT, "created_at" TEXT, "criterion_order" INTEGER,
            FOREIGN KEY (rubric_id) REFERENCES rubrics (id) ON DELETE CASCADE
        );
CREATE TABLE "rubrics" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            total_points REAL NOT NULL DEFAULT 100,
            is_active INTEGER DEFAULT 1,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            created_by INTEGER,
            FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE sabbatical_applications (
                    application_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    sabbatical_type TEXT DEFAULT 'research',
                    title TEXT NOT NULL,
                    research_proposal TEXT,
                    host_institution TEXT,
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    pay_percentage REAL DEFAULT 100,
                    cover_arrangements TEXT,
                    funding_details TEXT,
                    status TEXT DEFAULT 'draft',
                    department TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE "sabbatical_approvals" (
                    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    application_id INTEGER NOT NULL,
                    approval_level TEXT NOT NULL,
                    approver_id TEXT,
                    status TEXT DEFAULT 'pending',
                    comments TEXT,
                    reviewed_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (application_id) REFERENCES sabbatical_applications(application_id)
                );
CREATE TABLE sabbatical_eligibility (
                    eligibility_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL UNIQUE,
                    years_of_service REAL DEFAULT 0,
                    last_sabbatical_end TEXT,
                    next_eligible_date TEXT,
                    is_eligible INTEGER DEFAULT 0,
                    notes TEXT,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE sabbatical_progress_reports (
                    report_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    application_id INTEGER NOT NULL,
                    report_type TEXT DEFAULT 'interim',
                    report_date TEXT NOT NULL,
                    content TEXT NOT NULL,
                    achievements TEXT,
                    challenges TEXT,
                    status TEXT DEFAULT 'submitted',
                    reviewer_id TEXT,
                    review_comments TEXT,
                    review_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (application_id) REFERENCES sabbatical_applications(application_id)
                );
CREATE TABLE sabbatical_return_plans (
                    plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    application_id INTEGER NOT NULL,
                    return_date TEXT NOT NULL,
                    transition_period_weeks INTEGER DEFAULT 4,
                    research_outputs TEXT,
                    knowledge_sharing_plan TEXT,
                    meeting_scheduled INTEGER DEFAULT 0,
                    meeting_date TEXT,
                    status TEXT DEFAULT 'draft',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (application_id) REFERENCES sabbatical_applications(application_id)
                );
CREATE TABLE "safeguarding_flags" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                message_id INTEGER NOT NULL,
                room_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                matched_word TEXT NOT NULL,
                severity TEXT NOT NULL DEFAULT 'flag',
                created_at TEXT NOT NULL,
                FOREIGN KEY (message_id) REFERENCES chat_messages (id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE safeguarding_referrals (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    source TEXT, source_id INTEGER,
                    referred_by TEXT, referred_at TEXT,
                    reason TEXT, status TEXT DEFAULT 'open'
                );
CREATE TABLE safety_plans (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                warning_signs TEXT,
                coping_strategies TEXT,
                distractions TEXT,
                support_people TEXT,
                professionals TEXT,
                safe_environment TEXT,
                emergency_contacts TEXT,
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now'))
            );
CREATE TABLE saved_listings (
                    saved_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    listing_type TEXT NOT NULL,
                    listing_id INTEGER NOT NULL,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (user_id) REFERENCES students(student_id)
                );
CREATE TABLE "saved_searches" (
            search_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            name TEXT NOT NULL,
            search_criteria TEXT,
            created_at TEXT, search_name TEXT, created_date TEXT, is_shared INTEGER DEFAULT 0, last_used TEXT, "search_type" TEXT, "query_name" TEXT, "use_count" INTEGER DEFAULT 0, "id" INTEGER, "search_params" TEXT, "search_parameters" TEXT,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE savings_goals (
                        goal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        goal_name TEXT NOT NULL,
                        target_amount REAL NOT NULL,
                        current_amount REAL DEFAULT 0.0,
                        target_date TEXT,
                        priority TEXT CHECK(priority IN ('low', 'medium', 'high')),
                        status TEXT DEFAULT 'active' CHECK(status IN ('active', 'completed', 'cancelled')),
                        category TEXT,
                        description TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "deadline" TEXT,
                        FOREIGN KEY (student_id) REFERENCES students(student_id)
                    );
CREATE TABLE sc_announcements (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT,
        message TEXT,
        priority TEXT,
        posted_by TEXT,
        posted_at TEXT
    );
CREATE TABLE sc_candidates (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT UNIQUE,
        name TEXT,
        position TEXT,
        platform TEXT,
        registered_at TEXT
    );
CREATE TABLE sc_members (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT UNIQUE,
        name TEXT,
        email TEXT,
        department TEXT,
        position TEXT,
        joined_at TEXT
    );
CREATE TABLE sc_votes (
        voter_id TEXT PRIMARY KEY,
        candidate_id INTEGER,
        cast_at TEXT,
        FOREIGN KEY (candidate_id) REFERENCES sc_candidates(id)
    );
CREATE TABLE schedule_activity_types (
                    type_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    display_name TEXT NOT NULL,
                    color TEXT NOT NULL DEFAULT '#3498db',
                    is_active INTEGER DEFAULT 1,
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE schedule_conflicts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    conflict_type TEXT,
                    description TEXT,
                    affected_schedules TEXT,
                    resolved BOOLEAN DEFAULT 0,
                    resolution_notes TEXT,
                    detected_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    resolved_date TIMESTAMP
                );
CREATE TABLE schedule_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                schedule_id INTEGER,
                action TEXT,
                old_values TEXT,
                new_values TEXT,
                changed_by TEXT,
                change_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE schedule_templates (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                template_name TEXT UNIQUE,
                description TEXT,
                template_data TEXT,
                created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                created_by TEXT
            );
CREATE TABLE scheduled_emails (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    template_name TEXT,
                    recipient_email TEXT NOT NULL,
                    template_vars TEXT,
                    scheduled_date TEXT NOT NULL,
                    status TEXT DEFAULT 'pending',
                    created_at TEXT NOT NULL
                , "body" TEXT, "error_message" TEXT, "recipient" TEXT, "scheduled_time" TEXT, "sent_at" TEXT, "subject" TEXT);
CREATE TABLE scheduled_imports (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        schedule_type TEXT NOT NULL,
                        schedule_data TEXT NOT NULL,
                        is_active INTEGER DEFAULT 1,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE scheduled_reports (
            report_id INTEGER PRIMARY KEY AUTOINCREMENT,
            report_name TEXT NOT NULL,
            report_type TEXT NOT NULL,
            schedule_frequency TEXT NOT NULL,
            recipients TEXT NOT NULL,
            last_run_date TEXT,
            next_run_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            report_config TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , "created_by" TEXT, "format" TEXT DEFAULT 'pdf', "frequency" TEXT, "next_generation" TIMESTAMP, "parameters_json" TEXT, "recipients_json" TEXT, "last_generated" TIMESTAMP, "email_recipients" TEXT, "id" INTEGER, "last_run" DATETIME, "schedule_pattern" TEXT, "search_criteria" TEXT, "user_id" TEXT);
CREATE TABLE scheduling_system_settings (
                key TEXT PRIMARY KEY,
                value TEXT,
                description TEXT,
                last_modified TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , "id" INTEGER, "setting_key" TEXT, "setting_value" TEXT, updated_at TIMESTAMP DEFAULT NULL);
CREATE TABLE schema_migrations (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        version INTEGER NOT NULL UNIQUE,
        migration_name TEXT NOT NULL,
        applied_at TEXT NOT NULL,
        status TEXT DEFAULT 'success',
        error_message TEXT,
        rollback_sql TEXT
    );
CREATE TABLE scholarship_applications (
    application_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    scholarship_id INTEGER NOT NULL,
    application_date TEXT DEFAULT CURRENT_TIMESTAMP,
    status TEXT DEFAULT 'pending',
    essay TEXT,
    additional_documents TEXT,
    reviewer_id TEXT,
    review_date TEXT,
    review_notes TEXT,
    decision_date TEXT,
    award_amount DECIMAL(10,2), essay_text TEXT, gpa REAL, transcript_url TEXT, resume_url TEXT, "academic_year" TEXT, "financial_need_statement" TEXT, "reviewed_by" INTEGER, "review_comments" TEXT, "review_score" REAL,
    FOREIGN KEY (student_id) REFERENCES students (student_id),
    FOREIGN KEY (scholarship_id) REFERENCES scholarships (scholarship_id)
);
CREATE TABLE scholarship_awards (
    award_id INTEGER PRIMARY KEY AUTOINCREMENT,
    scholarship_id INTEGER NOT NULL,
    student_id TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    amount REAL NOT NULL,
    award_date DATE,
    status TEXT DEFAULT 'active',  -- active, suspended, revoked, completed
    is_renewable BOOLEAN DEFAULT 0,
    renewal_deadline DATE,
    renewal_status TEXT,  -- NULL, pending, approved, denied
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "amount_awarded" REAL, "application_id" INTEGER, "disbursement_schedule" TEXT, "terms_accepted" BOOLEAN DEFAULT 0, "terms_accepted_date" TIMESTAMP,
    FOREIGN KEY (scholarship_id) REFERENCES scholarships(scholarship_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE scholarship_awards_history (
                        award_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        scholarship_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        application_id INTEGER,
                        award_amount REAL NOT NULL,
                        academic_year TEXT NOT NULL,
                        semester TEXT,
                        award_date TEXT NOT NULL,
                        disbursement_date TEXT,
                        disbursement_amount REAL,
                        disbursement_status TEXT CHECK(disbursement_status IN ('pending', 'partial', 'completed', 'cancelled')),
                        is_renewable BOOLEAN DEFAULT 0,
                        renewal_deadline TEXT,
                        renewal_requirements TEXT,
                        renewal_gpa_requirement REAL,
                        thankyou_letter_sent BOOLEAN DEFAULT 0,
                        thankyou_letter_date TEXT,
                        impact_statement_submitted BOOLEAN DEFAULT 0,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (scholarship_id) REFERENCES scholarship_opportunities(scholarship_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (application_id) REFERENCES student_scholarship_applications(application_id)
                    );
CREATE TABLE scholarship_deadline_reminders (
                        reminder_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        application_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        scholarship_id INTEGER NOT NULL,
                        deadline_date TEXT NOT NULL,
                        reminder_date TEXT NOT NULL,
                        reminder_type TEXT CHECK(reminder_type IN ('one-month', 'two-weeks', 'one-week', 'three-days', 'one-day', 'custom')),
                        days_before_deadline INTEGER,
                        reminder_sent BOOLEAN DEFAULT 0,
                        reminder_sent_date TEXT,
                        notification_method TEXT CHECK(notification_method IN ('email', 'sms', 'push', 'all')),
                        message TEXT,
                        is_active BOOLEAN DEFAULT 1,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (application_id) REFERENCES student_scholarship_applications(application_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (scholarship_id) REFERENCES scholarship_opportunities(scholarship_id)
                    );
CREATE TABLE scholarship_document_vault (
                        document_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        document_name TEXT NOT NULL,
                        document_type TEXT CHECK(document_type IN ('essay', 'transcript', 'resume', 'recommendation', 'financial-document', 'certificate', 'portfolio', 'other')),
                        file_path TEXT NOT NULL,
                        file_size INTEGER,
                        file_format TEXT,
                        description TEXT,
                        tags TEXT,
                        version INTEGER DEFAULT 1,
                        is_current_version BOOLEAN DEFAULT 1,
                        parent_document_id INTEGER,
                        associated_scholarship_id INTEGER,
                        upload_date TEXT DEFAULT (date('now')),
                        last_modified TEXT DEFAULT (date('now')),
                        expiry_date TEXT,
                        is_verified BOOLEAN DEFAULT 0,
                        verified_by INTEGER,
                        verified_date TEXT,
                        usage_count INTEGER DEFAULT 0,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (parent_document_id) REFERENCES scholarship_document_vault(document_id),
                        FOREIGN KEY (associated_scholarship_id) REFERENCES scholarship_opportunities(scholarship_id)
                    );
CREATE TABLE scholarship_matching_rules (
                        rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        rule_name TEXT NOT NULL,
                        rule_category TEXT CHECK(rule_category IN ('academic', 'demographic', 'financial', 'activity', 'geographic', 'special')),
                        rule_weight REAL DEFAULT 1.0,
                        rule_logic TEXT NOT NULL,
                        is_required BOOLEAN DEFAULT 0,
                        description TEXT,
                        is_active BOOLEAN DEFAULT 1,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE scholarship_opportunities (
                        scholarship_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        scholarship_name TEXT NOT NULL,
                        organization TEXT NOT NULL,
                        organization_type TEXT CHECK(organization_type IN ('university', 'government', 'private', 'corporate', 'foundation', 'nonprofit', 'community')),
                        award_amount_min REAL,
                        award_amount_max REAL,
                        award_type TEXT CHECK(award_type IN ('one-time', 'renewable', 'multi-year')),
                        description TEXT,
                        detailed_requirements TEXT,
                        eligibility_criteria TEXT,
                        academic_level TEXT CHECK(academic_level IN ('freshman', 'sophomore', 'junior', 'senior', 'graduate', 'any')),
                        min_gpa REAL,
                        max_gpa REAL,
                        required_majors TEXT,
                        excluded_majors TEXT,
                        required_enrollment_status TEXT,
                        citizenship_requirements TEXT,
                        state_residency_requirements TEXT,
                        financial_need_required BOOLEAN DEFAULT 0,
                        merit_based BOOLEAN DEFAULT 0,
                        demographic_requirements TEXT,
                        special_criteria TEXT,
                        application_url TEXT,
                        application_deadline TEXT NOT NULL,
                        notification_date TEXT,
                        award_disbursement_date TEXT,
                        renewable_terms TEXT,
                        number_of_awards INTEGER,
                        estimated_applicants INTEGER,
                        competition_level TEXT CHECK(competition_level IN ('low', 'moderate', 'high', 'very-high')),
                        required_documents TEXT,
                        essay_required BOOLEAN DEFAULT 0,
                        essay_prompts TEXT,
                        recommendation_letters_required INTEGER DEFAULT 0,
                        transcript_required BOOLEAN DEFAULT 0,
                        interview_required BOOLEAN DEFAULT 0,
                        contact_email TEXT,
                        contact_phone TEXT,
                        tags TEXT,
                        source TEXT,
                        is_active BOOLEAN DEFAULT 1,
                        is_internal BOOLEAN DEFAULT 0,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE scholarship_recommendations (
                        recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        scholarship_id INTEGER NOT NULL,
                        match_score REAL NOT NULL,
                        eligibility_status TEXT CHECK(eligibility_status IN ('highly-eligible', 'eligible', 'possibly-eligible', 'not-eligible')),
                        matching_criteria TEXT,
                        missing_criteria TEXT,
                        recommendation_reason TEXT,
                        estimated_competition TEXT,
                        priority_level TEXT CHECK(priority_level IN ('high', 'medium', 'low')),
                        recommended_date TEXT DEFAULT (date('now')),
                        expires_date TEXT,
                        viewed BOOLEAN DEFAULT 0,
                        viewed_date TEXT,
                        dismissed BOOLEAN DEFAULT 0,
                        dismissed_date TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (scholarship_id) REFERENCES scholarship_opportunities(scholarship_id),
                        UNIQUE(student_id, scholarship_id)
                    );
CREATE TABLE scholarships (
            scholarship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            scholarship_name TEXT NOT NULL,
            description TEXT,
            amount DECIMAL(10,2),
            academic_year TEXT,
            criteria TEXT,
            deadline TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        , "total_awarded" INTEGER DEFAULT 0);
CREATE TABLE "school_announcements" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT,
                content TEXT,
                priority TEXT DEFAULT 'normal',
                category TEXT,
                audience TEXT,
                created_by INTEGER,
                created_date TEXT,
                expiry_date TEXT,
                requires_acknowledgment BOOLEAN DEFAULT 0,
                FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE screen_layouts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            screen_number INTEGER UNIQUE NOT NULL,
            name TEXT,
            rows INTEGER NOT NULL DEFAULT 8,
            seats_per_row INTEGER NOT NULL DEFAULT 12,
            vip_rows TEXT,
            wheelchair_positions TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE screen_maintenance (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            screen_number INTEGER NOT NULL,
            maintenance_type TEXT NOT NULL,
            description TEXT,
            start_datetime TEXT NOT NULL,
            end_datetime TEXT,
            technician TEXT,
            cost REAL,
            status TEXT DEFAULT 'scheduled',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE screening_results (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            screening_type TEXT NOT NULL,
            results TEXT,
            date_performed TEXT NOT NULL,
            next_due_date TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE screening_schedules (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    screening_type TEXT,
                    due_date TEXT,
                    completed_date TEXT,
                    status TEXT DEFAULT 'due',
                    provider TEXT,
                    results TEXT,
                    next_due_date TEXT,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE screenings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            movie_id INTEGER NOT NULL,
            screen_number INTEGER NOT NULL,
            show_time TEXT NOT NULL,
            price REAL NOT NULL,
            status TEXT DEFAULT 'active', is_3d INTEGER DEFAULT 0, is_imax INTEGER DEFAULT 0, social_distancing INTEGER DEFAULT 0,
            FOREIGN KEY (movie_id) REFERENCES movies(id)
        );
CREATE TABLE search_analytics (
            search_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            search_query TEXT NOT NULL,
            search_type TEXT NOT NULL,  -- faq, resource, ticket, global
            results_count INTEGER NOT NULL,
            clicked_result_id TEXT,
            search_datetime TEXT NOT NULL,
            session_id TEXT
        , search_criteria TEXT, execution_time REAL);
CREATE TABLE search_clicks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    query TEXT NOT NULL,
                    entity_type TEXT,
                    clicked_id TEXT NOT NULL,
                    click_position INTEGER,
                    user_id TEXT,
                    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE search_metrics (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    query TEXT NOT NULL,
                    entity_type TEXT,
                    user_id TEXT,
                    results_count INTEGER,
                    response_time_ms INTEGER,
                    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE search_presets (
                    id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    user_id TEXT NOT NULL,
                    filters TEXT NOT NULL,
                    date_added TEXT NOT NULL,
                    is_active BOOLEAN DEFAULT TRUE
                );
CREATE TABLE search_profiles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                criteria TEXT,
                created_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                created_by TEXT,
                is_shared BOOLEAN DEFAULT FALSE
            , "created_at" TEXT, "is_default" INTEGER DEFAULT 0, "profile_name" TEXT, "search_criteria" TEXT, "user_id" INTEGER);
CREATE TABLE search_result_archives (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT,
                saved_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                search_name TEXT,
                search_criteria TEXT,
                results_json TEXT
            , "archived_at" TEXT, "expires_at" TEXT, "result_count" INTEGER DEFAULT 0, "results_data" TEXT, "search_query" TEXT);
CREATE TABLE season_passes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            pass_code TEXT UNIQUE NOT NULL,
            member_id INTEGER,
            customer_name TEXT NOT NULL,
            customer_email TEXT NOT NULL,
            pass_type TEXT NOT NULL,
            purchase_date TEXT DEFAULT CURRENT_TIMESTAMP,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            movies_used INTEGER DEFAULT 0,
            status TEXT DEFAULT 'active',
            FOREIGN KEY (member_id) REFERENCES members(id)
        );
CREATE TABLE seat_holds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            seat_id INTEGER NOT NULL,
            session_id TEXT NOT NULL,
            held_at TEXT DEFAULT CURRENT_TIMESTAMP,
            expires_at TEXT NOT NULL,
            FOREIGN KEY (seat_id) REFERENCES seats(id)
        );
CREATE TABLE seats (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            screening_id INTEGER NOT NULL,
            row TEXT NOT NULL,
            seat_number INTEGER NOT NULL,
            seat_type TEXT DEFAULT 'standard',
            status TEXT DEFAULT 'available', is_wheelchair INTEGER DEFAULT 0, is_companion INTEGER DEFAULT 0, is_couple INTEGER DEFAULT 0,
            FOREIGN KEY (screening_id) REFERENCES screenings(id),
            UNIQUE(screening_id, row, seat_number)
        );
CREATE TABLE section_meetings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        section_id INTEGER NOT NULL,
        day_of_week TEXT NOT NULL,
        start_time TEXT NOT NULL DEFAULT '09:00',
        end_time TEXT NOT NULL DEFAULT '10:00',
        location TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now')), room_id INTEGER,
        FOREIGN KEY (section_id) REFERENCES course_sections (id)
    );
CREATE TABLE security_desk_counter (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    counter INTEGER DEFAULT 1000
);
CREATE TABLE security_desk_tickets (
    id TEXT PRIMARY KEY,
    type TEXT,
    category TEXT,
    priority TEXT DEFAULT 'Normal',
    status TEXT DEFAULT 'Open',
    subject TEXT,
    description TEXT,
    location TEXT,
    user_id TEXT,
    user_name TEXT,
    user_email TEXT,
    admin_notes TEXT,
    created_at TEXT,
    updated_at TEXT
);
CREATE TABLE "security_events" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                event_type TEXT NOT NULL,
                severity TEXT DEFAULT 'medium',
                details TEXT,
                ip_address TEXT,
                event_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "source" TEXT, "created_at" TIMESTAMP DEFAULT NULL,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE security_incident_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                incident_pk INTEGER NOT NULL,       -- FK to security_incidents.id
                event_time TEXT DEFAULT CURRENT_TIMESTAMP,
                event_type TEXT,                    -- note, containment, escalation, closure, etc.
                details TEXT,
                actor TEXT
            , "incident_id" INTEGER, "description" TEXT, "performed_by" INTEGER, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE security_incidents (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                incident_id TEXT UNIQUE,            -- human-friendly ref (e.g., INC-2025-0001)
                summary TEXT,
                description TEXT,
                severity TEXT,                      -- low/medium/high/critical
                status TEXT,                        -- open/contained/eradicated/monitoring/closed
                detected_at TEXT DEFAULT CURRENT_TIMESTAMP,
                reported_by TEXT,
                assigned_to TEXT,
                category TEXT,                      -- phishing, malware, policy_violation, etc.
                source TEXT,                        -- system/user/external
                affected_user TEXT,
                containment TEXT,
                eradication TEXT,
                recovery TEXT,
                resolved_at TEXT,
                root_cause TEXT,
                tags TEXT
            , title TEXT, opened_at TEXT, closed_at TEXT, priority TEXT, "resolution_notes" TEXT, created_at TIMESTAMP DEFAULT NULL, "detected_by" INTEGER, "incident_type" TEXT, "resolution" TEXT);
CREATE TABLE security_policies (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                policy_key TEXT UNIQUE NOT NULL,
                value TEXT,
                description TEXT,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            , policy_name TEXT, status TEXT, last_updated TEXT, "policy_type" TEXT, "policy_config" TEXT, "is_active" INTEGER DEFAULT 1, "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE security_settings (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    setting_name TEXT UNIQUE,
                    setting_value TEXT,
                    updated_at TEXT,
                    updated_by TEXT
                );
CREATE TABLE self_check_usage (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_hash TEXT NOT NULL,
                score_range TEXT NOT NULL,
                timestamp TEXT NOT NULL
            );
CREATE TABLE semester_plans (
                        plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        plan_name TEXT NOT NULL,
                        program_code TEXT,
                        start_semester TEXT NOT NULL,
                        total_semesters INTEGER DEFAULT 8,
                        credits_per_semester INTEGER DEFAULT 15,
                        include_summer BOOLEAN DEFAULT 0,
                        status TEXT DEFAULT 'Draft',
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE semesters (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    academic_year_id TEXT NOT NULL,
                    name TEXT NOT NULL,
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    registration_start TEXT,
                    registration_end TEXT,
                    final_exams_start TEXT,
                    final_exams_end TEXT,
                    date_added TEXT NOT NULL,
                    FOREIGN KEY (academic_year_id) REFERENCES academic_years (id) ON DELETE CASCADE,
                    UNIQUE(academic_year_id, name),
                    CONSTRAINT valid_semester_dates CHECK (start_date < end_date)
                );
CREATE TABLE sent_notifications (
            notification_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            template_id INTEGER NOT NULL,
            recipient_email TEXT,
            recipient_phone TEXT,
            subject TEXT,
            message_body TEXT,
            send_method TEXT,
            status TEXT DEFAULT 'pending', -- pending, sent, failed, bounced
            sent_at TEXT,
            error_message TEXT,
            created_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (template_id) REFERENCES notification_templates (template_id)
        );
CREATE TABLE "session_activity_log" (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id INTEGER,
        user_id INTEGER,
        activity_type TEXT NOT NULL,
        details TEXT,
        activity_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );
CREATE TABLE session_participants (
    participant_id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    user_type TEXT NOT NULL,  -- student, instructor, guest
    join_time TIMESTAMP,
    leave_time TIMESTAMP,
    duration INTEGER,  -- seconds
    connection_quality TEXT,  -- excellent, good, fair, poor
    device_type TEXT,  -- desktop, mobile, tablet
    is_muted BOOLEAN DEFAULT 0,
    is_video_on BOOLEAN DEFAULT 1,
    raised_hand_count INTEGER DEFAULT 0,
    chat_message_count INTEGER DEFAULT 0,
    attendance_status TEXT DEFAULT 'absent', "attendance_duration" INTEGER DEFAULT 0, "is_present" BOOLEAN DEFAULT 0, "joined_at" TIMESTAMP, "left_at" TIMESTAMP, "role" TEXT DEFAULT 'attendee',  -- present, absent, late, left_early
    FOREIGN KEY (session_id) REFERENCES virtual_sessions(session_id) ON DELETE CASCADE
);
CREATE TABLE "sessions" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                session_token TEXT UNIQUE,
                ip_address TEXT,
                location TEXT,
                user_agent TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                last_activity TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP,
                is_active INTEGER DEFAULT 1, session_id_hash TEXT, device_fingerprint TEXT, terminated_at TIMESTAMP, termination_reason TEXT,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE shared_academic_resources (
                resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                subject TEXT,
                resource_type TEXT,
                description TEXT,
                file_path TEXT,
                uploaded_by TEXT,
                upload_date TEXT,
                downloads INTEGER DEFAULT 0
            );
CREATE TABLE shared_resources (
            resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
            uploader_id TEXT,
            resource_title TEXT,
            resource_type TEXT,
            subject TEXT,
            file_path TEXT,
            description TEXT,
            upload_date TEXT,
            downloads INTEGER DEFAULT 0,
            rating REAL DEFAULT 0.0,
            FOREIGN KEY (uploader_id) REFERENCES students (student_id)
        );
CREATE TABLE shift_swap_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            requester_id INTEGER NOT NULL,
            original_shift_id INTEGER NOT NULL,
            requested_with_id INTEGER,
            target_shift_id INTEGER,
            reason TEXT,
            status TEXT DEFAULT 'pending',
            reviewed_by INTEGER,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            resolved_at TEXT,
            FOREIGN KEY (requester_id) REFERENCES staff(id),
            FOREIGN KEY (original_shift_id) REFERENCES shifts(id),
            FOREIGN KEY (requested_with_id) REFERENCES staff(id),
            FOREIGN KEY (target_shift_id) REFERENCES shifts(id),
            FOREIGN KEY (reviewed_by) REFERENCES staff(id)
        );
CREATE TABLE shifts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id INTEGER NOT NULL,
            shift_date TEXT NOT NULL,
            start_time TEXT NOT NULL,
            end_time TEXT NOT NULL,
            position TEXT DEFAULT 'general',
            screen_assigned INTEGER,
            break_start TEXT,
            break_end TEXT,
            status TEXT DEFAULT 'scheduled',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (staff_id) REFERENCES staff(id)
        );
CREATE TABLE "shop_cart" (
                    cart_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER NOT NULL,
                    product_id INTEGER NOT NULL,
                    quantity INTEGER NOT NULL DEFAULT 1,
                    added_at TEXT NOT NULL,
                    FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
                    FOREIGN KEY (product_id) REFERENCES products (product_id),
                    UNIQUE(user_id, product_id)
                );
CREATE TABLE shop_discounts (
            discount_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            description TEXT,
            discount_type TEXT NOT NULL,
            discount_value REAL NOT NULL,
            start_date TEXT,
            end_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            applicable_products TEXT,
            min_purchase_amount REAL DEFAULT 0,
            created_at TEXT NOT NULL
        );
CREATE TABLE "shop_inventory" (
                inventory_id INTEGER PRIMARY KEY AUTOINCREMENT,
                product_id TEXT NOT NULL,
                quantity INTEGER NOT NULL DEFAULT 0,
                last_restock_date TEXT,
                restock_threshold INTEGER DEFAULT 5
            );
CREATE TABLE shop_products (
                    product_id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    description TEXT,
                    price REAL NOT NULL,
                    category TEXT,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    tax_rate REAL DEFAULT 0.2,
                    is_active BOOLEAN DEFAULT 1
                );
CREATE TABLE "shop_transaction_items" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                transaction_id TEXT NOT NULL,
                product_id TEXT NOT NULL,
                quantity INTEGER NOT NULL,
                price_per_item REAL NOT NULL,
                subtotal REAL NOT NULL
            );
CREATE TABLE "shop_transactions" (
                    transaction_id TEXT PRIMARY KEY,
                    user_id INTEGER,
                    student_id TEXT,
                    total_amount REAL NOT NULL,
                    transaction_date TEXT NOT NULL,
                    payment_method TEXT,
                    status TEXT NOT NULL,
                    notes TEXT,
                    FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE shuttle_buses (
    bus_id INTEGER PRIMARY KEY AUTOINCREMENT,
    route_id INTEGER,
    bus_number TEXT UNIQUE,
    capacity INTEGER DEFAULT 40,
    current_location TEXT,  -- lat,lon
    current_stop_id INTEGER,
    in_service BOOLEAN DEFAULT 1,
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "id" INTEGER, "current_route_id" INTEGER, "status" TEXT DEFAULT 'active',
    FOREIGN KEY (route_id) REFERENCES shuttle_routes(route_id)
);
CREATE TABLE shuttle_routes (
    route_id INTEGER PRIMARY KEY AUTOINCREMENT,
    route_name TEXT NOT NULL,
    description TEXT,
    schedule TEXT,  -- JSON
    stops TEXT,  -- JSON array
    is_active BOOLEAN DEFAULT 1
, "id" INTEGER, "start_time" TEXT, "end_time" TEXT, "frequency_minutes" INTEGER DEFAULT 15, "created_at" TEXT);
CREATE TABLE shuttle_stops (
    stop_id INTEGER PRIMARY KEY AUTOINCREMENT,
    stop_name TEXT NOT NULL,
    latitude REAL,
    longitude REAL,
    arrival_time TIME,
    amenities TEXT  -- JSON
, "estimated_time_from_start" INTEGER, "id" INTEGER, "route_id" INTEGER, "stop_order" INTEGER);
CREATE TABLE sis_sync_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    sync_type TEXT NOT NULL,
                    records_synced INTEGER DEFAULT 0,
                    records_failed INTEGER DEFAULT 0,
                    synced_by TEXT,
                    synced_at TEXT DEFAULT (datetime('now')),
                    details_json TEXT
                , "details" TEXT, "records_added" TEXT, "records_updated" TEXT, "errors" TEXT, "records_processed" TEXT, "source_file" TEXT);
CREATE TABLE skill_endorsements (
                    endorsement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    skill_id INTEGER NOT NULL,
                    endorser_id TEXT NOT NULL,
                    endorser_role TEXT CHECK(endorser_role IN (
                        'faculty', 'peer', 'employer', 'mentor'
                    )),
                    comment TEXT,
                    relationship TEXT,
                    endorsed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (skill_id) REFERENCES student_skills(skill_id) ON DELETE CASCADE,
                    UNIQUE(skill_id, endorser_id)
                );
CREATE TABLE sla_policies (
            sla_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            priority TEXT,
            impact TEXT,
            urgency TEXT,
            first_response_hours INTEGER,
            resolution_hours INTEGER,
            escalation_hours INTEGER,
            business_hours_only BOOLEAN DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        , team TEXT);
CREATE TABLE sleep_tracking (
                    sleep_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    sleep_date TEXT NOT NULL,
                    bedtime TEXT,
                    wake_time TEXT,
                    hours_slept REAL,
                    sleep_quality INTEGER CHECK(sleep_quality BETWEEN 1 AND 5),
                    interruptions INTEGER DEFAULT 0,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE sms_log (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        recipient_phone TEXT NOT NULL,
                        message TEXT NOT NULL,
                        provider TEXT,
                        status TEXT DEFAULT 'sent',
                        sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        student_id TEXT,
                        related_to TEXT,
                        error_message TEXT,
                        message_sid TEXT
                    );
CREATE TABLE sms_messages (
                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                            sender_username TEXT,
                            recipient_name TEXT,
                            phone_number TEXT,
                            message TEXT,
                            status TEXT,
                            sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                        , "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "delivered_at" TEXT, "error_message" TEXT, "recipient_phone" TEXT);
CREATE TABLE sms_templates (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        name TEXT UNIQUE NOT NULL,
                        category TEXT,
                        message TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE "social_activities" (
                activity_id INTEGER PRIMARY KEY AUTOINCREMENT,
                activity_name TEXT NOT NULL,
                activity_type TEXT NOT NULL,
                description TEXT,
                location TEXT,
                activity_date DATE,
                activity_time TIME,
                max_participants INTEGER,
                current_participants INTEGER DEFAULT 0,
                interests_matched TEXT,
                created_by TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (created_by) REFERENCES users(username) ON DELETE CASCADE
            );
CREATE TABLE social_impact_projects (
        project_id INTEGER PRIMARY KEY AUTOINCREMENT,
        project_name TEXT,
        lead_student_id TEXT,
        description TEXT,
        impact_area TEXT,
        target_beneficiaries INTEGER DEFAULT 0,
        status TEXT DEFAULT 'planning',
        created_at TEXT
    );
CREATE TABLE space_utilization (
                utilization_id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER NOT NULL,
                measurement_date TEXT NOT NULL,
                occupancy_rate REAL,
                booking_rate REAL,
                peak_usage_time TEXT,
                average_attendees REAL,
                total_booking_hours REAL,
                FOREIGN KEY (room_id) REFERENCES rooms (id)
            );
CREATE TABLE special_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            event_type TEXT NOT NULL,
            description TEXT,
            event_date TEXT NOT NULL,
            start_time TEXT NOT NULL,
            end_time TEXT,
            screen_number INTEGER,
            movie_id INTEGER,
            ticket_price REAL,
            max_capacity INTEGER,
            tickets_sold INTEGER DEFAULT 0,
            special_guests TEXT,
            status TEXT DEFAULT 'upcoming',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (movie_id) REFERENCES movies(id)
        );
CREATE TABLE sports_bets (
                    bet_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    event_id INTEGER NOT NULL,
                    bet_type TEXT NOT NULL,
                    selection TEXT NOT NULL,
                    odds DECIMAL(6,2) NOT NULL,
                    stake DECIMAL(10,2) NOT NULL,
                    potential_return DECIMAL(10,2) NOT NULL,
                    actual_return DECIMAL(10,2) DEFAULT 0.00,
                    status TEXT DEFAULT 'pending',
                    placed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    settled_at TIMESTAMP, "odds_type" TEXT, "odds_value" REAL, "account_id" INTEGER, "bet_amount" REAL, "created_at" TEXT, "event_name" TEXT, "potential_payout" TEXT,
                    FOREIGN KEY (event_id) REFERENCES betting_events(event_id)
                );
CREATE TABLE sso_identities (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                provider_id TEXT NOT NULL,
                external_id TEXT NOT NULL,
                external_email TEXT,
                attributes_json TEXT,
                last_login_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (provider_id) REFERENCES sso_providers(provider_id) ON DELETE CASCADE,
                UNIQUE(provider_id, external_id)
            );
CREATE TABLE sso_providers (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                provider_id TEXT UNIQUE NOT NULL,
                provider_type TEXT NOT NULL CHECK(provider_type IN ('saml', 'oidc')),
                display_name TEXT NOT NULL,
                config_json TEXT NOT NULL,
                is_enabled BOOLEAN DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE sso_sessions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                provider_id TEXT NOT NULL,
                session_index TEXT,
                access_token_hash TEXT,
                token_expires_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                FOREIGN KEY (provider_id) REFERENCES sso_providers(provider_id) ON DELETE CASCADE
            );
CREATE TABLE staff (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            name TEXT NOT NULL,
            email TEXT,
            phone TEXT,
            role TEXT NOT NULL,
            hire_date TEXT,
            last_login TEXT,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , salt TEXT);
CREATE TABLE staff_absence_alerts (
        alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        trigger_kind TEXT NOT NULL CHECK (trigger_kind IN ('bradford', 'episodes', 'days')),
        value REAL NOT NULL,
        threshold REAL NOT NULL,
        window_start TEXT NOT NULL,
        window_end TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN
            ('open', 'reviewed', 'actioned', 'dismissed')),
        raised_at TEXT NOT NULL DEFAULT (datetime('now')),
        reviewed_by TEXT,
        reviewed_at TEXT,
        outcome TEXT
    );
CREATE TABLE staff_absence_episodes (
        episode_id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        start_date TEXT NOT NULL,
        end_date TEXT,
        first_day_half INTEGER NOT NULL DEFAULT 0,
        reason_category TEXT NOT NULL DEFAULT 'Other',
        reason_detail TEXT,
        certification TEXT NOT NULL DEFAULT 'self' CHECK (certification IN
            ('self', 'fit_note', 'none')),
        working_days REAL NOT NULL DEFAULT 0,
        work_related INTEGER NOT NULL DEFAULT 0,
        disability_related INTEGER NOT NULL DEFAULT 0,
        pregnancy_related INTEGER NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'cancelled')),
        reported_by TEXT,
        reported_at TEXT NOT NULL DEFAULT (datetime('now')),
        closed_by TEXT,
        closed_at TEXT,
        leave_request_id INTEGER,
        notes TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_announcement_reads (
        read_id INTEGER PRIMARY KEY AUTOINCREMENT,
        announcement_id INTEGER NOT NULL,
        user_id TEXT NOT NULL,
        read_date TEXT DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(announcement_id, user_id),
        FOREIGN KEY (announcement_id) REFERENCES staff_announcements(announcement_id)
    );
CREATE TABLE staff_announcements (
                announcement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                category TEXT DEFAULT 'general',
                target_audience TEXT DEFAULT 'all',
                target_departments TEXT,
                target_roles TEXT,
                posted_by TEXT NOT NULL,
                posted_by_name TEXT,
                post_date TEXT DEFAULT CURRENT_TIMESTAMP,
                expiry_date TEXT,
                is_pinned INTEGER DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                view_count INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            , "priority" TEXT DEFAULT 'normal', "moderation_status" TEXT DEFAULT 'approved', "moderated_by" TEXT, "moderated_at" TEXT, "rejection_reason" TEXT);
CREATE TABLE staff_assignments (
            assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id TEXT NOT NULL,
            category TEXT NOT NULL,
            is_primary BOOLEAN DEFAULT 0,
            max_concurrent_tickets INTEGER DEFAULT 10,
            current_ticket_count INTEGER DEFAULT 0,
            expertise_level INTEGER DEFAULT 1,  -- 1-5 scale
            auto_assign_enabled BOOLEAN DEFAULT 1
        );
CREATE TABLE staff_availability (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id INTEGER NOT NULL,
            day_of_week INTEGER NOT NULL,
            available_from TEXT,
            available_until TEXT,
            is_available INTEGER DEFAULT 1,
            notes TEXT,
            FOREIGN KEY (staff_id) REFERENCES staff(id),
            UNIQUE(staff_id, day_of_week)
        );
CREATE TABLE staff_certifications (
    cert_id     INTEGER PRIMARY KEY AUTOINCREMENT,
    staff_id    TEXT NOT NULL,
    kind        TEXT NOT NULL,
    issued_on   TEXT,
    expires_on  TEXT,
    issuer      TEXT,
    document_id INTEGER,
    notes       TEXT,
    is_active   INTEGER NOT NULL DEFAULT 1,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);
CREATE TABLE staff_compliance_settings (
        key TEXT PRIMARY KEY,
        value TEXT,
        updated_by TEXT,
        updated_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE staff_contracts (
                    contract_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    contract_type TEXT NOT NULL DEFAULT 'permanent',
                    start_date TEXT NOT NULL,
                    end_date TEXT,
                    salary REAL,
                    salary_currency TEXT DEFAULT 'GBP',
                    pay_frequency TEXT DEFAULT 'monthly',
                    terms TEXT,
                    status TEXT DEFAULT 'active',
                    renewal_date TEXT,
                    probation_end_date TEXT,
                    notice_period_days INTEGER DEFAULT 30,
                    working_hours_per_week REAL DEFAULT 37.5,
                    department TEXT,
                    job_title TEXT,
                    manager_id TEXT,
                    document_path TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    created_by TEXT
                , "fte" REAL DEFAULT 1.0, "grade_code" TEXT, "spine_point" INTEGER, "pension_scheme" TEXT, "salary_override" REAL, "salary_override_reason" TEXT, "salary_override_by" TEXT);
CREATE TABLE staff_disciplinary_actions (
        action_id INTEGER PRIMARY KEY AUTOINCREMENT,
        record_id INTEGER NOT NULL REFERENCES staff_disciplinary_records (record_id)
            ON DELETE CASCADE,
        action_type TEXT NOT NULL,
        action_level TEXT,
        effective_date TEXT NOT NULL,
        end_date TEXT,
        duration_days INTEGER,
        imposed_by TEXT NOT NULL,
        reason TEXT,
        conditions TEXT,
        appeal_deadline TEXT,
        appeal_submitted BOOLEAN DEFAULT 0,
        appeal_outcome TEXT,
        document_path TEXT,
        acknowledged_by_employee BOOLEAN DEFAULT 0,
        acknowledged_date TEXT,
        expires_on TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE staff_disciplinary_appeals (
        appeal_id INTEGER PRIMARY KEY AUTOINCREMENT,
        action_id INTEGER NOT NULL REFERENCES staff_disciplinary_actions (action_id)
            ON DELETE CASCADE,
        appellant_id TEXT NOT NULL,
        appeal_date TEXT NOT NULL,
        grounds TEXT NOT NULL,
        supporting_documents TEXT,
        status TEXT DEFAULT 'submitted',
        hearing_date TEXT,
        panel_members TEXT,
        outcome TEXT,
        outcome_date TEXT,
        outcome_details TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE staff_disciplinary_records (
        record_id INTEGER PRIMARY KEY AUTOINCREMENT,
        reference_number TEXT UNIQUE,
        user_id TEXT NOT NULL,
        offense_type TEXT NOT NULL,
        offense_category TEXT,
        severity TEXT DEFAULT 'minor',
        description TEXT NOT NULL,
        date_occurred TEXT NOT NULL,
        date_reported TEXT,
        reported_by TEXT,
        witnesses TEXT,
        evidence_path TEXT,
        status TEXT DEFAULT 'under_review',
        investigation_notes TEXT,
        investigating_officer TEXT,
        is_confidential BOOLEAN DEFAULT 1,
        previous_warnings INTEGER DEFAULT 0,
        moved_from_record_id INTEGER UNIQUE,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE staff_equality_declarations (
        username TEXT PRIMARY KEY,
        sex TEXT,
        gender_identity TEXT,
        ethnicity TEXT,
        disability TEXT,
        religion TEXT,
        sexual_orientation TEXT,
        caring_responsibilities TEXT,
        declared_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_expertise (
                    expertise_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    expertise_area TEXT NOT NULL,
                    category TEXT DEFAULT 'academic',
                    proficiency TEXT DEFAULT 'intermediate',
                    keywords TEXT,
                    is_public INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE staff_family_leave_cases (
        case_id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        kind TEXT NOT NULL CHECK (kind IN
            ('maternity', 'paternity', 'adoption', 'shared_parental')),
        status TEXT NOT NULL DEFAULT 'notified' CHECK (status IN
            ('notified', 'confirmed', 'on_leave', 'returned', 'cancelled')),
        ewc TEXT,
        birth_date TEXT,
        matching_date TEXT,
        placement_date TEXT,
        qualifying_week TEXT,
        leave_start TEXT,
        leave_weeks INTEGER,
        leave_end TEXT,
        return_date TEXT,
        actual_return_date TEXT,
        statutory_weeks_used INTEGER NOT NULL DEFAULT 0,
        average_weekly_earnings REAL,
        service_start TEXT,
        leave_eligible INTEGER,
        pay_eligible INTEGER,
        eligibility_notes TEXT,
        pay_schedule TEXT,
        leave_request_id INTEGER,
        notes TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_fit_notes (
        fit_note_id INTEGER PRIMARY KEY AUTOINCREMENT,
        episode_id INTEGER NOT NULL REFERENCES staff_absence_episodes (episode_id)
            ON DELETE CASCADE,
        issued_date TEXT NOT NULL,
        from_date TEXT NOT NULL,
        to_date TEXT NOT NULL,
        assessment TEXT NOT NULL DEFAULT 'not_fit' CHECK (assessment IN
            ('not_fit', 'may_be_fit')),
        adjustments TEXT,
        condition TEXT,
        issued_by TEXT,
        document_path TEXT,
        received_by TEXT,
        received_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_flexible_working_requests (
        fw_id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        submitted_at TEXT NOT NULL DEFAULT (datetime('now')),
        change_type TEXT NOT NULL DEFAULT 'hours',
        current_pattern TEXT,
        requested_pattern TEXT NOT NULL,
        requested_days TEXT,
        requested_hours REAL,
        requested_start TEXT,
        temporary_until TEXT,
        effect_notes TEXT,
        approver TEXT,
        status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN
            ('submitted', 'meeting_scheduled', 'approved', 'approved_trial', 'rejected',
             'withdrawn', 'appealed', 'appeal_upheld', 'appeal_dismissed')),
        decision_due TEXT NOT NULL,
        extended_to TEXT,
        meeting_date TEXT,
        meeting_notes TEXT,
        consulted INTEGER NOT NULL DEFAULT 0,
        decision_by TEXT,
        decided_at TEXT,
        decision_notes TEXT,
        rejection_reason TEXT,
        trial_end TEXT,
        appeal_grounds TEXT,
        appealed_at TEXT,
        appeal_decided_by TEXT,
        appeal_decided_at TEXT,
        appeal_notes TEXT,
        contract_variation TEXT,
        varied_at TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_hr_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        at TEXT NOT NULL DEFAULT (datetime('now')),
        actor TEXT,
        action TEXT NOT NULL,
        subject_username TEXT,
        entity TEXT,
        entity_id TEXT,
        details TEXT
    );
CREATE TABLE staff_hr_check_requirements (
        job_type TEXT NOT NULL,
        check_type TEXT NOT NULL CHECK (check_type IN
            ('right_to_work', 'dbs', 'qualifications', 'health', 'references')),
        set_by TEXT,
        set_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (job_type, check_type)
    );
CREATE TABLE staff_hr_offers (
        offer_id INTEGER PRIMARY KEY AUTOINCREMENT,
        application_id INTEGER NOT NULL,
        offer_type TEXT NOT NULL DEFAULT 'conditional' CHECK (offer_type IN
            ('conditional', 'unconditional')),
        job_title TEXT,
        department TEXT,
        contract_type TEXT NOT NULL DEFAULT 'permanent',
        salary REAL,
        grade TEXT,
        fte REAL NOT NULL DEFAULT 1.0,
        start_date TEXT,
        end_date TEXT,
        probation_months INTEGER NOT NULL DEFAULT 6,
        manager_id TEXT,
        onboarding_template_id INTEGER,
        conditions TEXT,
        status TEXT NOT NULL DEFAULT 'made' CHECK (status IN
            ('made', 'accepted', 'declined', 'withdrawn', 'hired')),
        start_confirmed INTEGER NOT NULL DEFAULT 0,
        made_by TEXT,
        made_at TEXT NOT NULL DEFAULT (datetime('now')),
        responded_at TEXT,
        response_note TEXT,
        withdrawn_by TEXT,
        withdraw_reason TEXT,
        staff_username TEXT,
        contract_id INTEGER,
        hired_by TEXT,
        hired_at TEXT
    );
CREATE TABLE staff_hr_pre_employment_checks (
        check_id INTEGER PRIMARY KEY AUTOINCREMENT,
        application_id INTEGER,
        staff_username TEXT,
        check_type TEXT NOT NULL CHECK (check_type IN
            ('right_to_work', 'dbs', 'qualifications', 'health')),
        status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN
            ('pending', 'in_progress', 'cleared', 'failed', 'waived')),
        document_type TEXT,
        share_code TEXT,
        checked_by TEXT,
        check_date TEXT,
        follow_up_date TEXT,
        dbs_level TEXT CHECK (dbs_level IS NULL OR dbs_level IN
            ('basic', 'standard', 'enhanced', 'enhanced_barred')),
        certificate_number TEXT,
        issue_date TEXT,
        update_service INTEGER NOT NULL DEFAULT 0,
        recheck_date TEXT,
        details TEXT,
        notes TEXT,
        created_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (application_id, check_type)
    );
CREATE TABLE staff_hr_references (
        reference_id INTEGER PRIMARY KEY AUTOINCREMENT,
        application_id INTEGER NOT NULL,
        referee_name TEXT NOT NULL,
        referee_email TEXT,
        relationship TEXT,
        status TEXT NOT NULL DEFAULT 'requested' CHECK (status IN
            ('requested', 'received', 'declined')),
        requested_by TEXT,
        requested_at TEXT,
        received_at TEXT,
        content TEXT,
        satisfactory INTEGER,
        assessed_by TEXT,
        notes TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_hr_reminder_log (
        reminder_key TEXT NOT NULL,
        recipient TEXT NOT NULL,
        kind TEXT,
        subject_username TEXT,
        sent_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (reminder_key, recipient)
    );
CREATE TABLE staff_hr_roles (
        username TEXT NOT NULL,
        role TEXT NOT NULL CHECK (role IN ('hr_admin', 'hr_officer', 'payroll', 'recruiter')),
        granted_by TEXT,
        granted_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (username, role)
    );
CREATE TABLE staff_kit_days (
        kit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL REFERENCES staff_family_leave_cases (case_id)
            ON DELETE CASCADE,
        day TEXT NOT NULL,
        hours REAL,
        notes TEXT,
        agreed_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (case_id, day)
    );
CREATE TABLE staff_leave_entitlements (
        leave_type_id INTEGER PRIMARY KEY,
        basis TEXT NOT NULL DEFAULT 'fixed' CHECK (basis IN
            ('fte_pro_rata', 'fixed', 'absence', 'case', 'none')),
        full_time_days REAL,
        pro_rata_service INTEGER NOT NULL DEFAULT 1,
        carry_over INTEGER NOT NULL DEFAULT 0,
        carry_over_cap REAL,
        includes_bank_holidays INTEGER NOT NULL DEFAULT 0,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_leave_holidays (
        holiday_date TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        kind TEXT NOT NULL DEFAULT 'closure' CHECK (kind IN ('closure', 'bank_holiday')),
        added_by TEXT,
        added_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_leave_reminders (
        reminder_key TEXT NOT NULL,
        recipient TEXT NOT NULL,
        sent_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (reminder_key, recipient)
    );
CREATE TABLE staff_leave_settings (
        key TEXT PRIMARY KEY,
        value TEXT,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_mentoring_goals (
                    goal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    match_id INTEGER NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    target_date TEXT,
                    completion_date TEXT,
                    status TEXT DEFAULT 'in_progress',
                    progress_pct INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (match_id) REFERENCES staff_mentoring_matches(match_id)
                );
CREATE TABLE staff_mentoring_matches (
                    match_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    programme_id INTEGER NOT NULL,
                    mentor_id INTEGER NOT NULL,
                    mentee_user_id TEXT NOT NULL,
                    match_reason TEXT,
                    status TEXT DEFAULT 'proposed',
                    start_date TEXT,
                    expected_end_date TEXT,
                    actual_end_date TEXT,
                    mentor_rating INTEGER,
                    mentee_rating INTEGER,
                    notes TEXT,
                    matched_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_id) REFERENCES staff_mentoring_programmes(programme_id),
                    FOREIGN KEY (mentor_id) REFERENCES staff_mentors(mentor_id)
                );
CREATE TABLE staff_mentoring_programmes (
                    programme_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    programme_type TEXT DEFAULT 'general',
                    department TEXT,
                    max_mentees_per_mentor INTEGER DEFAULT 3,
                    duration_months INTEGER DEFAULT 12,
                    status TEXT DEFAULT 'active',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE staff_mentoring_sessions (
                    session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    match_id INTEGER NOT NULL,
                    session_date TEXT NOT NULL,
                    duration_minutes INTEGER DEFAULT 60,
                    session_type TEXT DEFAULT 'one_on_one',
                    location TEXT,
                    virtual_link TEXT,
                    topics_discussed TEXT,
                    action_items TEXT,
                    mentor_notes TEXT,
                    mentee_notes TEXT,
                    status TEXT DEFAULT 'scheduled',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (match_id) REFERENCES staff_mentoring_matches(match_id)
                );
CREATE TABLE staff_mentors (
                    mentor_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    programme_id INTEGER NOT NULL,
                    expertise_areas TEXT,
                    max_mentees INTEGER DEFAULT 3,
                    current_mentees INTEGER DEFAULT 0,
                    availability TEXT DEFAULT 'available',
                    bio TEXT,
                    status TEXT DEFAULT 'active',
                    joined_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_id) REFERENCES staff_mentoring_programmes(programme_id)
                );
CREATE TABLE staff_noticeboard (
                notice_id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT,
                category TEXT DEFAULT 'general',
                posted_by TEXT NOT NULL,
                posted_by_name TEXT,
                contact_info TEXT,
                post_date TEXT DEFAULT CURRENT_TIMESTAMP,
                expiry_date TEXT,
                is_active INTEGER DEFAULT 1,
                view_count INTEGER DEFAULT 0
            );
CREATE TABLE staff_office_hours_directory (
                    hours_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    day_of_week INTEGER NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    location TEXT,
                    virtual_link TEXT,
                    is_by_appointment INTEGER DEFAULT 0,
                    semester TEXT,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                , "office_hour_id" INTEGER);
CREATE TABLE staff_oh_referrals (
        referral_id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        episode_id INTEGER,
        referred_by TEXT NOT NULL,
        referred_at TEXT NOT NULL DEFAULT (datetime('now')),
        reason TEXT NOT NULL,
        questions TEXT,
        consent_given INTEGER NOT NULL DEFAULT 0,
        consent_at TEXT,
        provider TEXT,
        appointment_date TEXT,
        status TEXT NOT NULL DEFAULT 'awaiting_consent' CHECK (status IN
            ('awaiting_consent', 'referred', 'appointment_booked', 'report_received',
             'closed', 'declined')),
        fitness TEXT CHECK (fitness IS NULL OR fitness IN
            ('fit', 'fit_with_adjustments', 'temporarily_unfit', 'long_term_unfit')),
        adjustments TEXT,
        outcome TEXT,
        report_received_at TEXT,
        review_date TEXT,
        closed_by TEXT,
        closed_at TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_performance (
                performance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_id INTEGER,
                punctuality_score INTEGER DEFAULT 5,
                quality_score INTEGER DEFAULT 5,
                efficiency_score INTEGER DEFAULT 5,
                teamwork_score INTEGER DEFAULT 5,
                overall_score REAL DEFAULT 5.0,
                evaluation_date DATE DEFAULT CURRENT_DATE,
                notes TEXT,
                FOREIGN KEY (staff_id) REFERENCES restaurant_staff(staff_id)
            );
CREATE TABLE staff_profiles (
                profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT UNIQUE NOT NULL,
                employee_id TEXT UNIQUE,
                department TEXT,
                job_title TEXT,
                employment_type TEXT DEFAULT 'full-time',
                hire_date TEXT,
                contract_end_date TEXT,
                manager_id TEXT,
                office_location TEXT,
                phone_extension TEXT,
                emergency_contact_name TEXT,
                emergency_contact_phone TEXT,
                emergency_contact_relationship TEXT,
                bio TEXT,
                expertise_areas TEXT,
                qualifications TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            , "date_of_birth" TEXT, "nationality" TEXT);
CREATE TABLE staff_recruitment_applications (
                application_id INTEGER PRIMARY KEY AUTOINCREMENT,
                posting_id INTEGER NOT NULL,
                job_title TEXT,
                applicant_name TEXT NOT NULL,
                applicant_email TEXT NOT NULL,
                applicant_phone TEXT,
                applicant_address TEXT,
                cv_path TEXT,
                cover_letter_path TEXT,
                portfolio_url TEXT,
                application_date TEXT DEFAULT CURRENT_TIMESTAMP,
                status TEXT DEFAULT 'received',
                shortlisted INTEGER DEFAULT 0,
                shortlisted_by TEXT,
                shortlisted_date TEXT,
                rejection_reason TEXT,
                notes TEXT, "hired_username" TEXT,
                FOREIGN KEY (posting_id) REFERENCES staff_recruitment_postings(posting_id)
            );
CREATE TABLE staff_recruitment_interviews (
        interview_id INTEGER PRIMARY KEY AUTOINCREMENT,
        application_id INTEGER NOT NULL
            REFERENCES staff_recruitment_applications (application_id) ON DELETE CASCADE,
        applicant_name TEXT,
        interview_type TEXT NOT NULL DEFAULT 'in-person',
        interview_round INTEGER DEFAULT 1,
        interview_date TEXT NOT NULL,
        interview_time TEXT NOT NULL,
        duration_minutes INTEGER DEFAULT 60,
        location TEXT,
        video_link TEXT,
        interviewers TEXT,
        status TEXT DEFAULT 'scheduled',
        feedback TEXT,
        strengths TEXT,
        concerns TEXT,
        recommendation TEXT,
        overall_score INTEGER,
        notes TEXT,
        scheduled_by TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE staff_recruitment_postings (
                posting_id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_title TEXT NOT NULL,
                department TEXT NOT NULL,
                job_type TEXT DEFAULT 'permanent',
                location TEXT,
                description TEXT,
                requirements TEXT,
                responsibilities TEXT,
                salary_range TEXT,
                benefits TEXT,
                posted_by TEXT NOT NULL,
                posted_by_name TEXT,
                post_date TEXT,
                closing_date TEXT,
                status TEXT DEFAULT 'draft',
                hiring_manager_id TEXT,
                hiring_manager_name TEXT,
                applications_count INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE staff_retention_holds (
        hold_id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        reason TEXT NOT NULL,
        placed_by TEXT,
        placed_at TEXT NOT NULL DEFAULT (datetime('now')),
        released_by TEXT,
        released_at TEXT
    );
CREATE TABLE staff_retention_policies (
        record_type TEXT PRIMARY KEY,
        label TEXT NOT NULL,
        keep_months INTEGER NOT NULL CHECK (keep_months >= 0),
        trigger TEXT NOT NULL,
        action TEXT NOT NULL DEFAULT 'anonymise' CHECK (action IN ('anonymise', 'delete')),
        enabled INTEGER NOT NULL DEFAULT 0,
        updated_by TEXT,
        updated_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE staff_retention_runs (
        run_id INTEGER PRIMARY KEY AUTOINCREMENT,
        at TEXT NOT NULL DEFAULT (datetime('now')),
        actor TEXT,
        record_type TEXT NOT NULL,
        table_name TEXT NOT NULL,
        action TEXT NOT NULL,
        rows_affected INTEGER NOT NULL DEFAULT 0,
        details TEXT
    );
CREATE TABLE staff_rtw_interviews (
        rtw_id INTEGER PRIMARY KEY AUTOINCREMENT,
        episode_id INTEGER NOT NULL UNIQUE REFERENCES staff_absence_episodes (episode_id)
            ON DELETE CASCADE,
        interview_date TEXT NOT NULL,
        conducted_by TEXT NOT NULL,
        fit_to_return INTEGER NOT NULL DEFAULT 1,
        adjustments_agreed TEXT,
        support_offered TEXT,
        wellbeing_notes TEXT,
        triggers_discussed INTEGER NOT NULL DEFAULT 0,
        oh_referral_recommended INTEGER NOT NULL DEFAULT 0,
        employee_comments TEXT,
        employee_confirmed INTEGER NOT NULL DEFAULT 0,
        employee_confirmed_at TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_schedules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_id TEXT NOT NULL,
                shift_date DATE NOT NULL,
                start_time TIME NOT NULL,
                end_time TIME NOT NULL,
                position TEXT NOT NULL,
                status TEXT DEFAULT 'scheduled',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , "day_of_week" INTEGER, "effective_from" TEXT, "effective_to" TEXT, "is_recurring" INTEGER DEFAULT 1, "location" TEXT, "notes" TEXT, "schedule_type" TEXT DEFAULT 'office_hours', "user_id" TEXT, "schedule_id" INTEGER);
CREATE TABLE staff_working_patterns (
        user_id TEXT PRIMARY KEY,
        work_days TEXT NOT NULL DEFAULT '0,1,2,3,4',
        hours_per_week REAL,
        fte REAL,
        effective_from TEXT,
        source TEXT,
        updated_by TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE staff_workload (
                workload_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                academic_year TEXT NOT NULL,
                semester TEXT,
                teaching_hours REAL DEFAULT 0,
                research_hours REAL DEFAULT 0,
                admin_hours REAL DEFAULT 0,
                service_hours REAL DEFAULT 0,
                total_fte REAL DEFAULT 1.0,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(user_id, academic_year, semester)
            );
CREATE TABLE stage_submissions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        stage_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        content TEXT,
                        file_path TEXT,
                        status TEXT NOT NULL DEFAULT 'draft',
                        feedback TEXT,
                        submitted_at TEXT,
                        reviewed_at TEXT, "reviewed_by" TEXT, "score" INTEGER,
                        FOREIGN KEY (stage_id) REFERENCES assignment_stages(id)
                    );
CREATE TABLE statement_runs (
            run_id            INTEGER PRIMARY KEY AUTOINCREMENT,
            period_start      TEXT,
            period_end        TEXT NOT NULL,
            generated_at      TEXT NOT NULL DEFAULT (datetime('now')),
            generated_by      TEXT,
            status            TEXT NOT NULL DEFAULT 'completed',
            total_students    INTEGER NOT NULL DEFAULT 0,
            total_with_balance INTEGER NOT NULL DEFAULT 0
        );
CREATE TABLE stored_emails (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            recipient_email TEXT NOT NULL,
            subject TEXT NOT NULL,
            body TEXT NOT NULL,
            sender_email TEXT NOT NULL,
            sender_name TEXT NOT NULL,
            cc_recipients TEXT,
            bcc_recipients TEXT,
            attachment_paths TEXT,
            created_date TEXT NOT NULL,
            template_name TEXT,
            template_vars TEXT,
            related_to TEXT,
            student_id TEXT
        );
CREATE TABLE sts_actions (
        action_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL REFERENCES sts_cases (case_id),
        stage INTEGER NOT NULL,
        action_text TEXT NOT NULL,
        owner TEXT NOT NULL DEFAULT 'student',
        due_date TEXT,
        status TEXT NOT NULL DEFAULT 'open',
        notes TEXT,
        created_by TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        completed_at TEXT
    );
CREATE TABLE sts_cases (
        case_id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        stage INTEGER NOT NULL DEFAULT 1 CHECK (stage BETWEEN 1 AND 3),
        status TEXT NOT NULL DEFAULT 'open',
        reason TEXT,
        case_manager TEXT,
        opened_by TEXT NOT NULL,
        opened_at TEXT NOT NULL DEFAULT (datetime('now')),
        closed_by TEXT,
        closed_at TEXT,
        closed_reason TEXT,
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE sts_letters (
        letter_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL REFERENCES sts_cases (case_id),
        kind TEXT NOT NULL,
        ref_id INTEGER,
        path TEXT NOT NULL,
        created_by TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE sts_links (
        link_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL REFERENCES sts_cases (case_id),
        kind TEXT NOT NULL,
        ref_id TEXT NOT NULL,
        note TEXT,
        linked_by TEXT NOT NULL,
        linked_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (case_id, kind, ref_id)
    );
CREATE TABLE sts_meetings (
        meeting_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL REFERENCES sts_cases (case_id),
        stage INTEGER NOT NULL,
        meeting_date TEXT NOT NULL,
        meeting_time TEXT,
        location TEXT,
        attendees TEXT,
        panel_members TEXT,
        supporter TEXT,
        status TEXT NOT NULL DEFAULT 'scheduled',
        student_attended INTEGER,
        summary TEXT,
        scheduled_by TEXT NOT NULL,
        recorded_by TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE sts_outcomes (
        outcome_id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL REFERENCES sts_cases (case_id),
        stage INTEGER NOT NULL,
        outcome_type TEXT NOT NULL,
        decision TEXT,
        review_date TEXT,
        lifecycle_history_id INTEGER,
        expected_return_date TEXT,
        decided_by TEXT NOT NULL,
        decided_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE sts_stage_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        case_id INTEGER NOT NULL REFERENCES sts_cases (case_id),
        from_stage INTEGER,
        to_stage INTEGER NOT NULL,
        reason TEXT,
        changed_by TEXT NOT NULL,
        changed_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE student_absences (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                absence_date TEXT,
                return_date TEXT,
                reason TEXT,
                reported_by TEXT,
                reported_date TEXT,
                notes TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE student_accommodations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    accommodation_type TEXT NOT NULL CHECK(accommodation_type IN ('extended_time','alt_format','screen_reader','large_text','other')),
                    details TEXT,
                    time_multiplier REAL DEFAULT 1.0,
                    is_active INTEGER DEFAULT 1,
                    approved_by TEXT,
                    created_at TEXT DEFAULT (datetime('now')),
                    expires_at TEXT
                , "created_by" TEXT, "expiry_date" TEXT, "updated_at" TEXT, "source_accommodation_id" INTEGER);
CREATE TABLE student_activities (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                activity_id INTEGER,
                enrollment_date TEXT,
                status TEXT DEFAULT 'active', "activity_name" TEXT, "end_date" TEXT, "role" TEXT, "start_date" TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (activity_id) REFERENCES extracurricular_activities (id)
            );
CREATE TABLE "student_answers" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            submission_id INTEGER,
            answer_text TEXT,
            is_correct INTEGER DEFAULT 0,
            points_earned REAL DEFAULT 0,
            time_spent_seconds INTEGER,
            answered_at TEXT DEFAULT CURRENT_TIMESTAMP, "feedback" REAL, "graded" TEXT, "graded_at" TEXT,
            FOREIGN KEY (question_id) REFERENCES questions (id) ON DELETE CASCADE,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE
        );
CREATE TABLE student_app_notifications (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    notification_type TEXT DEFAULT 'announcement',
                    title TEXT NOT NULL,
                    message TEXT,
                    is_read INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    expires_at TEXT
                );
CREATE TABLE student_app_preferences (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT UNIQUE NOT NULL,
                    theme TEXT DEFAULT 'light',
                    notifications_enabled INTEGER DEFAULT 1,
                    language TEXT DEFAULT 'en',
                    dashboard_layout TEXT,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE student_attendance(
  student_id TEXT,
  module_code TEXT,
  date TEXT,
  status TEXT,
  notes TEXT,
  recorded_at TEXT
);
CREATE TABLE student_badges (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            badge_id INTEGER,
            earned_date TEXT, "awarded_at" TEXT, "awarded_by" TEXT, "is_displayed" INTEGER DEFAULT 0, "reason" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (badge_id) REFERENCES achievement_badges (badge_id)
        );
CREATE TABLE student_behavior (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                incident_date TEXT,
                behavior_type TEXT,
                severity TEXT,
                description TEXT,
                action_taken TEXT,
                reported_by TEXT,
                follow_up_required BOOLEAN DEFAULT 0,
                resolved BOOLEAN DEFAULT 0,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE student_biometrics (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            face_encoding BLOB,
            face_photo_path TEXT,
            enrolled_date TEXT DEFAULT CURRENT_TIMESTAMP,
            last_updated TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'active',
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE student_budget_categories (
                        category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        budget_id INTEGER NOT NULL,
                        category_name TEXT NOT NULL,
                        category_type TEXT CHECK(category_type IN ('essential', 'discretionary', 'savings', 'debt')),
                        allocated_amount REAL NOT NULL,
                        spent_amount REAL DEFAULT 0.0,
                        color_code TEXT,
                        icon TEXT,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        UNIQUE(budget_id, category_name)
                    );
CREATE TABLE student_budgets (
                        budget_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        budget_name TEXT NOT NULL,
                        budget_type TEXT CHECK(budget_type IN ('monthly', 'weekly', 'semester', 'annual', 'custom')),
                        start_date TEXT NOT NULL,
                        end_date TEXT NOT NULL,
                        total_income REAL DEFAULT 0.0,
                        total_budget REAL NOT NULL,
                        allocated_amount REAL DEFAULT 0.0,
                        spent_amount REAL DEFAULT 0.0,
                        is_active BOOLEAN DEFAULT 1,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "semester" TEXT,
                        FOREIGN KEY (student_id) REFERENCES students(student_id)
                    );
CREATE TABLE student_charges (
            charge_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            registration_id INTEGER,
            charge_type TEXT NOT NULL,
            currency TEXT NOT NULL,
            amount_minor INTEGER NOT NULL CHECK (amount_minor >= 0),
            due_at TEXT,
            status TEXT NOT NULL DEFAULT 'open',
            source_type TEXT NOT NULL,
            source_id TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (source_type, source_id),
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (registration_id)
                REFERENCES programme_registrations(registration_id)
        );
CREATE TABLE student_clubs (
                    club_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    club_name TEXT UNIQUE NOT NULL,
                    description TEXT,
                    category TEXT,
                    member_count INTEGER DEFAULT 0,
                    president_id TEXT,
                    treasurer_id TEXT,
                    secretary_id TEXT,
                    status TEXT DEFAULT 'active',
                    created_date TEXT, "budget" REAL DEFAULT 0.0, "founding_date" TEXT,
                    FOREIGN KEY (president_id) REFERENCES students (student_id),
                    FOREIGN KEY (treasurer_id) REFERENCES students (student_id),
                    FOREIGN KEY (secretary_id) REFERENCES students (student_id)
                );
CREATE TABLE student_competencies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            competency_id INTEGER NOT NULL,
            level_id INTEGER NOT NULL,
            assessment_date TEXT,
            evidence TEXT,
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (competency_id) REFERENCES competencies(competency_id),
            FOREIGN KEY (level_id) REFERENCES competency_levels(level_id)
        );
CREATE TABLE "student_credits" (
            credit_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            credit_amount DECIMAL(10,2) NOT NULL,
            currency TEXT DEFAULT 'GBP',
            credit_source TEXT, -- 'overpayment', 'refund', 'scholarship', 'adjustment'
            description TEXT,
            expiry_date TEXT,
            remaining_amount DECIMAL(10,2) NOT NULL,
            status TEXT DEFAULT 'active', -- active, used, expired
            created_by TEXT,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE student_degree_progress (
                progress_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                program_id INTEGER NOT NULL,
                enrollment_year INTEGER NOT NULL,
                total_credits_earned INTEGER DEFAULT 0,
                current_gpa REAL DEFAULT 0.0,
                completion_percentage REAL DEFAULT 0.0,
                expected_graduation_date TEXT,
                last_updated TEXT NOT NULL DEFAULT (datetime('now')), "status" TEXT DEFAULT 'in_progress',
                FOREIGN KEY (program_id) REFERENCES degree_programs(program_id),
                UNIQUE(student_id, program_id)
            );
CREATE TABLE student_demographics (
                student_id TEXT PRIMARY KEY,
                age_group TEXT,
                gender TEXT,
                ethnicity TEXT,
                native_language TEXT,
                academic_level TEXT,
                accommodations TEXT
            );
CREATE TABLE student_disabilities (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            category TEXT NOT NULL,
            details TEXT,
            adjustment_type TEXT,
            adjustment_request_id INTEGER,
            source TEXT NOT NULL DEFAULT 'student',
            status TEXT NOT NULL DEFAULT 'active',
            declared_by TEXT,
            declared_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (student_id) REFERENCES students(student_id)
        );
CREATE TABLE student_duplicate_reviews (
        student_a TEXT NOT NULL,
        student_b TEXT NOT NULL,
        decision TEXT NOT NULL CHECK (decision IN ('not_duplicate', 'duplicate')),
        note TEXT,
        reviewed_by TEXT NOT NULL,
        reviewed_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (student_a, student_b)
    );
CREATE TABLE "student_employment" (
                        employment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        job_id INTEGER NOT NULL,
                        application_id INTEGER,
                        start_date TEXT NOT NULL,
                        end_date TEXT,
                        employment_status TEXT DEFAULT 'active' CHECK(employment_status IN ('active', 'on-leave', 'completed', 'terminated')),
                        hourly_rate REAL NOT NULL,
                        max_hours_per_week INTEGER,
                        supervisor_id INTEGER,
                        department TEXT,
                        position_title TEXT NOT NULL,
                        is_work_study BOOLEAN DEFAULT 0,
                        work_study_allocation REAL DEFAULT 0.0,
                        work_study_used REAL DEFAULT 0.0,
                        performance_rating REAL,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (job_id) REFERENCES campus_job_postings(job_id) ON DELETE CASCADE,
                        FOREIGN KEY (application_id) REFERENCES campus_job_applications(application_id) ON DELETE CASCADE
                    );
CREATE TABLE student_erasure_requests (
        request_id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        case_reference TEXT NOT NULL,
        reason TEXT NOT NULL,
        requested_by TEXT NOT NULL,
        requested_at TEXT NOT NULL DEFAULT (datetime('now')),
        impact_json TEXT,
        status TEXT NOT NULL DEFAULT 'requested'
            CHECK (status IN ('requested', 'approved', 'rejected', 'completed')),
        decided_by TEXT,
        decided_at TEXT,
        decision_note TEXT,
        completed_by TEXT,
        completed_at TEXT
    );
CREATE TABLE student_expenses (
                        expense_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        budget_id INTEGER,
                        category_id INTEGER,
                        expense_date TEXT NOT NULL,
                        amount REAL NOT NULL,
                        merchant_name TEXT,
                        description TEXT,
                        payment_method TEXT CHECK(payment_method IN ('cash', 'debit', 'credit', 'meal-plan', 'financial-aid', 'other')),
                        receipt_url TEXT,
                        is_recurring BOOLEAN DEFAULT 0,
                        recurrence_pattern TEXT,
                        tags TEXT,
                        location TEXT,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (budget_id) REFERENCES student_budgets(budget_id),
                        FOREIGN KEY (category_id) REFERENCES budget_categories(category_id)
                    );
CREATE TABLE student_fees (
            student_fee_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            fee_type_id INTEGER NOT NULL,
            amount DECIMAL(10,2) NOT NULL,
            currency TEXT DEFAULT 'GBP',
            status TEXT DEFAULT 'unpaid',
            due_date TEXT,
            last_reminder_sent TEXT,
            reminder_count INTEGER DEFAULT 0,
            created_at TEXT,
            updated_at TEXT, "description" TEXT, "fee_type" TEXT, "payment_status" TEXT DEFAULT 'pending', "paid_date" TEXT, "payment_method" TEXT, "transaction_id" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (fee_type_id) REFERENCES fee_types (fee_type_id)
        );
CREATE TABLE student_finance_accounts (
    account_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT UNIQUE NOT NULL,
    balance DECIMAL(10,2) DEFAULT 0.00,
    currency TEXT DEFAULT 'GBP',
    account_status TEXT DEFAULT 'active',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, "account_type" TEXT, "total_charges" REAL, "total_payments" REAL);
CREATE TABLE student_finance_transactions (
            transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            account_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            transaction_type TEXT NOT NULL,
            amount DECIMAL(10,2) NOT NULL,
            balance_before DECIMAL(10,2),
            balance_after DECIMAL(10,2),
            description TEXT,
            reference_id TEXT,
            processed_by TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (account_id) REFERENCES student_finance_accounts(account_id),
            FOREIGN KEY (student_id) REFERENCES students(student_id)
        );
CREATE TABLE student_financial_aid (
            aid_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            aid_type_id INTEGER NOT NULL,
            awarded_amount DECIMAL(10,2) NOT NULL,
            disbursed_amount DECIMAL(10,2) DEFAULT 0,
            remaining_amount DECIMAL(10,2) NOT NULL,
            currency TEXT DEFAULT 'GBP',
            status TEXT DEFAULT 'pending', -- pending, approved, disbursed, completed, cancelled
            application_date TEXT,
            approval_date TEXT,
            disbursement_schedule TEXT, -- JSON with disbursement dates and amounts
            repayment_start_date TEXT,
            monthly_payment_amount DECIMAL(10,2),
            total_repaid DECIMAL(10,2) DEFAULT 0,
            approved_by TEXT,
            notes TEXT,
            created_at TEXT,
            updated_at TEXT, "aid_type" TEXT, "amount" REAL, "academic_year" INTEGER,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (aid_type_id) REFERENCES financial_aid_types (aid_type_id)
        );
CREATE TABLE student_followups (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        reason TEXT NOT NULL,
        priority TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('high', 'medium', 'low')),
        due_on TEXT,
        assigned_to TEXT,
        status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'done')),
        created_by TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        closed_by TEXT,
        closed_at TEXT,
        outcome TEXT
    );
CREATE TABLE student_grades (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            assessment_name TEXT,
            grade TEXT,
            grade_date TEXT, "assessment_date" TEXT, "assessment_type" TEXT, "comments" TEXT, "created_at" TEXT DEFAULT CURRENT_TIMESTAMP, "grade_id" INTEGER, "grade_value" TEXT, "instructor" TEXT, "is_final" BOOLEAN DEFAULT 0, "module_id" TEXT, "percentage" DECIMAL(5,2), "updated_at" TEXT DEFAULT CURRENT_TIMESTAMP, "weight" DECIMAL(5,2), "import_date" TEXT, "semester" TEXT, "year" TEXT, "credits" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE student_graduation_forecasts (
                    forecast_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    program_code TEXT NOT NULL,
                    estimated_graduation_date TEXT,
                    estimated_semester TEXT,
                    remaining_credits INTEGER DEFAULT 0,
                    required_semesters INTEGER DEFAULT 0,
                    on_track BOOLEAN DEFAULT 1,
                    delay_reasons_json TEXT,
                    acceleration_options_json TEXT,
                    confidence_level REAL DEFAULT 0.0,
                    last_calculated TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(student_id)
                );
CREATE TABLE student_id_cards (
                    card_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL UNIQUE,
                    card_number TEXT NOT NULL,
                    issue_date TEXT DEFAULT (date('now')),
                    expiry_date TEXT,
                    status TEXT DEFAULT 'active',
                    photo_path TEXT DEFAULT '',
                    qr_data TEXT DEFAULT ''
                , "created_at" TEXT);
CREATE TABLE student_identity_changes (
            change_id TEXT PRIMARY KEY, student_id TEXT NOT NULL,
            change_type TEXT NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL,
            reason TEXT NOT NULL, requested_by TEXT NOT NULL, approved_by TEXT NOT NULL,
            reversed_at TEXT, reversed_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE student_identity_merges (
            merge_id TEXT PRIMARY KEY, survivor_id TEXT NOT NULL, merged_id TEXT NOT NULL UNIQUE,
            reason TEXT NOT NULL, requested_by TEXT NOT NULL, approved_by TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'active', reversed_at TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE student_income (
                        income_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        budget_id INTEGER,
                        income_date TEXT NOT NULL,
                        amount REAL NOT NULL,
                        source TEXT NOT NULL,
                        income_type TEXT CHECK(income_type IN ('work-study', 'scholarship', 'grant', 'loan', 'family', 'job', 'investment', 'other')),
                        description TEXT,
                        is_recurring BOOLEAN DEFAULT 0,
                        recurrence_pattern TEXT,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (budget_id) REFERENCES student_budgets(budget_id)
                    );
CREATE TABLE "student_job_performance" (
                        review_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        employment_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        reviewer_id INTEGER NOT NULL,
                        review_date TEXT NOT NULL,
                        review_period_start TEXT,
                        review_period_end TEXT,
                        attendance_rating INTEGER CHECK(attendance_rating BETWEEN 1 AND 5),
                        quality_rating INTEGER CHECK(quality_rating BETWEEN 1 AND 5),
                        initiative_rating INTEGER CHECK(initiative_rating BETWEEN 1 AND 5),
                        teamwork_rating INTEGER CHECK(teamwork_rating BETWEEN 1 AND 5),
                        overall_rating REAL,
                        strengths TEXT,
                        areas_for_improvement TEXT,
                        supervisor_comments TEXT,
                        student_comments TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (employment_id) REFERENCES student_employment(employment_id) ON DELETE CASCADE,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (reviewer_id) REFERENCES users(id) ON DELETE CASCADE
                    );
CREATE TABLE student_lifecycle_actions (
            action_id INTEGER PRIMARY KEY AUTOINCREMENT,
            history_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            target_system TEXT NOT NULL,
            action TEXT NOT NULL,
            payload_json TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending',
            attempts INTEGER NOT NULL DEFAULT 0,
            last_error TEXT,
            completed_at TEXT,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(history_id, target_system),
            FOREIGN KEY (history_id)
                REFERENCES student_lifecycle_history(history_id) ON DELETE CASCADE
        );
CREATE TABLE student_lifecycle_consumer_receipts (
            action_id INTEGER NOT NULL,
            target_system TEXT NOT NULL,
            handler_version INTEGER NOT NULL,
            outcome TEXT NOT NULL,
            processed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY(action_id, target_system, handler_version),
            FOREIGN KEY(action_id) REFERENCES student_lifecycle_actions(action_id)
        );
CREATE TABLE student_lifecycle_corrections (
            correction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            history_id INTEGER NOT NULL, reversal_history_id INTEGER,
            reason TEXT NOT NULL, requested_by TEXT NOT NULL,
            approved_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(history_id), FOREIGN KEY(history_id) REFERENCES student_lifecycle_history(history_id)
        );
CREATE TABLE student_lifecycle_history (
            history_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            action TEXT NOT NULL,
            from_status TEXT,
            to_status TEXT,
            effective_date TEXT NOT NULL,
            academic_year TEXT,
            old_programme TEXT,
            new_programme TEXT,
            old_mode TEXT,
            new_mode TEXT,
            old_campus TEXT,
            new_campus TEXT,
            repeat_year INTEGER,
            expected_return_date TEXT,
            reason TEXT NOT NULL,
            actor_id TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students(student_id)
        );
CREATE TABLE student_meal_plans (
                        student_id TEXT PRIMARY KEY,
                        student_name TEXT,
                        plan_type TEXT,
                        balance REAL,
                        plan_start_date DATE,
                        plan_end_date DATE,
                        is_active BOOLEAN DEFAULT 1
                    );
CREATE TABLE student_medical_info (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                condition_type TEXT,
                description TEXT,
                medication_name TEXT,
                dosage TEXT,
                administration_time TEXT,
                emergency_contact TEXT,
                doctor_contact TEXT,
                expiry_date TEXT,
                notes TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE student_milestone_progress (
                    progress_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    milestone_id INTEGER NOT NULL,
                    achieved BOOLEAN DEFAULT 0,
                    achieved_date TEXT,
                    achieved_semester INTEGER,
                    notes TEXT,
                    FOREIGN KEY (milestone_id) REFERENCES degree_milestones(milestone_id),
                    UNIQUE(student_id, milestone_id)
                );
CREATE TABLE student_modules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            enrollment_date TEXT DEFAULT (date('now')),
            status TEXT DEFAULT 'Enrolled', module_type TEXT DEFAULT 'Standard', module_name TEXT, grade TEXT, completion_date TEXT, "credits_earned" INTEGER DEFAULT 0, "enrollment_id" INTEGER, "module_id" TEXT, "semester" TEXT, "year" TEXT, "created_at" TIMESTAMP DEFAULT NULL, section_id INTEGER,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code),
            UNIQUE(student_id, module_code)
        );
CREATE TABLE student_payment_plans (
            payment_plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            template_id INTEGER,
            total_amount DECIMAL(10,2) NOT NULL,
            remaining_amount DECIMAL(10,2) NOT NULL,
            currency TEXT DEFAULT 'GBP',
            status TEXT DEFAULT 'active', -- active, completed, defaulted, cancelled
            start_date TEXT NOT NULL,
            next_due_date TEXT,
            setup_fee_paid BOOLEAN DEFAULT 0,
            auto_payment_enabled BOOLEAN DEFAULT 0,
            payment_method_id INTEGER,
            notes TEXT,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (template_id) REFERENCES payment_plan_templates (template_id)
        );
CREATE TABLE "student_points" (
            points_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            points_earned INTEGER,
            points_spent INTEGER DEFAULT 0,
            current_balance INTEGER,
            activity_type TEXT,
            activity_description TEXT,
            earned_date TEXT
        );
CREATE TABLE student_quick_links (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    link_title TEXT NOT NULL,
                    link_url TEXT NOT NULL,
                    display_order INTEGER DEFAULT 0,
                    is_active INTEGER DEFAULT 1
                );
CREATE TABLE student_record_changes (
        change_id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        field TEXT NOT NULL,
        old_value TEXT,
        new_value TEXT,
        reason TEXT NOT NULL,
        actor_id TEXT,
        changed_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE student_registrations (
            registration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            academic_year TEXT NOT NULL,
            registration_type TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'completed',
            mode_of_study TEXT,
            programme_code TEXT,
            campus_code TEXT,
            registered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            registered_by TEXT,
            declarations_json TEXT NOT NULL DEFAULT '{}', regulation_version_id INTEGER,
            UNIQUE(student_id, academic_year),
            FOREIGN KEY (student_id) REFERENCES students(student_id)
        );
CREATE TABLE student_regulation_assignments (
    assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    programme_id INTEGER NOT NULL,
    version_id INTEGER NOT NULL,
    assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    assigned_by TEXT NOT NULL,
    reason TEXT NOT NULL,
    active INTEGER NOT NULL DEFAULT 1,
    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id),
    FOREIGN KEY (version_id) REFERENCES programme_versions(version_id)
);
CREATE TABLE student_report_schedules (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        owner TEXT NOT NULL,
        name TEXT NOT NULL,
        saved_search_id INTEGER REFERENCES student_saved_searches(id) ON DELETE CASCADE,
        frequency TEXT NOT NULL CHECK (frequency IN ('daily', 'weekly', 'monthly')),
        recipients TEXT NOT NULL,
        fields_json TEXT,
        active INTEGER NOT NULL DEFAULT 1,
        next_run_on TEXT NOT NULL,
        last_run_at TEXT,
        last_result TEXT,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE student_requirement_progress (
                    id TEXT PRIMARY KEY,
                    student_id TEXT NOT NULL,
                    requirement_id TEXT NOT NULL,
                    credits_completed REAL DEFAULT 0.0,
                    completion_percentage REAL DEFAULT 0.0,
                    status TEXT DEFAULT 'in_progress',
                    completion_date TEXT,
                    notes TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id),
                    FOREIGN KEY (requirement_id) REFERENCES graduation_requirements (id),
                    UNIQUE(student_id, requirement_id)
                );
CREATE TABLE student_resumes (
            resume_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            resume_name TEXT NOT NULL,
            file_url TEXT NOT NULL,
            template_used TEXT,
            is_primary BOOLEAN DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE student_review_flags (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                submission_id INTEGER,
                reason TEXT NOT NULL,
                severity TEXT NOT NULL,
                flagged_by TEXT,
                flagged_at TEXT NOT NULL,
                status TEXT DEFAULT 'active',
                resolved_at TEXT,
                resolved_by TEXT,
                resolution_notes TEXT
            );
CREATE TABLE student_risk_assessment (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            risk_score REAL NOT NULL,
            risk_level TEXT NOT NULL,
            assessment_date TEXT,
            prediction_model TEXT,
            confidence REAL,
            FOREIGN KEY (student_id) REFERENCES students(student_id)
        );
CREATE TABLE student_saved_searches (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        owner TEXT NOT NULL,
        name TEXT NOT NULL,
        criteria_json TEXT NOT NULL,
        shared INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (owner, name)
    );
CREATE TABLE student_scholarship_applications (
                        application_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        scholarship_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        application_date TEXT DEFAULT (date('now')),
                        deadline_date TEXT NOT NULL,
                        status TEXT DEFAULT 'draft' CHECK(status IN ('draft', 'in-progress', 'submitted', 'under-review', 'finalist', 'awarded', 'denied', 'withdrawn')),
                        match_score REAL,
                        estimated_competition TEXT,
                        essay_completed BOOLEAN DEFAULT 0,
                        recommendations_obtained INTEGER DEFAULT 0,
                        recommendations_required INTEGER DEFAULT 0,
                        transcript_uploaded BOOLEAN DEFAULT 0,
                        documents_completed BOOLEAN DEFAULT 0,
                        application_progress REAL DEFAULT 0.0,
                        submission_date TEXT,
                        notification_received BOOLEAN DEFAULT 0,
                        notification_date TEXT,
                        award_amount REAL,
                        award_accepted BOOLEAN DEFAULT 0,
                        acceptance_date TEXT,
                        decline_reason TEXT,
                        notes TEXT,
                        reminder_sent BOOLEAN DEFAULT 0,
                        last_reminder_date TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (scholarship_id) REFERENCES scholarship_opportunities(scholarship_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        UNIQUE(scholarship_id, student_id)
                    );
CREATE TABLE student_scholarship_profiles (
                        profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL UNIQUE,
                        citizenship_status TEXT,
                        state_residency TEXT,
                        ethnicity TEXT,
                        gender TEXT,
                        first_generation BOOLEAN DEFAULT 0,
                        military_affiliation TEXT,
                        disability_status TEXT,
                        financial_need_level TEXT CHECK(financial_need_level IN ('none', 'low', 'moderate', 'high', 'exceptional')),
                        intended_career_field TEXT,
                        community_service_hours INTEGER DEFAULT 0,
                        leadership_positions TEXT,
                        academic_honors TEXT,
                        extracurricular_activities TEXT,
                        special_talents TEXT,
                        languages_spoken TEXT,
                        study_abroad_interest BOOLEAN DEFAULT 0,
                        research_interest BOOLEAN DEFAULT 0,
                        preferred_scholarship_types TEXT,
                        minimum_award_amount REAL,
                        willing_to_write_essays BOOLEAN DEFAULT 1,
                        max_recommendation_letters INTEGER DEFAULT 3,
                        profile_completeness REAL DEFAULT 0.0,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id)
                    );
CREATE TABLE student_scholarships (
            student_scholarship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            scholarship_id INTEGER NOT NULL,
            amount DECIMAL(10,2) NOT NULL,
            status TEXT DEFAULT 'active',
            awarded_date TEXT,
            created_at TEXT, "amount_awarded" REAL, "award_date" TEXT, "at_risk_checked_at" TEXT, "at_risk_last_notified_at" TEXT, "at_risk_pct" TEXT, "updated_at" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (scholarship_id) REFERENCES scholarships (scholarship_id)
        );
CREATE TABLE student_search_audit (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        actor TEXT NOT NULL,
        action TEXT NOT NULL CHECK (action IN ('search', 'export', 'bulk', 'report')),
        criteria_json TEXT,
        result_count INTEGER,
        detail TEXT,
        at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE student_search_favourites (
        owner TEXT NOT NULL,
        student_id TEXT NOT NULL,
        note TEXT,
        added_at TEXT NOT NULL DEFAULT (datetime('now')),
        PRIMARY KEY (owner, student_id)
    );
CREATE TABLE "student_skills" ( skill_id INTEGER PRIMARY KEY AUTOINCREMENT, student_id TEXT NOT NULL, skill_name TEXT NOT NULL, skill_category TEXT CHECK(skill_category IN (  'technical', 'soft_skill', 'language', 'tool', 'domain' )), proficiency_level TEXT CHECK(proficiency_level IN (  'beginner', 'intermediate', 'advanced', 'expert' )), years_experience REAL, is_featured BOOLEAN DEFAULT 0, added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "acquired_date" TEXT, "verified" BOOLEAN DEFAULT 0, "verified_by" INTEGER, "verified_date" TEXT, "created_at" TIMESTAMP, UNIQUE(student_id, skill_name));
CREATE TABLE student_statements (
            statement_id        INTEGER PRIMARY KEY AUTOINCREMENT,
            run_id              INTEGER NOT NULL REFERENCES statement_runs(run_id) ON DELETE CASCADE,
            student_id          TEXT    NOT NULL,
            period_start        TEXT,
            period_end          TEXT    NOT NULL,
            opening_balance     REAL    NOT NULL DEFAULT 0,
            charges_in_period   REAL    NOT NULL DEFAULT 0,
            payments_in_period  REAL    NOT NULL DEFAULT 0,
            refunds_in_period   REAL    NOT NULL DEFAULT 0,
            closing_balance     REAL    NOT NULL DEFAULT 0
        );
CREATE TABLE student_supervisions (
                supervision_id INTEGER PRIMARY KEY AUTOINCREMENT,
                supervisor_id TEXT NOT NULL,
                student_id TEXT NOT NULL,
                student_name TEXT,
                program_type TEXT,
                thesis_title TEXT,
                start_date TEXT,
                expected_end_date TEXT,
                actual_end_date TEXT,
                status TEXT DEFAULT 'active',
                supervision_role TEXT DEFAULT 'primary',
                progress_notes TEXT,
                milestones TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            , degree TEXT, department TEXT, secondary_supervisor_id TEXT, submission_date TEXT, viva_date TEXT, internal_examiner_id TEXT, external_examiner_id TEXT, outcome TEXT);
CREATE TABLE student_textbook_purchases (
                        purchase_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        listing_id INTEGER,
                        isbn TEXT NOT NULL,
                        title TEXT NOT NULL,
                        course_code TEXT,
                        purchase_date TEXT NOT NULL,
                        vendor TEXT NOT NULL,
                        purchase_type TEXT CHECK(purchase_type IN ('buy-new', 'buy-used', 'rent', 'digital')),
                        price_paid REAL NOT NULL,
                        condition TEXT,
                        rental_due_date TEXT,
                        resale_value REAL,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (listing_id) REFERENCES textbook_listings(listing_id)
                    );
CREATE TABLE student_timetables (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            module_code TEXT NOT NULL,
            day_of_week TEXT NOT NULL,
            time_slot TEXT NOT NULL,
            room TEXT,
            instructor_id INTEGER,
            academic_year TEXT,
            semester TEXT,
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (module_code) REFERENCES modules(module_code),
            FOREIGN KEY (instructor_id) REFERENCES instructors(id)
        );
CREATE TABLE student_union_clubs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                category TEXT,
                created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                status TEXT DEFAULT 'active'
            , hall_id TEXT);
CREATE TABLE "students" (
        student_id TEXT PRIMARY KEY,
        email_address TEXT,
        title TEXT,
        first_name TEXT,
        middle_name TEXT,
        last_name TEXT,
        gender TEXT,
        dob TEXT,
        age INTEGER,
        course TEXT,
        registration_datetime TEXT,
        status TEXT DEFAULT 'Active',
        enrollment_date TEXT
    , emergency_contact TEXT DEFAULT '', pronouns TEXT DEFAULT '', previous_system TEXT, previous_system_id TEXT, "year" INTEGER, "program" TEXT, "phone" TEXT, "address" TEXT, "is_active" BOOLEAN DEFAULT 1, "grade_level" TEXT, created_date TIMESTAMP DEFAULT NULL, year_of_study INTEGER, gpa REAL, journey_id TEXT, entry_qualifications TEXT, conditions_met INTEGER, ucas_tariff INTEGER, academic_year TEXT, mode_of_study TEXT DEFAULT 'full-time', campus_code TEXT, expected_return_date TEXT, record_closed_at TEXT, "course_year" TEXT, "enrollment_status" TEXT, "enrollment_year" TEXT, "parent_email" TEXT, "parent_phone" TEXT, "department" TEXT, "major" TEXT, "nationality" TEXT, "personal_email" TEXT, "fee_status" TEXT, "entry_route" TEXT, "entry_override_reason" TEXT);
CREATE TABLE study_companion_reminders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        reminder_date TEXT NOT NULL,
        kind TEXT NOT NULL,
        summary TEXT,
        sent_at TEXT NOT NULL DEFAULT (datetime('now')),
        UNIQUE (student_id, reminder_date, kind)
    );
CREATE TABLE study_companion_settings (
        student_id TEXT PRIMARY KEY,
        reminders_enabled INTEGER NOT NULL DEFAULT 1,
        email_reminders INTEGER NOT NULL DEFAULT 0,
        share_with_tutor INTEGER NOT NULL DEFAULT 1,
        daily_card_limit INTEGER NOT NULL DEFAULT 20
            CHECK (daily_card_limit BETWEEN 1 AND 500),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
CREATE TABLE study_group_members (
                    membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    group_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    role TEXT DEFAULT 'Member',
                    joined_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    contribution_score INTEGER DEFAULT 0,
                    attendance_count INTEGER DEFAULT 0,
                    FOREIGN KEY (group_id) REFERENCES study_groups(group_id) ON DELETE CASCADE,
                    UNIQUE(group_id, student_id)
                );
CREATE TABLE study_groups (
                    group_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    course_id TEXT NOT NULL,
                    group_name TEXT NOT NULL,
                    creator_id TEXT NOT NULL,
                    max_members INTEGER DEFAULT 6,
                    current_members INTEGER DEFAULT 1,
                    meeting_schedule TEXT,
                    location TEXT,
                    is_virtual BOOLEAN DEFAULT 1,
                    status TEXT DEFAULT 'Active',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                , "description" TEXT, "meeting_time" TEXT, "organizer_id" TEXT, "study_date" TEXT, "study_group_id" INTEGER, "subject" TEXT, "topic" TEXT, "name" TEXT, "id" TEXT, "module_code" TEXT);
CREATE TABLE study_match_suggestions (
                    suggestion_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    suggested_student_id TEXT NOT NULL,
                    course_id TEXT,
                    compatibility_score REAL DEFAULT 0.0,
                    match_reason TEXT,
                    status TEXT DEFAULT 'Pending',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    responded_at TEXT
                );
CREATE TABLE study_plan_tasks (
                    task_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    plan_id INTEGER NOT NULL,
                    task_title TEXT NOT NULL,
                    task_description TEXT,
                    scheduled_date TEXT NOT NULL,
                    duration_minutes INTEGER DEFAULT 60,
                    priority TEXT DEFAULT 'Medium',
                    completed BOOLEAN DEFAULT 0,
                    completed_at TEXT, "created_at" TEXT, "module_code" TEXT, "topic" TEXT, "task_kind" TEXT DEFAULT 'custom', "status" TEXT DEFAULT 'pending', "original_date" TEXT, "rescheduled_count" INTEGER DEFAULT 0, "notes" TEXT, "updated_at" TEXT,
                    FOREIGN KEY (plan_id) REFERENCES study_plans(plan_id) ON DELETE CASCADE
                );
CREATE TABLE study_plans (
                    plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    course_id TEXT,
                    plan_name TEXT NOT NULL,
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    total_hours INTEGER DEFAULT 0,
                    difficulty_level TEXT DEFAULT 'Medium',
                    status TEXT DEFAULT 'Active',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                , "exam_date" TEXT, "exam_id" INTEGER, "hours_per_day" REAL, "notes" TEXT, "updated_at" TEXT, "completed_at" TEXT, "archived_at" TEXT);
CREATE TABLE study_profiles (
                    profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL UNIQUE,
                    study_style TEXT DEFAULT 'Visual',
                    preferred_time TEXT DEFAULT 'Evening',
                    group_size_preference TEXT DEFAULT 'Small',
                    communication_style TEXT DEFAULT 'Collaborative',
                    noise_preference TEXT DEFAULT 'Quiet',
                    availability_json TEXT,
                    interests_json TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                , "preferred_times" TEXT, "id" TEXT, "learning_style" TEXT, "strengths" TEXT, "study_hours_per_week" TEXT, "weaknesses" TEXT, hours_per_week REAL DEFAULT 0);
CREATE TABLE study_recommendations (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    module_code TEXT,
                    recommendation_type TEXT DEFAULT 'focus_area',
                    title TEXT NOT NULL,
                    description TEXT,
                    priority TEXT DEFAULT 'medium',
                    is_completed INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    expires_at TEXT
                );
CREATE TABLE study_room_bookings (
                    booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    room_id INTEGER NOT NULL,
                    booked_by TEXT NOT NULL,
                    booking_date TEXT NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    purpose TEXT DEFAULT 'study',
                    group_size INTEGER DEFAULT 1,
                    notes TEXT DEFAULT '',
                    status TEXT DEFAULT 'confirmed',
                    created_at TEXT DEFAULT (datetime('now')), "student_id" TEXT,
                    FOREIGN KEY (room_id) REFERENCES study_rooms(room_id)
                );
CREATE TABLE study_room_participants (
                    participant_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    room_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    joined_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    left_at TEXT,
                    total_time_minutes INTEGER DEFAULT 0,
                    pomodoro_sessions_completed INTEGER DEFAULT 0,
                    is_currently_active BOOLEAN DEFAULT 1,
                    FOREIGN KEY (room_id) REFERENCES virtual_study_rooms(room_id) ON DELETE CASCADE
                );
CREATE TABLE study_rooms (
                    room_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    room_number TEXT NOT NULL,
                    building TEXT DEFAULT '',
                    capacity INTEGER DEFAULT 4,
                    room_type TEXT DEFAULT 'study',
                    equipment TEXT DEFAULT '',
                    has_whiteboard INTEGER DEFAULT 0,
                    has_projector INTEGER DEFAULT 0,
                    has_power_outlets INTEGER DEFAULT 1,
                    status TEXT DEFAULT 'available'
                , "room_name" TEXT, "amenities" TEXT, "created_at" TEXT, "is_bookable" INTEGER DEFAULT 0, "location" TEXT);
CREATE TABLE study_sessions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    module_code TEXT,
                    topic TEXT,
                    duration_minutes INTEGER DEFAULT 0,
                    effectiveness_rating INTEGER,
                    notes TEXT,
                    studied_at TEXT DEFAULT CURRENT_TIMESTAMP
                , source TEXT DEFAULT 'manual', source_id INTEGER);
CREATE TABLE style_fingerprints (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                fingerprint_data TEXT NOT NULL,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
CREATE TABLE su_advocacy_requests (
    request_id   INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id   TEXT NOT NULL,
    case_id      INTEGER NOT NULL,
    case_kind    TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'pending',
    su_rep_id    TEXT,
    requested_at TEXT NOT NULL,
    claimed_at   TEXT,
    notes        TEXT
);
CREATE TABLE sublet_listings (
                    sublet_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    landlord_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT NOT NULL,
                    address TEXT NOT NULL,
                    monthly_rent REAL NOT NULL,
                    utilities_included BOOLEAN DEFAULT 0,
                    bedrooms INTEGER,
                    bathrooms REAL,
                    square_feet INTEGER,
                    furnished BOOLEAN DEFAULT 0,
                    pets_allowed BOOLEAN DEFAULT 0,
                    parking_available BOOLEAN DEFAULT 0,
                    available_from TEXT NOT NULL,
                    available_to TEXT NOT NULL,
                    min_lease_months INTEGER DEFAULT 1,
                    security_deposit REAL,
                    amenities TEXT,
                    contact_email TEXT,
                    contact_phone TEXT,
                    status TEXT DEFAULT 'Available',
                    view_count INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (landlord_id) REFERENCES students(student_id)
                );
CREATE TABLE "submission_annotations" (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            submission_id INTEGER NOT NULL,
            reviewer_id INTEGER NOT NULL,
            line_number INTEGER,
            position_start INTEGER,
            position_end INTEGER,
            comment TEXT NOT NULL,
            category TEXT DEFAULT 'suggestion' CHECK (category IN ('praise', 'suggestion', 'correction', 'question')),
            student_response TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE,
            FOREIGN KEY (reviewer_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE submission_drafts (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        assignment_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        content TEXT,
                        version INTEGER DEFAULT 1,
                        file_path TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    , "saved_at" TEXT);
CREATE TABLE submission_grades (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                marks INTEGER,
                feedback TEXT,
                graded_by TEXT,
                graded_at TEXT DEFAULT (datetime('now'))
            );
CREATE TABLE submission_receipts (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        submission_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        assignment_title TEXT,
                        submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        receipt_hash TEXT,
                        email_sent INTEGER DEFAULT 0,
                        confirmation_code TEXT
                    , "generated_at" TEXT);
CREATE TABLE submission_rubric_scores (
        submission_id INTEGER NOT NULL,
        criterion_id INTEGER NOT NULL,
        criterion_name TEXT NOT NULL,
        score REAL NOT NULL,
        max_points REAL NOT NULL,
        marked_at TEXT NOT NULL,
        PRIMARY KEY (submission_id, criterion_id),
        FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id) ON DELETE CASCADE
    );
CREATE TABLE support_erasure_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    requester_username TEXT,
    student_id TEXT,
    case_reference TEXT NOT NULL,
    reason TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'requested'
        CHECK (status IN ('requested', 'approved', 'rejected', 'completed')),
    tickets_json TEXT,
    requested_by TEXT NOT NULL,
    requested_at TEXT NOT NULL,
    decided_by TEXT,
    decided_at TEXT,
    decision_note TEXT,
    completed_by TEXT,
    completed_at TEXT,
    result_json TEXT
);
CREATE TABLE support_escalation_fires (
    fire_id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticket_id INTEGER NOT NULL,
    rule_id INTEGER NOT NULL,
    action_type TEXT NOT NULL,
    fired_at TEXT NOT NULL,
    UNIQUE (ticket_id, rule_id),
    FOREIGN KEY (ticket_id) REFERENCES support_tickets (ticket_id) ON DELETE CASCADE
);
CREATE TABLE support_group_members (
            membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_id INTEGER,
            student_id TEXT,
            join_date TEXT,
            anonymous_id TEXT,
            status TEXT DEFAULT 'active', "id" TEXT,
            FOREIGN KEY (group_id) REFERENCES peer_support_groups (group_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE support_inbound_mail (
    mail_id INTEGER PRIMARY KEY AUTOINCREMENT,
    message_key TEXT NOT NULL UNIQUE,
    from_address TEXT,
    subject TEXT,
    received_at TEXT NOT NULL,
    status TEXT NOT NULL
        CHECK (status IN ('processed', 'quarantined', 'ignored', 'failed', 'accepted', 'discarded')),
    reason TEXT,
    ticket_id INTEGER,
    response_id INTEGER,
    username TEXT,
    raw_path TEXT,
    reviewed_by TEXT,
    reviewed_at TEXT
);
CREATE TABLE support_incidents (
    incident_id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    public_message TEXT,
    team TEXT,
    severity TEXT NOT NULL DEFAULT 'major'
        CHECK (severity IN ('minor', 'major', 'critical')),
    status TEXT NOT NULL DEFAULT 'open'
        CHECK (status IN ('open', 'monitoring', 'resolved')),
    resolution TEXT,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    resolved_by TEXT,
    resolved_at TEXT
);
CREATE TABLE support_requests (
            request_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            anonymous_id TEXT,
            group_id INTEGER,
            group_name TEXT,
            reason TEXT,
            status TEXT DEFAULT 'pending',
            requested_date TEXT NOT NULL,
            resolved_date TEXT,
            resolved_by TEXT
        );
CREATE TABLE support_resources (
            resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT NOT NULL,
            category TEXT NOT NULL,
            url TEXT,
            file_path TEXT,
            created_by TEXT NOT NULL,
            created_datetime TEXT NOT NULL,
            updated_datetime TEXT,
            access_count INTEGER DEFAULT 0,
            tags TEXT,  -- JSON array
            content_type TEXT,
            is_featured BOOLEAN DEFAULT 0,
            requires_auth BOOLEAN DEFAULT 0
        );
CREATE TABLE support_ticket_followers (
    ticket_id INTEGER NOT NULL,
    username TEXT NOT NULL,
    added_by TEXT NOT NULL,
    added_at TEXT NOT NULL,
    PRIMARY KEY (ticket_id, username),
    FOREIGN KEY (ticket_id) REFERENCES support_tickets (ticket_id) ON DELETE CASCADE
);
CREATE TABLE support_ticket_referrals (
    referral_id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticket_id INTEGER NOT NULL,
    kind TEXT NOT NULL,
    target_ref TEXT,
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'created', 'failed')),
    consent_basis TEXT,
    error TEXT,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    completed_at TEXT,
    FOREIGN KEY (ticket_id) REFERENCES support_tickets (ticket_id) ON DELETE CASCADE
);
CREATE TABLE support_tickets (
            ticket_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            assigned_to TEXT,
            subject TEXT NOT NULL,
            description TEXT NOT NULL,
            category TEXT NOT NULL,
            subcategory TEXT,
            status TEXT DEFAULT 'open',
            priority TEXT DEFAULT 'medium',
            impact TEXT DEFAULT 'low',
            urgency TEXT DEFAULT 'low',
            source TEXT DEFAULT 'web',
            resolution TEXT,
            satisfaction_rating INTEGER,
            satisfaction_feedback TEXT,
            estimated_hours REAL,
            actual_hours REAL,
            due_date TEXT,
            resolved_at TEXT,
            first_response_at TEXT,
            last_activity_at TEXT,
            escalation_level INTEGER DEFAULT 0,
            tags TEXT,
            department TEXT,
            organization_id INTEGER,
            parent_ticket_id INTEGER,
            knowledge_base_articles TEXT,
            created_at TEXT,
            updated_at TEXT,
            escalated_at TEXT,
            closed_at TEXT,
            estimated_resolution TEXT,
            sentiment TEXT DEFAULT 'neutral', message TEXT DEFAULT '', "requester_username" TEXT, "student_id" TEXT, "channel" TEXT, "team" TEXT, "confidentiality" TEXT DEFAULT 'standard' CHECK (confidentiality IN ('standard', 'restricted', 'safeguarding')), "crisis_flag" INTEGER DEFAULT 0, "sla_due_at" TEXT, "share_consent" TEXT CHECK (share_consent IS NULL OR share_consent IN ('granted', 'declined')), "share_consent_at" TEXT, "data_purged_at" TEXT, "sla_paused_at" TEXT, "sla_paused_hours" REAL DEFAULT 0, "incident_id" INTEGER,
            FOREIGN KEY (parent_ticket_id) REFERENCES support_tickets (ticket_id)
        );
CREATE TABLE survey_responses (
            response_id INTEGER PRIMARY KEY AUTOINCREMENT,
            survey_id INTEGER,
            alumni_id TEXT,
            responses TEXT,
            submission_date TEXT,
            FOREIGN KEY (survey_id) REFERENCES event_surveys (survey_id),
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE "sustainability_tracking" (
            tracking_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER,
            club_id INTEGER,
            carbon_footprint REAL,
            waste_generated REAL,
            waste_recycled REAL,
            transport_method TEXT,
            sustainability_score REAL,
            notes TEXT,
            recorded_date TEXT,
            FOREIGN KEY (event_id) REFERENCES unified_events(event_id),
            FOREIGN KEY (club_id) REFERENCES student_clubs (club_id)
        );
CREATE TABLE syllabi (
                    syllabus_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    module_code TEXT NOT NULL,
                    academic_year TEXT NOT NULL,
                    template_id INTEGER,
                    content_json TEXT NOT NULL,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    reviewed_by TEXT,
                    review_date TEXT,
                    review_comments TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (template_id) REFERENCES syllabus_templates(template_id)
                );
CREATE TABLE syllabus_templates (
                    template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    sections_json TEXT NOT NULL,
                    level TEXT DEFAULT 'undergraduate',
                    created_by TEXT,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE sync_queue (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                queue_name TEXT,        -- optional: 'default','labs','claims'
                entity_type TEXT,       -- e.g., 'student','claim','lab_order'
                entity_id TEXT,
                operation TEXT,         -- upsert/delete/sync
                payload TEXT,
                priority INTEGER DEFAULT 5,
                attempts INTEGER DEFAULT 0,
                next_attempt_at TEXT,
                last_error TEXT,
                status TEXT,            -- pending/locked/failed/done
                locked_by TEXT,
                locked_at TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT
            );
CREATE TABLE system_integration_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                source_system TEXT,
                target_system TEXT,
                operation TEXT,
                status TEXT,
                details TEXT,
                timestamp TEXT
            );
CREATE TABLE system_integrations (
            integration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            type TEXT NOT NULL,  -- sso, lms, sis, calendar, etc.
            config TEXT NOT NULL,  -- JSON configuration
            is_active BOOLEAN DEFAULT 0,
            last_sync_datetime TEXT,
            sync_status TEXT DEFAULT 'never',
            error_log TEXT
        );
CREATE TABLE system_logs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    action_type TEXT,
                    description TEXT,
                    details TEXT,
                    created_date TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE system_metrics (
            metric_id INTEGER PRIMARY KEY AUTOINCREMENT,
            metric_name TEXT NOT NULL,
            metric_value REAL NOT NULL,
            category TEXT NOT NULL,
            recorded_datetime TEXT NOT NULL,
            metadata TEXT  -- JSON data
        );
CREATE TABLE system_performance (
                performance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                metric_name TEXT NOT NULL,
                metric_value REAL,
                recorded_date DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE system_settings (
                key TEXT PRIMARY KEY,
                value TEXT,
                description TEXT,
                last_modified TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , "setting_value" TEXT, "updated_date" TEXT, "setting_name" TEXT);
CREATE TABLE ta_assignments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    section_id TEXT,
                    module_code TEXT,
                    role TEXT NOT NULL DEFAULT 'ta' CHECK(role IN ('ta','co_instructor')),
                    can_grade INTEGER DEFAULT 0,
                    can_create_assignments INTEGER DEFAULT 0,
                    can_view_analytics INTEGER DEFAULT 0,
                    assigned_by TEXT,
                    assigned_at TEXT DEFAULT (datetime('now'))
                , hours_per_week REAL DEFAULT 0, "can_manage_assignments" INTEGER DEFAULT 0, "section" TEXT, "ta_user_id" INTEGER, "is_active" INTEGER DEFAULT 0, "updated_at" TEXT);
CREATE TABLE ta_evaluations (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        ta_id TEXT NOT NULL,
                        module_code TEXT NOT NULL,
                        evaluation_period TEXT,
                        hours_logged REAL DEFAULT 0,
                        avg_grading_turnaround_days REAL DEFAULT 0,
                        submissions_graded INTEGER DEFAULT 0,
                        feedback_score REAL,
                        evaluator_id TEXT,
                        evaluated_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE ta_permissions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        ta_id INTEGER NOT NULL,
                        permission_type TEXT NOT NULL,
                        module_code TEXT NOT NULL,
                        granted_by TEXT NOT NULL,
                        granted_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (ta_id) REFERENCES teaching_assistants(id),
                        UNIQUE(ta_id, permission_type, module_code)
                    );
CREATE TABLE "takeaway_addresses" (
            address_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            label TEXT DEFAULT 'Home',
            building TEXT,
            room_number TEXT,
            address_line TEXT NOT NULL,
            phone TEXT,
            is_default BOOLEAN DEFAULT 0,
            created_at TEXT NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE takeaway_restaurants (
            restaurant_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            cuisine_type TEXT,
            description TEXT,
            delivery_fee REAL DEFAULT 2.00,
            min_order_amount REAL DEFAULT 10.00,
            estimated_delivery_time INTEGER DEFAULT 30,
            is_open BOOLEAN DEFAULT 1,
            opening_hours TEXT,
            rating REAL DEFAULT 0.0,
            total_orders INTEGER DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        );
CREATE TABLE tax_brackets (
                    bracket_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    tax_year TEXT NOT NULL,
                    bracket_name TEXT NOT NULL,
                    lower_limit REAL NOT NULL,
                    upper_limit REAL,
                    rate REAL NOT NULL,
                    personal_allowance REAL DEFAULT 0,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE taxi_booking_services (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                service_name TEXT NOT NULL,
                vehicle_type TEXT NOT NULL,
                capacity INTEGER NOT NULL,
