                    large_class_threshold INTEGER DEFAULT 50,
                    large_class_factor REAL DEFAULT 1.25,
                    overload_rate REAL DEFAULT 0,
                    is_default INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
