                    verified_date TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE "team_formations" (
                team_id INTEGER PRIMARY KEY AUTOINCREMENT,
