        );
CREATE TABLE templates (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    category TEXT,
                    body TEXT NOT NULL,
                    created_by TEXT,
                    is_shared INTEGER DEFAULT 0,         -- 0/1
                    version INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT
                );
CREATE TABLE textbook_listings (
                        listing_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        isbn TEXT NOT NULL,
                        title TEXT NOT NULL,
                        author TEXT,
                        edition TEXT,
                        publisher TEXT,
                        course_code TEXT,
                        vendor TEXT NOT NULL,
                        condition TEXT CHECK(condition IN ('new', 'like-new', 'good', 'acceptable', 'digital')),
                        price REAL NOT NULL,
                        availability TEXT CHECK(availability IN ('in-stock', 'limited', 'out-of-stock', 'pre-order')),
                        shipping_cost REAL DEFAULT 0.0,
                        rental_option BOOLEAN DEFAULT 0,
                        rental_price REAL,
                        rental_period_days INTEGER,
                        digital_option BOOLEAN DEFAULT 0,
                        digital_price REAL,
                        url TEXT,
                        last_updated TEXT DEFAULT (date('now')),
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                    , "status" TEXT DEFAULT 'available', "notes" TEXT DEFAULT '', "seller_id" TEXT, "textbook_id" INTEGER, "photo_url" TEXT);
CREATE TABLE textbook_orders (
                    order_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    listing_id INTEGER,
                    buyer_id TEXT NOT NULL,
                    seller_id TEXT NOT NULL,
                    price REAL NOT NULL,
                    status TEXT DEFAULT 'pending',
                    order_date TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (listing_id) REFERENCES textbook_listings(listing_id)
                );
CREATE TABLE textbooks (
                    textbook_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    isbn TEXT DEFAULT '',
                    title TEXT NOT NULL,
                    author TEXT DEFAULT '',
                    edition TEXT DEFAULT '',
                    publisher TEXT DEFAULT '',
                    year INTEGER,
