                purchase_date TEXT NOT NULL, status TEXT DEFAULT 'active',
                FOREIGN KEY (service_id) REFERENCES train_station_services (id)
            );
CREATE TABLE training_courses (
                    course_id INTEGER PRIMARY KEY AUTOINCREMENT,
