    amount DECIMAL(10,2),
    total_amount REAL,
    subtotal REAL,
    discount_amount REAL,
    tax_amount REAL,
    tip_amount DECIMAL(10,2),
    balance_before DECIMAL(10,2),
    balance_after DECIMAL(10,2),
    currency TEXT DEFAULT 'GBP',
    payment_method TEXT,
    reference_type TEXT,
    reference_id TEXT,
    reference_number TEXT,
    account_id INTEGER,
    description TEXT,
    items_json TEXT,
    status TEXT DEFAULT 'completed',
    receipt_sent INTEGER DEFAULT 0,
    receipt_number TEXT,
    quantity_change INTEGER,
    location TEXT,
    processed_by TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT
, "transaction_time" TEXT, "user_id" INTEGER);
