                    arrival_datetime TEXT,
                    booking_reference TEXT,
                    carrier TEXT,
                    cost REAL DEFAULT 0,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (request_id) REFERENCES travel_requests(request_id)
                );
CREATE TABLE travel_requests (
                    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    purpose TEXT NOT NULL,
                    destination TEXT NOT NULL,
                    departure_date TEXT NOT NULL,
                    return_date TEXT NOT NULL,
                    estimated_budget REAL DEFAULT 0,
                    budget_breakdown_json TEXT,
                    funding_source TEXT DEFAULT 'department',
                    status TEXT DEFAULT 'draft',
                    justification TEXT,
                    department TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE trip_approvals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL REFERENCES trips (id),
    stage TEXT NOT NULL CHECK (stage IN ('department', 'health_safety', 'finance', 'international')),
    decision TEXT NOT NULL DEFAULT 'pending' CHECK (decision IN ('pending', 'approved', 'rejected', 'returned')),
    decided_by TEXT,
    decided_at TEXT,
    comments TEXT,
    trip_version INTEGER,
    created_at TEXT
);
CREATE TABLE trip_evaluations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL REFERENCES trips (id),
    respondent TEXT,
    role TEXT,
    rating INTEGER CHECK (rating BETWEEN 1 AND 5),
    went_well TEXT,
    improve TEXT,
    submitted_at TEXT,
    UNIQUE (trip_id, respondent)
);
CREATE TABLE "trip_expenses" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                category TEXT NOT NULL,
                description TEXT NOT NULL,
                amount REAL NOT NULL,
                date TEXT NOT NULL,
                recorded_by INTEGER,
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                FOREIGN KEY (recorded_by) REFERENCES users (id) ON DELETE CASCADE
            );
CREATE TABLE trip_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL REFERENCES trips (id),
    version INTEGER,
    changed_by TEXT,
    changed_at TEXT,
    action TEXT,
    field TEXT,
    old_value TEXT,
    new_value TEXT
);
CREATE TABLE trip_incidents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL REFERENCES trips (id),
    kind TEXT NOT NULL CHECK (kind IN ('incident', 'near_miss', 'illness', 'injury', 'safeguarding', 'conduct', 'other')),
    severity TEXT NOT NULL CHECK (severity IN ('minor', 'moderate', 'serious', 'critical')),
    occurred_at TEXT,
    location TEXT,
    description TEXT,
    persons_involved TEXT,
    actions_taken TEXT,
    reported_by TEXT,
    reported_at TEXT,
    riddor_reportable INTEGER DEFAULT 0,
    hs_reference TEXT,
    conduct_case_ref TEXT,
    status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'under_review', 'closed')),
    reviewed_by TEXT,
    reviewed_at TEXT,
    review_notes TEXT
);
CREATE TABLE trip_instalments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL REFERENCES trips (id),
    label TEXT,
    due_date TEXT,
    amount REAL
);
CREATE TABLE trip_itinerary (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                day_number INTEGER NOT NULL,
                activity TEXT NOT NULL,
                location TEXT,
                start_time TEXT,
                end_time TEXT,
                notes TEXT,
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                UNIQUE (trip_id, day_number, start_time)
            );
CREATE TABLE "trip_participants" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                student_id TEXT,
                user_id INTEGER,
                registration_date TEXT NOT NULL,
                payment_status TEXT DEFAULT 'pending',
                emergency_contact TEXT,
                medical_info TEXT,
                dietary_requirements TEXT,
                status TEXT DEFAULT 'registered', payment_method TEXT, payment_reference TEXT, "cancellation_date" TEXT, "cancellation_reason" TEXT, "waitlist_position" INTEGER, "waitlisted_at" TEXT, "offer_expires_at" TEXT, "conduct_accepted_at" TEXT, "parental_consent_by" TEXT, "parental_consent_at" TEXT, "health_share_consent_at" TEXT, "accessibility_needs" TEXT, "emergency_contact_name" TEXT, "emergency_contact_phone" TEXT, "emergency_contact_relationship" TEXT, "passport_expiry" TEXT, "visa_status" TEXT, "amount_paid" REAL DEFAULT 0, "amount_refunded" REAL DEFAULT 0, "hardship_award" REAL DEFAULT 0, "source" TEXT DEFAULT 'operations',
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
                UNIQUE (trip_id, student_id),
                CHECK (payment_status IN ('pending', 'partial', 'paid', 'refunded')),
                CHECK (status IN ('registered', 'waitlisted', 'offered', 'confirmed', 'cancelled', 'attended', 'no_show', 'removed'))
            );
CREATE TABLE trip_reconciliations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL UNIQUE REFERENCES trips (id),
    budget REAL,
    actual REAL,
    income REAL,
    notes TEXT,
    signed_off_by TEXT,
    signed_off_at TEXT
);
CREATE TABLE trip_risk_assessments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL REFERENCES trips (id),
    template TEXT,
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'submitted', 'signed_off', 'returned')),
    assessor TEXT,
    created_at TEXT,
    submitted_at TEXT,
    signed_off_by TEXT,
    signed_off_at TEXT,
    overall_residual TEXT,
    review_notes TEXT,
    trip_version INTEGER
);
CREATE TABLE trip_risk_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    assessment_id INTEGER NOT NULL REFERENCES trip_risk_assessments (id),
    hazard TEXT,
    who_at_risk TEXT,
    controls TEXT,
    likelihood INTEGER CHECK (likelihood BETWEEN 1 AND 5),
    severity INTEGER CHECK (severity BETWEEN 1 AND 5),
    residual_likelihood INTEGER,
    residual_severity INTEGER,
    owner TEXT
);
CREATE TABLE trip_rollcall_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    rollcall_id INTEGER NOT NULL REFERENCES trip_rollcalls (id),
    participant_id INTEGER NOT NULL REFERENCES trip_participants (id),
    present INTEGER,
    note TEXT,
    UNIQUE (rollcall_id, participant_id)
);
CREATE TABLE trip_rollcalls (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id INTEGER NOT NULL REFERENCES trips (id),
    label TEXT,
    taken_at TEXT,
    taken_by TEXT
);
CREATE TABLE "trip_staff" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                staff_user_id INTEGER NOT NULL,
                role TEXT DEFAULT 'supervisor',
                assigned_date TEXT NOT NULL, "dbs_checked_at" TEXT, "dbs_status" TEXT, "first_aider" INTEGER DEFAULT 0,
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                FOREIGN KEY (staff_user_id) REFERENCES users (id) ON DELETE CASCADE,
                UNIQUE (trip_id, staff_user_id),
                CHECK (role IN ('supervisor', 'coordinator', 'medical', 'transport'))
            );
CREATE TABLE "trips" (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_name TEXT NOT NULL,
                description TEXT,
                destination TEXT NOT NULL,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                max_participants INTEGER DEFAULT 50,
                cost REAL DEFAULT 0.0,
                status TEXT DEFAULT 'proposed',
                created_by INTEGER,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL, "trip_type" TEXT DEFAULT 'day', "source" TEXT DEFAULT 'operations', "organising_club" TEXT, "module_code" TEXT, "country" TEXT, "is_overseas" INTEGER DEFAULT 0, "fcdo_advice_level" TEXT, "fcdo_checked_at" TEXT, "fcdo_checked_by" TEXT, "insurance_reference" TEXT, "insurance_registered_at" TEXT, "high_risk" INTEGER DEFAULT 0, "involves_minors" INTEGER DEFAULT 0, "involves_vulnerable_adults" INTEGER DEFAULT 0, "min_staff_ratio" INTEGER DEFAULT 10, "requires_first_aider" INTEGER DEFAULT 1, "emergency_contact_24h" TEXT, "budget" REAL, "deposit_amount" REAL DEFAULT 0, "deposit_due" TEXT, "balance_due" TEXT, "refund_policy" TEXT, "hardship_eligible" INTEGER DEFAULT 1, "counts_as_attendance" INTEGER DEFAULT 0, "version" INTEGER DEFAULT 1, "updated_by" TEXT, "archived_at" TEXT, "archived_by" TEXT, "data_purged_at" TEXT,
                FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE CASCADE,
                CHECK (status IN ('proposed', 'planning', 'approved', 'open', 'full', 'closed', 'in_progress', 'cancelled', 'completed', 'archived'))
            );
CREATE TABLE turnover_analytics (
                    record_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    department TEXT,
                    period_start TEXT NOT NULL,
                    period_end TEXT NOT NULL,
                    period_type TEXT DEFAULT 'monthly',
                    headcount_start INTEGER DEFAULT 0,
                    headcount_end INTEGER DEFAULT 0,
                    voluntary_exits INTEGER DEFAULT 0,
                    involuntary_exits INTEGER DEFAULT 0,
                    retirements INTEGER DEFAULT 0,
                    transfers_out INTEGER DEFAULT 0,
                    new_hires INTEGER DEFAULT 0,
                    transfers_in INTEGER DEFAULT 0,
                    turnover_rate REAL,
                    retention_rate REAL,
                    avg_tenure_months REAL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE tutor_group_meetings (
                    meeting_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    group_id INTEGER NOT NULL,
                    scheduled_at TEXT NOT NULL,
                    duration_minutes INTEGER DEFAULT 60,
                    location TEXT,
                    agenda TEXT,
                    attendance_count INTEGER,
                    notes TEXT,
                    status TEXT DEFAULT 'scheduled',
                    created_at TEXT DEFAULT (datetime('now')),
                    FOREIGN KEY (group_id) REFERENCES tutor_groups (group_id)
                );
CREATE TABLE tutor_group_members (
                    membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    group_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    role TEXT NOT NULL DEFAULT 'student',
                    joined_date TEXT NOT NULL,
                    left_date TEXT,
                    is_active INTEGER DEFAULT 1,
                    FOREIGN KEY (group_id) REFERENCES tutor_groups (group_id)
                );
CREATE TABLE tutor_groups (
                    group_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    academic_year TEXT NOT NULL,
                    programme TEXT,
                    lead_tutor_id INTEGER,
                    capacity INTEGER NOT NULL DEFAULT 20,
                    meeting_pattern TEXT DEFAULT 'weekly',
                    notes TEXT,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT (datetime('now')),
                    updated_at TEXT DEFAULT (datetime('now'))
                );
CREATE TABLE tutoring_offers (
            offer_id INTEGER PRIMARY KEY AUTOINCREMENT,
            tutor_id TEXT,
            subject TEXT,
            topic TEXT,
            hourly_rate REAL,
            availability TEXT,
            experience_level TEXT,
            description TEXT,
            rating REAL DEFAULT 0.0,
            total_sessions INTEGER DEFAULT 0,
            status TEXT DEFAULT 'available',
            FOREIGN KEY (tutor_id) REFERENCES students (student_id)
        );
CREATE TABLE two_fa_recovery_codes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            code_hash TEXT NOT NULL,
            is_used INTEGER DEFAULT 0,
            created_at TEXT NOT NULL,
            used_at TEXT,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE ucas_admissions_notes (
    note_id              INTEGER PRIMARY KEY AUTOINCREMENT,
    link_id              INTEGER NOT NULL,
    body                 TEXT NOT NULL,
    author               TEXT,
    created_at           TEXT DEFAULT (datetime('now')),
    updated_at           TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (link_id)
        REFERENCES ucas_application_links(link_id) ON DELETE CASCADE
);
CREATE TABLE ucas_application_links (
    link_id              INTEGER PRIMARY KEY AUTOINCREMENT,
    sf_application_id    INTEGER NOT NULL,
    sf_choice_id         INTEGER NOT NULL,
    sf_student_id        TEXT NOT NULL,
    uni_application_id   INTEGER,
    uni_student_id       TEXT,
    status               TEXT NOT NULL DEFAULT 'open',
    linked_by            TEXT,
    linked_at            TEXT DEFAULT (datetime('now')),
    updated_at           TEXT DEFAULT (datetime('now')),
    UNIQUE(sf_choice_id)
);
CREATE TABLE ucas_decisions (
            decision_id       INTEGER PRIMARY KEY AUTOINCREMENT,
            sf_choice_id      INTEGER NOT NULL,
            sf_application_id INTEGER,
            sf_student_id     TEXT,
            decision_status   TEXT NOT NULL,
            offer_terms       TEXT,
            notes             TEXT,
            decided_by        TEXT,
            decided_at        TEXT DEFAULT (datetime('now'))
        );
CREATE TABLE ucas_offer_terms (
            terms_id                 INTEGER PRIMARY KEY AUTOINCREMENT,
            sf_choice_id             INTEGER NOT NULL UNIQUE,
            grade_requirement        TEXT,
            grade_alternative        TEXT,
            reply_deadline           TEXT,
            expiry_date              TEXT,
            scholarship              TEXT,
            accommodation_guaranteed INTEGER NOT NULL DEFAULT 0,
            notes                    TEXT,
            issued_by                TEXT,
            issued_at                TEXT DEFAULT (datetime('now')),
            updated_at               TEXT DEFAULT (datetime('now'))
        );
CREATE TABLE ucas_results_holds (
    hold_id        INTEGER PRIMARY KEY AUTOINCREMENT,
    sf_choice_id   INTEGER NOT NULL,
    sf_student_id  TEXT,
    action         TEXT NOT NULL CHECK (action IN ('confirm', 'decline')),
    automatic      INTEGER NOT NULL DEFAULT 0,
    verdict        TEXT,
    reason         TEXT,
    note           TEXT,
    status         TEXT NOT NULL DEFAULT 'Held' CHECK (status IN
                       ('Held', 'Applied', 'Lapsed', 'Cancelled', 'Failed')),
    release_at     TEXT,
    held_by        TEXT,
    held_at        TEXT NOT NULL DEFAULT (datetime('now')),
    released_by    TEXT,
    released_at    TEXT,
    outcome        TEXT
);
CREATE TABLE ukvi_engagement_alerts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        student_id TEXT NOT NULL,
        detected_on TEXT NOT NULL,
        consecutive_missed INTEGER NOT NULL,
        last_engaged_on TEXT,
        report_due TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'open',
        ukvi_reference TEXT,
        outcome_notes TEXT,
        resolved_by TEXT,
        resolved_at TEXT
    );
CREATE TABLE ukvi_engagement_events (
         id INTEGER PRIMARY KEY AUTOINCREMENT,
         student_id TEXT NOT NULL, event_type TEXT NOT NULL,
         event_date TEXT NOT NULL, notes TEXT, recorded_by TEXT,
         recorded_at TEXT DEFAULT CURRENT_TIMESTAMP
       );
CREATE TABLE unified_event_registrations (
    registration_id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_id INTEGER NOT NULL,
    user_id TEXT,
    user_type TEXT,
    registration_date TEXT DEFAULT (datetime('now')),
    attendance_status TEXT DEFAULT 'registered',
    checked_in_at TEXT,
    check_out_time TEXT,
    payment_status TEXT,
    payment_amount REAL,
    payment_method TEXT,
    is_waitlisted INTEGER DEFAULT 0,
    num_guests INTEGER DEFAULT 0,
    feedback_rating INTEGER,
    feedback_comment TEXT,
    qr_code TEXT,
    cpd_credits REAL, "check_in_time" TEXT, "status" TEXT, "attendance_confirmed" TEXT, "created_at" TEXT, "max_capacity" TEXT, "registered_at" TEXT, "student_id" TEXT, attendee_name TEXT,
    FOREIGN KEY (event_id) REFERENCES unified_events(event_id)
);
CREATE TABLE unified_events (
    event_id INTEGER PRIMARY KEY AUTOINCREMENT,
    source_type TEXT NOT NULL,
    source_event_id TEXT,
    title TEXT NOT NULL,
    description TEXT,
    event_type TEXT,
    event_category TEXT,
    start_datetime TEXT,
    end_datetime TEXT,
    location TEXT,
    building TEXT,
    room TEXT,
    room_id INTEGER,
    organizer_id TEXT,
    organizer_name TEXT,
    organizer_type TEXT,
    max_capacity INTEGER,
    registration_required INTEGER DEFAULT 0,
    registration_deadline TEXT,
    is_public INTEGER DEFAULT 1,
    is_featured INTEGER DEFAULT 0,
    status TEXT DEFAULT 'scheduled',
    tags TEXT,
    image_url TEXT,
    virtual_link TEXT,
    event_fee REAL DEFAULT 0,
    payment_required INTEGER DEFAULT 0,
    waitlist_enabled INTEGER DEFAULT 0,
    qr_code_path TEXT,
    club_id INTEGER,
    created_by TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT,
    notes TEXT
, "event_name" TEXT, "id" TEXT, "event_date" TEXT, "start_time" TEXT, "end_time" TEXT, "assignment_id" INTEGER, "trip_id" INTEGER, "audience" TEXT, "participants" TEXT, "country_code" TEXT, "region" TEXT, "is_active" BOOLEAN DEFAULT 1, "committee_id" INTEGER, "secretary_id" TEXT, "recurrence" TEXT);
CREATE TABLE unified_refunds (
    refund_id INTEGER PRIMARY KEY AUTOINCREMENT,
    source_type TEXT NOT NULL,
    source_refund_id INTEGER,
    reference_type TEXT,
    reference_id TEXT,
    student_id TEXT,
    customer_name TEXT,
    customer_email TEXT,
    amount DECIMAL(10,2) NOT NULL,
    original_amount DECIMAL(10,2),
    currency TEXT DEFAULT 'GBP',
    refund_type TEXT,
    refund_method TEXT,
    refund_reference TEXT,
    reason TEXT,
    status TEXT DEFAULT 'processed',
    department TEXT,
    processed_by TEXT,
    requested_by TEXT,
    approved_by TEXT,
    refund_date TEXT NOT NULL,
    request_date TEXT,
    approval_date TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
, vat_rate TEXT, vat_amount REAL);
CREATE TABLE union_elections (
            election_id INTEGER PRIMARY KEY AUTOINCREMENT,
            position TEXT,
            department TEXT,
            nomination_start TEXT,
            nomination_end TEXT,
            voting_start TEXT,
            voting_end TEXT,
            status TEXT DEFAULT 'upcoming'
        , "created_at" TEXT, "description" TEXT);
CREATE TABLE union_equipment (
            equipment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_name TEXT,
            category TEXT,
            description TEXT,
            serial_number TEXT,
            purchase_date TEXT,
            condition_status TEXT DEFAULT 'good',
            location TEXT,
            availability_status TEXT DEFAULT 'available',
            maintenance_due TEXT,
            replacement_cost REAL
        );
CREATE TABLE union_facilities (
            facility_id INTEGER PRIMARY KEY AUTOINCREMENT,
            facility_name TEXT UNIQUE,
            location TEXT,
            capacity INTEGER,
            description TEXT,
            status TEXT DEFAULT 'available',
            equipment TEXT,
            booking_fee REAL DEFAULT 0.0
        );
CREATE TABLE union_representatives (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            position TEXT,
            department TEXT,
            election_date TEXT,
            term_end_date TEXT,
            status TEXT DEFAULT 'active', "term_end" TEXT, "term_start" TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE union_voting_settings (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE university_disposition_log (
            disposition_id INTEGER PRIMARY KEY AUTOINCREMENT,
            record_type TEXT NOT NULL,
            record_id TEXT NOT NULL,
            action TEXT NOT NULL CHECK(action IN ('delete', 'redact', 'archive')),
            actor_id TEXT NOT NULL,
            disposed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE university_event_outbox (
            event_id TEXT PRIMARY KEY,
            event_name TEXT NOT NULL,
            event_version INTEGER NOT NULL CHECK (event_version > 0),
            aggregate_id TEXT NOT NULL,
            correlation_id TEXT NOT NULL,
            causation_id TEXT,
            idempotency_key TEXT NOT NULL UNIQUE,
            payload_json TEXT NOT NULL,
            available_at TEXT NOT NULL,
            attempts INTEGER NOT NULL DEFAULT 0,
            delivered_at TEXT,
            dead_lettered_at TEXT,
            last_error TEXT
        );
CREATE TABLE university_job_runs (job TEXT PRIMARY KEY, last_run_date TEXT NOT NULL);
CREATE TABLE university_legal_holds (
            hold_id TEXT PRIMARY KEY,
            record_type TEXT NOT NULL,
            record_id TEXT NOT NULL,
            reason TEXT NOT NULL,
            placed_by TEXT NOT NULL,
            placed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            released_by TEXT,
            released_at TEXT,
            UNIQUE(record_type, record_id, hold_id)
        );
CREATE TABLE usage_analytics (
            analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
            date TEXT NOT NULL,
            metric_name TEXT NOT NULL,
            metric_value REAL NOT NULL,
            category TEXT,
            additional_data TEXT
        );
CREATE TABLE user_accounts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            salt TEXT NOT NULL,
            user_id INTEGER NOT NULL,
            is_active INTEGER DEFAULT 1,
            last_login TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            password_reset_required INTEGER DEFAULT 0,
            two_fa_enabled INTEGER DEFAULT 0,
            two_fa_secret TEXT,
            FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
        );
CREATE TABLE user_achievements (
            achievement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            achievement_type TEXT NOT NULL,
            achievement_name TEXT NOT NULL,
            description TEXT,
            earned_date TEXT NOT NULL,
            points INTEGER DEFAULT 0
        );
CREATE TABLE user_activity_log (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            activity_type TEXT,
            activity_description TEXT,
            timestamp TEXT,
            ip_address TEXT,
            user_agent TEXT
        );
CREATE TABLE user_feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id TEXT, rating INTEGER, comment TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "user_interests" (
                interest_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                interest_category TEXT NOT NULL,
                interest_name TEXT NOT NULL,
                interest_level INTEGER DEFAULT 5,
                is_public INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(username) ON DELETE CASCADE,
                UNIQUE(user_id, interest_category, interest_name)
            );
CREATE TABLE user_permissions (
                    user_id TEXT PRIMARY KEY,
                    role TEXT,
                    permissions TEXT,
                    created_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                    updated_date DATETIME DEFAULT CURRENT_TIMESTAMP
                , "granted" INTEGER, "id" INTEGER, "permission_id" INTEGER);
CREATE TABLE "user_personality" (
                personality_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL UNIQUE,
                personality_type TEXT,
                extroversion_score INTEGER,
                openness_score INTEGER,
                social_preference TEXT,
                group_size_preference TEXT,
                activity_level TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(username) ON DELETE CASCADE
            );
CREATE TABLE user_preferences (
            user_id TEXT PRIMARY KEY,
            email_notifications BOOLEAN DEFAULT 1,
            in_app_notifications BOOLEAN DEFAULT 1,
            push_notifications BOOLEAN DEFAULT 1,
            digest_frequency TEXT DEFAULT 'daily',  -- immediate, daily, weekly
            theme TEXT DEFAULT 'light',
            language TEXT DEFAULT 'en',
            timezone TEXT DEFAULT 'UTC',
            preferences_json TEXT  -- Additional JSON preferences
        );
CREATE TABLE "user_privacy_settings" (
                privacy_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL UNIQUE,
                allow_matching INTEGER DEFAULT 1,
                show_profile INTEGER DEFAULT 1,
                allow_messages INTEGER DEFAULT 1,
                show_interests INTEGER DEFAULT 1,
                show_in_search INTEGER DEFAULT 1,
                match_same_major INTEGER DEFAULT 0,
                match_same_year INTEGER DEFAULT 0,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(username) ON DELETE CASCADE
            );
CREATE TABLE "user_resumes" (
                            resume_id INTEGER PRIMARY KEY AUTOINCREMENT,
                            student_id TEXT NOT NULL,
                            resume_name TEXT NOT NULL,
                            template_id INTEGER,
                            content TEXT NOT NULL,
                            last_generated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                            format TEXT DEFAULT 'pdf' CHECK(format IN ('pdf', 'docx', 'html')),
                            FOREIGN KEY (template_id) REFERENCES resume_templates(template_id)
                        );
CREATE TABLE user_sessions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER NOT NULL,
                    session_token TEXT UNIQUE NOT NULL,
                    created_at TEXT NOT NULL,
                    expires_at TEXT NOT NULL,
                    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
                );
CREATE TABLE "user_timezone_preferences" (
                    user_id INTEGER PRIMARY KEY,
                    timezone_name TEXT NOT NULL,
                    auto_dst BOOLEAN DEFAULT TRUE,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
                );
CREATE TABLE users (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "username" TEXT UNIQUE NOT NULL,
    "first_name" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "email" TEXT UNIQUE NOT NULL,
    "role" TEXT NOT NULL,
    "student_id" TEXT,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    "service_account" INTEGER DEFAULT 0,
    FOREIGN KEY (student_id) REFERENCES students (student_id)
);
CREATE TABLE vaccination_records (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    vaccine_name TEXT,
                    administered_date TEXT,
                    expiry_date TEXT,
                    lot_number TEXT,
                    manufacturer TEXT,
                    administered_by TEXT,
                    location TEXT,
                    adverse_reaction INTEGER DEFAULT 0,
                    reaction_description TEXT,
                    verified INTEGER DEFAULT 0,
                    verified_by TEXT,
                    verified_date TEXT,
                    created_at TEXT, "last_vaccination_date" TEXT, "next_due_date" TEXT, "vaccine_type" TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE "vehicles" (
