CREATE VIEW attendance AS
SELECT id, student_id, module_code, date, status, reason,
       check_in_time AS arrival_time, record_id AS attendance_id, date AS class_date,
       departure_time, NULL AS module_id, notes, recorded_by, recorded_at AS created_at,
       NULL AS prior, NULL AS course_name, NULL AS recent
  FROM attendance_records;
CREATE VIEW legacy_attendance_compat AS
           SELECT attendance_event_id AS record_id, session_id, student_id,
                  occurred_at AS check_in_time, source AS check_in_method,
                  status, reason AS notes
             FROM attendance_events;
CREATE VIEW legacy_enrollments_compat AS
           SELECT registration_id AS enrollment_id, student_id,
                  programme_code AS course_id, academic_year,
                  effective_from AS enrollment_date, status
             FROM programme_registrations;
CREATE VIEW legacy_payments_compat AS
    SELECT payment_id, student_id, ABS(amount) AS amount,
           COALESCE(currency, 'GBP') AS currency,
           'payments:' || payment_id AS provider_reference, status,
           payment_date AS payment_date
      FROM payments;
CREATE VIEW legacy_student_modules_compat AS
           SELECT module_enrolment_id AS id, student_id, module_code,
                  effective_from AS enrollment_date, status
             FROM module_enrolments;
CREATE VIEW student_payments AS
    SELECT payment_id,
           student_id,
           COALESCE(currency, 'GBP') AS currency,
           CAST(ROUND(ABS(amount) * 100) AS INTEGER) AS amount_minor,
           COALESCE(NULLIF(gateway_name, ''), NULLIF(payment_method, ''),
                    COALESCE(source_type, 'general')) AS provider,
           'payments:' || payment_id AS provider_reference,
           CASE WHEN source_payment_id IS NOT NULL
                THEN COALESCE(source_type, 'general') || ':' || source_payment_id
                ELSE 'payments:' || payment_id END AS idempotency_key,
           status,
           payment_date AS received_at,
           COALESCE(created_at, payment_date) AS created_at
      FROM payments
     WHERE student_id IS NOT NULL AND amount IS NOT NULL AND ABS(amount) > 0;
CREATE VIEW v_course_module_map AS
SELECT DISTINCT TRIM(course_code) AS course_code, TRIM(module_code) AS module_code
  FROM course_curriculum
 WHERE COALESCE(TRIM(course_code), '') <> ''
   AND COALESCE(TRIM(module_code), '') <> ''
UNION
SELECT DISTINCT TRIM(course_code) AS course_code, TRIM(module_code) AS module_code
  FROM course_module_map
 WHERE COALESCE(TRIM(course_code), '') <> ''
   AND COALESCE(TRIM(module_code), '') <> ''
UNION
SELECT DISTINCT TRIM(course) AS course_code, TRIM(module_code) AS module_code
  FROM modules
 WHERE COALESCE(TRIM(course), '') <> ''
   AND COALESCE(TRIM(module_code), '') <> '';
CREATE VIEW v_course_occupancy AS
SELECT
    c.id AS course_id,
    COALESCE(NULLIF(TRIM(c.course_code), ''), c.code) AS course_code,
    COALESCE(c.max_enrollment, 0) AS capacity,
    (SELECT COUNT(DISTINCT sm.student_id)
       FROM student_modules sm
       JOIN v_course_module_map m ON m.module_code = sm.module_code
       LEFT JOIN v_student_course sc ON sc.student_id = sm.student_id
      WHERE m.course_code = COALESCE(NULLIF(TRIM(c.course_code), ''), c.code)
        AND sm.status = 'Enrolled'
        AND (sc.course_code IS NULL
             OR sc.course_code = COALESCE(NULLIF(TRIM(c.course_code), ''), c.code))
      ) AS headcount,
    (SELECT COUNT(*)
       FROM student_modules sm
       JOIN v_course_module_map m ON m.module_code = sm.module_code
      WHERE m.course_code = COALESCE(NULLIF(TRIM(c.course_code), ''), c.code)
        AND sm.status = 'Enrolled') AS enrolments,
    (SELECT COUNT(DISTINCT m.module_code)
       FROM v_course_module_map m
      WHERE m.course_code = COALESCE(NULLIF(TRIM(c.course_code), ''), c.code)) AS module_count
FROM courses c;
CREATE VIEW v_module_occupancy AS
SELECT
    m.module_code AS module_code,
    m.module_name AS module_name,
    CASE WHEN COALESCE(m.capacity, 0) > 0 THEN m.capacity ELSE NULL END AS capacity,
    (SELECT COUNT(*) FROM student_modules sm
      WHERE sm.module_code = m.module_code AND sm.status = 'Enrolled') AS enrolled
FROM modules m;
CREATE VIEW v_student_course AS
SELECT s.student_id AS student_id,
       COALESCE(
           (SELECT COALESCE(NULLIF(TRIM(c.course_code), ''), c.code) FROM courses c
             WHERE UPPER(TRIM(COALESCE(NULLIF(TRIM(c.course_code), ''), c.code)))
                   = UPPER(TRIM(s.course)) LIMIT 1),
           (SELECT COALESCE(NULLIF(TRIM(c.course_code), ''), c.code) FROM courses c
             WHERE UPPER(TRIM(COALESCE(NULLIF(TRIM(c.course_name), ''), c.name)))
                   = UPPER(TRIM(s.course)) LIMIT 1)
       ) AS course_code
FROM students s
WHERE COALESCE(TRIM(s.course), '') <> '';
