CREATE TRIGGER absence_request_approved AFTER UPDATE OF status ON absence_requests
    WHEN LOWER(NEW.status) = 'approved' AND LOWER(COALESCE(OLD.status, '')) <> 'approved'
    BEGIN
        UPDATE attendance_records
           SET status = 'excused', reason = 'authorised absence (request #' || NEW.id || ')'
         WHERE student_id = NEW.student_id AND LOWER(status) = 'absent'
           AND (NEW.module_code IS NULL OR NEW.module_code = '' OR module_code = NEW.module_code)
           AND date BETWEEN NEW.date AND COALESCE(NULLIF(NEW.date_end, ''), NEW.date);
    END;
CREATE TRIGGER absence_request_inserted_approved AFTER INSERT ON absence_requests
    WHEN LOWER(NEW.status) = 'approved'
    BEGIN
        UPDATE attendance_records
           SET status = 'excused', reason = 'authorised absence (request #' || NEW.id || ')'
         WHERE student_id = NEW.student_id AND LOWER(status) = 'absent'
           AND (NEW.module_code IS NULL OR NEW.module_code = '' OR module_code = NEW.module_code)
           AND date BETWEEN NEW.date AND COALESCE(NULLIF(NEW.date_end, ''), NEW.date);
    END;
CREATE TRIGGER absence_request_unapproved AFTER UPDATE OF status ON absence_requests
    WHEN LOWER(COALESCE(OLD.status, '')) = 'approved' AND LOWER(NEW.status) <> 'approved'
    BEGIN
        UPDATE attendance_records SET status = 'absent', reason = NULL
         WHERE reason = 'authorised absence (request #' || OLD.id || ')';
    END;
CREATE TRIGGER attendance_auto_excuse AFTER INSERT ON attendance_records
    WHEN LOWER(NEW.status) = 'absent' AND EXISTS (
        SELECT 1 FROM absence_requests r WHERE r.student_id = NEW.student_id AND LOWER(r.status) = 'approved' AND (r.module_code IS NULL OR r.module_code = '' OR r.module_code = NEW.module_code) AND NEW.date BETWEEN r.date AND COALESCE(NULLIF(r.date_end, ''), r.date))
    BEGIN
        UPDATE attendance_records
           SET status = 'excused',
               reason = 'authorised absence (request #' || (SELECT r.id FROM absence_requests r
                                            WHERE r.student_id = NEW.student_id AND LOWER(r.status) = 'approved' AND (r.module_code IS NULL OR r.module_code = '' OR r.module_code = NEW.module_code) AND NEW.date BETWEEN r.date AND COALESCE(NULLIF(r.date_end, ''), r.date) LIMIT 1) || ')'
         WHERE id = NEW.id;
    END;
CREATE TRIGGER attendance_status_lower_insert AFTER INSERT ON attendance_records
    WHEN NEW.status IS NOT NULL AND NEW.status <> LOWER(NEW.status) COLLATE BINARY
    BEGIN
        UPDATE attendance_records SET status = LOWER(status) WHERE id = NEW.id;
    END;
CREATE TRIGGER attendance_status_lower_update AFTER UPDATE OF status ON attendance_records
    WHEN NEW.status IS NOT NULL AND NEW.status <> LOWER(NEW.status) COLLATE BINARY
    BEGIN
        UPDATE attendance_records SET status = LOWER(status) WHERE id = NEW.id;
    END;
CREATE TRIGGER attendance_view_delete INSTEAD OF DELETE ON attendance
    BEGIN
        DELETE FROM attendance_records WHERE id = OLD.id;
    END;
CREATE TRIGGER attendance_view_insert INSTEAD OF INSERT ON attendance
    BEGIN
        INSERT INTO attendance_records (id, student_id, module_code, date, status, reason, notes,
                                        recorded_by, recorded_at, check_in_time, departure_time,
                                        check_in_method)
        VALUES (NEW.id, NEW.student_id, NEW.module_code, COALESCE(NEW.date, NEW.class_date),
                LOWER(NEW.status), NEW.reason, NEW.notes, COALESCE(NEW.recorded_by, 'register'),
                COALESCE(NEW.created_at, datetime('now')), NEW.arrival_time, NEW.departure_time,
                'register');
    END;
CREATE TRIGGER attendance_view_update INSTEAD OF UPDATE ON attendance
    BEGIN
        UPDATE attendance_records
           SET student_id = NEW.student_id, module_code = NEW.module_code, date = NEW.date,
               status = LOWER(NEW.status), reason = NEW.reason, notes = NEW.notes,
               recorded_by = NEW.recorded_by, check_in_time = NEW.arrival_time,
               departure_time = NEW.departure_time
         WHERE id = OLD.id;
    END;
CREATE TRIGGER ftp_cases_touch_updated_at
AFTER UPDATE ON ftp_cases
BEGIN
    UPDATE ftp_cases SET updated_at = CURRENT_TIMESTAMP
     WHERE case_id = NEW.case_id;
END;
CREATE TRIGGER grades_board_lock_delete BEFORE DELETE ON grades FOR EACH ROW WHEN EXISTS (SELECT 1 FROM assessments a JOIN module_grades mg         ON mg.module_code = a.module_code AND mg.student_id = OLD.student_id         WHERE a.assessment_id = OLD.assessment_id AND a.reassessment_of IS NULL           AND mg.locked = 1) BEGIN SELECT RAISE(ABORT, 'Marks for this module were ratified by an exam board. Reopen the board to change them.'); END;
CREATE TRIGGER grades_board_lock_insert BEFORE INSERT ON grades FOR EACH ROW WHEN EXISTS (SELECT 1 FROM assessments a JOIN module_grades mg         ON mg.module_code = a.module_code AND mg.student_id = NEW.student_id         WHERE a.assessment_id = NEW.assessment_id AND a.reassessment_of IS NULL           AND mg.locked = 1) BEGIN SELECT RAISE(ABORT, 'Marks for this module were ratified by an exam board. Reopen the board to change them.'); END;
CREATE TRIGGER grades_board_lock_update BEFORE UPDATE OF score, raw_score, result_code ON grades FOR EACH ROW WHEN EXISTS (SELECT 1 FROM assessments a JOIN module_grades mg         ON mg.module_code = a.module_code AND mg.student_id = OLD.student_id         WHERE a.assessment_id = OLD.assessment_id AND a.reassessment_of IS NULL           AND mg.locked = 1) BEGIN SELECT RAISE(ABORT, 'Marks for this module were ratified by an exam board. Reopen the board to change them.'); END;
CREATE TRIGGER housing_buildings_mirror_delete
        AFTER DELETE ON housing_buildings
        BEGIN
            DELETE FROM buildings
             WHERE building_code = OLD.building_id
               AND building_type = 'Residence';
        END;
CREATE TRIGGER housing_buildings_mirror_insert
        AFTER INSERT ON housing_buildings
        BEGIN
            INSERT OR IGNORE INTO buildings
                (building_name, building_code, address, total_rooms,
                 building_type, is_active, created_at)
            VALUES
                (NEW.building_name, NEW.building_id, NEW.address,
                 NEW.total_rooms, 'Residence', 1, NEW.created_at);
        END;
CREATE TRIGGER housing_buildings_mirror_update
        AFTER UPDATE ON housing_buildings
        BEGIN
            UPDATE buildings
               SET building_name = NEW.building_name,
                   address       = NEW.address,
                   total_rooms   = NEW.total_rooms
             WHERE building_code = OLD.building_id;
        END;
CREATE TRIGGER mobility_placements_touch
AFTER UPDATE ON mobility_placements
BEGIN
    UPDATE mobility_placements SET updated_at = CURRENT_TIMESTAMP
     WHERE placement_id = NEW.placement_id;
END;
CREATE TRIGGER mobility_recognition_rollup_delete
AFTER DELETE ON mobility_credit_recognitions
BEGIN
    UPDATE mobility_placements
       SET credits_recognised = (
               SELECT COALESCE(SUM(home_credits), 0)
                 FROM mobility_credit_recognitions
                WHERE placement_id = OLD.placement_id
                  AND outcome IN ('Recognised', 'Partially Recognised'))
     WHERE placement_id = OLD.placement_id;
END;
CREATE TRIGGER mobility_recognition_rollup_insert
AFTER INSERT ON mobility_credit_recognitions
BEGIN
    UPDATE mobility_placements
       SET credits_recognised = (
               SELECT COALESCE(SUM(home_credits), 0)
                 FROM mobility_credit_recognitions
                WHERE placement_id = NEW.placement_id
                  AND outcome IN ('Recognised', 'Partially Recognised'))
     WHERE placement_id = NEW.placement_id;
END;
CREATE TRIGGER notify_parent_on_absence AFTER INSERT ON attendance_records
WHEN LOWER(NEW.status) <> 'present'
BEGIN
    INSERT INTO parent_notifications (parent_id, student_id, notification_type,
                                      notification_content, created_date, read_status)
    SELECT psr.parent_id, NEW.student_id, 'attendance',
           'Absence recorded: ' || NEW.status || ' on ' || NEW.date, datetime('now'), 0
      FROM parent_student_relationships psr
      JOIN parent_preferences pp ON psr.parent_id = pp.parent_id
     WHERE psr.student_id = NEW.student_id AND pp.attendance_alerts = 1;
END;
CREATE TRIGGER notify_parent_on_grade
        AFTER INSERT ON student_grades
        BEGIN
            INSERT INTO parent_notifications (
                parent_id,
                student_id,
                notification_type,
                notification_content,
                created_date,
                read_status
            )
            SELECT
                psr.parent_id,
                NEW.student_id,
                'grade',
                'New grade recorded: ' || NEW.assessment_name || ' - ' || NEW.grade,
                datetime('now'),
                0
            FROM parent_student_relationships psr
            JOIN parent_preferences pp ON psr.parent_id = pp.parent_id
            WHERE psr.student_id = NEW.student_id AND pp.grade_alerts = 1;
        END;
