CREATE TRIGGER student_modules_mirror_delete
        AFTER DELETE ON student_modules
        BEGIN
        DELETE FROM module_enrolments
         WHERE student_id = OLD.student_id AND module_code = OLD.module_code
           AND NOT EXISTS (SELECT 1 FROM attendance_events ae
                            WHERE ae.module_enrolment_id = module_enrolments.module_enrolment_id);
        UPDATE module_enrolments SET status = 'withdrawn',
               effective_to = COALESCE(effective_to, date('now')), updated_at = CURRENT_TIMESTAMP
         WHERE student_id = OLD.student_id AND module_code = OLD.module_code;
        END;
CREATE TRIGGER student_modules_mirror_insert
        AFTER INSERT ON student_modules
        WHEN NEW.student_id IS NOT NULL AND NEW.module_code IS NOT NULL
        BEGIN
        
    INSERT INTO programme_registrations (student_id, programme_code, academic_year,
        occurrence_code, mode_of_study, status, effective_from, registered_at, registered_by)
    SELECT s.student_id, s.course, CASE WHEN CAST(strftime('%m', 'now') AS INTEGER) >= 9 THEN strftime('%Y', 'now') || '/' || (CAST(strftime('%Y', 'now') AS INTEGER) + 1) ELSE (CAST(strftime('%Y', 'now') AS INTEGER) - 1) || '/' || strftime('%Y', 'now') END, 'MAIN', COALESCE(NULLIF(s.mode_of_study, ''),
           'full-time'), 'registered', date('now'), datetime('now'), 'student_modules'
      FROM students s
     WHERE s.student_id = NEW.student_id AND COALESCE(s.course, '') <> ''
       AND NOT EXISTS (SELECT 1 FROM programme_registrations pr
                        WHERE pr.student_id = NEW.student_id);

        UPDATE module_enrolments SET status = CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END,
               effective_to = CASE WHEN CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END = 'enrolled' THEN NULL
                                   ELSE COALESCE(effective_to, date('now')) END,
               updated_at = CURRENT_TIMESTAMP
         WHERE student_id = NEW.student_id AND module_code = NEW.module_code;
        
    INSERT INTO module_enrolments (registration_id, student_id, module_code, academic_year,
        teaching_period, attempt_number, status, effective_from, effective_to)
    SELECT pr.registration_id, NEW.student_id, NEW.module_code, pr.academic_year,
           NEW.semester, 1, CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END,
           COALESCE(NULLIF(NEW.enrollment_date, ''), date('now')),
           CASE WHEN CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END = 'enrolled' THEN NULL
                ELSE COALESCE(NULLIF(NEW.completion_date, ''), date('now')) END
      FROM programme_registrations pr
     WHERE pr.student_id = NEW.student_id
       AND NOT EXISTS (SELECT 1 FROM module_enrolments me
                        WHERE me.student_id = NEW.student_id
                          AND me.module_code = NEW.module_code)
     ORDER BY pr.registration_id DESC LIMIT 1;

        END;
CREATE TRIGGER student_modules_mirror_rekey
        AFTER UPDATE OF student_id, module_code ON student_modules
        BEGIN
        UPDATE module_enrolments SET student_id = NEW.student_id, module_code = NEW.module_code,
               updated_at = CURRENT_TIMESTAMP
         WHERE student_id = OLD.student_id AND module_code = OLD.module_code;
        END;
CREATE TRIGGER student_modules_mirror_update
        AFTER UPDATE OF status, enrollment_date, completion_date, semester ON student_modules
        WHEN NEW.student_id IS NOT NULL AND NEW.module_code IS NOT NULL
        BEGIN
        
    INSERT INTO programme_registrations (student_id, programme_code, academic_year,
        occurrence_code, mode_of_study, status, effective_from, registered_at, registered_by)
    SELECT s.student_id, s.course, CASE WHEN CAST(strftime('%m', 'now') AS INTEGER) >= 9 THEN strftime('%Y', 'now') || '/' || (CAST(strftime('%Y', 'now') AS INTEGER) + 1) ELSE (CAST(strftime('%Y', 'now') AS INTEGER) - 1) || '/' || strftime('%Y', 'now') END, 'MAIN', COALESCE(NULLIF(s.mode_of_study, ''),
           'full-time'), 'registered', date('now'), datetime('now'), 'student_modules'
      FROM students s
     WHERE s.student_id = NEW.student_id AND COALESCE(s.course, '') <> ''
       AND NOT EXISTS (SELECT 1 FROM programme_registrations pr
                        WHERE pr.student_id = NEW.student_id);

        UPDATE module_enrolments SET status = CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END,
               teaching_period = COALESCE(NEW.semester, teaching_period),
               effective_from = COALESCE(NULLIF(NEW.enrollment_date, ''), effective_from),
               effective_to = CASE WHEN CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END = 'enrolled' THEN NULL
                                   ELSE COALESCE(NULLIF(NEW.completion_date, ''), effective_to,
                                                 date('now')) END,
               updated_at = CURRENT_TIMESTAMP
         WHERE student_id = NEW.student_id AND module_code = NEW.module_code;
        
    INSERT INTO module_enrolments (registration_id, student_id, module_code, academic_year,
        teaching_period, attempt_number, status, effective_from, effective_to)
    SELECT pr.registration_id, NEW.student_id, NEW.module_code, pr.academic_year,
           NEW.semester, 1, CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END,
           COALESCE(NULLIF(NEW.enrollment_date, ''), date('now')),
           CASE WHEN CASE WHEN NEW.status = 'Enrolled' OR LOWER(NEW.status) = 'enrolled' THEN 'enrolled' ELSE LOWER(COALESCE(NEW.status, 'enrolled')) END = 'enrolled' THEN NULL
                ELSE COALESCE(NULLIF(NEW.completion_date, ''), date('now')) END
      FROM programme_registrations pr
     WHERE pr.student_id = NEW.student_id
       AND NOT EXISTS (SELECT 1 FROM module_enrolments me
                        WHERE me.student_id = NEW.student_id
                          AND me.module_code = NEW.module_code)
     ORDER BY pr.registration_id DESC LIMIT 1;

        END;
CREATE TRIGGER submissions_board_lock_delete BEFORE DELETE ON assignment_submissions FOR EACH ROW WHEN EXISTS (SELECT 1 FROM assignments a JOIN module_grades mg         ON mg.module_code = a.module_code AND mg.student_id = OLD.student_id         WHERE a.id = OLD.assignment_id AND a.reassessment_of IS NULL           AND mg.locked = 1) BEGIN SELECT RAISE(ABORT, 'Marks for this module were ratified by an exam board. Reopen the board to change them.'); END;
CREATE TRIGGER submissions_board_lock_update BEFORE UPDATE OF grade ON assignment_submissions FOR EACH ROW WHEN EXISTS (SELECT 1 FROM assignments a JOIN module_grades mg         ON mg.module_code = a.module_code AND mg.student_id = OLD.student_id         WHERE a.id = OLD.assignment_id AND a.reassessment_of IS NULL           AND mg.locked = 1) BEGIN SELECT RAISE(ABORT, 'Marks for this module were ratified by an exam board. Reopen the board to change them.'); END;
CREATE TRIGGER sync_disc_status_to_misc AFTER UPDATE OF status ON disciplinary_records WHEN NEW.status IS NOT OLD.status      AND NEW.status IN ('Under Review', 'Resolved', 'Appealed') BEGIN   UPDATE academic_misconduct_cases      SET status = CASE NEW.status WHEN 'Under Review' THEN 'Under Review' WHEN 'Resolved' THEN 'Resolved' WHEN 'Appealed' THEN 'Pending Hearing' ELSE NEW.status END,          updated_at = CURRENT_TIMESTAMP    WHERE source_record_id = NEW.record_id      AND status != CASE NEW.status WHEN 'Under Review' THEN 'Under Review' WHEN 'Resolved' THEN 'Resolved' WHEN 'Appealed' THEN 'Pending Hearing' ELSE NEW.status END; END;
CREATE TRIGGER sync_ftp_stage_to_disc
AFTER UPDATE OF stage ON ftp_cases
WHEN NEW.stage IS NOT OLD.stage
     AND NEW.source_record_id IS NOT NULL
     AND NEW.stage IN ('Outcome Issued', 'Closed')
BEGIN
    UPDATE disciplinary_records
       SET status = CASE NEW.stage
                        WHEN 'Closed' THEN 'Resolved'
                        ELSE 'Resolved'
                    END,
           updated_at = CURRENT_TIMESTAMP
     WHERE record_id = NEW.source_record_id
       AND status NOT IN ('Resolved', 'Closed');
END;
CREATE TRIGGER sync_misc_status_to_disc AFTER UPDATE OF status ON academic_misconduct_cases WHEN NEW.status IS NOT OLD.status      AND NEW.source_record_id IS NOT NULL      AND NEW.status IN ('Under Review', 'Resolved', 'Pending Hearing') BEGIN   UPDATE disciplinary_records      SET status = CASE NEW.status WHEN 'Under Review' THEN 'Under Review' WHEN 'Resolved' THEN 'Resolved' WHEN 'Pending Hearing' THEN 'Appealed' ELSE NEW.status END,          updated_at = CURRENT_TIMESTAMP    WHERE record_id = NEW.source_record_id      AND status != CASE NEW.status WHEN 'Under Review' THEN 'Under Review' WHEN 'Resolved' THEN 'Resolved' WHEN 'Pending Hearing' THEN 'Appealed' ELSE NEW.status END; END;
CREATE TRIGGER trg_support_tickets_canonical_insert
AFTER INSERT ON support_tickets
WHEN NEW.requester_username IS NULL OR NEW.source IS NULL OR NEW.source NOT IN ('support', 'helpdesk')
  OR (NEW.status IS NOT NULL AND NEW.status NOT IN ('open', 'in_progress', 'waiting_on_student', 'escalated', 'resolved', 'closed'))
BEGIN
  UPDATE support_tickets SET
    requester_username = COALESCE(NEW.requester_username, (SELECT username FROM users WHERE username = NEW.user_id), (SELECT username FROM users WHERE student_id = NEW.user_id ORDER BY id LIMIT 1), (SELECT username FROM users WHERE CAST(id AS TEXT) = CAST(NEW.user_id AS TEXT))),
    student_id = COALESCE(NEW.student_id, (SELECT student_id FROM users WHERE username = NEW.requester_username), (SELECT student_id FROM users WHERE username = NEW.user_id), (SELECT student_id FROM users WHERE student_id = NEW.user_id ORDER BY id LIMIT 1), (SELECT student_id FROM users WHERE CAST(id AS TEXT) = CAST(NEW.user_id AS TEXT)), (SELECT student_id FROM students WHERE student_id = NEW.user_id)),
    channel = CASE WHEN NEW.source IN ('support', 'helpdesk') THEN channel
                   ELSE COALESCE(channel, NEW.source) END,
    source = CASE WHEN NEW.source IN ('support', 'helpdesk') THEN NEW.source
                  WHEN NEW.status GLOB '[A-Z]*' THEN 'support'
                  ELSE 'helpdesk' END,
    status = (CASE lower(trim(replace(replace(NEW.status, '_', ' '), '-', ' '))) WHEN 'open' THEN 'open' WHEN 'new' THEN 'open' WHEN 'reopened' THEN 'open' WHEN 'submitted' THEN 'open' WHEN 'in progress' THEN 'in_progress' WHEN 'inprogress' THEN 'in_progress' WHEN 'assigned' THEN 'in_progress' WHEN 'active' THEN 'in_progress' WHEN 'working' THEN 'in_progress' WHEN 'waiting on student' THEN 'waiting_on_student' WHEN 'waiting for customer' THEN 'waiting_on_student' WHEN 'waiting for student' THEN 'waiting_on_student' WHEN 'waiting' THEN 'waiting_on_student' WHEN 'pending' THEN 'waiting_on_student' WHEN 'on hold' THEN 'waiting_on_student' WHEN 'awaiting response' THEN 'waiting_on_student' WHEN 'awaiting student' THEN 'waiting_on_student' WHEN 'escalated' THEN 'escalated' WHEN 'resolved' THEN 'resolved' WHEN 'completed' THEN 'resolved' WHEN 'done' THEN 'resolved' WHEN 'fixed' THEN 'resolved' WHEN 'closed' THEN 'closed' WHEN 'cancelled' THEN 'closed' WHEN 'canceled' THEN 'closed' WHEN 'merged' THEN 'closed' ELSE NEW.status END)
  WHERE ticket_id = NEW.ticket_id;
END;
CREATE TRIGGER trg_support_tickets_status_vocabulary
AFTER UPDATE OF status ON support_tickets
WHEN NEW.status IS NOT NULL AND NEW.status NOT IN ('open', 'in_progress', 'waiting_on_student', 'escalated', 'resolved', 'closed')
BEGIN
  UPDATE support_tickets SET status = (CASE lower(trim(replace(replace(NEW.status, '_', ' '), '-', ' '))) WHEN 'open' THEN 'open' WHEN 'new' THEN 'open' WHEN 'reopened' THEN 'open' WHEN 'submitted' THEN 'open' WHEN 'in progress' THEN 'in_progress' WHEN 'inprogress' THEN 'in_progress' WHEN 'assigned' THEN 'in_progress' WHEN 'active' THEN 'in_progress' WHEN 'working' THEN 'in_progress' WHEN 'waiting on student' THEN 'waiting_on_student' WHEN 'waiting for customer' THEN 'waiting_on_student' WHEN 'waiting for student' THEN 'waiting_on_student' WHEN 'waiting' THEN 'waiting_on_student' WHEN 'pending' THEN 'waiting_on_student' WHEN 'on hold' THEN 'waiting_on_student' WHEN 'awaiting response' THEN 'waiting_on_student' WHEN 'awaiting student' THEN 'waiting_on_student' WHEN 'escalated' THEN 'escalated' WHEN 'resolved' THEN 'resolved' WHEN 'completed' THEN 'resolved' WHEN 'done' THEN 'resolved' WHEN 'fixed' THEN 'resolved' WHEN 'closed' THEN 'closed' WHEN 'cancelled' THEN 'closed' WHEN 'canceled' THEN 'closed' WHEN 'merged' THEN 'closed' ELSE NEW.status END)
  WHERE ticket_id = NEW.ticket_id;
END;
CREATE TRIGGER update_document_timestamp 
                AFTER UPDATE ON document_repository
                BEGIN
                    UPDATE document_repository SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
                END;
